INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37332, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その店は偽な時計を売っていました。", "corrected_sentence": "その店は偽の時計を売っていました。", "error_description": "「偽」は名詞なので、名詞を修飾する時は「の」で続ける。「な」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37332, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その時計は偽かったので、店で返品しました。", "corrected_sentence": "その時計は偽だったので、店で返品しました。", "error_description": "「偽」は名詞に「だ」を付ける形。過去は「だった」で、「かった」は形容詞の活用なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37333, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「偽の名前」と名詞を修飾する連体修飾の「の」で、偽の直後に入る。"}, {"text": "を", "is_correct": false, "explanation": "「偽を名前で」と目的語にできず、文の構造が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「偽が名前で」では文として成立しない。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示すが、「偽に名前で」では修飾の関係にならない。"}], "correct_answer": "の", "explanations": {"の": "「偽の名前」と名詞を修飾する連体修飾の「の」で、偽の直後に入る。", "を": "「偽を名前で」と目的語にできず、文の構造が成り立たない。", "が": "主語を示すが、「偽が名前で」では文として成立しない。", "に": "場所や相手を示すが、「偽に名前で」では修飾の関係にならない。"}, "error_tags": {"を": "目的語にできず、名詞修飾の形にならない", "が": "主語にできず、文が成立しない", "に": "修飾関係にならず、「偽に」では意味が通らない"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真実", "is_correct": true, "explanation": "「偽り（うそ）」の対義語で、事実として本当のことを指す。"}, {"text": "噂", "is_correct": false, "explanation": "不確かな情報を指す名詞で、「偽」の対義語とはされない。"}, {"text": "計画", "is_correct": false, "explanation": "これからの予定を指す名詞で、「偽」の対義語ではない。"}, {"text": "伝言", "is_correct": false, "explanation": "人づてに伝える言葉で、「偽」の対義語とはされない。"}], "correct_answer": "真実", "explanations": {"真実": "「偽り（うそ）」の対義語で、事実として本当のことを指す。", "噂": "不確かな情報を指す名詞で、「偽」の対義語とはされない。", "計画": "これからの予定を指す名詞で、「偽」の対義語ではない。", "伝言": "人づてに伝える言葉で、「偽」の対義語とはされない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
