INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37333, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "本物ではないこと。実際には存在しないことや、うそであること。", "primary_collocate": null, "pronunciation": "にせ", "ipa": "ɲise", "syllable_count": 2, "sentences": [{"text": "偽の情報を信じて、多くの人が駅に集まってしまいました。", "target_word": "偽", "complexity_tier": "T3", "furigana": "偽[にせ]の情報[じょうほう]を信[しん]じて、多[おお]くの人[ひと]が駅[えき]に集[あつ]まってしまいました。", "sentence_source": "generated"}, {"text": "彼は偽の名前でホテルに泊まっていました。", "target_word": "偽", "complexity_tier": "T3", "furigana": "彼[かれ]は偽[にせ]の名前[なまえ]でホテルに泊[と]まっていました。", "sentence_source": "generated"}, {"text": "偽の住所を書いたので、荷物が届きませんでした。", "target_word": "偽", "complexity_tier": "T3", "furigana": "偽[にせ]の住所[じゅうしょ]を書[か]いたので、荷物[にもつ]が届[とど]きませんでした。", "sentence_source": "generated"}, {"text": "銀行を名乗る偽のメールが届いたら、開かずに消してください。", "target_word": "偽", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]を名乗[なの]る偽[にせ]のメールが届[とど]いたら、開[ひら]かずに消[け]してください。", "sentence_source": "generated"}, {"text": "偽の証言をした男は、後で警察に本当のことを話しました。", "target_word": "偽", "complexity_tier": "T3", "furigana": "偽[にせ]の証言[しょうげん]をした男[おとこ]は、後[あと]で警察[けいさつ]に本当[ほんとう]のことを話[はな]しました。", "sentence_source": "generated"}, {"text": "偽の請求書に注意するよう、市役所が呼びかけています。", "target_word": "偽", "complexity_tier": "T3", "furigana": "偽[にせ]の請求書[せいきゅうしょ]に注意[ちゅうい]するよう、市役所[しやくしょ]が呼[よ]びかけています。", "sentence_source": "generated"}, {"text": "犯人は偽の話を作って、警察をだまそうとしました。", "target_word": "偽", "complexity_tier": "T3", "furigana": "犯人[はんにん]は偽[にせ]の話[はなし]を作[つく]って、警察[けいさつ]をだまそうとしました。", "sentence_source": "generated"}, {"text": "偽のうわさが広まり、店の客が減ってしまいました。", "target_word": "偽", "complexity_tier": "T3", "furigana": "偽[にせ]のうわさが広[ひろ]まり、店[みせ]の客[きゃく]が減[へ]ってしまいました。", "sentence_source": "generated"}, {"text": "ネットには偽のニュースが多いので、確認が必要です。", "target_word": "偽", "complexity_tier": "T3", "furigana": "ネットには偽[にせ]のニュースが多[おお]いので、確認[かくにん]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "偽の理由を言って会社を休んだことを、今は反省しています。", "target_word": "偽", "complexity_tier": "T3", "furigana": "偽[にせ]の理由[りゆう]を言[い]って会社[かいしゃ]を休[やす]んだことを、今[いま]は反省[はんせい]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "偽", "label": "基本形"}, {"form": "偽の", "label": "連体修飾（の）"}, {"form": "偽だ", "label": "断定形"}, {"form": "偽で", "label": "で形"}], "register": "neutral", "sense_fingerprint": "事実ではなく、人をだますために作られたうその内容・名前・情報であること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: だまそ (Zipf 1.78)']::text[], '24bff216-7aef-4422-8d8a-73355dcf2e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37333, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偽", "is_correct": true, "explanation": "名詞として「偽の情報」と続け、うその情報を表す。"}, {"text": "偽る", "is_correct": false, "explanation": "動詞で、名詞の前に「の」を付けて修飾することができない。"}, {"text": "偽って", "is_correct": false, "explanation": "て形の動詞で、名詞の前に置いて修飾できない。"}, {"text": "偽ろう", "is_correct": false, "explanation": "意志形の動詞で、名詞を修飾する形として成立しない。"}], "explanations": {"偽": "名詞として「偽の情報」と続け、うその情報を表す。", "偽る": "動詞で、名詞の前に「の」を付けて修飾することができない。", "偽って": "て形の動詞で、名詞の前に置いて修飾できない。", "偽ろう": "意志形の動詞で、名詞を修飾する形として成立しない。"}, "sentence_index": 0, "correct_answer": "偽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この偽の看板は、実際の店の場所を正確に示していた。", "explanation": "ここは〈正確な案内〉の意味。偽は本物ではない、実際には存在しないという意味なので、「偽の看板が正確に示す」は矛盾する。"}, {"text": "この偽の書類は、実際の記録と正確に一致していた。", "explanation": "ここは〈記録と一致する〉の意味。偽は本物ではない、うそであるという意味なので、「偽の書類が実際の記録と一致する」は矛盾する。"}, {"text": "偽の噂は、実際に起きた出来事を正確に伝えていた。", "explanation": "ここは〈真実を伝える〉の意味。偽はうそであるという意味なので、「偽の噂が正確に伝える」は矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37333, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偽", "is_correct": true, "explanation": "名詞として「偽の話」と続け、事実でないうその話を表す。"}, {"text": "偽られ", "is_correct": false, "explanation": "受身の語幹で、名詞を修飾する形として成立しない。"}, {"text": "偽れ", "is_correct": false, "explanation": "命令形で、名詞句の一部として成立しない。"}, {"text": "偽ります", "is_correct": false, "explanation": "丁寧形の動詞で、「の」に続けて名詞を修飾できない。"}], "explanations": {"偽": "名詞として「偽の話」と続け、事実でないうその話を表す。", "偽られ": "受身の語幹で、名詞を修飾する形として成立しない。", "偽れ": "命令形で、名詞句の一部として成立しない。", "偽ります": "丁寧形の動詞で、「の」に続けて名詞を修飾できない。"}, "sentence_index": 6, "correct_answer": "偽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "偽の謝罪文は、本当の気持ちを正直に伝えていた。", "explanation": "ここは〈うそ〉の意味。偽はうそであるという意味なので、「偽の謝罪文が本当の気持ちを伝える」は矛盾する。"}, {"text": "偽の作業記録は、実際に行われた作業を正確に示していた。", "explanation": "ここは〈事実を示す〉の意味。偽はうそであるという意味なので、「偽の記録が事実を示す」は矛盾する。"}, {"text": "偽の証言は、実際の事件を正確に記録していた。", "explanation": "ここは〈事実を記録する〉の意味。偽はうそであるという意味なので、「偽の証言が事実を記録する」は矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37333, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は偽話で皆をだましました。", "corrected_sentence": "彼は偽の話で皆をだましました。", "error_description": "「偽」は名詞で、後ろに名詞を続けるには「偽の」とする必要がある。「偽話」と続けるのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37333, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "偽造の噂を広めた人が、後で謝りました。", "corrected_sentence": "偽の噂を広めた人が、後で謝りました。", "error_description": "「偽造」は文書や紙幣などを作って偽る意味。うわさやうそを表すには「偽」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37336, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「英語を話す」と言語を対象に取る格助詞で、話す内容を示す。"}, {"text": "に", "is_correct": false, "explanation": "「英語に上手に話します」では話す対象の関係が成り立たず、不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表すが、「英語と上手に話します」では不自然になる。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「英語から話す」では言語を対象にできない。"}], "correct_answer": "を", "explanations": {"を": "「英語を話す」と言語を対象に取る格助詞で、話す内容を示す。", "に": "「英語に上手に話します」では話す対象の関係が成り立たず、不自然になる。", "と": "相手や並列を表すが、「英語と上手に話します」では不自然になる。", "から": "起点を示すが、「英語から話す」では言語を対象にできない。"}, "error_tags": {"と": "相手を示すが、言語を対象にできない", "から": "起点を示すが、言語を対象にできない", "に": "相手を示すが、言語を対象にできない"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聞く", "is_correct": true, "explanation": "「話す」の対義語で、言葉を受け取る行為を表す。"}, {"text": "歩く", "is_correct": false, "explanation": "移動の動詞で、「話す」の対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "休息の動詞で、「話す」の対義語とはされない。"}, {"text": "笑う", "is_correct": false, "explanation": "表情や感情を表す動詞で、「話す」の対義語ではない。"}], "correct_answer": "聞く", "explanations": {"聞く": "「話す」の対義語で、言葉を受け取る行為を表す。", "歩く": "移動の動詞で、「話す」の対義語ではない。", "眠る": "休息の動詞で、「話す」の対義語とはされない。", "笑う": "表情や感情を表す動詞で、「話す」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37336, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「今日は」と話題を示す係助詞で、「あまり話せません」の文脈を作る。"}, {"text": "を", "is_correct": false, "explanation": "「今日を」と目的語にはできず、文が不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「今日へあまり話せません」では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、比べる相手がなく文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「今日は」と話題を示す係助詞で、「あまり話せません」の文脈を作る。", "を": "「今日を」と目的語にはできず、文が不自然になる。", "へ": "方向を示すが、「今日へあまり話せません」では意味が通らない。", "より": "比較を表すが、比べる相手がなく文が成り立たない。"}, "error_tags": {"を": "目的語にできず、時を表す語に続かない", "へ": "方向を示すが、時を表す語には使えない", "より": "比較の相手がなく不自然になる"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "聞く", "is_correct": true, "explanation": "「話す」の対義語で、言葉を受け取る行為を表す。"}, {"text": "眺める", "is_correct": false, "explanation": "見る行為を表す動詞で、「話す」の対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "移動させる動詞で、「話す」の対義語とはされない。"}, {"text": "作る", "is_correct": false, "explanation": "作り出す動詞で、「話す」の対義語ではない。"}], "correct_answer": "聞く", "explanations": {"聞く": "「話す」の対義語で、言葉を受け取る行為を表す。", "眺める": "見る行為を表す動詞で、「話す」の対義語ではない。", "運ぶ": "移動させる動詞で、「話す」の対義語とはされない。", "作る": "作り出す動詞で、「話す」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37336, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "くちから ことばを だす。", "primary_collocate": null, "pronunciation": "はなす", "ipa": "hanasɯ", "syllable_count": 3, "sentences": [{"text": "赤ちゃんはまだ話せませんが、よく笑います。", "target_word": "話せません", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんはまだ話[はな]せませんが、よく笑[わら]います。", "sentence_source": "generated"}, {"text": "兄は英語を上手に話します。", "target_word": "話します", "complexity_tier": "T3", "furigana": "兄[あに]は英語[えいご]を上手[じょうず]に話[はな]します。", "sentence_source": "generated"}, {"text": "小さな声で話してください。", "target_word": "話して", "complexity_tier": "T3", "furigana": "小[ちい]さな声[こえ]で話[はな]してください。", "sentence_source": "generated"}, {"text": "ゆっくり話すと、外国の人もよく分かります。", "target_word": "話す", "complexity_tier": "T3", "furigana": "ゆっくり話[はな]すと、外国[がいこく]の人[ひと]もよく分[わ]かります。", "sentence_source": "generated"}, {"text": "図書館では大きな声で話さないでください。", "target_word": "話さない", "complexity_tier": "T3", "furigana": "図書館[としょかん]では大[おお]きな声[こえ]で話[はな]さないでください。", "sentence_source": "generated"}, {"text": "彼女は速く話すので、聞き取りにくいです。", "target_word": "話す", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は速[はや]く話[はな]すので、聞[き]き取[と]りにくいです。", "sentence_source": "generated"}, {"text": "授業中に話すのは、やめましょう。", "target_word": "話す", "complexity_tier": "T3", "furigana": "授業中[じゅぎょうちゅう]に話[はな]すのは、やめましょう。", "sentence_source": "generated"}, {"text": "のどが痛くて、今日はあまり話せません。", "target_word": "話せません", "complexity_tier": "T3", "furigana": "のどが痛[いた]くて、今日[きょう]はあまり話[はな]せません。", "sentence_source": "generated"}, {"text": "このロボットは、人の言葉を聞いて話します。", "target_word": "話します", "complexity_tier": "T3", "furigana": "このロボットは、人[ひと]の言葉[ことば]を聞[き]いて話[はな]します。", "sentence_source": "generated"}, {"text": "私の国の言葉を話せる人は、このクラスに三人います。", "target_word": "話せる", "complexity_tier": "T3", "furigana": "私[わたし]の国[くに]の言葉[ことば]を話[はな]せる人[ひと]は、このクラスに三人[さんにん]います。", "sentence_source": "generated"}], "morphological_forms": [{"form": "話します", "label": "丁寧形"}, {"form": "話さない", "label": "否定形"}, {"form": "話して", "label": "て形"}, {"form": "話した", "label": "た形"}, {"form": "話せば", "label": "仮定形"}, {"form": "話そう", "label": "意志形"}, {"form": "話せる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "口を使って言葉を発する、しゃべる行為そのもの（話し方・言語・声の大きさ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24bff216-7aef-4422-8d8a-73355dcf2e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37336, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "話せません", "is_correct": true, "explanation": "否定の可能形で、「まだ〜が」の逆接の流れに合い、話せない様子を表す。"}, {"text": "話して", "is_correct": false, "explanation": "て形で、「が」の前に置いても逆接の文が成立しない。"}, {"text": "話そう", "is_correct": false, "explanation": "意志形で、「が」の前に置くと文が成り立たない。"}, {"text": "話せ", "is_correct": false, "explanation": "命令形で、「が」に続く文として成立しない。"}], "explanations": {"話せません": "否定の可能形で、「まだ〜が」の逆接の流れに合い、話せない様子を表す。", "話して": "て形で、「が」の前に置いても逆接の文が成立しない。", "話そう": "意志形で、「が」の前に置くと文が成り立たない。", "話せ": "命令形で、「が」に続く文として成立しない。"}, "sentence_index": 0, "correct_answer": "話せません"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会長は原稿を、みんなの前で話しました。", "explanation": "ここは〈読み上げる〉の意味。原稿を読むことは「話す」とは言わない。"}, {"text": "友だちに手紙を話しました。", "explanation": "ここは〈書く〉の意味。手紙は書くもので、話すとは言わない。"}, {"text": "掲示板に意見を話しました。", "explanation": "ここは〈書き込む〉の意味。掲示板には書き込むもので、話すとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37336, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "話す", "is_correct": true, "explanation": "辞書形で「授業中に話すのは」と名詞句を作り、文が成立する。"}, {"text": "話さ", "is_correct": false, "explanation": "未然形の語幹で、名詞句を作ることができない。"}, {"text": "話させ", "is_correct": false, "explanation": "使役の語幹で、「のは」に続けると文が成り立たない。"}, {"text": "話すこと", "is_correct": false, "explanation": "「こと」の形は「のは」と重ねられず、不自然になる。"}], "explanations": {"話す": "辞書形で「授業中に話すのは」と名詞句を作り、文が成立する。", "話さ": "未然形の語幹で、名詞句を作ることができない。", "話させ": "使役の語幹で、「のは」に続けると文が成り立たない。", "話すこと": "「こと」の形は「のは」と重ねられず、不自然になる。"}, "sentence_index": 6, "correct_answer": "話す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生の質問に、はっきり話しました。", "explanation": "ここは〈答える〉の意味。質問への返答は「答える」で、「話す」では合わない。"}, {"text": "庭の猫を外に話しました。", "explanation": "ここは〈放す〉の意味。同じ読みでも「話す」とは別の語で、この文では使えない。"}, {"text": "寝る前に、子どもに絵本を話してあげました。", "explanation": "ここは〈読む〉の意味。絵本は読んで聞かせるもので、話すとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37336, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は中国語に話せます。", "corrected_sentence": "妹は中国語を話せます。", "error_description": "「話す」は言語を対象にして「〜を話す」と言うので「を」を取る。「に」は相手を表すので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "話します", "is_correct": true, "explanation": "丁寧形で文末に入り、「兄は英語を上手に話す」という文が成立する。"}, {"text": "話し", "is_correct": false, "explanation": "連用形のみでは文を終えられず、文が不完全になる。"}, {"text": "話せば", "is_correct": false, "explanation": "仮定形は後ろに主節が必要で、文末には置けない。"}, {"text": "話して", "is_correct": false, "explanation": "て形は文末に置けず、文が途中で切れて不自然になる。"}], "correct_form": "話します", "base_form": "話す", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"話します": "丁寧形で文末に入り、「兄は英語を上手に話す」という文が成立する。", "話し": "連用形のみでは文を終えられず、文が不完全になる。", "話せば": "仮定形は後ろに主節が必要で、文末には置けない。", "話して": "て形は文末に置けず、文が途中で切れて不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37336, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "図書館では、小さな声で話すましょう。", "corrected_sentence": "図書館では、小さな声で話しましょう。", "error_description": "「ましょう」は連用形（話し）に続く。辞書形「話す」には続かないので誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "話せません", "is_correct": true, "explanation": "可能形の丁寧否定形で、「あまり〜ません」と文を終えられる。"}, {"text": "話せる", "is_correct": false, "explanation": "肯定の可能形で、文末に置いても否定の意味にならない。"}, {"text": "話せたら", "is_correct": false, "explanation": "仮定形は後ろに主節が必要で、文末には置けない。"}, {"text": "話さ", "is_correct": false, "explanation": "未然形の語幹で、文を終えることができない。"}], "correct_form": "話せません", "base_form": "話す", "form_label": "可能形の丁寧否定形", "sentence_index": 7, "explanations": {"話せません": "可能形の丁寧否定形で、「あまり〜ません」と文を終えられる。", "話せる": "肯定の可能形で、文末に置いても否定の意味にならない。", "話せたら": "仮定形は後ろに主節が必要で、文末には置けない。", "話さ": "未然形の語幹で、文を終えることができない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37337, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「内容を話す」の「を」。話す内容である「予定」を示す。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表し、話す内容には使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「予定へ話す」は話す内容にならない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語で、予定が話すことになり文の意味が変わる。"}], "correct_answer": "を", "explanations": {"を": "「内容を話す」の「を」。話す内容である「予定」を示す。", "で": "「で」は場所や手段を表し、話す内容には使えない。", "へ": "「へ」は方向を示し、「予定へ話す」は話す内容にならない。", "が": "「が」は主語で、予定が話すことになり文の意味が変わる。"}, "error_tags": {"を": "対象", "で": "手段・場所", "へ": "方向", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
