INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37337, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人が言葉を声に出して伝える。", "primary_collocate": null, "pronunciation": "はなす", "ipa": "hanasɯ", "syllable_count": 3, "sentences": [{"text": "先生に悩みを話しました。", "target_word": "話しました", "complexity_tier": "T3", "furigana": "先生[せんせい]に悩[なや]みを話[はな]しました。", "sentence_source": "generated"}, {"text": "友だちに旅行の予定を話すと、一緒に行きたいと言われました。", "target_word": "話す", "complexity_tier": "T3", "furigana": "友[とも]だちに旅行[りょこう]の予定[よてい]を話[はな]すと、一緒[いっしょ]に行[い]きたいと言[い]われました。", "sentence_source": "generated"}, {"text": "母に本当のことを話して、気持ちが楽になりました。", "target_word": "話して", "complexity_tier": "T3", "furigana": "母[はは]に本当[ほんとう]のことを話[はな]して、気持[きも]ちが楽[らく]になりました。", "sentence_source": "generated"}, {"text": "この秘密は誰にも話さないと約束しました。", "target_word": "話さない", "complexity_tier": "T3", "furigana": "この秘密[ひみつ]は誰[だれ]にも話[はな]さないと約束[やくそく]しました。", "sentence_source": "generated"}, {"text": "昨日あったことを家族に話しました。", "target_word": "話しました", "complexity_tier": "T3", "furigana": "昨日[きのう]あったことを家族[かぞく]に話[はな]しました。", "sentence_source": "generated"}, {"text": "彼は将来の夢を私に話してくれました。", "target_word": "話して", "complexity_tier": "T3", "furigana": "彼[かれ]は将来[しょうらい]の夢[ゆめ]を私[わたし]に話[はな]してくれました。", "sentence_source": "generated"}, {"text": "事故のことを警察に話したので、すぐに調べてもらえました。", "target_word": "話した", "complexity_tier": "T3", "furigana": "事故[じこ]のことを警察[けいさつ]に話[はな]したので、すぐに調[しら]べてもらえました。", "sentence_source": "generated"}, {"text": "結果が出たら、すぐにあなたに話します。", "target_word": "話します", "complexity_tier": "T3", "furigana": "結果[けっか]が出[で]たら、すぐにあなたに話[はな]します。", "sentence_source": "generated"}, {"text": "困ったことは一人で悩まずに、私に話してください。", "target_word": "話して", "complexity_tier": "T3", "furigana": "困[こま]ったことは一人[ひとり]で悩[なや]まずに、私[わたし]に話[はな]してください。", "sentence_source": "generated"}, {"text": "祖父は戦争の経験を私たちに話してくれました。", "target_word": "話して", "complexity_tier": "T3", "furigana": "祖父[そふ]は戦争[せんそう]の経験[けいけん]を私[わたし]たちに話[はな]してくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "話します", "label": "丁寧形"}, {"form": "話さない", "label": "否定形"}, {"form": "話して", "label": "て形"}, {"form": "話した", "label": "た形"}, {"form": "話せば", "label": "仮定形"}, {"form": "話そう", "label": "意志形"}, {"form": "話せる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "相手に事柄・考え・経験などを言葉で伝え、知らせる（に＋内容を話す）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24bff216-7aef-4422-8d8a-73355dcf2e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37337, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "話しました", "is_correct": true, "explanation": "相手に悩みを言葉で伝えた、の意味。先生に打ち明ける文脈に合う。"}, {"text": "焼きました", "is_correct": false, "explanation": "「悩みを焼く」とは言わず、伝える文脈とは合わない。"}, {"text": "運びました", "is_correct": false, "explanation": "悩みは物ではないので、運ぶ対象にならない。"}, {"text": "壊しました", "is_correct": false, "explanation": "「悩みを壊す」とは言わず、伝えるという場面と合わない。"}], "explanations": {"話しました": "相手に悩みを言葉で伝えた、の意味。先生に打ち明ける文脈に合う。", "焼きました": "「悩みを焼く」とは言わず、伝える文脈とは合わない。", "運びました": "悩みは物ではないので、運ぶ対象にならない。", "壊しました": "「悩みを壊す」とは言わず、伝えるという場面と合わない。"}, "sentence_index": 0, "correct_answer": "話しました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鳥かごの扉を話すと、鳥が外へ飛び立った。", "explanation": "ここは〈放す〉（解き放つ）の意味。同じ読みの〈放す〉と取り違えた例で、〈話す〉は言葉を伝える意味なので扉には使えない。"}, {"text": "日記に、その日の出来事を話した。", "explanation": "〈話す〉は声に出して伝えることなので、日記に書いた内容には使えない。"}, {"text": "会議で資料を話した。", "explanation": "〈話す〉は言葉で伝える語なので、資料を対象にする用法はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37337, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "話した", "is_correct": true, "explanation": "言葉で事情を伝えた、の意味。警察に知らせた文脈に合う。"}, {"text": "磨いた", "is_correct": false, "explanation": "「警察に磨いた」は意味が通らず、伝える文脈と合わない。"}, {"text": "眺めた", "is_correct": false, "explanation": "「警察を眺めた」は意味が通らず、伝える場面と合わない。"}, {"text": "沸かした", "is_correct": false, "explanation": "「警察を沸かした」とは使わず、事故の報告とは関係しない。"}], "explanations": {"話した": "言葉で事情を伝えた、の意味。警察に知らせた文脈に合う。", "磨いた": "「警察に磨いた」は意味が通らず、伝える文脈と合わない。", "眺めた": "「警察を眺めた」は意味が通らず、伝える場面と合わない。", "沸かした": "「警察を沸かした」とは使わず、事故の報告とは関係しない。"}, "sentence_index": 6, "correct_answer": "話した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は戦争の記録を写真に話してくれました。", "explanation": "〈話す〉は言葉で伝える語なので、写真に残す対象にはならない。"}, {"text": "祖父は戦争の役を話してくれました。", "explanation": "〈話す〉は言葉を伝える語なので、役を対象にする用法はない。"}, {"text": "祖父は戦争の歌を話してくれました。", "explanation": "〈話す〉は言葉を伝える語なので、歌を対象にする用法はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37337, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちに旅行の計画を話さると、一緒に行きたいと言われました。", "corrected_sentence": "友だちに旅行の計画を話すと、一緒に行きたいと言われました。", "error_description": "「話す」に「と」をつける時は「話すと」。「話さると」は誤った形で、「話す」の活用が崩れている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "話す", "is_correct": true, "explanation": "辞書形。「〜と」の前に来る基本形で、文の流れに合う。"}, {"text": "話し", "is_correct": false, "explanation": "連用形。「〜と」の前に置けず、文が成立しない。"}, {"text": "話して", "is_correct": false, "explanation": "て形。「〜と」に続かず、文が成立しない。"}, {"text": "話せば", "is_correct": false, "explanation": "仮定形。「〜と」と重ねると文が不自然になる。"}], "correct_form": "話す", "base_form": "話す", "form_label": "辞書形", "sentence_index": 1, "explanations": {"話す": "辞書形。「〜と」の前に来る基本形で、文の流れに合う。", "話し": "連用形。「〜と」の前に置けず、文が成立しない。", "話して": "て形。「〜と」に続かず、文が成立しない。", "話せば": "仮定形。「〜と」と重ねると文が不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37337, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "連絡が来たら、すぐにあなたに話しします。", "corrected_sentence": "連絡が来たら、すぐにあなたに話します。", "error_description": "丁寧形は「話します」。「話しします」は「し」が重なった誤りで、正しくは「話します」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "話します", "is_correct": true, "explanation": "丁寧形。文末で、今後の報告を丁寧に述べる形。"}, {"text": "話し", "is_correct": false, "explanation": "連用形。文末に置けず、文が途中で止まる。"}, {"text": "話さ", "is_correct": false, "explanation": "未然形。文末に置けず、文が途中で止まる。"}, {"text": "話させ", "is_correct": false, "explanation": "使役の連用形。文末に置けず、文が成立しない。"}], "correct_form": "話します", "base_form": "話す", "form_label": "丁寧形", "sentence_index": 7, "explanations": {"話します": "丁寧形。文末で、今後の報告を丁寧に述べる形。", "話し": "連用形。文末に置けず、文が途中で止まる。", "話さ": "未然形。文末に置けず、文が途中で止まる。", "話させ": "使役の連用形。文末に置けず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37338, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「足が動く」の「が」。動く主体の足を示す。"}, {"text": "を", "is_correct": false, "explanation": "「足を動かなくなる」は対象の形にならず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「足に動かなくなる」は位置や相手を示す形にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「足へ動かなくなる」は方向を表さず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「足が動く」の「が」。動く主体の足を示す。", "を": "「足を動かなくなる」は対象の形にならず不自然。", "に": "「足に動かなくなる」は位置や相手を示す形にならず不自然。", "へ": "「足へ動かなくなる」は方向を表さず、文が成り立たない。"}, "error_tags": {"を": "対象", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
