INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37338, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や動物が体や手足の位置を変える。", "primary_collocate": null, "pronunciation": "うごく", "ipa": "ɯɡokɯ", "syllable_count": 3, "sentences": [{"text": "朝起きたら、足が痛くて動けませんでした。", "target_word": "動けません", "complexity_tier": "T3", "furigana": "朝[あさ]起[お]きたら、足[あし]が痛[いた]くて動[うご]けませんでした。", "sentence_source": "generated"}, {"text": "走ったあとで、足が動かなくなりました。", "target_word": "動かなく", "complexity_tier": "T3", "furigana": "走[はし]ったあとで、足[あし]が動[うご]かなくなりました。", "sentence_source": "generated"}, {"text": "動かないでください。写真を撮ります。", "target_word": "動かないで", "complexity_tier": "T3", "furigana": "動[うご]かないでください。写真[しゃしん]を撮[と]ります。", "sentence_source": "generated"}, {"text": "犬は寝ていて、少しも動きません。", "target_word": "動きません", "complexity_tier": "T3", "furigana": "犬[いぬ]は寝[ね]ていて、少[すこ]しも動[うご]きません。", "sentence_source": "generated"}, {"text": "寒くて手が動きません。", "target_word": "動きません", "complexity_tier": "T3", "furigana": "寒[さむ]くて手[て]が動[うご]きません。", "sentence_source": "generated"}, {"text": "子どもたちは公園で元気よく動いています。", "target_word": "動いて", "complexity_tier": "T3", "furigana": "子[こ]どもたちは公園[こうえん]で元気[げんき]よく動[うご]いています。", "sentence_source": "generated"}, {"text": "年を取ると、前のように体が動かなくなります。", "target_word": "動かなく", "complexity_tier": "T3", "furigana": "年[とし]を取[と]ると、前[まえ]のように体[からだ]が動[うご]かなくなります。", "sentence_source": "generated"}, {"text": "音楽に合わせて動いてみましょう。", "target_word": "動いて", "complexity_tier": "T3", "furigana": "音楽[おんがく]に合[あ]わせて動[うご]いてみましょう。", "sentence_source": "generated"}, {"text": "病気で、三日間ほとんど動けなかった。", "target_word": "動けなかった", "complexity_tier": "T3", "furigana": "病気[びょうき]で、三日間[みっかかん]ほとんど動[うご]けなかった。", "sentence_source": "generated"}, {"text": "急に動くと、けがをした足が痛くなります。", "target_word": "動く", "complexity_tier": "T3", "furigana": "急[きゅう]に動[うご]くと、けがをした足[あし]が痛[いた]くなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動きます", "label": "丁寧形"}, {"form": "動かない", "label": "否定形"}, {"form": "動いて", "label": "て形"}, {"form": "動いた", "label": "た形"}, {"form": "動けば", "label": "仮定形"}, {"form": "動こう", "label": "意志形"}, {"form": "動ける", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "人や動物が体や手足の位置を変える、体を動かす（機械や物事が動く意味ではない）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24bff216-7aef-4422-8d8a-73355dcf2e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37338, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動けません", "is_correct": true, "explanation": "体を動かす意味の「動く」の可能形否定。足の痛みで体を動かせない文脈に合う。"}, {"text": "聞こえません", "is_correct": false, "explanation": "耳に音が届かない意味で、足の痛みとは関係しない。"}, {"text": "見えません", "is_correct": false, "explanation": "目で見えない意味で、足の痛みの文脈と合わない。"}, {"text": "光りません", "is_correct": false, "explanation": "光る意味で、体の痛みの状況とは合わない。"}], "explanations": {"動けません": "体を動かす意味の「動く」の可能形否定。足の痛みで体を動かせない文脈に合う。", "聞こえません": "耳に音が届かない意味で、足の痛みとは関係しない。", "見えません": "目で見えない意味で、足の痛みの文脈と合わない。", "光りません": "光る意味で、体の痛みの状況とは合わない。"}, "sentence_index": 0, "correct_answer": "動けません"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は頭痛によく動く。", "explanation": "〈動く〉は体や物の位置が変わる意味で、薬の効果を表すことはできない。"}, {"text": "駅の近くで事故が動いた。", "explanation": "〈動く〉は人や物の位置が変わる意味で、事故が起こる意味では使えない。"}, {"text": "その映画を見て、涙が動いた。", "explanation": "〈動く〉は体の位置が変わる意味で、涙があふれる意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37338, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動かなく", "is_correct": true, "explanation": "体を動かす意味の否定連用形。年齢で体が衰える文脈に合う。"}, {"text": "割れなく", "is_correct": false, "explanation": "割れる意味で、体の動きの変化とは関係しない。"}, {"text": "濡れなく", "is_correct": false, "explanation": "濡れる意味で、体が動かなくなる文脈と合わない。"}, {"text": "焦げなく", "is_correct": false, "explanation": "焦げる意味で、人の体の変化には使わない。"}], "explanations": {"動かなく": "体を動かす意味の否定連用形。年齢で体が衰える文脈に合う。", "割れなく": "割れる意味で、体の動きの変化とは関係しない。", "濡れなく": "濡れる意味で、体が動かなくなる文脈と合わない。", "焦げなく": "焦げる意味で、人の体の変化には使わない。"}, "sentence_index": 6, "correct_answer": "動かなく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の花が一斉に動いた。", "explanation": "〈動く〉は体や物の位置が変わる意味で、花が開く意味は表せない。"}, {"text": "玄関のチャイムが急に動いた。", "explanation": "〈動く〉は位置や状態が変わる意味で、音を出す意味は表せない。"}, {"text": "その店の評判が町中に動いた。", "explanation": "〈動く〉は人や物が移る意味で、評判が広がる意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37338, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "急に動くて、けがをした足が痛くなります。", "corrected_sentence": "急に動いて、けがをした足が痛くなります。", "error_description": "「動く」のて形は「動いて」。「動くて」は誤った活用形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "動かなく", "is_correct": true, "explanation": "否定形の連用形。「〜なくなる」で、動きが止まっていく変化を表す。"}, {"text": "動かない", "is_correct": false, "explanation": "否定形。「動かないなりました」となり、「なくなる」の形に合わない。"}, {"text": "動けば", "is_correct": false, "explanation": "仮定形。「〜なくなりました」に続かず、文が成立しない。"}, {"text": "動けない", "is_correct": false, "explanation": "可能形の否定。「動けないなりました」となり、文の形が合わない。"}], "correct_form": "動かなく", "base_form": "動く", "form_label": "否定形の連用形", "sentence_index": 1, "explanations": {"動かなく": "否定形の連用形。「〜なくなる」で、動きが止まっていく変化を表す。", "動かない": "否定形。「動かないなりました」となり、「なくなる」の形に合わない。", "動けば": "仮定形。「〜なくなりました」に続かず、文が成立しない。", "動けない": "可能形の否定。「動けないなりました」となり、文の形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37338, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ここで少しも動かないて待ってください。", "corrected_sentence": "ここで少しも動かないで待ってください。", "error_description": "「動かない」のて形（ないで）は「動かないで」。「動かないて」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "動いて", "is_correct": true, "explanation": "て形。「てみましょう」に続けて、試しに動く提案を表す。"}, {"text": "動いた", "is_correct": false, "explanation": "た形。「動いたみましょう」とは続かず、文が成立しない。"}, {"text": "動きます", "is_correct": false, "explanation": "丁寧形。「動きますてみましょう」となり、文の形が合わない。"}, {"text": "動こう", "is_correct": false, "explanation": "意志形。「動こうてみましょう」では文が不自然になる。"}], "correct_form": "動いて", "base_form": "動く", "form_label": "て形", "sentence_index": 7, "explanations": {"動いて": "て形。「てみましょう」に続けて、試しに動く提案を表す。", "動いた": "た形。「動いたみましょう」とは続かず、文が成立しない。", "動きます": "丁寧形。「動きますてみましょう」となり、文の形が合わない。", "動こう": "意志形。「動こうてみましょう」では文が不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37339, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「犬が動く」の「が」。動く主体の犬を示す。"}, {"text": "を", "is_correct": false, "explanation": "「犬を動いた」は対象の形にならず、動く語とは結びつかない。"}, {"text": "に", "is_correct": false, "explanation": "「犬に動いた」は位置や相手を示さず、文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「犬へ動いた」は方向を示せず、文が不自然。"}], "correct_answer": "が", "explanations": {"が": "「犬が動く」の「が」。動く主体の犬を示す。", "を": "「犬を動いた」は対象の形にならず、動く語とは結びつかない。", "に": "「犬に動いた」は位置や相手を示さず、文が成立しない。", "へ": "「犬へ動いた」は方向を示せず、文が不自然。"}, "error_tags": {"を": "対象", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "止まる", "is_correct": true, "explanation": "「動く」の対義語。位置の移動や作動が止まる意味で、対応する。"}, {"text": "眺める", "is_correct": false, "explanation": "見る意味で、「動く」の対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "移動させる意味だが、「動く」の対義語ではない。"}, {"text": "増える", "is_correct": false, "explanation": "数や量が増す意味で、「動く」の対義語にはならない。"}], "correct_answer": "止まる", "explanations": {"止まる": "「動く」の対義語。位置の移動や作動が止まる意味で、対応する。", "眺める": "見る意味で、「動く」の対義語ではない。", "運ぶ": "移動させる意味だが、「動く」の対義語ではない。", "増える": "数や量が増す意味で、「動く」の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
