INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37339, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "位置や状態を変える。動作をする。", "primary_collocate": null, "pronunciation": "うごく", "ipa": "uɡoku", "syllable_count": 3, "sentences": [{"text": "電車が動くまで、ホームで待とう。", "target_word": "動く", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が動[うご]くまで、ホームで待[ま]とう。", "sentence_source": "generated"}, {"text": "犬が急に動いたので、写真がぼやけてしまった。", "target_word": "動いた", "complexity_tier": "T3", "furigana": "犬[いぬ]が急[きゅう]に動[うご]いたので、写真[しゃしん]がぼやけてしまった。", "sentence_source": "generated"}, {"text": "足をけがして、今日は動くのがつらい。", "target_word": "動く", "complexity_tier": "T3", "furigana": "足[あし]をけがして、今日[きょう]は動[うご]くのがつらい。", "sentence_source": "generated"}, {"text": "このロボットは電池がなくなると動かなくなる。", "target_word": "動かなく", "complexity_tier": "T3", "furigana": "このロボットは電池[でんち]がなくなると動[うご]かなくなる。", "sentence_source": "generated"}, {"text": "重い机は一人では動かなかった。", "target_word": "動かなかった", "complexity_tier": "T3", "furigana": "重[おも]い机[つくえ]は一人[ひとり]では動[うご]かなかった。", "sentence_source": "generated"}, {"text": "地震のあと、地面が少し動いたように感じた。", "target_word": "動いた", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、地面[じめん]が少[すこ]し動[うご]いたように感[かん]じた。", "sentence_source": "generated"}, {"text": "赤ちゃんが起きるから、動かないで。", "target_word": "動かないで", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが起[お]きるから、動[うご]かないで。", "sentence_source": "generated"}, {"text": "朝は体が動くように、軽い体操をする。", "target_word": "動く", "complexity_tier": "T3", "furigana": "朝[あさ]は体[からだ]が動[うご]くように、軽[かる]い体操[たいそう]をする。", "sentence_source": "generated"}, {"text": "この古い時計は電池を替えると、また針が動いた。", "target_word": "動いた", "complexity_tier": "T3", "furigana": "この古[ふる]い時計[とけい]は電池[でんち]を替[か]えると、また針[はり]が動[うご]いた。", "sentence_source": "generated"}, {"text": "魚が水の中で動くのを、子どもたちはじっと見ていた。", "target_word": "動く", "complexity_tier": "T3", "furigana": "魚[さかな]が水[みず]の中[なか]で動[うご]くのを、子[こ]どもたちはじっと見[み]ていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動く", "label": "終止形"}, {"form": "動かない", "label": "否定形"}, {"form": "動いた", "label": "過去形"}, {"form": "動いて", "label": "て形"}, {"form": "動けば", "label": "仮定形"}, {"form": "動こう", "label": "意向形"}], "register": "neutral", "sense_fingerprint": "物や機械が位置を変える、または作動する意味の「動く」（人・動物の体の動きは含まない）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: けがし (Zipf 2.18)']::text[], '24bff216-7aef-4422-8d8a-73355dcf2e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37339, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動く", "is_correct": true, "explanation": "電車が位置を変えて走り出す意味。出発までの待つ文脈に合う。"}, {"text": "眠る", "is_correct": false, "explanation": "電車は眠らないので、ここでは意味が通らない。"}, {"text": "笑う", "is_correct": false, "explanation": "電車は笑わないので、文脈と合わない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "電車は叫ばないので、ホームで待つ文脈と合わない。"}], "explanations": {"動く": "電車が位置を変えて走り出す意味。出発までの待つ文脈に合う。", "眠る": "電車は眠らないので、ここでは意味が通らない。", "笑う": "電車は笑わないので、文脈と合わない。", "叫ぶ": "電車は叫ばないので、ホームで待つ文脈と合わない。"}, "sentence_index": 0, "correct_answer": "動く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "赤ちゃんは、ゆりかごでぐっすり動いた。", "explanation": "〈動く〉は位置や状態が変わる意味で、眠る意味は表せない。"}, {"text": "昨日の出来事が、ふと頭に動いた。", "explanation": "〈動く〉は位置が変わる意味で、考えが浮かぶ意味では使えない。"}, {"text": "庭の花が一斉に動いた。", "explanation": "〈動く〉は位置や状態が変わる意味で、花が開く意味は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37339, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動かないで", "is_correct": true, "explanation": "否定の「ないで」形。赤ちゃんを起こさないよう、動きを止めるよう頼む文に合う。"}, {"text": "書かないで", "is_correct": false, "explanation": "書く意味で、赤ちゃんが起きる文脈とは関係しない。"}, {"text": "凍らないで", "is_correct": false, "explanation": "凍る意味で、赤ちゃんが起きる文脈とは関係しない。"}, {"text": "描かないで", "is_correct": false, "explanation": "描く意味で、赤ちゃんが起きる文脈と合わない。"}], "explanations": {"動かないで": "否定の「ないで」形。赤ちゃんを起こさないよう、動きを止めるよう頼む文に合う。", "書かないで": "書く意味で、赤ちゃんが起きる文脈とは関係しない。", "凍らないで": "凍る意味で、赤ちゃんが起きる文脈とは関係しない。", "描かないで": "描く意味で、赤ちゃんが起きる文脈と合わない。"}, "sentence_index": 6, "correct_answer": "動かないで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関のチャイムが急に動いた。", "explanation": "〈動く〉は位置や状態が変わる意味で、音を出す意味は表せない。"}, {"text": "その店の評判が町中に動いた。", "explanation": "〈動く〉は人や物が移る意味で、評判が広がる意味では使えない。"}, {"text": "スープが急に動いた。", "explanation": "〈動く〉は冷める意味を持たないので、スープが動いたという文は不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37339, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電車を動く時、ホームで待とう。", "corrected_sentence": "電車が動く時、ホームで待とう。", "error_description": "「動く」は主語（電車）に「が」をつける。「電車を動く」の「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "動いた", "is_correct": true, "explanation": "過去形。過去の出来事として、写真がぼやけた原因を示す。"}, {"text": "動いて", "is_correct": false, "explanation": "て形。「動いてので」とは続かず、理由の文が成立しない。"}, {"text": "動けば", "is_correct": false, "explanation": "仮定形。「動ければので」となり、理由の文に合わない。"}, {"text": "動こう", "is_correct": false, "explanation": "意志形。犬の意思を表す文になり、写真の結果と合わない。"}], "correct_form": "動いた", "base_form": "動く", "form_label": "過去形", "sentence_index": 1, "explanations": {"動いた": "過去形。過去の出来事として、写真がぼやけた原因を示す。", "動いて": "て形。「動いてので」とは続かず、理由の文が成立しない。", "動けば": "仮定形。「動ければので」となり、理由の文に合わない。", "動こう": "意志形。犬の意思を表す文になり、写真の結果と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37339, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い時計の針が動くた。", "corrected_sentence": "古い時計の針が動いた。", "error_description": "「動く」の過去形は「動いた」。「動くた」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "動く", "is_correct": true, "explanation": "辞書形。「ように」の前に来る基本形で、体が動くようにという目的を示す。"}, {"text": "動かず", "is_correct": false, "explanation": "連用形。「ように」に続かず、目的の文が成立しない。"}, {"text": "動かせば", "is_correct": false, "explanation": "仮定形。「動かせばように」となり、文の形が合わない。"}, {"text": "動くな", "is_correct": false, "explanation": "禁止形。「動くなように」では意味が成立しない。"}], "correct_form": "動く", "base_form": "動く", "form_label": "辞書形", "sentence_index": 7, "explanations": {"動く": "辞書形。「ように」の前に来る基本形で、体が動くようにという目的を示す。", "動かず": "連用形。「ように」に続かず、目的の文が成立しない。", "動かせば": "仮定形。「動かせばように」となり、文の形が合わない。", "動くな": "禁止形。「動くなように」では意味が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e0ff9a7-c104-4e4a-8ede-14a3651cff99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
