INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37344, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "けんかをしないことです。いけんがちがっても、なかまをたたいたりしません。", "primary_collocate": null, "pronunciation": "けんかはしません", "ipa": "keŋka wa ɕimaseɴ", "syllable_count": 8, "sentences": [{"text": "私たちは意見が違っても、喧嘩はしません。", "target_word": "喧嘩はしません", "complexity_tier": "T3", "furigana": "私[わたし]たちは意見[いけん]が違[ちが]っても、喧嘩[けんか]はしません。", "sentence_source": "generated"}, {"text": "兄と私は仲がいいので、喧嘩はしない。", "target_word": "喧嘩はしない", "complexity_tier": "T3", "furigana": "兄[あに]と私[わたし]は仲[なか]がいいので、喧嘩[けんか]はしない。", "sentence_source": "generated"}, {"text": "この学校の生徒は、何があっても喧嘩はしません。", "target_word": "喧嘩はしません", "complexity_tier": "T3", "furigana": "この学校[がっこう]の生徒[せいと]は、何[なに]があっても喧嘩[けんか]はしません。", "sentence_source": "generated"}, {"text": "友達とは喧嘩はしないで、仲よくしましょう。", "target_word": "喧嘩はしないで", "complexity_tier": "T3", "furigana": "友達[ともだち]とは喧嘩[けんか]はしないで、仲[なか]よくしましょう。", "sentence_source": "generated"}, {"text": "小さいころ、弟とは一度も喧嘩はしなかった。", "target_word": "喧嘩はしなかった", "complexity_tier": "T3", "furigana": "小[ちい]さいころ、弟[おとうと]とは一度[いちど]も喧嘩[けんか]はしなかった。", "sentence_source": "generated"}, {"text": "私は話し合いで解決したいので、喧嘩はしません。", "target_word": "喧嘩はしません", "complexity_tier": "T3", "furigana": "私[わたし]は話[はな]し合[あ]いで解決[かいけつ]したいので、喧嘩[けんか]はしません。", "sentence_source": "generated"}, {"text": "先生は「クラスの中で喧嘩はしないでください」と言った。", "target_word": "喧嘩はしないで", "complexity_tier": "T3", "furigana": "先生[せんせい]は「クラスの中[なか]で喧嘩[けんか]はしないでください」と言[い]った。", "sentence_source": "generated"}, {"text": "あの二人は考え方が違うが、喧嘩はしない。", "target_word": "喧嘩はしない", "complexity_tier": "T3", "furigana": "あの二人[ふたり]は考[かんが]え方[かた]が違[ちが]うが、喧嘩[けんか]はしない。", "sentence_source": "generated"}, {"text": "祖父は怒っても、決して喧嘩はしませんでした。", "target_word": "喧嘩はしません", "complexity_tier": "T4", "furigana": "祖父[そふ]は怒[おこ]っても、決[けっ]して喧嘩[けんか]はしませんでした。", "sentence_source": "generated"}, {"text": "このチームは練習中に意見が割れても、喧嘩はしません。", "target_word": "喧嘩はしません", "complexity_tier": "T3", "furigana": "このチームは練習中(れんしゅうちゅう)に意見(いけん)が割(わ)れても、喧嘩(けんか)はしません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "喧嘩はしません", "label": "polite negative"}, {"form": "喧嘩はしない", "label": "plain negative"}, {"form": "喧嘩はしなかった", "label": "past negative"}, {"form": "喧嘩はしないで", "label": "negative te-form"}], "register": "neutral", "sense_fingerprint": "けんかをしない（意見が違っても争わない）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7bfaf5f-7601-4049-bf95-765962747195') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37344, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喧嘩はしません", "is_correct": true, "explanation": "意見が違っても争わないという意味で、文の内容に合う。"}, {"text": "喧嘩は食べません", "is_correct": false, "explanation": "「喧嘩を食べる」は成り立たないので、この文には合わない。"}, {"text": "喧嘩は洗いません", "is_correct": false, "explanation": "「洗う」は喧嘩には使わないので、この文には合わない。"}, {"text": "喧嘩は書きません", "is_correct": false, "explanation": "「書く」は喧嘩には使わないので、この文には合わない。"}], "explanations": {"喧嘩はしません": "意見が違っても争わないという意味で、文の内容に合う。", "喧嘩は食べません": "「喧嘩を食べる」は成り立たないので、この文には合わない。", "喧嘩は洗いません": "「洗う」は喧嘩には使わないので、この文には合わない。", "喧嘩は書きません": "「書く」は喧嘩には使わないので、この文には合わない。"}, "sentence_index": 0, "correct_answer": "喧嘩はしません"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姉は喧嘩はして、願書の名前を書いた。", "explanation": "喧嘩は争いの意味なので、用紙に名前を書く文には合わない。"}, {"text": "先生は喧嘩はして、クラスの出席を取った。", "explanation": "喧嘩は争いの意味なので、出席を確認する文には合わない。"}, {"text": "母は喧嘩はして、小麦粉の重さを量った。", "explanation": "喧嘩は争いの意味なので、材料の重さを測る文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37344, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喧嘩はしないで", "is_correct": true, "explanation": "「してはいけない」という禁止の意味で、先生の指示として合う。"}, {"text": "喧嘩は泳がないで", "is_correct": false, "explanation": "「泳ぐ」は喧嘩には使わないので、禁止の文として合わない。"}, {"text": "喧嘩は冷やさないで", "is_correct": false, "explanation": "「冷やす」は喧嘩には使わないので、この文には合わない。"}, {"text": "喧嘩は歌わないで", "is_correct": false, "explanation": "「歌う」は喧嘩には使わないので、この文には合わない。"}], "explanations": {"喧嘩はしないで": "「してはいけない」という禁止の意味で、先生の指示として合う。", "喧嘩は泳がないで": "「泳ぐ」は喧嘩には使わないので、禁止の文として合わない。", "喧嘩は冷やさないで": "「冷やす」は喧嘩には使わないので、この文には合わない。", "喧嘩は歌わないで": "「歌う」は喧嘩には使わないので、この文には合わない。"}, "sentence_index": 6, "correct_answer": "喧嘩はしないで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このチームは練習中、選手の動きを喧嘩はして採点します。", "explanation": "喧嘩は争いの意味なので、選手の動きを点数で評価する文には合わない。"}, {"text": "このチームは練習中に、ボールを喧嘩はして回収します。", "explanation": "喧嘩は争いの意味なので、ボールを集める作業には合わない。"}, {"text": "監督は練習中、選手の意見を喧嘩にまとめて、話を終えた。", "explanation": "喧嘩は争いの意味なので、意見を簡潔に整理する文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37344, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹とは一度も喧嘩はしました。", "corrected_sentence": "妹とは一度も喧嘩はしなかった。", "error_description": "「一度も」は否定と結びつくので、肯定形の「しました」ではなく否定の「しなかった」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "喧嘩はしない", "is_correct": true, "explanation": "普通体の否定形で、文の内容に合う。"}, {"text": "喧嘩はしないよう", "is_correct": false, "explanation": "「ように」の途中の形なので、文を終えられない。"}, {"text": "喧嘩はしなければ", "is_correct": false, "explanation": "仮定の形なので、文を終えられない。"}, {"text": "喧嘩はしないで", "is_correct": false, "explanation": "て形なので、文の述語として終わらない。"}], "correct_form": "喧嘩はしない", "base_form": "喧嘩はする", "form_label": "否定形", "sentence_index": 1, "explanations": {"喧嘩はしない": "普通体の否定形で、文の内容に合う。", "喧嘩はしないよう": "「ように」の途中の形なので、文を終えられない。", "喧嘩はしなければ": "仮定の形なので、文を終えられない。", "喧嘩はしないで": "て形なので、文の述語として終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37344, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日は妹と喧嘩はしますでした。", "corrected_sentence": "昨日は妹と喧嘩はしませんでした。", "error_description": "過去の否定は「しませんでした」が正しく、「しますでした」は活用が誤っている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "喧嘩はしない", "is_correct": true, "explanation": "普通体の否定形で、文の内容に合う。"}, {"text": "喧嘩はしよう", "is_correct": false, "explanation": "意志形なので、事実を述べる文と合わない。"}, {"text": "喧嘩はしたら", "is_correct": false, "explanation": "条件形なので、「考え方が違うが」の文と合わない。"}, {"text": "喧嘩はさせない", "is_correct": false, "explanation": "使役の否定形で、誰かにさせないという意味になり文と合わない。"}], "correct_form": "喧嘩はしない", "base_form": "喧嘩はする", "form_label": "否定形", "sentence_index": 7, "explanations": {"喧嘩はしない": "普通体の否定形で、文の内容に合う。", "喧嘩はしよう": "意志形なので、事実を述べる文と合わない。", "喧嘩はしたら": "条件形なので、「考え方が違うが」の文と合わない。", "喧嘩はさせない": "使役の否定形で、誰かにさせないという意味になり文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37348, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「チーム全員で」と、努力の手段・共同の場を表す「で」。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」で、自動詞の「頑張る」には続かない。"}, {"text": "に", "is_correct": false, "explanation": "位置や対象の「に」で、「チーム全員に頑張った」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、「チーム全員へ頑張った」は文意が合わない。"}], "correct_answer": "で", "explanations": {"で": "「チーム全員で」と、努力の手段・共同の場を表す「で」。", "を": "目的語の「を」で、自動詞の「頑張る」には続かない。", "に": "位置や対象の「に」で、「チーム全員に頑張った」は不自然。", "へ": "方向を示す「へ」で、「チーム全員へ頑張った」は文意が合わない。"}, "error_tags": {"を": "目的語", "に": "位置・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
