INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37348, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "みんなで力を合わせて最後まであきらめないこと。", "primary_collocate": null, "pronunciation": "がんばる", "ipa": "ɡambaɾɯ", "syllable_count": 4, "sentences": [{"text": "みんなで頑張って、最後まで走りきりました。", "target_word": "頑張って", "complexity_tier": "T3", "furigana": "みんなで頑張[がんば]って、最後[さいご]まで走[はし]りきりました。", "sentence_source": "generated"}, {"text": "試合は苦しかったが、チーム全員で頑張った。", "target_word": "頑張った", "complexity_tier": "T3", "furigana": "試合[しあい]は苦[く]しかったが、チーム全員[ぜんいん]で頑張[がんば]った。", "sentence_source": "generated"}, {"text": "文化祭の準備を、クラス全員で頑張っています。", "target_word": "頑張って", "complexity_tier": "T3", "furigana": "文化祭[ぶんかさい]の準備[じゅんび]を、クラス全員[ぜんいん]で頑張[がんば]っています。", "sentence_source": "generated"}, {"text": "雨が降ってきても、みんなで頑張って荷物を運んだ。", "target_word": "頑張って", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ってきても、みんなで頑張[がんば]って荷物[にもつ]を運[はこ]んだ。", "sentence_source": "generated"}, {"text": "あと少しだから、みんなで頑張ろう。", "target_word": "頑張ろう", "complexity_tier": "T3", "furigana": "あと少[すこ]しだから、みんなで頑張[がんば]ろう。", "sentence_source": "generated"}, {"text": "私たちは力を合わせて頑張ったので、劇は大成功だった。", "target_word": "頑張った", "complexity_tier": "T3", "furigana": "私[わたし]たちは力[ちから]を合[あ]わせて頑張[がんば]ったので、劇[げき]は大成功[だいせいこう]だった。", "sentence_source": "generated"}, {"text": "家族みんなで頑張れば、この大掃除も夕方までに終わるはずだ。", "target_word": "頑張れば", "complexity_tier": "T3", "furigana": "家族[かぞく]みんなで頑張[がんば]れば、この大掃除[おおそうじ]も夕方[ゆうがた]までに終[お]わるはずだ。", "sentence_source": "generated"}, {"text": "最後まで頑張ったおかげで、チームは初めて優勝できた。", "target_word": "頑張った", "complexity_tier": "T3", "furigana": "最後[さいご]まで頑張[がんば]ったおかげで、チームは初[はじ]めて優勝[ゆうしょう]できた。", "sentence_source": "generated"}, {"text": "負けそうでも、みんなで最後まで頑張るつもりです。", "target_word": "頑張る", "complexity_tier": "T3", "furigana": "負[ま]けそうでも、みんなで最後[さいご]まで頑張[がんば]るつもりです。", "sentence_source": "generated"}, {"text": "寒い中、村の人たちが頑張って雪かきをしてくれた。", "target_word": "頑張って", "complexity_tier": "T3", "furigana": "寒[さむ]い中[なか]、村[むら]の人[ひと]たちが頑張[がんば]って雪[ゆき]かきをしてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頑張る", "label": "基本形"}, {"form": "頑張ります", "label": "丁寧形"}, {"form": "頑張って", "label": "て形"}, {"form": "頑張った", "label": "過去形"}, {"form": "頑張ろう", "label": "意志形"}, {"form": "頑張れば", "label": "仮定形"}, {"form": "頑張らない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "仲間と協力して、最後まであきらめずにやり通す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aebd181-359a-45dc-80f8-127f2fbef7ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37348, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頑張って", "is_correct": true, "explanation": "て形で、後ろの「最後まで走りきりました」へ続く「頑張って」。"}, {"text": "頑張る", "is_correct": false, "explanation": "基本形で読点の前に置くと、後ろの過去の文と続かない。"}, {"text": "頑張れ", "is_correct": false, "explanation": "命令形で、「みんなで頑張れ、…走りきりました」とは続かない。"}, {"text": "頑張ろう", "is_correct": false, "explanation": "意志形で、過去の結果を述べる文と合わない。"}], "explanations": {"頑張って": "て形で、後ろの「最後まで走りきりました」へ続く「頑張って」。", "頑張る": "基本形で読点の前に置くと、後ろの過去の文と続かない。", "頑張れ": "命令形で、「みんなで頑張れ、…走りきりました」とは続かない。", "頑張ろう": "意志形で、過去の結果を述べる文と合わない。"}, "sentence_index": 0, "correct_answer": "頑張って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この地震は、みんなで頑張って起こった。", "explanation": "ここは〈努力して成し遂げる〉の意味。地震は人の努力で起こせるものではないので、頑張るとは合わない。"}, {"text": "寝坊して、頑張って遅刻した。", "explanation": "ここは〈遅刻しないよう努める〉の意味。寝坊による遅刻は努力して防ぐ行為ではないので、頑張るとは合わない。"}, {"text": "うっかり頑張って、財布を落とした。", "explanation": "ここは〈意図して努力する〉の意味。うっかりは意図せず行うことなので、頑張るとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37348, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頑張れば", "is_correct": true, "explanation": "仮定形で、「頑張れば、…終わるはずだ」と条件を示すので合う。"}, {"text": "頑張った", "is_correct": false, "explanation": "過去形で、「頑張った、…終わるはずだ」と条件の形にならない。"}, {"text": "頑張らない", "is_correct": false, "explanation": "否定形で、努力しないことになり、「頑張れば〜終わる」という条件の文意と逆になる。"}, {"text": "頑張ります", "is_correct": false, "explanation": "丁寧形で、普通体の「終わるはずだ」と続けると文体が合わず、条件の形にもならない。"}], "explanations": {"頑張れば": "仮定形で、「頑張れば、…終わるはずだ」と条件を示すので合う。", "頑張った": "過去形で、「頑張った、…終わるはずだ」と条件の形にならない。", "頑張らない": "否定形で、努力しないことになり、「頑張れば〜終わる」という条件の文意と逆になる。", "頑張ります": "丁寧形で、普通体の「終わるはずだ」と続けると文体が合わず、条件の形にもならない。"}, "sentence_index": 6, "correct_answer": "頑張れば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は母の言葉に反発して、頑張って家を出なかった。", "explanation": "ここは〈意地を張る〉の意味。頑張るは努力する意味で、意固地に拒むことではないので合わない。"}, {"text": "このお菓子は、頑張って三日で腐った。", "explanation": "ここは〈努力して状態を変える〉の意味。お菓子が腐るのは努力で左右できる変化ではないので、頑張るとは合わない。"}, {"text": "店員は、客を頑張って冷たくあしらった。", "explanation": "ここは〈冷淡に振る舞う〉の意味。頑張るは努力する意味で、人を冷たく扱う意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37348, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "みんなで頑張るて、最後まで歌いきりました。", "corrected_sentence": "みんなで頑張って、最後まで歌いきりました。", "error_description": "「頑張る」のて形は「頑張って」。「頑張るて」は活用形が誤りで、正しくは「って」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "頑張った", "is_correct": true, "explanation": "過去形で、試合が苦しかったが努力したという過去の文に合う。"}, {"text": "頑張れば", "is_correct": false, "explanation": "仮定形で、文を終えられず過去の出来事を述べる文と合わない。"}, {"text": "頑張ろう", "is_correct": false, "explanation": "意志形で、過去に努力した事実を述べる文と合わない。"}, {"text": "頑張らない", "is_correct": false, "explanation": "否定形で、チーム全員が努力したという文意と逆になる。"}], "correct_form": "頑張った", "base_form": "頑張る", "form_label": "過去形", "sentence_index": 1, "explanations": {"頑張った": "過去形で、試合が苦しかったが努力したという過去の文に合う。", "頑張れば": "仮定形で、文を終えられず過去の出来事を述べる文と合わない。", "頑張ろう": "意志形で、過去に努力した事実を述べる文と合わない。", "頑張らない": "否定形で、チーム全員が努力したという文意と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37348, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最後まで頑張れので、試合に勝てた。", "corrected_sentence": "最後まで頑張ったので、試合に勝てた。", "error_description": "過去の結果を示すには「頑張った」が正しい。「頑張れ」は命令や可能の形で、「ので」の前では過去の結果と合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "頑張った", "is_correct": true, "explanation": "過去形で、最後まで努力した結果優勝したという文に合う。"}, {"text": "頑張ります", "is_correct": false, "explanation": "丁寧形で、「おかげで」と続く形にならず、文が成り立たない。"}, {"text": "頑張り", "is_correct": false, "explanation": "連用形で、「頑張りおかげで」と続かず、文が成り立たない。"}, {"text": "頑張れ", "is_correct": false, "explanation": "命令形で、「頑張れおかげで」と続かず、結果を示す文に合わない。"}], "correct_form": "頑張った", "base_form": "頑張る", "form_label": "過去形", "sentence_index": 7, "explanations": {"頑張った": "過去形で、最後まで努力した結果優勝したという文に合う。", "頑張ります": "丁寧形で、「おかげで」と続く形にならず、文が成り立たない。", "頑張り": "連用形で、「頑張りおかげで」と続かず、文が成り立たない。", "頑張れ": "命令形で、「頑張れおかげで」と続かず、結果を示す文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
