INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37349, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "目標に向かって努力し続けること。", "primary_collocate": null, "pronunciation": "がんばる", "ipa": "ɡambaɾɯ", "syllable_count": 4, "sentences": [{"text": "医者になるために、毎日遅くまで頑張っています。", "target_word": "頑張って", "complexity_tier": "T3", "furigana": "医者[いしゃ]になるために、毎日[まいにち]遅[おそ]くまで頑張[がんば]っています。", "sentence_source": "generated"}, {"text": "彼は試験に合格するまで頑張り続けた。", "target_word": "頑張り", "complexity_tier": "T3", "furigana": "彼[かれ]は試験[しけん]に合格[ごうかく]するまで頑張[がんば]り続[つづ]けた。", "sentence_source": "generated"}, {"text": "夢をかなえようと、妹は毎朝ピアノを頑張っている。", "target_word": "頑張って", "complexity_tier": "T3", "furigana": "夢[ゆめ]をかなえようと、妹[いもうと]は毎朝[まいあさ]ピアノを頑張[がんば]っている。", "sentence_source": "generated"}, {"text": "来月の大会で優勝したいから、今は練習を頑張る。", "target_word": "頑張る", "complexity_tier": "T3", "furigana": "来月[らいげつ]の大会[たいかい]で優勝[ゆうしょう]したいから、今[いま]は練習[れんしゅう]を頑張[がんば]る。", "sentence_source": "generated"}, {"text": "日本語が上手になりたくて、毎日漢字を頑張って覚えている。", "target_word": "頑張って", "complexity_tier": "T3", "furigana": "日本語[にほんご]が上手[じょうず]になりたくて、毎日[まいにち]漢字[かんじ]を頑張[がんば]って覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "彼女は目標の貯金額まで、頑張って働いた。", "target_word": "頑張って", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は目標[もくひょう]の貯金額[ちょきんがく]まで、頑張[がんば]って働[はたら]いた。", "sentence_source": "generated"}, {"text": "結果が出なくても、目標があるから頑張れる。", "target_word": "頑張れる", "complexity_tier": "T3", "furigana": "結果[けっか]が出[で]なくても、目標[もくひょう]があるから頑張[がんば]れる。", "sentence_source": "generated"}, {"text": "志望校に入るため、兄は一年間頑張った。", "target_word": "頑張った", "complexity_tier": "T3", "furigana": "志望校[しぼうこう]に入[はい]るため、兄[あに]は一年間[いちねんかん]頑張[がんば]った。", "sentence_source": "generated"}, {"text": "マラソンで三時間を切るために、頑張って走り込んでいる。", "target_word": "頑張って", "complexity_tier": "T3", "furigana": "マラソンで三時間[さんじかん]を切[き]るために、頑張[がんば]って走[はし]り込[こ]んでいる。", "sentence_source": "generated"}, {"text": "頑張ったかいがあって、ついに資格を取ることができた。", "target_word": "頑張った", "complexity_tier": "T3", "furigana": "頑張[がんば]ったかいがあって、ついに資格[しかく]を取[と]ることができた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頑張る", "label": "基本形"}, {"form": "頑張ります", "label": "丁寧形"}, {"form": "頑張って", "label": "て形"}, {"form": "頑張った", "label": "過去形"}, {"form": "頑張れる", "label": "可能形"}, {"form": "頑張り続けた", "label": "継続の過去形"}, {"form": "頑張らない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "自分の目標のために、努力を続ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4aebd181-359a-45dc-80f8-127f2fbef7ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37349, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頑張って", "is_correct": true, "explanation": "て形で、「頑張っています」と続いて努力の継続を表す。"}, {"text": "頑張る", "is_correct": false, "explanation": "基本形は「頑張るいます」となり、「います」と続かない。"}, {"text": "頑張れ", "is_correct": false, "explanation": "命令形は「頑張れいます」となり、文として成り立たない。"}, {"text": "頑張り", "is_correct": false, "explanation": "連用形は「頑張りいます」となり、「います」と続かない。"}], "explanations": {"頑張って": "て形で、「頑張っています」と続いて努力の継続を表す。", "頑張る": "基本形は「頑張るいます」となり、「います」と続かない。", "頑張れ": "命令形は「頑張れいます」となり、文として成り立たない。", "頑張り": "連用形は「頑張りいます」となり、「います」と続かない。"}, "sentence_index": 0, "correct_answer": "頑張って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日は、頑張って雨を止めた。", "explanation": "ここは〈努力して実現させる〉の意味。雨は努力で止められるものではないので、頑張るとは合わない。"}, {"text": "うっかり頑張って、鍵を閉め忘れた。", "explanation": "ここは〈意図して努力する〉の意味。うっかりは意図せず行うことなので、目標に向けた努力の頑張るとは合わない。"}, {"text": "テストが近いので、頑張って寝坊した。", "explanation": "ここは〈努力して時間を守る〉の意味。寝坊は努力の結果ではないので、頑張るとは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37349, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頑張れる", "is_correct": true, "explanation": "可能形で、「目標があるから頑張れる」と続いて、努力できる状態を表す。"}, {"text": "頑張れない", "is_correct": false, "explanation": "可能形の否定で、「結果が出なくても、目標があるから頑張れない」は前後の論理が合わず文意が逆になる。"}, {"text": "頑張らない", "is_correct": false, "explanation": "否定形で、目標があるのに努力しないことになり、「頑張れる」の文意と逆になる。"}, {"text": "頑張り", "is_correct": false, "explanation": "連用形で、文を終えられず「目標があるから頑張り。」は不完全になる。"}], "explanations": {"頑張れる": "可能形で、「目標があるから頑張れる」と続いて、努力できる状態を表す。", "頑張れない": "可能形の否定で、「結果が出なくても、目標があるから頑張れない」は前後の論理が合わず文意が逆になる。", "頑張らない": "否定形で、目標があるのに努力しないことになり、「頑張れる」の文意と逆になる。", "頑張り": "連用形で、文を終えられず「目標があるから頑張り。」は不完全になる。"}, "sentence_index": 6, "correct_answer": "頑張れる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母の反対に負けず、頑張って家から出なかった。", "explanation": "ここは〈意地を張る〉の意味。頑張るは目標に向けた努力で、拒み続ける意味では使わないので合わない。"}, {"text": "この湯呑みは、頑張って四角くなった。", "explanation": "ここは〈努力して形を変える〉の意味。湯呑みは努力で形を変えられないので、頑張るとは合わない。"}, {"text": "この牛乳は、頑張って冷蔵庫の中で腐った。", "explanation": "ここは〈努力して状態を保つ〉の意味。牛乳が腐るのは努力で防げるものではないので、頑張るとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37349, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎晩遅くまで頑張りている。", "corrected_sentence": "毎晩遅くまで頑張っている。", "error_description": "「頑張っている」が正しい。「頑張りている」は連用形に「いる」が続く形として誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "頑張り", "is_correct": true, "explanation": "連用形で、「頑張り続けた」と続ける形に合う。"}, {"text": "頑張る", "is_correct": false, "explanation": "基本形は「頑張る続けた」とつながらず、続ける形にならない。"}, {"text": "頑張れ", "is_correct": false, "explanation": "命令形で、「頑張れ続けた」と続かず文が成り立たない。"}, {"text": "頑張れば", "is_correct": false, "explanation": "仮定形は「頑張れば続けた」と続かず、文が成り立たない。"}], "correct_form": "頑張り", "base_form": "頑張る", "form_label": "連用形", "sentence_index": 1, "explanations": {"頑張り": "連用形で、「頑張り続けた」と続ける形に合う。", "頑張る": "基本形は「頑張る続けた」とつながらず、続ける形にならない。", "頑張れ": "命令形で、「頑張れ続けた」と続かず文が成り立たない。", "頑張れば": "仮定形は「頑張れば続けた」と続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37349, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大学に合格するため、兄は一年間頑張り。", "corrected_sentence": "大学に合格するため、兄は一年間頑張った。", "error_description": "過去の努力の結果を示すには「頑張った」が必要。「頑張り」は連用形で、文を終えることができない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "頑張った", "is_correct": true, "explanation": "過去形で、志望校に向けて一年間努力したという過去の文に合う。"}, {"text": "頑張ろう", "is_correct": false, "explanation": "意志形で、過去に一年間努力した事実を述べる文と合わない。"}, {"text": "頑張らない", "is_correct": false, "explanation": "否定形で、努力しなかったことになり、合格に向けた過去の努力の文と逆になる。"}, {"text": "頑張ります", "is_correct": false, "explanation": "丁寧形で、普通体の過去の文に続かず、時制と文体が合わない。"}], "correct_form": "頑張った", "base_form": "頑張る", "form_label": "過去形", "sentence_index": 7, "explanations": {"頑張った": "過去形で、志望校に向けて一年間努力したという過去の文に合う。", "頑張ろう": "意志形で、過去に一年間努力した事実を述べる文と合わない。", "頑張らない": "否定形で、努力しなかったことになり、合格に向けた過去の努力の文と逆になる。", "頑張ります": "丁寧形で、普通体の過去の文に続かず、時制と文体が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79f8e74f-4175-487a-b2b6-8bd39861bdc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37350, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ラジオをオンにする」で、「する」の対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「ラジオがオンにする」では「する」の主語が不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「ラジオへオンにする」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「ラジオとオンにする」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「ラジオをオンにする」で、「する」の対象を表す。", "が": "「ラジオがオンにする」では「する」の主語が不自然。", "へ": "「ラジオへオンにする」では文が成り立たない。", "と": "「ラジオとオンにする」では文が成り立たない。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "オフ", "is_correct": true, "explanation": "入っている状態のオンに対し、切れているオフが対義語。"}, {"text": "ボタン", "is_correct": false, "explanation": "ボタンは操作する部品で、オンの対義語ではない。"}, {"text": "ランプ", "is_correct": false, "explanation": "ランプは明かりのことで、オンの対義語ではない。"}, {"text": "ケーブル", "is_correct": false, "explanation": "ケーブルは配線のことで、オンの対義語ではない。"}], "correct_answer": "オフ", "explanations": {"オフ": "入っている状態のオンに対し、切れているオフが対義語。", "ボタン": "ボタンは操作する部品で、オンの対義語ではない。", "ランプ": "ランプは明かりのことで、オンの対義語ではない。", "ケーブル": "ケーブルは配線のことで、オンの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37350, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「オンにすれば」で、状態の変化の結果を表す。"}, {"text": "を", "is_correct": false, "explanation": "「オンをすれば」では「する」の使い方が不自然。"}, {"text": "が", "is_correct": false, "explanation": "「オンがすれば」では文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「オンのすれば」では文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「オンにすれば」で、状態の変化の結果を表す。", "を": "「オンをすれば」では「する」の使い方が不自然。", "が": "「オンがすれば」では文が成り立たない。", "の": "「オンのすれば」では文が成り立たない。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "の": "possessive"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "オフ", "is_correct": true, "explanation": "入っている状態のオンに対し、切れているオフが対義語。"}, {"text": "パワー", "is_correct": false, "explanation": "パワーは力のことで、オンの対義語ではない。"}, {"text": "サイン", "is_correct": false, "explanation": "サインは合図のことで、オンの対義語ではない。"}, {"text": "メモリ", "is_correct": false, "explanation": "メモリは記憶領域のことで、オンの対義語ではない。"}], "correct_answer": "オフ", "explanations": {"オフ": "入っている状態のオンに対し、切れているオフが対義語。", "パワー": "パワーは力のことで、オンの対義語ではない。", "サイン": "サインは合図のことで、オンの対義語ではない。", "メモリ": "メモリは記憶領域のことで、オンの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37350, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「オン」は、スイッチが入っていることや、インターネットにつながっていることをあらわすことばです。", "primary_collocate": null, "pronunciation": "おん", "ipa": "oɴ", "syllable_count": 2, "sentences": [{"text": "電源はオンだ。", "target_word": "オン", "complexity_tier": "T1", "furigana": "電源[でんげん]はオンだ。", "sentence_source": "generated"}, {"text": "ラジオをオンにする。", "target_word": "オン", "complexity_tier": "T1", "furigana": "ラジオをオンにする。", "sentence_source": "generated"}, {"text": "パソコンがオンになっています。", "target_word": "オン", "complexity_tier": "T2", "furigana": "パソコンがオンになっています。", "sentence_source": "generated"}, {"text": "夜はスマホをオンにしません。", "target_word": "オン", "complexity_tier": "T2", "furigana": "夜[よる]はスマホをオンにしません。", "sentence_source": "generated"}, {"text": "スイッチがオンかどうか、見てください。", "target_word": "オン", "complexity_tier": "T3", "furigana": "スイッチがオンかどうか、見[み]てください。", "sentence_source": "generated"}, {"text": "友達とゲームをするため、通信をオンにした。", "target_word": "オン", "complexity_tier": "T3", "furigana": "友達[ともだち]とゲームをするため、通信[つうしん]をオンにした。", "sentence_source": "generated"}, {"text": "ライトをオンにしたまま、寝てしまった。", "target_word": "オン", "complexity_tier": "T3", "furigana": "ライトをオンにしたまま、寝[ね]てしまった。", "sentence_source": "generated"}, {"text": "設定をオンにすれば、通知が届くようになる。", "target_word": "オン", "complexity_tier": "T4", "furigana": "設定[せってい]をオンにすれば、通知[つうち]が届[とど]くようになる。", "sentence_source": "generated"}, {"text": "オンの状態では、バッテリーがすぐになくなってしまう。", "target_word": "オン", "complexity_tier": "T4", "furigana": "オンの状態[じょうたい]では、バッテリーがすぐになくなってしまう。", "sentence_source": "generated"}, {"text": "通信がオンになっているのに、なぜかインターネットにつながらない。", "target_word": "オン", "complexity_tier": "T5", "furigana": "通信[つうしん]がオンになっているのに、なぜかインターネットにつながらない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "オンライン", "label": "派生"}, {"form": "オンエア", "label": "派生"}, {"form": "オンタイム", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | スイッチが入っている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afb0b9dc-8502-47d9-83d8-0f94025ad970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37350, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "オン", "is_correct": true, "explanation": "「おん」と読む、聞こえた語そのもの。"}, {"text": "運", "is_correct": false, "explanation": "「うん」で、最初の音が「お」ではなく「う」。"}, {"text": "円", "is_correct": false, "explanation": "「えん」で、最初の音が「お」ではなく「え」。"}, {"text": "案", "is_correct": false, "explanation": "「あん」で、最初の音が「お」ではなく「あ」。"}, {"text": "缶", "is_correct": false, "explanation": "「かん」で、最初の音が「お」ではなく「か」。"}], "explanations": {"オン": "「おん」と読む、聞こえた語そのもの。", "運": "「うん」で、最初の音が「お」ではなく「う」。", "円": "「えん」で、最初の音が「お」ではなく「え」。", "案": "「あん」で、最初の音が「お」ではなく「あ」。", "缶": "「かん」で、最初の音が「お」ではなく「か」。"}, "sentence_index": null, "correct_answer": "オン"}, "level_3": {"options": [{"text": "オン", "is_correct": true, "explanation": "電源が入っている状態を表し、「電源はオンだ」が自然。"}, {"text": "犬", "is_correct": false, "explanation": "形は合うが意味が合わない。「電源は犬だ」では意味が通らない。"}, {"text": "海", "is_correct": false, "explanation": "形は合うが意味が合わない。「電源は海だ」では意味が通らない。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが意味が合わない。「電源は野菜だ」では意味が通らない。"}], "explanations": {"オン": "電源が入っている状態を表し、「電源はオンだ」が自然。", "犬": "形は合うが意味が合わない。「電源は犬だ」では意味が通らない。", "海": "形は合うが意味が合わない。「電源は海だ」では意味が通らない。", "野菜": "形は合うが意味が合わない。「電源は野菜だ」では意味が通らない。"}, "sentence_index": 0, "correct_answer": "オン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机をオンにして、きれいに拭いた。", "explanation": "「オン」はスイッチの状態なので、スイッチのない机には使えない。"}, {"text": "朝ごはんにオンを焼いて食べた。", "explanation": "「オン」は食べ物ではないので「焼く」の目的語にならない。"}, {"text": "兄はオンで学校まで走った。", "explanation": "「オン」は移動手段ではなく、「で」で手段を表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
