INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37351, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "オン", "is_correct": true, "explanation": "「おん」と読む、聞こえた語そのもの。"}, {"text": "親", "is_correct": false, "explanation": "「おや」で、最後の音が「ん」ではなく「や」。"}, {"text": "鬼", "is_correct": false, "explanation": "「おに」で、最後の音が「ん」ではなく「に」。"}, {"text": "斧", "is_correct": false, "explanation": "「おの」で、最後の音が「ん」ではなく「の」。"}, {"text": "帯", "is_correct": false, "explanation": "「おび」で、最後の音が「ん」ではなく「び」。"}], "explanations": {"オン": "「おん」と読む、聞こえた語そのもの。", "親": "「おや」で、最後の音が「ん」ではなく「や」。", "鬼": "「おに」で、最後の音が「ん」ではなく「に」。", "斧": "「おの」で、最後の音が「ん」ではなく「の」。", "帯": "「おび」で、最後の音が「ん」ではなく「び」。"}, "sentence_index": null, "correct_answer": "オン"}, "level_3": {"options": [{"text": "オン", "is_correct": true, "explanation": "マイクのスイッチを入れる意味で、「マイクをオンにして」が自然。"}, {"text": "雨", "is_correct": false, "explanation": "形は合うが意味が合わない。「マイクを雨にして」では意味が通らない。"}, {"text": "魚", "is_correct": false, "explanation": "形は合うが意味が合わない。「マイクを魚にして」では意味が通らない。"}, {"text": "山", "is_correct": false, "explanation": "形は合うが意味が合わない。「マイクを山にして」では意味が通らない。"}], "explanations": {"オン": "マイクのスイッチを入れる意味で、「マイクをオンにして」が自然。", "雨": "形は合うが意味が合わない。「マイクを雨にして」では意味が通らない。", "魚": "形は合うが意味が合わない。「マイクを魚にして」では意味が通らない。", "山": "形は合うが意味が合わない。「マイクを山にして」では意味が通らない。"}, "sentence_index": 6, "correct_answer": "オン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の夜、オンが空を飛んでいた。", "explanation": "「オン」は状態を表す語で、空を飛ぶ主体にはなれない。"}, {"text": "本をオンにして、図書館へ返しに行った。", "explanation": "「オン」は機器の状態なので、本を「オンにする」ことはできない。"}, {"text": "コンビニでオンを三本買って帰った。", "explanation": "「オン」は数えて買える物ではなく、状態を表す語である。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid =