INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37352, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "紙や地面、布などに引かれた、細くて長い線。", "primary_collocate": null, "pronunciation": "らいん", "ipa": "ɾaiɴ", "syllable_count": 3, "sentences": [{"text": "紙にラインを書く。", "target_word": "ライン", "complexity_tier": "T1", "furigana": "紙[かみ]にラインを書[か]く。", "sentence_source": "generated"}, {"text": "青いラインがきれいだ。", "target_word": "ライン", "complexity_tier": "T1", "furigana": "青[あお]いラインがきれいだ。", "sentence_source": "generated"}, {"text": "コートに細いラインが入っています。", "target_word": "ライン", "complexity_tier": "T2", "furigana": "コートに細[ほそ]いラインが入[はい]っています。", "sentence_source": "generated"}, {"text": "地面にラインを引きました。", "target_word": "ライン", "complexity_tier": "T2", "furigana": "地面[じめん]にラインを引[ひ]きました。", "sentence_source": "generated"}, {"text": "ラインに沿って、ゆっくり歩いていった。", "target_word": "ライン", "complexity_tier": "T3", "furigana": "ラインに沿[そ]って、ゆっくり歩[ある]いていった。", "sentence_source": "generated"}, {"text": "シャツの白いラインがかっこいい。", "target_word": "ライン", "complexity_tier": "T3", "furigana": "シャツの白[しろ]いラインがかっこいい。", "sentence_source": "generated"}, {"text": "二つの点をラインで結んでみよう。", "target_word": "ライン", "complexity_tier": "T3", "furigana": "二[ふた]つの点[てん]をラインで結[むす]んでみよう。", "sentence_source": "generated"}, {"text": "道路のラインが消えかけていて、運転しにくい。", "target_word": "ライン", "complexity_tier": "T4", "furigana": "道路[どうろ]のラインが消[き]えかけていて、運転[うんてん]しにくい。", "sentence_source": "generated"}, {"text": "ラインをまっすぐ引くために、定規を使うことにした。", "target_word": "ライン", "complexity_tier": "T4", "furigana": "ラインをまっすぐ引[ひ]くために、定規[じょうぎ]を使[つか]うことにした。", "sentence_source": "generated"}, {"text": "地図に書かれたラインをたどっていくと、小さな駅にたどり着いた。", "target_word": "ライン", "complexity_tier": "T5", "furigana": "地図[ちず]に書[か]かれたラインをたどっていくと、小[ちい]さな駅[えき]にたどり着[つ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ラインナップ", "label": "派生"}, {"form": "ライン引き", "label": "派生"}, {"form": "オンライン", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | つなぐ細長い線や道すじ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afb0b9dc-8502-47d9-83d8-0f94025ad970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37352, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ライン", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "サイン", "is_correct": false, "explanation": "ラ→サの一拍だけが違う別の語。"}, {"text": "パイン", "is_correct": false, "explanation": "ラ→パの一拍だけが違う別の語。"}, {"text": "ライス", "is_correct": false, "explanation": "ン→スの一拍だけが違う別の語。"}, {"text": "ライム", "is_correct": false, "explanation": "ン→ムの一拍だけが違う別の語。"}], "explanations": {"ライン": "見出し語そのもの。", "サイン": "ラ→サの一拍だけが違う別の語。", "パイン": "ラ→パの一拍だけが違う別の語。", "ライス": "ン→スの一拍だけが違う別の語。", "ライム": "ン→ムの一拍だけが違う別の語。"}, "sentence_index": null, "correct_answer": "ライン"}, "level_3": {"options": [{"text": "ライン", "is_correct": true, "explanation": "紙に書くことができる細長い線なので意味が合う。"}, {"text": "空気", "is_correct": false, "explanation": "形は合うが、紙に空気を書くという意味は合わない。"}, {"text": "におい", "is_correct": false, "explanation": "形は合うが、においは紙に書けるものではない。"}, {"text": "あくび", "is_correct": false, "explanation": "形は合うが、あくびを紙に書くという意味は通らない。"}], "explanations": {"ライン": "紙に書くことができる細長い線なので意味が合う。", "空気": "形は合うが、紙に空気を書くという意味は合わない。", "におい": "形は合うが、においは紙に書けるものではない。", "あくび": "形は合うが、あくびを紙に書くという意味は通らない。"}, "sentence_index": 0, "correct_answer": "ライン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ご飯に地面のラインを飲みました。", "explanation": "ラインは線や道すじで、飲む物ではない。"}, {"text": "地面にラインが笑いながら歩いていました。", "explanation": "ラインは生き物ではなく、「笑って歩く」の主語にならない。"}, {"text": "ラインを三人、公園で待っています。", "explanation": "ラインは人ではなく、「三人」と数えて待つことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37352, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "ライン", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "ワイン", "is_correct": false, "explanation": "ラ→ワの一拍だけが違う別の語。"}, {"text": "ライト", "is_correct": false, "explanation": "ン→トの一拍だけが違う別の語。"}, {"text": "ライブ", "is_correct": false, "explanation": "ン→ブの一拍だけが違う別の語。"}, {"text": "ライフ", "is_correct": false, "explanation": "ン→フの一拍だけが違う別の語。"}], "explanations": {"ライン": "見出し語そのもの。", "ワイン": "ラ→ワの一拍だけが違う別の語。", "ライト": "ン→トの一拍だけが違う別の語。", "ライブ": "ン→ブの一拍だけが違う別の語。", "ライフ": "ン→フの一拍だけが違う別の語。"}, "sentence_index": null, "correct_answer": "ライン"}, "level_3": {"options": [{"text": "ライン", "is_correct": true, "explanation": "二つの点を結ぶ細長い線なので意味が合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、点を天気で結ぶという意味は合わない。"}, {"text": "悲しみ", "is_correct": false, "explanation": "形は合うが、点を悲しみで結ぶ意味は不自然。"}, {"text": "牛乳", "is_correct": false, "explanation": "形は合うが、点を牛乳で結ぶ意味は合わない。"}], "explanations": {"ライン": "二つの点を結ぶ細長い線なので意味が合う。", "天気": "形は合うが、点を天気で結ぶという意味は合わない。", "悲しみ": "形は合うが、点を悲しみで結ぶ意味は不自然。", "牛乳": "形は合うが、点を牛乳で結ぶ意味は合わない。"}, "sentence_index": 6, "correct_answer": "ライン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地図に書かれたラインを食べていくと、小さな駅にたどり着いた。", "explanation": "ラインは地図上の線で、食べる物ではない。"}, {"text": "地図に書かれたラインが怒っていくと、小さな駅にたどり着いた。", "explanation": "ラインは感情を持たず、「怒る」の主語にならない。"}, {"text": "地図に書かれたラインを着ていくと、小さな駅にたどり着いた。", "explanation": "ラインは衣服ではなく、「着る」とは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_war