INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37354, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "たくさんの人が、だれかが一番になるために、ほかの人よりがんばること。", "primary_collocate": null, "pronunciation": "きょうそう", "ipa": "kjoːsoː", "syllable_count": 4, "sentences": [{"text": "運動会の競争で、私は二位になりました。", "target_word": "競争", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の競争[きょうそう]で、私[わたし]は二位[にい]になりました。", "sentence_source": "generated"}, {"text": "子どもたちは、だれが速いか競争して走っています。", "target_word": "競争", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、だれが速[はや]いか競争[きょうそう]して走[はし]っています。", "sentence_source": "generated"}, {"text": "一番になりたくて、友だちと勉強の競争をしました。", "target_word": "競争", "complexity_tier": "T3", "furigana": "一番[いちばん]になりたくて、友[とも]だちと勉強[べんきょう]の競争[きょうそう]をしました。", "sentence_source": "generated"}, {"text": "入学試験は競争が激しいので、毎日遅くまで勉強します。", "target_word": "競争", "complexity_tier": "T3", "furigana": "入学試験[にゅうがくしけん]は競争[きょうそう]が激[はげ]しいので、毎日[まいにち]遅[おそ]くまで勉強[べんきょう]します。", "sentence_source": "generated"}, {"text": "兄とはよく競争して、どちらが先に食べ終わるか決めます。", "target_word": "競争", "complexity_tier": "T3", "furigana": "兄[あに]とはよく競争[きょうそう]して、どちらが先[さき]に食[た]べ終[お]わるか決[き]めます。", "sentence_source": "generated"}, {"text": "競争に負けても、最後まであきらめないでください。", "target_word": "競争", "complexity_tier": "T3", "furigana": "競争[きょうそう]に負[ま]けても、最後[さいご]まであきらめないでください。", "sentence_source": "generated"}, {"text": "町の花屋さんは、新しい店との競争に勝つために、安く売っています。", "target_word": "競争", "complexity_tier": "T3", "furigana": "町[まち]の花屋[はなや]さんは、新[あたら]しい店[みせ]との競争[きょうそう]に勝[か]つために、安[やす]く売[う]っています。", "sentence_source": "generated"}, {"text": "動物の世界でも、食べ物をめぐる競争があります。", "target_word": "競争", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の世界[せかい]でも、食[た]べ物[もの]をめぐる競争[きょうそう]があります。", "sentence_source": "generated"}, {"text": "人気のある仕事は、応募する人が多く、競争が厳しいです。", "target_word": "競争", "complexity_tier": "T3", "furigana": "人気[にんき]のある仕事[しごと]は、応募[おうぼ]する人[ひと]が多[おお]く、競争[きょうそう]が厳[きび]しいです。", "sentence_source": "generated"}, {"text": "競争ばかりでは疲れるので、ときには仲間と楽しく走りたいです。", "target_word": "競争", "complexity_tier": "T3", "furigana": "競争[きょうそう]ばかりでは疲[つか]れるので、ときには仲間[なかま]と楽[たの]しく走[はし]りたいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "競争", "label": "基本形"}, {"form": "競争する", "label": "サ変動詞形"}, {"form": "競争した", "label": "過去形"}], "register": "丁寧", "sense_fingerprint": "一番になるために他の人と速さ・成績などを争うこと(運動会・勉強・試験など身近な場面)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1bc596f-8b8d-4af6-bf10-97dcd2d33ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37354, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "競争", "is_correct": true, "explanation": "「運動会の〜で、私は二位になりました」に入り、一番を争う行事の場面を表す。"}, {"text": "天気", "is_correct": false, "explanation": "運動会の天気で順位が決まることはなく、「二位になりました」とつながらない。"}, {"text": "給食", "is_correct": false, "explanation": "給食は順位を争う行事ではないので、「二位になりました」と意味が合わない。"}, {"text": "準備", "is_correct": false, "explanation": "準備では順位は決まらないので、「二位になりました」という結果と合わない。"}], "explanations": {"競争": "「運動会の〜で、私は二位になりました」に入り、一番を争う行事の場面を表す。", "天気": "運動会の天気で順位が決まることはなく、「二位になりました」とつながらない。", "給食": "給食は順位を争う行事ではないので、「二位になりました」と意味が合わない。", "準備": "準備では順位は決まらないので、「二位になりました」という結果と合わない。"}, "sentence_index": 0, "correct_answer": "競争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "けんかの競争で、二人はもう口をきかなくなりました。", "explanation": "ここは〈争い〉の意味。競争は目標に向けて努力し、優劣を競うことで、けんかや言い争いには使わない。"}, {"text": "ひとりで毎日の競争を続けて、ピアノが少しずつ上手になりました。", "explanation": "ここは〈努力〉の意味。競争は相手がいてこそ成り立つので、ひとりの練習には使わない。"}, {"text": "三人で協力して競争し、重い荷物を運び終えました。", "explanation": "ここは〈協力〉の意味。競争は互いに勝とうとすることなので、協力して同じ仕事をする場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37354, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "競争", "is_correct": true, "explanation": "「新しい店との〜に勝つために」に入り、店どうしが勝ちを争う意味になる。"}, {"text": "注文", "is_correct": false, "explanation": "店との注文に勝つという言い方は成り立たず、文の意味が通らない。"}, {"text": "掃除", "is_correct": false, "explanation": "店との掃除に勝つという意味にはならず、文が不自然になる。"}, {"text": "体温", "is_correct": false, "explanation": "体温に勝つという対象にはならず、店の売り方の文脈に合わない。"}], "explanations": {"競争": "「新しい店との〜に勝つために」に入り、店どうしが勝ちを争う意味になる。", "注文": "店との注文に勝つという言い方は成り立たず、文の意味が通らない。", "掃除": "店との掃除に勝つという意味にはならず、文が不自然になる。", "体温": "体温に勝つという対象にはならず、店の売り方の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "競争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友だちと競争して、問題の解き方を教え合いました。", "explanation": "ここは〈協力〉の意味。解き方を教え合うのは協力で、相手に勝とうとする競争とは合わない。"}, {"text": "競争が始まり、町は焼けてしまいました。", "explanation": "ここは〈戦い〉の意味。町を焼くような破壊は戦いで、勝ちを目指す努力の競争とは合わない。"}, {"text": "仕事を競争すると、一人の負担が減ります。", "explanation": "ここは〈分担〉の意味。仕事を分けて負担を減らすのは分担で、競争は勝ちを争うことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37354, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "テストの競争を、私は一番になりました。", "corrected_sentence": "テストの競争で、私は一番になりました。", "error_description": "「で」が正しい。「競争で一番になる」は場面を表す「で」が必要で、「を」にすると「競争を一番になる」となり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37354, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ライバル店との競争を、値段が下がりました。", "corrected_sentence": "ライバル店との競争で、値段が下がりました。", "error_description": "「で」が正しい。「下がる」は自動詞なので「を」の目的語は取らず、きっかけや場面を示す「で」が入る。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
