INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37355, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "複数の人が同じ目標に向かって、相手より優れた結果を出そうとすること。", "primary_collocate": null, "pronunciation": "きょうそう", "ipa": "kjoːsoː", "syllable_count": 4, "sentences": [{"text": "三つの会社が、同じ契約を取ろうと競争しています。", "target_word": "競争", "complexity_tier": "T3", "furigana": "三[みっ]つの会社[かいしゃ]が、同[おな]じ契約[けいやく]を取[と]ろうと競争[きょうそう]しています。", "sentence_source": "generated"}, {"text": "商品の質を上げるために、各社が競争しています。", "target_word": "競争", "complexity_tier": "T3", "furigana": "商品[しょうひん]の質[しつ]を上[あ]げるために、各社[かくしゃ]が競争[きょうそう]しています。", "sentence_source": "generated"}, {"text": "市場での競争が厳しくなり、価格が下がりました。", "target_word": "競争", "complexity_tier": "T3", "furigana": "市場[しじょう]での競争[きょうそう]が厳[きび]しくなり、価格[かかく]が下[さ]がりました。", "sentence_source": "generated"}, {"text": "健全な競争は、技術の進歩につながります。", "target_word": "競争", "complexity_tier": "T3", "furigana": "健全[けんぜん]な競争[きょうそう]は、技術[ぎじゅつ]の進歩[しんぽ]につながります。", "sentence_source": "generated"}, {"text": "二人の研究者は、先に新しい薬を完成させようと競争しました。", "target_word": "競争", "complexity_tier": "T3", "furigana": "二人[ふたり]の研究者[けんきゅうしゃ]は、先[さき]に新[あたら]しい薬[くすり]を完成[かんせい]させようと競争[きょうそう]しました。", "sentence_source": "generated"}, {"text": "他社との競争に勝つため、新しい機械を入れました。", "target_word": "競争", "complexity_tier": "T3", "furigana": "他社[たしゃ]との競争[きょうそう]に勝[か]つため、新[あたら]しい機械[きかい]を入[い]れました。", "sentence_source": "generated"}, {"text": "選手たちは、優勝をめざして競争を続けています。", "target_word": "競争", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは、優勝[ゆうしょう]をめざして競争[きょうそう]を続[つづ]けています。", "sentence_source": "generated"}, {"text": "同じ地域の会社どうしが競争すると、サービスがよくなります。", "target_word": "競争", "complexity_tier": "T3", "furigana": "同[おな]じ地域[ちいき]の会社[かいしゃ]どうしが競争[きょうそう]すると、サービスがよくなります。", "sentence_source": "generated"}, {"text": "航空会社の競争は、季節によって厳しさが変わります。", "target_word": "競争", "complexity_tier": "T3", "furigana": "航空会社[こうくうがいしゃ]の競争[きょうそう]は、季節[きせつ]によって厳[きび]しさが変[か]わります。", "sentence_source": "generated"}, {"text": "国どうしが技術で競争すると、新しい発明が生まれやすくなります。", "target_word": "競争", "complexity_tier": "T3", "furigana": "国[くに]どうしが技術[ぎじゅつ]で競争[きょうそう]すると、新[あたら]しい発明[はつめい]が生[う]まれやすくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "競争", "label": "基本形"}, {"form": "競争する", "label": "サ変動詞形"}, {"form": "競争した", "label": "過去形"}], "register": "丁寧", "sense_fingerprint": "企業・研究者・国などが同じ目標に向かい、相手より優れた成果や結果を出そうと争うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1bc596f-8b8d-4af6-bf10-97dcd2d33ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37355, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "競争", "is_correct": true, "explanation": "「同じ契約を取ろうと〜しています」に入り、会社どうしが相手より優れた結果を出そうとする意味になる。"}, {"text": "天気", "is_correct": false, "explanation": "「天気しています」は成り立たず、契約を取ろうとする動作にならない。"}, {"text": "掃除", "is_correct": false, "explanation": "「掃除しています」は契約を取ろうとする動作と結びつかず、文が通らない。"}, {"text": "給食", "is_correct": false, "explanation": "「給食しています」は契約の文脈に合わず、意味が通らない。"}], "explanations": {"競争": "「同じ契約を取ろうと〜しています」に入り、会社どうしが相手より優れた結果を出そうとする意味になる。", "天気": "「天気しています」は成り立たず、契約を取ろうとする動作にならない。", "掃除": "「掃除しています」は契約を取ろうとする動作と結びつかず、文が通らない。", "給食": "「給食しています」は契約の文脈に合わず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "競争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの会社は競争して、新しい商品を一緒に作ることになりました。", "explanation": "ここは〈提携〉の意味。一緒に作る関係は提携と言い、互いに勝とうとする競争とは合わない。"}, {"text": "二人の研究者は競争して、一つの論文を書き上げました。", "explanation": "ここは〈共同〉の意味。成果を共に作るのは共同で、競争は相手より優れようとすることを指す。"}, {"text": "各社が仕事を分担して、競争で商品を作っています。", "explanation": "ここは〈分担〉の意味。役割を分けて進めるのは分担で、競争は優劣を争う関係を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37355, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "競争", "is_correct": true, "explanation": "「優勝をめざして〜を続けています」に入り、選手が相手と勝ちを争う意味になる。"}, {"text": "誤字", "is_correct": false, "explanation": "「誤字を続けています」は意味が通らず、優勝をめざす文脈に合わない。"}, {"text": "切符", "is_correct": false, "explanation": "「切符を続けています」は成り立たず、優勝をめざす行動にならない。"}, {"text": "体温", "is_correct": false, "explanation": "「体温を続けています」は不自然で、優勝をめざす文脈と合わない。"}], "explanations": {"競争": "「優勝をめざして〜を続けています」に入り、選手が相手と勝ちを争う意味になる。", "誤字": "「誤字を続けています」は意味が通らず、優勝をめざす文脈に合わない。", "切符": "「切符を続けています」は成り立たず、優勝をめざす行動にならない。", "体温": "「体温を続けています」は不自然で、優勝をめざす文脈と合わない。"}, "sentence_index": 6, "correct_answer": "競争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週、この土地は競争にかけられます。", "explanation": "ここは〈競売〉の意味。売り手が買い手を競わせて売る手続きは競売で、競争とは言い換えられない。"}, {"text": "家族は互いに競争して、生活を支え合っています。", "explanation": "ここは〈支え合い〉の意味。助け合う関係は支え合いで、相手に勝とうとする競争とは両立しない。"}, {"text": "研究者どうしが競争して、新しい薬の問題を相談しました。", "explanation": "ここは〈相談〉の意味。問題を話し合って解決するのは相談で、競争は相手に勝とうとすることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37355, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい薬の競争を、二社が勝ちました。", "corrected_sentence": "新しい薬の競争に、二社が勝ちました。", "error_description": "「に」が正しい。「競争に勝つ」の「に」が標準の形で、「を」にすると「競争を勝つ」となり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37355, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国どうしの競争を、新しい技術を生み出しました。", "corrected_sentence": "国どうしの競争が、新しい技術を生み出しました。", "error_description": "「が」が正しい。文の主語は「競争が」で示す。「を」にすると「競争を」が目的語になり、後の「を」と重なって文が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37356, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「はっきりさせる」の目的語を示す「を」で、「この会議の目的を」と続いて自然になる。"}, {"text": "が", "is_correct": false, "explanation": "「はっきりさせる」は他動詞なので、目的語には「を」が必要で「が」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「はっきりさせる」の目的語は「を」で示すため、「に」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すので、「はっきりさせる」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「はっきりさせる」の目的語を示す「を」で、「この会議の目的を」と続いて自然になる。", "が": "「はっきりさせる」は他動詞なので、目的語には「を」が必要で「が」は合わない。", "に": "「はっきりさせる」の目的語は「を」で示すため、「に」では文が成り立たない。", "で": "「で」は手段や場所を表すので、「はっきりさせる」の目的語にはならない。"}, "error_tags": {"が": "主格の誤用", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37356, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37356, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "やりたいことや、めざすこと。", "primary_collocate": null, "pronunciation": "もくてき", "ipa": "mokɯteki", "syllable_count": 4, "sentences": [{"text": "旅行の目的は、友だちに会うことです。", "target_word": "目的", "complexity_tier": "T3", "furigana": "旅行[りょこう]の目的[もくてき]は、友[とも]だちに会[あ]うことです。", "sentence_source": "generated"}, {"text": "この会議の目的をはっきりさせてから、話を始めましょう。", "target_word": "目的", "complexity_tier": "T3", "furigana": "この会議[かいぎ]の目的[もくてき]をはっきりさせてから、話[はなし]を始[はじ]めましょう。", "sentence_source": "generated"}, {"text": "目的がないまま勉強しても、続けるのはむずかしいです。", "target_word": "目的", "complexity_tier": "T3", "furigana": "目的[もくてき]がないまま勉強[べんきょう]しても、続[つづ]けるのはむずかしいです。", "sentence_source": "generated"}, {"text": "彼は日本語を学ぶ目的で、東京に来ました。", "target_word": "目的", "complexity_tier": "T3", "furigana": "彼[かれ]は日本語[にほんご]を学[まな]ぶ目的[もくてき]で、東京[とうきょう]に来[き]ました。", "sentence_source": "generated"}, {"text": "私たちは同じ目的のために、毎日いっしょに練習しています。", "target_word": "目的", "complexity_tier": "T3", "furigana": "私[わたし]たちは同[おな]じ目的[もくてき]のために、毎日[まいにち]いっしょに練習[れんしゅう]しています。", "sentence_source": "generated"}, {"text": "何の目的でこのアプリを作ったのか、説明してください。", "target_word": "目的", "complexity_tier": "T3", "furigana": "何[なん]の目的[もくてき]でこのアプリを作[つく]ったのか、説明[せつめい]してください。", "sentence_source": "generated"}, {"text": "目的を達成するまで、あきらめないつもりです。", "target_word": "目的", "complexity_tier": "T3", "furigana": "目的[もくてき]を達成[たっせい]するまで、あきらめないつもりです。", "sentence_source": "generated"}, {"text": "健康が目的なら、毎日少し歩くだけでも十分です。", "target_word": "目的", "complexity_tier": "T3", "furigana": "健康[けんこう]が目的[もくてき]なら、毎日[まいにち]少[すこ]し歩[ある]くだけでも十分[じゅうぶん]です。", "sentence_source": "generated"}, {"text": "買い物ではなく、写真をとる目的で町へ行きました。", "target_word": "目的", "complexity_tier": "T3", "furigana": "買[か]い物[もの]ではなく、写真[しゃしん]をとる目的[もくてき]で町[まち]へ行[い]きました。", "sentence_source": "generated"}, {"text": "目的は同じでも、人によってやり方はちがいます。", "target_word": "目的", "complexity_tier": "T3", "furigana": "目的[もくてき]は同[おな]じでも、人[ひと]によってやり方[かた]はちがいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "目的", "label": "base"}, {"form": "目的で", "label": "with particle で (for the purpose of)"}, {"form": "目的の", "label": "attributive with の"}], "register": "neutral", "sense_fingerprint": "purpose or goal that a person aims at; the thing one wants to achieve by an action", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1bc596f-8b8d-4af6-bf10-97dcd2d33ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37356, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目的", "is_correct": true, "explanation": "「旅行の〜は、友だちに会うことです」に入り、そこへ行く理由や狙いを表す。"}, {"text": "天気", "is_correct": false, "explanation": "「旅行の天気は友だちに会うことです」は意味が通らず、文の主語として成り立たない。"}, {"text": "給食", "is_correct": false, "explanation": "「旅行の給食」は旅行の中身として成り立たず、「友だちに会うこと」とも合わない。"}, {"text": "準備", "is_correct": false, "explanation": "「旅行の準備は友だちに会うことです」は、準備の内容として意味が通らない。"}], "explanations": {"目的": "「旅行の〜は、友だちに会うことです」に入り、そこへ行く理由や狙いを表す。", "天気": "「旅行の天気は友だちに会うことです」は意味が通らず、文の主語として成り立たない。", "給食": "「旅行の給食」は旅行の中身として成り立たず、「友だちに会うこと」とも合わない。", "準備": "「旅行の準備は友だちに会うことです」は、準備の内容として意味が通らない。"}, "sentence_index": 0, "correct_answer": "目的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅行の目的は、とても楽しかったです。", "explanation": "ここは〈感想〉の意味。楽しかったという気持ちは感想で、目的はこれからめざすことを表す。"}, {"text": "遅れた目的は、電車が止まったからです。", "explanation": "ここは〈理由〉の意味。遅れた原因は理由で、目的は達成しようとすることを指す。"}, {"text": "この実験の目的は、三十人の参加者でした。", "explanation": "ここは〈人数〉の意味。参加者の数は人数で、目的はめざすことを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37356, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目的", "is_correct": true, "explanation": "「〜を達成するまで」に入り、達成すべき狙いを表す。"}, {"text": "切符", "is_correct": false, "explanation": "切符は達成の対象にならず、「〜を達成するまで」と合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除を達成するという言い方は不自然で、文の意味が通らない。"}, {"text": "体温", "is_correct": false, "explanation": "体温を達成するという対象にはならず、文が成り立たない。"}], "explanations": {"目的": "「〜を達成するまで」に入り、達成すべき狙いを表す。", "切符": "切符は達成の対象にならず、「〜を達成するまで」と合わない。", "掃除": "掃除を達成するという言い方は不自然で、文の意味が通らない。", "体温": "体温を達成するという対象にはならず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "目的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車は、東京に行くための目的です。", "explanation": "ここは〈手段〉の意味。電車は目的を実現する方法なので手段で、目的は何をめざすかを表す。"}, {"text": "レポートの目的は、来週の金曜日までです。", "explanation": "ここは〈期限〉の意味。締め切りの日は期限で、目的は達成しようとする内容を指す。"}, {"text": "勉強の目的は、部屋の中の机でした。", "explanation": "ここは〈場所〉の意味。机は置かれた場所で、目的はめざすことを表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37356, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究の目的が、先生に説明してください。", "corrected_sentence": "研究の目的を、先生に説明してください。", "error_description": "「を」が正しい。「説明する」は目的語を「を」で示すので、「が」にすると文の形が合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37356, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この実験の目的に、熱の変化を調べることです。", "corrected_sentence": "この実験の目的は、熱の変化を調べることです。", "error_description": "「は」が正しい。「目的は〜ことです」と主題を示す「は」が必要で、「に」にすると「目的に」が述語と合わず文が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37358, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "を", "is_correct": false, "explanation": "「多い」は形容詞で目的語の「を」を取らないので、ここでは入らない。"}, {"text": "が", "is_correct": true, "explanation": "「プレーヤーが多いほど」と主語を示す「が」で、ほどによる比例の文として自然に続く。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示す。「プレーヤーに多い」は不自然で、主語の位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。「プレーヤーで多い」と続かないので合わない。"}], "correct_answer": "が", "explanations": {"を": "「多い」は形容詞で目的語の「を」を取らないので、ここでは入らない。", "が": "「プレーヤーが多いほど」と主語を示す「が」で、ほどによる比例の文として自然に続く。", "に": "「に」は相手や場所を示す。「プレーヤーに多い」は不自然で、主語の位置には合わない。", "で": "「で」は場所や手段を示す。「プレーヤーで多い」と続かないので合わない。"}, "error_tags": {"を": "目的語", "に": "相手・場所", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37358, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "が", "is_correct": false, "explanation": "「が」を入れると「初めてのプレーヤーがも」となり、「でも」の形が作れず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「プレーヤーを遊べる」は人を遊ぶ対象にできず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。「プレーヤーの〜でも」の形は文の骨組みに合わず不自然。"}, {"text": "で", "is_correct": true, "explanation": "「初めてのプレーヤーでも」の「で」。「初心者でも」の意味で、自然に続く。"}], "correct_answer": "で", "explanations": {"が": "「が」を入れると「初めてのプレーヤーがも」となり、「でも」の形が作れず不自然。", "を": "「を」は目的語を示すが、「プレーヤーを遊べる」は人を遊ぶ対象にできず不自然。", "の": "「の」は名詞をつなぐ。「プレーヤーの〜でも」の形は文の骨組みに合わず不自然。", "で": "「初めてのプレーヤーでも」の「で」。「初心者でも」の意味で、自然に続く。"}, "error_tags": {"が": "主語", "を": "目的語", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37358, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ゲームをする人", "primary_collocate": null, "pronunciation": "ぷれーやー", "ipa": "pɯɾeːjaː", "syllable_count": 5, "sentences": [{"text": "このゲームは、四人のプレーヤーで遊びます。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "このゲームは、四人[よにん]のプレーヤーで遊[あそ]びます。", "sentence_source": "generated"}, {"text": "プレーヤーが多いほど、ゲームは楽しくなる。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "プレーヤーが多[おお]いほど、ゲームは楽[たの]しくなる。", "sentence_source": "generated"}, {"text": "新しいプレーヤーに、ルールを教えてあげた。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "新[あたら]しいプレーヤーに、ルールを教[おし]えてあげた。", "sentence_source": "generated"}, {"text": "強いプレーヤーは、負けても落ち着いている。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "強[つよ]いプレーヤーは、負[ま]けても落[お]ち着[つ]いている。", "sentence_source": "generated"}, {"text": "私はカードゲームのプレーヤーとして大会に出た。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "私[わたし]はカードゲームのプレーヤーとして大会[たいかい]に出[で]た。", "sentence_source": "generated"}, {"text": "プレーヤーは順番にさいころをふります。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "プレーヤーは順番[じゅんばん]にさいころをふります。", "sentence_source": "generated"}, {"text": "このオンラインゲームには、世界中のプレーヤーがいる。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "このオンラインゲームには、世界中[せかいじゅう]のプレーヤーがいる。", "sentence_source": "generated"}, {"text": "初めてのプレーヤーでも、すぐに遊べる。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "初[はじ]めてのプレーヤーでも、すぐに遊[あそ]べる。", "sentence_source": "generated"}, {"text": "一人のプレーヤーが遅れたので、ゲームが始まらなかった。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "一人[ひとり]のプレーヤーが遅[おく]れたので、ゲームが始[はじ]まらなかった。", "sentence_source": "generated"}, {"text": "ゲームが終わると、プレーヤーたちは握手をした。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "ゲームが終[お]わると、プレーヤーたちは握手[あくしゅ]をした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プレーヤー", "label": "基本形"}], "register": "口語", "sense_fingerprint": "ゲームを遊ぶ人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ecbfbe-96fb-4154-838a-29e711cd0c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37358, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "審判", "is_correct": false, "explanation": "審判は試合を裁く人で、ゲームを遊ぶ参加者ではない。「四人の審判で遊ぶ」は意味が通らない。"}, {"text": "プレーヤー", "is_correct": true, "explanation": "ゲームを遊ぶ参加者を指し、「四人のプレーヤーで遊びます」と自然に続く。"}, {"text": "コーチ", "is_correct": false, "explanation": "コーチは選手を指導する人で、ゲームに参加して遊ぶ人ではないので空欄に入らない。"}, {"text": "ルール", "is_correct": false, "explanation": "ルールは決まりごとで人ではない。「四人のルールで遊びます」は人数の文脈に合わない。"}], "explanations": {"審判": "審判は試合を裁く人で、ゲームを遊ぶ参加者ではない。「四人の審判で遊ぶ」は意味が通らない。", "プレーヤー": "ゲームを遊ぶ参加者を指し、「四人のプレーヤーで遊びます」と自然に続く。", "コーチ": "コーチは選手を指導する人で、ゲームに参加して遊ぶ人ではないので空欄に入らない。", "ルール": "ルールは決まりごとで人ではない。「四人のルールで遊びます」は人数の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "プレーヤー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新人のプレーヤーは、今日の出来事を記事にまとめた。", "explanation": "ここは〈記者〉の意味。記事を書く人はゲームをする人ではないので、プレーヤーとは言わない。"}, {"text": "この料理アプリのプレーヤーは、毎月何万人も増えている。", "explanation": "ここは〈ユーザー〉の意味。アプリの利用者はゲームをする人ではないので、プレーヤーとは言わない。"}, {"text": "このロボットのプレーヤーは、部品を一つずつ溶接して組み立てた。", "explanation": "ここは〈製作者〉の意味。ロボットを組み立てる人はゲームをする人ではないので、プレーヤーとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37358, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "さいころ", "is_correct": false, "explanation": "ゲームで使う道具で人ではないので、「世界中のさいころがいる」と人の存在を示す文には合わない。"}, {"text": "プレーヤー", "is_correct": true, "explanation": "オンラインゲームに参加して遊ぶ人を指し、「世界中のプレーヤーがいる」と自然に続く。"}, {"text": "ボール", "is_correct": false, "explanation": "ゲームで使う道具で人ではないので、「世界中のボールがいる」は人の存在を示す文に合わない。"}, {"text": "カード", "is_correct": false, "explanation": "カードゲームの道具で人ではないので、「世界中のカードがいる」は人の存在を示す文に合わない。"}], "explanations": {"さいころ": "ゲームで使う道具で人ではないので、「世界中のさいころがいる」と人の存在を示す文には合わない。", "プレーヤー": "オンラインゲームに参加して遊ぶ人を指し、「世界中のプレーヤーがいる」と自然に続く。", "ボール": "ゲームで使う道具で人ではないので、「世界中のボールがいる」は人の存在を示す文に合わない。", "カード": "カードゲームの道具で人ではないので、「世界中のカードがいる」は人の存在を示す文に合わない。"}, "sentence_index": 6, "correct_answer": "プレーヤー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "病院のプレーヤーは、患者の熱を測って薬を出した。", "explanation": "ここは〈医師〉の意味。患者を診て薬を出す人はゲームをする人ではないので、プレーヤーとは言わない。"}, {"text": "この番組のプレーヤーは、毎週何万人も増えている。", "explanation": "ここは〈視聴者〉の意味。番組を見る人はゲームをする人ではないので、プレーヤーとは言わない。"}, {"text": "この店のプレーヤーは、レジで代金を受け取った。", "explanation": "ここは〈店員〉の意味。レジで代金を受け取る人はゲームをする人ではないので、プレーヤーとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37358, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このカードゲームは、三人のプレーヤーを遊びます。", "corrected_sentence": "このカードゲームは、三人のプレーヤーで遊びます。", "error_description": "「遊ぶ」は手段の「で」をとる。「プレーヤーを」は誤りで、「プレーヤーで」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37358, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あのプレーヤーを、ゲームに慣れるのが早い。", "corrected_sentence": "あのプレーヤーは、ゲームに慣れるのが早い。", "error_description": "「慣れる」は目的語を取らないので「を」は誤り。主題を示す「は」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37359, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "を", "is_correct": false, "explanation": "「集まる」は目的語を取らないので、「を」は入らない。"}, {"text": "が", "is_correct": true, "explanation": "「プレーヤーが全員集まった」と主語を示す「が」で、自然に続く。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示す。「プレーヤーで全員集まった」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「プレーヤーへ集まった」は不自然で主語の位置に合わない。"}], "correct_answer": "が", "explanations": {"を": "「集まる」は目的語を取らないので、「を」は入らない。", "が": "「プレーヤーが全員集まった」と主語を示す「が」で、自然に続く。", "で": "「で」は手段を示す。「プレーヤーで全員集まった」は意味が通らない。", "へ": "「へ」は方向を示すが、「プレーヤーへ集まった」は不自然で主語の位置に合わない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37359, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37359, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ゲームやスポーツなどで、参加して活動する人。", "primary_collocate": null, "pronunciation": "ぷれーやー", "ipa": "pɯɾeːjaː", "syllable_count": 5, "sentences": [{"text": "彼はサッカーチームの中心的なプレーヤーだ。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "彼[かれ]はサッカーチームの中心的[ちゅうしんてき]なプレーヤーだ。", "sentence_source": "generated"}, {"text": "試合の前に、プレーヤーが全員集まった。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]に、プレーヤーが全員[ぜんいん]集[あつ]まった。", "sentence_source": "generated"}, {"text": "世界で有名なテニスのプレーヤーが、今年の大会に出場する。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "世界[せかい]で有名[ゆうめい]なテニスのプレーヤーが、今年[ことし]の大会[たいかい]に出場[しゅつじょう]する。", "sentence_source": "generated"}, {"text": "バスケットボールは、五人のプレーヤーで戦う。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "バスケットボールは、五人[ごにん]のプレーヤーで戦[たたか]う。", "sentence_source": "generated"}, {"text": "けがをしたプレーヤーは、試合を休んだ。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "けがをしたプレーヤーは、試合[しあい]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "彼は走るのが速く、チームで一番のプレーヤーだ。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "彼[かれ]は走[はし]るのが速[はや]く、チームで一番[いちばん]のプレーヤーだ。", "sentence_source": "generated"}, {"text": "監督は、若いプレーヤーを試合に出した。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "監督[かんとく]は、若[わか]いプレーヤーを試合[しあい]に出[だ]した。", "sentence_source": "generated"}, {"text": "プレーヤーたちは、毎朝グラウンドで練習している。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "プレーヤーたちは、毎朝[まいあさ]グラウンドで練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "野球のプレーヤーには、体力が必要だ。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "野球[やきゅう]のプレーヤーには、体力[たいりょく]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "優勝したあと、プレーヤーは笑顔で手をふった。", "target_word": "プレーヤー", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]したあと、プレーヤーは笑顔[えがお]で手[て]をふった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プレーヤー", "label": "基本形"}], "register": "中立", "sense_fingerprint": "スポーツや試合に参加する競技者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ecbfbe-96fb-4154-838a-29e711cd0c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37359, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ボール", "is_correct": false, "explanation": "競技で使う道具で人ではないので、「中心的なボールだ」と人を評する文には合わない。"}, {"text": "ユニフォーム", "is_correct": false, "explanation": "選手が着る服で人ではないので、人の役割を述べる空欄には入らない。"}, {"text": "プレーヤー", "is_correct": true, "explanation": "チームの中心となる競技者を指し、「彼はチームの中心的なプレーヤーだ」と自然に続く。"}, {"text": "ホイッスル", "is_correct": false, "explanation": "審判などが吹く笛で人ではないので、空欄には入らない。"}], "explanations": {"ボール": "競技で使う道具で人ではないので、「中心的なボールだ」と人を評する文には合わない。", "ユニフォーム": "選手が着る服で人ではないので、人の役割を述べる空欄には入らない。", "プレーヤー": "チームの中心となる競技者を指し、「彼はチームの中心的なプレーヤーだ」と自然に続く。", "ホイッスル": "審判などが吹く笛で人ではないので、空欄には入らない。"}, "sentence_index": 0, "correct_answer": "プレーヤー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "プレーヤーは、毎朝新聞を家々に配って歩いた。", "explanation": "ここは〈新聞配達員〉の意味。新聞を配る人は試合やゲームに参加する人ではないので、プレーヤーとは言わない。"}, {"text": "プレーヤーは、窓口でお客さんの口座を開設した。", "explanation": "ここは〈銀行員〉の意味。口座を開く人は試合やゲームに参加する人ではないので、プレーヤーとは言わない。"}, {"text": "プレーヤーは、法廷で被告人のために弁論した。", "explanation": "ここは〈弁護士〉の意味。法廷で弁論する人は競技に参加する人ではないので、プレーヤーとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37359, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "グラウンド", "is_correct": false, "explanation": "練習する場所で人ではないので、「若いグラウンドを試合に出した」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで人ではないので、「若い天気を試合に出した」は成立しない。"}, {"text": "プレーヤー", "is_correct": true, "explanation": "試合に出て競技する人を指し、「監督は若いプレーヤーを試合に出した」と自然に続く。"}, {"text": "作戦", "is_correct": false, "explanation": "試合の計画で人ではないので、「若い作戦を試合に出した」は成立しない。"}], "explanations": {"グラウンド": "練習する場所で人ではないので、「若いグラウンドを試合に出した」は意味が通らない。", "天気": "空模様のことで人ではないので、「若い天気を試合に出した」は成立しない。", "プレーヤー": "試合に出て競技する人を指し、「監督は若いプレーヤーを試合に出した」と自然に続く。", "作戦": "試合の計画で人ではないので、「若い作戦を試合に出した」は成立しない。"}, "sentence_index": 6, "correct_answer": "プレーヤー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "プレーヤーは、お客さんの髪をカットして仕上げた。", "explanation": "ここは〈美容師〉の意味。髪を切る人は試合やゲームに参加する人ではないので、プレーヤーとは言わない。"}, {"text": "プレーヤーは、処方箋どおりに薬を調合した。", "explanation": "ここは〈薬剤師〉の意味。薬を調合する人は競技に参加する人ではないので、プレーヤーとは言わない。"}, {"text": "プレーヤーは、朝礼で全校生徒に話をした。", "explanation": "ここは〈校長〉の意味。朝礼で生徒に話す人は競技に参加する人ではないので、プレーヤーとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37359, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "まだ若いプレーヤーを、大会で活躍した。", "corrected_sentence": "まだ若いプレーヤーが、大会で活躍した。", "error_description": "「活躍する」は主語に「が」をとる。「を」は誤りで、「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37359, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ゴールを決めたプレーヤーで、観客が拍手を送った。", "corrected_sentence": "ゴールを決めたプレーヤーに、観客が拍手を送った。", "error_description": "「拍手を送る」の相手は「に」で示す。「で」は誤りで、「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
