INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37360, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何人かでいっしょに、なにかをするために、ひとつのグループになること。", "primary_collocate": null, "pronunciation": "くむ", "ipa": "kɯmɯ", "syllable_count": 2, "sentences": [{"text": "授業でペアを組んで、会話の練習をしました。", "target_word": "組んで", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]でペアを組[く]んで、会話[かいわ]の練習[れんしゅう]をしました。", "sentence_source": "generated"}, {"text": "私は田中さんとチームを組んで、大会に出ることにしました。", "target_word": "組んで", "complexity_tier": "T3", "furigana": "私[わたし]は田中[たなか]さんとチームを組[く]んで、大会[たいかい]に出[で]ることにしました。", "sentence_source": "generated"}, {"text": "一人では無理なので、だれかと組みましょう。", "target_word": "組みましょう", "complexity_tier": "T3", "furigana": "一人[ひとり]では無理[むり]なので、だれかと組[く]みましょう。", "sentence_source": "generated"}, {"text": "二人は高校のときからコンビを組んでいます。", "target_word": "組んでいます", "complexity_tier": "T3", "furigana": "二人[ふたり]は高校[こうこう]のときからコンビを組[く]んでいます。", "sentence_source": "generated"}, {"text": "新しい仕事は、先輩と組むことになりました。", "target_word": "組む", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]は、先輩[せんぱい]と組[く]むことになりました。", "sentence_source": "generated"}, {"text": "彼とは組みたくありません。いつも遅刻するからです。", "target_word": "組みたく", "complexity_tier": "T3", "furigana": "彼[かれ]とは組[く]みたくありません。いつも遅刻[ちこく]するからです。", "sentence_source": "generated"}, {"text": "兄は友だちとバンドを組んで、週末に演奏しています。", "target_word": "組んで", "complexity_tier": "T3", "furigana": "兄[あに]は友[とも]だちとバンドを組[く]んで、週末[しゅうまつ]に演奏[えんそう]しています。", "sentence_source": "generated"}, {"text": "強い相手に勝つために、三人で組んで戦いました。", "target_word": "組んで", "complexity_tier": "T3", "furigana": "強[つよ]い相手[あいて]に勝[か]つために、三人[さんにん]で組[く]んで戦[たたか]いました。", "sentence_source": "generated"}, {"text": "会社をこえて組めば、もっと大きな計画ができます。", "target_word": "組めば", "complexity_tier": "T3", "furigana": "会社[かいしゃ]をこえて組[く]めば、もっと大[おお]きな計画[けいかく]ができます。", "sentence_source": "generated"}, {"text": "彼女は去年、留学生と組んで研究を発表しました。", "target_word": "組んで", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は去年[きょねん]、留学生[りゅうがくせい]と組[く]んで研究[けんきゅう]を発表[はっぴょう]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組む", "label": "dictionary form"}, {"form": "組まない", "label": "negative"}, {"form": "組み", "label": "masu stem"}, {"form": "組んで", "label": "te-form"}, {"form": "組んだ", "label": "past"}, {"form": "組める", "label": "potential"}, {"form": "組もう", "label": "volitional"}, {"form": "組めば", "label": "conditional ba"}], "register": "neutral", "sense_fingerprint": "several people team up as a pair or group in order to do something together (ペアを組む, チームを組む)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1bc596f-8b8d-4af6-bf10-97dcd2d33ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37360, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組んで", "is_correct": true, "explanation": "「ペアを〜、会話の練習をしました」の「て形」で、後ろの文と自然につながる。"}, {"text": "組もう", "is_correct": false, "explanation": "意志形なので「組もう、練習をしました」となり、過去の文とつながらない。"}, {"text": "組めば", "is_correct": false, "explanation": "条件形なので「組めば、練習をしました」となり、文の意味が成り立たない。"}, {"text": "組まない", "is_correct": false, "explanation": "否定形なので「ペアを組まない、練習をしました」となり、意味も文のつながりも合わない。"}], "explanations": {"組んで": "「ペアを〜、会話の練習をしました」の「て形」で、後ろの文と自然につながる。", "組もう": "意志形なので「組もう、練習をしました」となり、過去の文とつながらない。", "組めば": "条件形なので「組めば、練習をしました」となり、文の意味が成り立たない。", "組まない": "否定形なので「ペアを組まない、練習をしました」となり、意味も文のつながりも合わない。"}, "sentence_index": 0, "correct_answer": "組んで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人は高校のときからセーターを組んで、冬に売っています。", "explanation": "ここは〈編む〉の意味。セーターは編むもので、組むとは言わないので合わない。"}, {"text": "二人は高校のときから足を組んで、ゆっくり話しています。", "explanation": "ここは〈脚を交差させる〉の意味。足を組むのは姿勢で、グループになる意味ではない。"}, {"text": "二人は高校のときから腕を組んで、先生の話を聞いています。", "explanation": "ここは〈腕を組む〉の意味。両腕を胸の前で交差させる姿勢で、グループになる意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37360, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組んで", "is_correct": true, "explanation": "「バンドを〜、週末に演奏しています」の「て形」で、後ろの文と自然につながる。"}, {"text": "組め", "is_correct": false, "explanation": "命令形なので「組め、週末に演奏しています」となり、文が続かない。"}, {"text": "組める", "is_correct": false, "explanation": "可能形は単独で「組める、」と続けられず、文が崩れる。"}, {"text": "組みたく", "is_correct": false, "explanation": "希望の連用形なので「組みたく、演奏しています」となり、文がつながらない。"}], "explanations": {"組んで": "「バンドを〜、週末に演奏しています」の「て形」で、後ろの文と自然につながる。", "組め": "命令形なので「組め、週末に演奏しています」となり、文が続かない。", "組める": "可能形は単独で「組める、」と続けられず、文が崩れる。", "組みたく": "希望の連用形なので「組みたく、演奏しています」となり、文がつながらない。"}, "sentence_index": 6, "correct_answer": "組んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は去年、留学生と友情を組んで、研究を発表しました。", "explanation": "ここは〈結ぶ〉の意味。友情は結ぶもので、組むとは言わないので合わない。"}, {"text": "彼女は去年、留学生と約束を組んで、研究を発表しました。", "explanation": "ここは〈交わす〉の意味。約束は交わすもので、組むとは言わないので合わない。"}, {"text": "彼女は去年、留学生と契約を組んで、研究を発表しました。", "explanation": "ここは〈結ぶ〉の意味。契約は結ぶもので、組むとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37360, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ペアを組むで、授業で発表しました。", "corrected_sentence": "ペアを組んで、授業で発表しました。", "error_description": "「組んで」が正しい。「組む」はマ行五段の動詞で、「む」は「んで」に変わるので「組むで」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "組んで", "is_correct": true, "explanation": "「チームを組んで、大会に出る」と続く「て形」で、文の流れに合う。"}, {"text": "組もう", "is_correct": false, "explanation": "意志形なので「チームを組もう、大会に出る」となり、続けて文にならない。"}, {"text": "組め", "is_correct": false, "explanation": "命令形なので「組め、大会に出ることにしました」となり、文がつながらない。"}, {"text": "組まない", "is_correct": false, "explanation": "否定形なので「組まない、大会に出る」となり、チームを組んだ事実と矛盾する。"}], "correct_form": "組んで", "base_form": "組む", "form_label": "て形", "sentence_index": 1, "explanations": {"組んで": "「チームを組んで、大会に出る」と続く「て形」で、文の流れに合う。", "組もう": "意志形なので「チームを組もう、大会に出る」となり、続けて文にならない。", "組め": "命令形なので「組め、大会に出ることにしました」となり、文がつながらない。", "組まない": "否定形なので「組まない、大会に出る」となり、チームを組んだ事実と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37360, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は友だちに組んで、新しいゲームを作りました。", "corrected_sentence": "弟は友だちと組んで、新しいゲームを作りました。", "error_description": "「と」が正しい。「組む」の相手は「と」で示す。「に」だと「友だちに組む」となり不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "組んで", "is_correct": true, "explanation": "「三人で〜、戦いました」と続く「て形」で、動作の流れに合う。"}, {"text": "組んだ", "is_correct": false, "explanation": "過去形なので「組んだ、戦いました」となり、文がつながらない。"}, {"text": "組める", "is_correct": false, "explanation": "可能形なので「組める戦いました」となり、意味も文のつながりも合わない。"}, {"text": "組みたく", "is_correct": false, "explanation": "希望の連用形なので「組みたく戦いました」となり、文が成り立たない。"}], "correct_form": "組んで", "base_form": "組む", "form_label": "て形", "sentence_index": 7, "explanations": {"組んで": "「三人で〜、戦いました」と続く「て形」で、動作の流れに合う。", "組んだ": "過去形なので「組んだ、戦いました」となり、文がつながらない。", "組める": "可能形なので「組める戦いました」となり、意味も文のつながりも合わない。", "組みたく": "希望の連用形なので「組みたく戦いました」となり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37361, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "足場は〈組む〉の目的語なので、を が正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。足場が組むと自分で組み立てることになり、文の意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "共同の相手を示す。足場と組むという言い方はしない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。足場へ組むという言い方はしない。"}], "correct_answer": "を", "explanations": {"を": "足場は〈組む〉の目的語なので、を が正しい。", "が": "主語を示す。足場が組むと自分で組み立てることになり、文の意味が通らない。", "と": "共同の相手を示す。足場と組むという言い方はしない。", "へ": "方向を示す。足場へ組むという言い方はしない。"}, "error_tags": {"が": "主語の格", "と": "共同の相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37361, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「正しい順番で」と、やり方を示す〈で〉。組む際の様子を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。順番を組むという言い方はなく、文の意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。順番が組めばという形は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。正しい順番へ組むという言い方はしない。"}], "correct_answer": "で", "explanations": {"で": "「正しい順番で」と、やり方を示す〈で〉。組む際の様子を表す。", "を": "目的語を示す。順番を組むという言い方はなく、文の意味が通らない。", "が": "主語を示す。順番が組めばという形は成り立たない。", "へ": "方向を示す。正しい順番へ組むという言い方はしない。"}, "error_tags": {"を": "目的語の格", "が": "主語の格", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37361, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "複数の人や物が協力して一つのまとまりを作ること。", "primary_collocate": null, "pronunciation": "くむ", "ipa": "kɯmɯ", "syllable_count": 2, "sentences": [{"text": "大工さんは木を組んで、小さな小屋を作りました。", "target_word": "組んで", "complexity_tier": "T3", "furigana": "大工[だいく]さんは木[き]を組[く]んで、小[ちい]さな小屋[こや]を作[つく]りました。", "sentence_source": "generated"}, {"text": "工事の前に、建物のまわりに足場を組みます。", "target_word": "組みます", "complexity_tier": "T3", "furigana": "工事[こうじ]の前[まえ]に、建物[たてもの]のまわりに足場[あしば]を組[く]みます。", "sentence_source": "generated"}, {"text": "弟はパズルのピースを組んで、一枚の絵を完成させました。", "target_word": "組んで", "complexity_tier": "T3", "furigana": "弟[おとうと]はパズルのピースを組[く]んで、一枚[いちまい]の絵[え]を完成[かんせい]させました。", "sentence_source": "generated"}, {"text": "子どもたちは肩を組んで、校歌を歌いました。", "target_word": "組んで", "complexity_tier": "T3", "furigana": "子[こ]どもたちは肩[かた]を組[く]んで、校歌[こうか]を歌[うた]いました。", "sentence_source": "generated"}, {"text": "警官たちは隊列を組んで、広場に入りました。", "target_word": "組んで", "complexity_tier": "T3", "furigana": "警官[けいかん]たちは隊列[たいれつ]を組[く]んで、広場[ひろば]に入[はい]りました。", "sentence_source": "generated"}, {"text": "二つの会社が手を組んで、新しい商品を作りました。", "target_word": "組んで", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]が手[て]を組[く]んで、新[あたら]しい商品[しょうひん]を作[つく]りました。", "sentence_source": "generated"}, {"text": "技師たちは鉄の板を組んで、大きな橋の骨組みを作りました。", "target_word": "組んで", "complexity_tier": "T3", "furigana": "技師[ぎし]たちは鉄[てつ]の板[いた]を組[く]んで、大[おお]きな橋[はし]の骨組[ほねぐ]みを作[つく]りました。", "sentence_source": "generated"}, {"text": "部品を正しい順番で組めば、この棚は三十分でできます。", "target_word": "組めば", "complexity_tier": "T3", "furigana": "部品[ぶひん]を正[ただ]しい順番[じゅんばん]で組[く]めば、この棚[たな]は三十分[さんじゅっぷん]でできます。", "sentence_source": "generated"}, {"text": "庭師たちは竹垣を組んで、庭のまわりを囲みました。", "target_word": "組んで", "complexity_tier": "T3", "furigana": "庭師[にわし]たちは竹垣[たけがき]を組[く]んで、庭[にわ]のまわりを囲[かこ]みました。", "sentence_source": "generated"}, {"text": "選手たちは円陣を組んで、試合の前に声を出しました。", "target_word": "組んで", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは円陣[えんじん]を組[く]んで、試合[しあい]の前[まえ]に声[こえ]を出[だ]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組む", "label": "dictionary form"}, {"form": "組まない", "label": "negative"}, {"form": "組み", "label": "masu stem"}, {"form": "組んで", "label": "te-form"}, {"form": "組んだ", "label": "past"}, {"form": "組める", "label": "potential"}, {"form": "組もう", "label": "volitional"}, {"form": "組めば", "label": "conditional ba"}], "register": "neutral", "sense_fingerprint": "several people or things are joined or arranged together into one whole (足場を組む, 隊列を組む, 手を組む, 日程を組む)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: 竹垣 (Zipf 1.86)']::text[], 'f1bc596f-8b8d-4af6-bf10-97dcd2d33ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37361, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組んで", "is_correct": true, "explanation": "「木を組み立てて小屋を作る」流れに合う、て形の連用形。"}, {"text": "組もう", "is_correct": false, "explanation": "意志形なので、「木を組もう、小さな小屋を作りました」と続かない。"}, {"text": "組める", "is_correct": false, "explanation": "可能形なので、「木を組める、小屋を作りました」は文として成り立たない。"}, {"text": "組ませる", "is_correct": false, "explanation": "使役形なので、大工が誰かに組ませる意味になり、文の主語と合わない。"}], "explanations": {"組んで": "「木を組み立てて小屋を作る」流れに合う、て形の連用形。", "組もう": "意志形なので、「木を組もう、小さな小屋を作りました」と続かない。", "組める": "可能形なので、「木を組める、小屋を作りました」は文として成り立たない。", "組ませる": "使役形なので、大工が誰かに組ませる意味になり、文の主語と合わない。"}, "sentence_index": 0, "correct_answer": "組んで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姉は色紙を組んで、きれいな鶴を作りました。", "explanation": "ここは〈折る〉の意味。紙を折って形を作るときは〈折る〉を使い、〈組む〉とは言わないので不自然。"}, {"text": "二つの会社が契約を組んで、新しい商品を売ることにしました。", "explanation": "ここは〈契約を結ぶ〉の意味。契約には〈組む〉を使わず〈結ぶ〉と言うので、この使い方は不自然。"}, {"text": "母は毛糸でマフラーを組んで、冬にくれました。", "explanation": "ここは〈編む〉の意味。糸で布状のものを作るときは〈編む〉を使い、〈組む〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37361, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組んで", "is_correct": true, "explanation": "「鉄の板を組み合わせて骨組みを作る」流れに合う、て形の連用形。"}, {"text": "組みたい", "is_correct": false, "explanation": "願望形なので、板を組みたいという願いを述べる文になり、作ったという結果と合わない。"}, {"text": "組まれる", "is_correct": false, "explanation": "受身形なので、板が組まれるという文になり、技師が主語の文と合わない。"}, {"text": "組めない", "is_correct": false, "explanation": "可能の否定形なので、作りましたという過去の結果と続かない。"}], "explanations": {"組んで": "「鉄の板を組み合わせて骨組みを作る」流れに合う、て形の連用形。", "組みたい": "願望形なので、板を組みたいという願いを述べる文になり、作ったという結果と合わない。", "組まれる": "受身形なので、板が組まれるという文になり、技師が主語の文と合わない。", "組めない": "可能の否定形なので、作りましたという過去の結果と続かない。"}, "sentence_index": 6, "correct_answer": "組んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は荷物を組んで、車に積みました。", "explanation": "ここは〈縛る〉の意味。荷物を縛るのに〈組む〉は使わず、この文では不自然。"}, {"text": "母は野菜を組んで、夕食の準備をしました。", "explanation": "ここは〈洗う〉の意味。野菜を洗うのであって、野菜を組むとは言わない。"}, {"text": "作業員たちは溝を組んで、道路の水を流しました。", "explanation": "ここは〈掘る〉の意味。溝は掘って作るもので、〈組む〉とは言わないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37361, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作業員たちは鉄パイプで足場を組みて、高い壁の工事を始めました。", "corrected_sentence": "作業員たちは鉄パイプで足場を組んで、高い壁の工事を始めました。", "error_description": "「組みて」は誤りで、正しくは「組んで」。〈組む〉は五段活用なので、て形は「組んで」になる（連用形は「組み」）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "組みます", "is_correct": true, "explanation": "丁寧な非過去形で、文末の「組みます」にあたる正しい形。"}, {"text": "組まない", "is_correct": false, "explanation": "否定形なので、足場を組まないという意味になり、文の内容と合わない。"}, {"text": "組んで", "is_correct": false, "explanation": "て形なので文末に置けず、文が終わらない。"}, {"text": "組み", "is_correct": false, "explanation": "連用形（ます形の語幹）で、文を終わらせる丁寧形ではないため、文末に置けない。"}], "correct_form": "組みます", "base_form": "組む", "form_label": "ます形（丁寧・非過去）", "sentence_index": 1, "explanations": {"組みます": "丁寧な非過去形で、文末の「組みます」にあたる正しい形。", "組まない": "否定形なので、足場を組まないという意味になり、文の内容と合わない。", "組んで": "て形なので文末に置けず、文が終わらない。", "組み": "連用形（ます形の語幹）で、文を終わらせる丁寧形ではないため、文末に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37361, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町内会の人たちは協力して、夏祭りの屋台を組むました。", "corrected_sentence": "町内会の人たちは協力して、夏祭りの屋台を組みました。", "error_description": "「組むました」は誤りで、正しくは「組みました」。〈組む〉は五段活用なので、連用形は「組み」になり、「ました」に続く。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "組めば", "is_correct": true, "explanation": "条件形（ば）で、「正しい順番で組めば」という条件を表すので正しい。"}, {"text": "組みました", "is_correct": false, "explanation": "過去の丁寧形なので、「組みましたら」の条件の文にはならず、文の流れが合わない。"}, {"text": "組みません", "is_correct": false, "explanation": "否定の丁寧形なので、組まないという意味になり、棚ができるという結果と合わない。"}, {"text": "組んでいる", "is_correct": false, "explanation": "進行形なので、組んでいる最中という意味になり、条件を表す文と合わない。"}], "correct_form": "組めば", "base_form": "組む", "form_label": "ば形（条件）", "sentence_index": 7, "explanations": {"組めば": "条件形（ば）で、「正しい順番で組めば」という条件を表すので正しい。", "組みました": "過去の丁寧形なので、「組みましたら」の条件の文にはならず、文の流れが合わない。", "組みません": "否定の丁寧形なので、組まないという意味になり、棚ができるという結果と合わない。", "組んでいる": "進行形なので、組んでいる最中という意味になり、条件を表す文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
