INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37362, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "敵は〈作る〉の目的語なので、を が正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。敵が作るという形は文の意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "相手や位置を示す。敵に作るという言い方はなく、文の意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す。敵で作るという言い方はなく、文の意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "敵は〈作る〉の目的語なので、を が正しい。", "が": "主語を示す。敵が作るという形は文の意味が通らない。", "に": "相手や位置を示す。敵に作るという言い方はなく、文の意味が通らない。", "で": "手段を示す。敵で作るという言い方はなく、文の意味が通らない。"}, "error_tags": {"が": "主語の格", "に": "位置・相手", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37362, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分に害をしようとする人のこと。", "primary_collocate": null, "pronunciation": "てき", "ipa": "teki", "syllable_count": 2, "sentences": [{"text": "彼は私の敵ではありません。ただ意見がちがうだけです。", "target_word": "敵", "complexity_tier": "T3", "furigana": "彼[かれ]は私[わたし]の敵[てき]ではありません。ただ意見[いけん]がちがうだけです。", "sentence_source": "generated"}, {"text": "敵だと思っていた人が、困ったときに助けてくれました。", "target_word": "敵", "complexity_tier": "T3", "furigana": "敵[てき]だと思[おも]っていた人[ひと]が、困[こま]ったときに助[たす]けてくれました。", "sentence_source": "generated"}, {"text": "昔、この国は敵におそわれて、多くの人が家を失いました。", "target_word": "敵", "complexity_tier": "T3", "furigana": "昔[むかし]、この国[くに]は敵[てき]におそわれて、多[おお]くの人[ひと]が家[いえ]を失[うしな]いました。", "sentence_source": "generated"}, {"text": "見張りの人は、敵が近づくとすぐに鐘を鳴らします。", "target_word": "敵", "complexity_tier": "T3", "furigana": "見張[みは]りの人[ひと]は、敵[てき]が近[ちか]づくと、すぐに鐘[かね]を鳴[な]らします。", "sentence_source": "generated"}, {"text": "彼女は自分をだました男を、いまも敵だと思っています。", "target_word": "敵", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]をだました男[おとこ]を、いまも敵[てき]だと思[おも]っています。", "sentence_source": "generated"}, {"text": "敵か味方か分からない人には、秘密を話さないほうがいいです。", "target_word": "敵", "complexity_tier": "T3", "furigana": "敵[てき]か味方[みかた]か分[わ]からない人[ひと]には、秘密[ひみつ]を話[はな]さないほうがいいです。", "sentence_source": "generated"}, {"text": "犬は知らない人を敵だと思って、大きな声でほえました。", "target_word": "敵", "complexity_tier": "T3", "furigana": "犬[いぬ]は知[し]らない人[ひと]を敵[てき]だと思[おも]って、大[おお]きな声[こえ]でほえました。", "sentence_source": "generated"}, {"text": "彼は正直すぎて、知らないうちに敵を作ってしまいます。", "target_word": "敵", "complexity_tier": "T3", "furigana": "彼[かれ]は正直[しょうじき]すぎて、知[し]らないうちに敵[てき]を作[つく]ってしまいます。", "sentence_source": "generated"}, {"text": "兵士たちは森にかくれて、敵が通りすぎるのを待ちました。", "target_word": "敵", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは森[もり]にかくれて、敵[てき]が通[とお]りすぎるのを待[ま]ちました。", "sentence_source": "generated"}, {"text": "うわさを流した敵の正体が分かって、彼はおどろきました。", "target_word": "敵", "complexity_tier": "T3", "furigana": "うわさを流[なが]した敵[てき]の正体[しょうたい]が分[わ]かって、彼[かれ]はおどろきました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "敵", "label": "base"}, {"form": "敵を", "label": "with particle を"}, {"form": "敵の", "label": "attributive with の"}], "register": "neutral", "sense_fingerprint": "a person who wishes to harm or hurt oneself; an enemy, opposite of 味方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: おそわ (Zipf 2.2)','sentence 3 above tier T1: 4 words above tier T1 (max 2): 見張り (Zipf 3.22), 近づく (Zipf 3.95), 鐘 (Zipf 3.72), 鳴らし (Zipf 3.7)']::text[], 'f1bc596f-8b8d-4af6-bf10-97dcd2d33ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37362, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "敵", "is_correct": true, "explanation": "「自分に害をしようとする人」の意味で、ここでは〈敵ではない〉と否定しているので正しい。"}, {"text": "天気", "is_correct": false, "explanation": "「私の天気」は意味が通らず、人を表す語ではないので入らない。"}, {"text": "教室", "is_correct": false, "explanation": "「私の教室」は意味が通らず、人を表す語ではないので入らない。"}, {"text": "台所", "is_correct": false, "explanation": "「私の台所」は意味が通らず、人を表す語ではないので入らない。"}], "explanations": {"敵": "「自分に害をしようとする人」の意味で、ここでは〈敵ではない〉と否定しているので正しい。", "天気": "「私の天気」は意味が通らず、人を表す語ではないので入らない。", "教室": "「私の教室」は意味が通らず、人を表す語ではないので入らない。", "台所": "「私の台所」は意味が通らず、人を表す語ではないので入らない。"}, "sentence_index": 0, "correct_answer": "敵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弓の練習で、敵の真ん中を射抜きました。", "explanation": "ここは〈的〉（まと）の意味。矢を射る目標は〈的〉で、害を与える人の〈敵〉ではない。"}, {"text": "電話の敵は、なかなか出ませんでした。", "explanation": "ここは〈相手〉の意味。電話の向こうの人を〈敵〉とは言わないので、この使い方は不自然。"}, {"text": "次の大会で、敵が試合の判定を下しました。", "explanation": "ここは〈審判〉の意味。試合の判定を下す人を〈敵〉とは言わないので、この使い方は不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37362, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "敵", "is_correct": true, "explanation": "「知らない人を敵だと思う」の意味で、害を与えようとする人と思っている文に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「知らない人を冷蔵庫だと思う」は意味が通らず、人を表す語ではないので入らない。"}, {"text": "太陽", "is_correct": false, "explanation": "「知らない人を太陽だと思う」は意味が通らず、文の流れに合わない。"}, {"text": "雨", "is_correct": false, "explanation": "「知らない人を雨だと思う」は意味が通らず、人を表す語ではないので入らない。"}], "explanations": {"敵": "「知らない人を敵だと思う」の意味で、害を与えようとする人と思っている文に合う。", "冷蔵庫": "「知らない人を冷蔵庫だと思う」は意味が通らず、人を表す語ではないので入らない。", "太陽": "「知らない人を太陽だと思う」は意味が通らず、文の流れに合わない。", "雨": "「知らない人を雨だと思う」は意味が通らず、人を表す語ではないので入らない。"}, "sentence_index": 6, "correct_answer": "敵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この教室の敵は、みんな真面目に授業を聞きます。", "explanation": "ここは〈生徒〉の意味。授業を受ける人を〈敵〉とは言わないので、この使い方は不自然。"}, {"text": "この店の敵が、今日もたくさん買い物をしてくれました。", "explanation": "ここは〈客〉の意味。店で買い物をする人を〈敵〉とは言わないので、この使い方は不自然。"}, {"text": "敵の大きな声援が、選手の力になりました。", "explanation": "ここは〈観客〉の意味。害をしようとする人は声援を送らないので、〈敵〉では文が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37362, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村の人たちは、敵で町を守るために門を閉めました。", "corrected_sentence": "村の人たちは、敵から町を守るために門を閉めました。", "error_description": "「敵で」は誤りで、正しくは「敵から」。〈守る〉は〈〜から守る〉と言い、〈で〉は手段を表すので、敵を手段とする意味になり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37362, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、長い間ずっと敵のと思っていた男と和解しました。", "corrected_sentence": "彼は、長い間ずっと敵だと思っていた男と和解しました。", "error_description": "「敵のと思っていた」は誤りで、正しくは「敵だと思っていた」。〈敵〉に続けるときは〈だ〉を使うので、〈の〉にすると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37363, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「敵の動き」と、敵に属する動きを表す〈の〉。動きの前に置く正しい形。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。敵が動きをよく見るという形は、動きを見る対象が合わず不自然。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す。敵に動きという形は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。敵へ動きという形は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「敵の動き」と、敵に属する動きを表す〈の〉。動きの前に置く正しい形。", "が": "主語を示す。敵が動きをよく見るという形は、動きを見る対象が合わず不自然。", "に": "位置や相手を示す。敵に動きという形は意味が通らない。", "へ": "方向を示す。敵へ動きという形は意味が通らない。"}, "error_tags": {"が": "主語の格", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
