INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37363, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分にとって不利な存在。戦いや競争の相手。", "primary_collocate": null, "pronunciation": "てき", "ipa": "teki", "syllable_count": 2, "sentences": [{"text": "決勝戦の敵は、去年の優勝チームです。", "target_word": "敵", "complexity_tier": "T3", "furigana": "決勝戦[けっしょうせん]の敵[てき]は、去年[きょねん]の優勝[ゆうしょう]チームです。", "sentence_source": "generated"}, {"text": "試合では、敵の動きをよく見ることが大切です。", "target_word": "敵", "complexity_tier": "T3", "furigana": "試合[しあい]では、敵[てき]の動[うご]きをよく見[み]ることが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "同期の社員は、昇進を争う敵であると同時に、いちばん頼れる仲間でもあります。", "target_word": "敵", "complexity_tier": "T3", "furigana": "同期[どうき]の社員[しゃいん]は、昇進[しょうしん]を争[あらそ]う敵[てき]であると同時[どうじ]に、一番[いちばん]頼[たよ]れる仲間[なかま]でもあります。", "sentence_source": "generated"}, {"text": "彼にとって一番の敵は、自分の弱い心です。", "target_word": "敵", "complexity_tier": "T3", "furigana": "彼[かれ]にとって一番[いちばん]の敵[てき]は、自分[じぶん]の弱[よわ]い心[こころ]です。", "sentence_source": "generated"}, {"text": "ボクシングでは、敵の攻撃をかわせる選手ほど強いと言われます。", "target_word": "敵", "complexity_tier": "T3", "furigana": "ボクシングでは、敵[てき]の攻撃[こうげき]をかわせる選手[せんしゅ]ほど強[つよ]いと言[い]われます。", "sentence_source": "generated"}, {"text": "夜ふかしは健康の敵だと医者に言われました。", "target_word": "敵", "complexity_tier": "T3", "furigana": "夜[よる]ふかしは健康[けんこう]の敵[てき]だと医者[いしゃ]に言[い]われました。", "sentence_source": "generated"}, {"text": "このゲームでは、強い敵を倒すと新しい道具がもらえます。", "target_word": "敵", "complexity_tier": "T3", "furigana": "このゲームでは、強[つよ]い敵[てき]を倒[たお]すと新[あたら]しい道具[どうぐ]がもらえます。", "sentence_source": "generated"}, {"text": "彼は力が強くて、クラスに敵はいません。", "target_word": "敵", "complexity_tier": "T3", "furigana": "彼[かれ]は力[ちから]が強[つよ]くて、クラスに敵[てき]はいません。", "sentence_source": "generated"}, {"text": "夏の暑さは、マラソン選手にとって大きな敵です。", "target_word": "敵", "complexity_tier": "T3", "furigana": "夏[なつ]の暑[あつ]さは、マラソン選手[せんしゅ]にとって大[おお]きな敵[てき]です。", "sentence_source": "generated"}, {"text": "敵に負けないように、毎朝走って体をきたえています。", "target_word": "敵", "complexity_tier": "T3", "furigana": "敵[てき]に負[ま]けないように、毎朝[まいあさ]走[はし]って体[からだ]をきたえています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "敵", "label": "base"}, {"form": "敵を", "label": "with particle を"}, {"form": "敵の", "label": "attributive with の"}], "register": "neutral", "sense_fingerprint": "an opponent in a fight, game or competition, or something that works against one (e.g. 健康の敵)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 昇進 (Zipf 3.96), 争う (Zipf 3.77), 頼れる (Zipf 3.43)','sentence 4 above tier T1: contains vocabulary far above tier T1: かわせる (Zipf 1.3)']::text[], 'f1bc596f-8b8d-4af6-bf10-97dcd2d33ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37363, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "敵", "is_correct": true, "explanation": "「戦いや競争の相手」の意味で、決勝戦の相手チームを表すので正しい。"}, {"text": "天井", "is_correct": false, "explanation": "「決勝戦の天井」は意味が通らず、対戦相手を表せないので入らない。"}, {"text": "台所", "is_correct": false, "explanation": "「決勝戦の台所」は意味が通らず、対戦相手を表せないので入らない。"}, {"text": "天気", "is_correct": false, "explanation": "「決勝戦の天気」は意味が通らず、対戦相手を表せないので入らない。"}], "explanations": {"敵": "「戦いや競争の相手」の意味で、決勝戦の相手チームを表すので正しい。", "天井": "「決勝戦の天井」は意味が通らず、対戦相手を表せないので入らない。", "台所": "「決勝戦の台所」は意味が通らず、対戦相手を表せないので入らない。", "天気": "「決勝戦の天気」は意味が通らず、対戦相手を表せないので入らない。"}, "sentence_index": 0, "correct_answer": "敵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい敵が入って、チームの攻撃が強くなりました。", "explanation": "ここは〈助っ人〉の意味。味方として入ってチームを強くする人を〈敵〉とは言わない。"}, {"text": "敵の店員が、親切に商品を案内してくれました。", "explanation": "ここは〈店員〉の意味。店で商品を案内する人を〈敵〉とは言わないので、この使い方は不自然。"}, {"text": "敵の判定で、試合が再開されました。", "explanation": "ここは〈審判〉の意味。試合を裁く立場の人を〈敵〉とは言わないので、この使い方は不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37363, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "敵", "is_correct": true, "explanation": "「戦いや競争の相手」の意味で、倒すと道具がもらえる相手を表すので正しい。"}, {"text": "宝箱", "is_correct": false, "explanation": "「強い宝箱を倒す」は意味が通らず、倒せる相手ではないので入らない。"}, {"text": "空腹", "is_correct": false, "explanation": "「強い空腹を倒す」は意味が通らず、ゲームの相手にならないので入らない。"}, {"text": "教科書", "is_correct": false, "explanation": "「強い教科書を倒す」は意味が通らず、ゲームの相手にならないので入らない。"}], "explanations": {"敵": "「戦いや競争の相手」の意味で、倒すと道具がもらえる相手を表すので正しい。", "宝箱": "「強い宝箱を倒す」は意味が通らず、倒せる相手ではないので入らない。", "空腹": "「強い空腹を倒す」は意味が通らず、ゲームの相手にならないので入らない。", "教科書": "「強い教科書を倒す」は意味が通らず、ゲームの相手にならないので入らない。"}, "sentence_index": 6, "correct_answer": "敵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "敵が子どもたちに、やさしく料理を教えました。", "explanation": "ここは〈先生〉の意味。料理を教える人を〈敵〉とは言わないので、この使い方は不自然。"}, {"text": "敵が大きな声で声援を送りました。", "explanation": "ここは〈応援団〉の意味。選手を応援する人を〈敵〉とは言わないので、文の内容が合わない。"}, {"text": "敵の材料で、おいしい料理を作りました。", "explanation": "ここは〈材料〉の意味。料理に使う材料を〈敵〉とは言わないので、この使い方は不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37363, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "強い敵を戦う前に、よく準備をしておきましょう。", "corrected_sentence": "強い敵と戦う前に、よく準備をしておきましょう。", "error_description": "「敵を戦う」は誤りで、正しくは「敵と戦う」。〈戦う〉は〈〜と戦う〉と言うので、〈を〉は使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37363, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は、彼を強い敵のと思って、毎日練習しています。", "corrected_sentence": "私は、彼を強い敵だと思って、毎日練習しています。", "error_description": "「敵のと思って」は誤りで、正しくは「敵だと思って」。〈敵〉に続けるときは〈だ〉を使うので、〈の〉にすると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37364, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「クラスが」は勝つ主体を示す主語の「が」。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は勝つの主語を示せず、文が不自然になる。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では主語にならず、勝つ主体が表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は勝つの主語にならず、文の意味が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「クラスが」は勝つ主体を示す主語の「が」。", "へ": "方向の「へ」は勝つの主語を示せず、文が不自然になる。", "から": "起点の「から」では主語にならず、勝つ主体が表せない。", "より": "比較の「より」は勝つの主語にならず、文の意味が成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "負ける", "is_correct": true, "explanation": "試合の勝ち負けで対になる対義語。"}, {"text": "歌う", "is_correct": false, "explanation": "勝つの対義語ではなく、試合の結果とは関係がない。"}, {"text": "走る", "is_correct": false, "explanation": "勝つの対義語ではなく、動作を表す別の動詞。"}, {"text": "考える", "is_correct": false, "explanation": "勝つの対義語ではなく、思考を表す動詞。"}], "correct_answer": "負ける", "explanations": {"負ける": "試合の勝ち負けで対になる対義語。", "歌う": "勝つの対義語ではなく、試合の結果とは関係がない。", "走る": "勝つの対義語ではなく、動作を表す別の動詞。", "考える": "勝つの対義語ではなく、思考を表す動詞。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37364, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "負ける", "is_correct": true, "explanation": "勝つの対義語で、試合の結果として対になる。"}, {"text": "運ぶ", "is_correct": false, "explanation": "勝つの対義語ではなく、物を移動させる動詞。"}, {"text": "集める", "is_correct": false, "explanation": "勝つの対義語ではなく、ものを寄せる動詞。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "勝つの対義語ではなく、水中での動作を表す動詞。"}], "correct_answer": "負ける", "explanations": {"負ける": "勝つの対義語で、試合の結果として対になる。", "運ぶ": "勝つの対義語ではなく、物を移動させる動詞。", "集める": "勝つの対義語ではなく、ものを寄せる動詞。", "泳ぐ": "勝つの対義語ではなく、水中での動作を表す動詞。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37364, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ゲームやスポーツで、自分より強い人やチームに、最後に「よし、やった！」となること。", "primary_collocate": null, "pronunciation": "かつ", "ipa": "katsɯ", "syllable_count": 2, "sentences": [{"text": "弱いチームが強いチームに勝った。", "target_word": "勝った", "complexity_tier": "T3", "furigana": "弱[よわ]いチームが強[つよ]いチームに勝[か]った。", "sentence_source": "generated"}, {"text": "昨日の試合で、ぼくのクラスが勝って、みんなで喜んだ。", "target_word": "勝って", "complexity_tier": "T3", "furigana": "昨日[きのう]の試合[しあい]で、ぼくのクラスが勝[か]って、みんなで喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "兄にチェスで勝つのは難しいが、毎日練習している。", "target_word": "勝つ", "complexity_tier": "T3", "furigana": "兄[あに]にチェスで勝[か]つのは難[むずか]しいが、毎日[まいにち]練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "最後のゲームに勝てば、優勝だ。", "target_word": "勝てば", "complexity_tier": "T3", "furigana": "最後[さいご]のゲームに勝[か]てば、優勝[ゆうしょう]だ。", "sentence_source": "generated"}, {"text": "相手が強かったので、勝てると思わなかった。", "target_word": "勝てる", "complexity_tier": "T3", "furigana": "相手[あいて]が強[つよ]かったので、勝[か]てると思[おも]わなかった。", "sentence_source": "generated"}, {"text": "じゃんけんに勝った人から、先に選べます。", "target_word": "勝った", "complexity_tier": "T3", "furigana": "じゃんけんに勝[か]った人[ひと]から、先[さき]に選[えら]べます。", "sentence_source": "generated"}, {"text": "私たちはサッカーの試合に勝ちました。", "target_word": "勝ちました", "complexity_tier": "T3", "furigana": "私[わたし]たちはサッカーの試合[しあい]に勝[か]ちました。", "sentence_source": "generated"}, {"text": "あきらめなければ、強い相手にも勝つことができる。", "target_word": "勝つ", "complexity_tier": "T3", "furigana": "あきらめなければ、強[つよ]い相手[あいて]にも勝[か]つことができる。", "sentence_source": "generated"}, {"text": "弟はカードゲームで一度も勝てないので、悔しがっている。", "target_word": "勝てない", "complexity_tier": "T3", "furigana": "弟[おとうと]はカードゲームで一度も勝[か]てないので、悔[くや]しがっている。", "sentence_source": "generated"}, {"text": "去年は負けたが、今年は勝って決勝に進んだ。", "target_word": "勝って", "complexity_tier": "T3", "furigana": "去年[きょねん]は負[ま]けたが、今年[ことし]は勝[か]って決勝[けっしょう]に進[すす]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "勝つ", "label": "辞書形"}, {"form": "勝ちます", "label": "丁寧形"}, {"form": "勝った", "label": "過去形"}, {"form": "勝って", "label": "て形"}, {"form": "勝たない", "label": "否定形"}, {"form": "勝てば", "label": "仮定形"}, {"form": "勝てる", "label": "可能形"}], "register": "標準", "sense_fingerprint": "ゲームやスポーツで強い相手を破って喜ぶ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215eb90-f0e8-463e-beea-b84a82a01593') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37364, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勝った", "is_correct": true, "explanation": "過去形で文を終えられ、「弱いチームが強いチームに勝った」と自然につながる。"}, {"text": "勝って", "is_correct": false, "explanation": "て形は文末にならず、ここでは文が完結しない。"}, {"text": "勝てば", "is_correct": false, "explanation": "仮定形は続く主節が必要で、文末では成立しない。"}, {"text": "勝ち", "is_correct": false, "explanation": "連用形の語幹だけでは述語として文を終えられない。"}], "explanations": {"勝った": "過去形で文を終えられ、「弱いチームが強いチームに勝った」と自然につながる。", "勝って": "て形は文末にならず、ここでは文が完結しない。", "勝てば": "仮定形は続く主節が必要で、文末では成立しない。", "勝ち": "連用形の語幹だけでは述語として文を終えられない。"}, "sentence_index": 0, "correct_answer": "勝った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は友だちと鉛筆に勝って、新しいペンを手に入れた。", "explanation": "ここは〈交換する〉の意味。勝つは相手を負かす動詞で、物をやりとりする文では使わない。"}, {"text": "彼女は努力の末、ついに新しい家に勝った。", "explanation": "ここは〈手に入れる〉の意味。勝つは相手を負かす動詞で、家を手に入れる文では使わない。"}, {"text": "彼は毎日、家族のために料理に勝った。", "explanation": "ここは〈作る〉の意味。勝つは相手を負かす動詞で、料理を作る文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37364, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勝ちました", "is_correct": true, "explanation": "丁寧な過去形で、「サッカーの試合に勝ちました」と文を終えられる。"}, {"text": "勝たせ", "is_correct": false, "explanation": "使役の語幹で、文の述語として終えられない。"}, {"text": "勝ったら", "is_correct": false, "explanation": "たら形は条件節で、ここでは文が完結しない。"}, {"text": "勝ちに", "is_correct": false, "explanation": "目的を表す形は続きが必要で、文末に置けない。"}], "explanations": {"勝ちました": "丁寧な過去形で、「サッカーの試合に勝ちました」と文を終えられる。", "勝たせ": "使役の語幹で、文の述語として終えられない。", "勝ったら": "たら形は条件節で、ここでは文が完結しない。", "勝ちに": "目的を表す形は続きが必要で、文末に置けない。"}, "sentence_index": 6, "correct_answer": "勝ちました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日練習を重ねて、ついに大きな絵本に勝った。", "explanation": "ここは〈読む〉の意味。勝つは相手を負かす動詞で、絵本を読む文では使わない。"}, {"text": "店長は毎朝、スープに勝って、お客さんに出した。", "explanation": "ここは〈温める〉の意味。勝つは相手に打ち勝つ動詞で、スープを温める文では使わない。"}, {"text": "ようやく新しいノートパソコンに勝った。", "explanation": "ここは〈購入する〉の意味。勝つは相手に対して使い、物を買う文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37364, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日は弟を囲碁で勝った。", "corrected_sentence": "昨日は弟に囲碁で勝った。", "error_description": "「勝つ」は相手を「に」で示す。「弟を」は誤りで、正しくは「弟に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "勝って", "is_correct": true, "explanation": "て形で、後ろの「みんなで喜んだ」へ接続している。"}, {"text": "勝てば", "is_correct": false, "explanation": "仮定形では「喜んだ」へ接続できず、文が成り立たない。"}, {"text": "勝ちます", "is_correct": false, "explanation": "丁寧形は文中の接続に使えず、普通体の文と合わない。"}, {"text": "勝たない", "is_correct": false, "explanation": "否定形にすると勝たなかったという反対の内容になる。"}], "correct_form": "勝って", "base_form": "勝つ", "form_label": "て形", "sentence_index": 1, "explanations": {"勝って": "て形で、後ろの「みんなで喜んだ」へ接続している。", "勝てば": "仮定形では「喜んだ」へ接続できず、文が成り立たない。", "勝ちます": "丁寧形は文中の接続に使えず、普通体の文と合わない。", "勝たない": "否定形にすると勝たなかったという反対の内容になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37364, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "相手のミスで、ぼくたちは勝たった。", "corrected_sentence": "相手のミスで、ぼくたちは勝った。", "error_description": "「勝つ」の過去形は「勝った」。「勝たった」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "勝つ", "is_correct": true, "explanation": "辞書形で、「ことができる」に続く形として正しい。"}, {"text": "勝ちたい", "is_correct": false, "explanation": "願望形は「ことができる」と意味が合わず、文の内容と一致しない。"}, {"text": "勝てる", "is_correct": false, "explanation": "可能形を「ことができる」と重ねると不自然で、文が成り立たない。"}, {"text": "勝った", "is_correct": false, "explanation": "過去形は未来の可能性を述べる文と時制が合わない。"}], "correct_form": "勝つ", "base_form": "勝つ", "form_label": "辞書形", "sentence_index": 7, "explanations": {"勝つ": "辞書形で、「ことができる」に続く形として正しい。", "勝ちたい": "願望形は「ことができる」と意味が合わず、文の内容と一致しない。", "勝てる": "可能形を「ことができる」と重ねると不自然で、文が成り立たない。", "勝った": "過去形は未来の可能性を述べる文と時制が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37365, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「議論に」は勝つ相手を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「勝つ」は「を」を目的語にとらず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では議論が勝つ相手にならず、文が不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では勝つ相手を示せず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「議論に」は勝つ相手を示す「に」。", "を": "「勝つ」は「を」を目的語にとらず、文が成り立たない。", "から": "起点の「から」では議論が勝つ相手にならず、文が不自然になる。", "より": "比較の「より」では勝つ相手を示せず、文が成り立たない。"}, "error_tags": {"を": "目的語", "から": "起点", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "負ける", "is_correct": true, "explanation": "競争や議論の勝ち負けで対になる対義語。"}, {"text": "眠る", "is_correct": false, "explanation": "勝つの対義語ではなく、睡眠を表す動詞。"}, {"text": "歩く", "is_correct": false, "explanation": "勝つの対義語ではなく、移動を表す動詞。"}, {"text": "話す", "is_correct": false, "explanation": "勝つの対義語ではなく、言葉を発する動詞。"}], "correct_answer": "負ける", "explanations": {"負ける": "競争や議論の勝ち負けで対になる対義語。", "眠る": "勝つの対義語ではなく、睡眠を表す動詞。", "歩く": "勝つの対義語ではなく、移動を表す動詞。", "話す": "勝つの対義語ではなく、言葉を発する動詞。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37365, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「入札で」は勝った場面を示す「で」。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では入札の場面を示せず、文が不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "共同の「と」では入札の場面を示せず、意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」では入札が勝つ主体にならず、文が不自然になる。"}], "correct_answer": "で", "explanations": {"で": "「入札で」は勝った場面を示す「で」。", "へ": "方向の「へ」では入札の場面を示せず、文が不自然になる。", "と": "共同の「と」では入札の場面を示せず、意味が通らない。", "が": "主語の「が」では入札が勝つ主体にならず、文が不自然になる。"}, "error_tags": {"へ": "方向", "と": "共同", "が": "主語"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "負ける", "is_correct": true, "explanation": "競争で勝つことの対義語。"}, {"text": "運ぶ", "is_correct": false, "explanation": "勝つの対義語ではなく、物を移動させる動詞。"}, {"text": "集める", "is_correct": false, "explanation": "勝つの対義語ではなく、ものを寄せる動詞。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "勝つの対義語ではなく、水中での動作を表す動詞。"}], "correct_answer": "負ける", "explanations": {"負ける": "競争で勝つことの対義語。", "運ぶ": "勝つの対義語ではなく、物を移動させる動詞。", "集める": "勝つの対義語ではなく、ものを寄せる動詞。", "泳ぐ": "勝つの対義語ではなく、水中での動作を表す動詞。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37365, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "競争や戦いにおいて、相手よりも優れた結果を出して、成功すること。", "primary_collocate": null, "pronunciation": "かつ", "ipa": "katsɯ", "syllable_count": 2, "sentences": [{"text": "選挙で勝つために、毎日町を歩いて話を聞いた。", "target_word": "勝つ", "complexity_tier": "T3", "furigana": "選挙[せんきょ]で勝[か]つために、毎日[まいにち]町[まち]を歩[ある]いて話[はなし]を聞[き]いた。", "sentence_source": "generated"}, {"text": "彼は議論に勝ったが、友だちを失ってしまった。", "target_word": "勝った", "complexity_tier": "T3", "furigana": "彼[かれ]は議論[ぎろん]に勝[か]ったが、友[とも]だちを失[うしな]ってしまった。", "sentence_source": "generated"}, {"text": "新しい商品で他社に勝つには、値段を下げるしかない。", "target_word": "勝つ", "complexity_tier": "T3", "furigana": "新[あたら]しい商品[しょうひん]で他社[たしゃ]に勝[か]つには、値段[ねだん]を下[さ]げるしかない。", "sentence_source": "generated"}, {"text": "努力を続けた彼女は、ついにコンテストで勝った。", "target_word": "勝った", "complexity_tier": "T3", "furigana": "努力[どりょく]を続[つづ]けた彼女[かのじょ]は、ついにコンテストで勝[か]った。", "sentence_source": "generated"}, {"text": "競争に勝つことより、自分の力を出すことが大切だ。", "target_word": "勝つ", "complexity_tier": "T3", "furigana": "競争[きょうそう]に勝[か]つことより、自分[じぶん]の力[ちから]を出[だ]すことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "この裁判に勝てば、会社の名前を守ることができる。", "target_word": "勝てば", "complexity_tier": "T3", "furigana": "この裁判[さいばん]に勝[か]てば、会社[かいしゃ]の名前[なまえ]を守[まも]ることができる。", "sentence_source": "generated"}, {"text": "戦争で勝った国も、多くのものを失った。", "target_word": "勝った", "complexity_tier": "T3", "furigana": "戦争[せんそう]で勝[か]った国[くに]も、多[おお]くのものを失[うしな]った。", "sentence_source": "generated"}, {"text": "入札で勝った会社が、新しい橋をつくる。", "target_word": "勝った", "complexity_tier": "T3", "furigana": "入札[にゅうさつ]で勝[か]った会社[かいしゃ]が、新[あたら]しい橋[はし]をつくる。", "sentence_source": "generated"}, {"text": "彼らは強いライバルに勝って、全国大会への切符を手に入れた。", "target_word": "勝って", "complexity_tier": "T3", "furigana": "彼[かれ]らは強[つよ]いライバルに勝[か]って、全国[ぜんこく]大会[たいかい]への切符[きっぷ]を手[て]に入[い]れた。", "sentence_source": "generated"}, {"text": "勝てなかった理由を考えて、次の準備を始めた。", "target_word": "勝てなかった", "complexity_tier": "T3", "furigana": "勝[か]てなかった理由[りゆう]を考[かんが]えて、次[つぎ]の準備[じゅんび]を始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "勝つ", "label": "辞書形"}, {"form": "勝ちます", "label": "丁寧形"}, {"form": "勝った", "label": "過去形"}, {"form": "勝って", "label": "て形"}, {"form": "勝たない", "label": "否定形"}, {"form": "勝てば", "label": "仮定形"}, {"form": "勝てる", "label": "可能形"}], "register": "標準", "sense_fingerprint": "選挙・議論・商売などの競争で相手より上の結果を出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215eb90-f0e8-463e-beea-b84a82a01593') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37365, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勝つ", "is_correct": true, "explanation": "辞書形で「ために」に続き、「選挙で勝つために」と自然につながる。"}, {"text": "勝って", "is_correct": false, "explanation": "て形は「ために」へ続かず、目的の文として成り立たない。"}, {"text": "勝てば", "is_correct": false, "explanation": "仮定形は「ために」へ続けられず、文が不自然になる。"}, {"text": "勝ち", "is_correct": false, "explanation": "連用形は「ために」へ続けられず、文が成り立たない。"}], "explanations": {"勝つ": "辞書形で「ために」に続き、「選挙で勝つために」と自然につながる。", "勝って": "て形は「ために」へ続かず、目的の文として成り立たない。", "勝てば": "仮定形は「ために」へ続けられず、文が不自然になる。", "勝ち": "連用形は「ために」へ続けられず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "勝つ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は朝、プリントに勝って、生徒に配った。", "explanation": "ここは〈配る〉の意味。勝つは競争の相手を負かす動詞で、プリントを配る文では使わない。"}, {"text": "彼女は一週間かけて、大きな絵に勝った。", "explanation": "ここは〈描く〉の意味。勝つは競争の相手に使い、絵を描く文では使わない。"}, {"text": "彼は貯金を全部使って、新しい自転車に勝った。", "explanation": "ここは〈買う〉の意味。勝つは競争の相手に使い、物を買う文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37365, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勝った", "is_correct": true, "explanation": "過去形の連体修飾で、「戦争で勝った国も」と名詞を修飾できる。"}, {"text": "勝たせ", "is_correct": false, "explanation": "使役の語幹で、名詞を修飾する形として成り立たない。"}, {"text": "勝ちに", "is_correct": false, "explanation": "目的の形は名詞を修飾できず、文が不自然になる。"}, {"text": "勝たず", "is_correct": false, "explanation": "打ち消しの連用形では名詞を修飾できず、文が成り立たない。"}], "explanations": {"勝った": "過去形の連体修飾で、「戦争で勝った国も」と名詞を修飾できる。", "勝たせ": "使役の語幹で、名詞を修飾する形として成り立たない。", "勝ちに": "目的の形は名詞を修飾できず、文が不自然になる。", "勝たず": "打ち消しの連用形では名詞を修飾できず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "勝った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はアルバイトを続けて、ついに念願のマイホームに勝った。", "explanation": "ここは〈手に入れる〉の意味。勝つは競争の相手に使い、家を手に入れる文では使わない。"}, {"text": "彼女は徹夜して、ついに長い論文に勝った。", "explanation": "ここは〈完成させる〉の意味。勝つは競争の相手に使い、書類を完成させる文では使わない。"}, {"text": "研究チームは徹夜の末、画期的な模型に勝った。", "explanation": "ここは〈組み立てる〉の意味。勝つは競争の相手に使い、模型を組み立てる文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37365, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "選挙を勝つために、毎日町を歩いて話を聞いた。", "corrected_sentence": "選挙に勝つために、毎日町を歩いて話を聞いた。", "error_description": "「勝つ」は相手や対象を「に」で示す。「選挙を」は誤りで、正しくは「選挙に」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "勝った", "is_correct": true, "explanation": "過去形で、議論の結果を表す文に合う。"}, {"text": "勝たせ", "is_correct": false, "explanation": "使役の語幹で、「が」に続けると文が成り立たない。"}, {"text": "勝て", "is_correct": false, "explanation": "命令・条件の語幹で、「が」に続けると文が成り立たない。"}, {"text": "勝ちに", "is_correct": false, "explanation": "目的を表す形で、「が」に続けると文が成り立たない。"}], "correct_form": "勝った", "base_form": "勝つ", "form_label": "過去形", "sentence_index": 1, "explanations": {"勝った": "過去形で、議論の結果を表す文に合う。", "勝たせ": "使役の語幹で、「が」に続けると文が成り立たない。", "勝て": "命令・条件の語幹で、「が」に続けると文が成り立たない。", "勝ちに": "目的を表す形で、「が」に続けると文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37365, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "コンテストで勝えたので、家族は喜んだ。", "corrected_sentence": "コンテストで勝ったので、家族は喜んだ。", "error_description": "「勝つ」の過去形は「勝った」。「勝えた」は存在しない活用形の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "勝った", "is_correct": true, "explanation": "過去形で、勝った会社を修飾する形として正しい。"}, {"text": "勝とう", "is_correct": false, "explanation": "意向形で、「入札で勝とう会社が」と名詞を修飾できず、文が成り立たない。"}, {"text": "勝てば", "is_correct": false, "explanation": "仮定形では名詞を修飾できず、文が成り立たない。"}, {"text": "勝ちます", "is_correct": false, "explanation": "丁寧形は名詞を修飾できず、「入札で勝ちます会社」は成り立たない。"}], "correct_form": "勝った", "base_form": "勝つ", "form_label": "過去形", "sentence_index": 7, "explanations": {"勝った": "過去形で、勝った会社を修飾する形として正しい。", "勝とう": "意向形で、「入札で勝とう会社が」と名詞を修飾できず、文が成り立たない。", "勝てば": "仮定形では名詞を修飾できず、文が成り立たない。", "勝ちます": "丁寧形は名詞を修飾できず、「入札で勝ちます会社」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37366, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「才能を発揮した」の目的語を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「才能に発揮した」は成り立たず、目的語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "共同の「と」では才能を発揮する対象にならず、文が不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では発揮の目的語にならず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「才能を発揮した」の目的語を示す「を」。", "に": "「才能に発揮した」は成り立たず、目的語を示せない。", "と": "共同の「と」では才能を発揮する対象にならず、文が不自然になる。", "へ": "方向の「へ」では発揮の目的語にならず、文が成り立たない。"}, "error_tags": {"に": "到達点", "と": "共同", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
