INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37366, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分の力や才能を、しっかりと外に出して見せること。", "primary_collocate": null, "pronunciation": "はっき", "ipa": "hakki", "syllable_count": 3, "sentences": [{"text": "本番で力を発揮するために、毎日練習している。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "本番[ほんばん]で力[ちから]を発揮[はっき]するために、毎日[まいにち]練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "彼女は舞台で、すばらしい才能を発揮した。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は舞台[ぶたい]で、すばらしい才能[さいのう]を発揮[はっき]した。", "sentence_source": "generated"}, {"text": "緊張していて、実力を発揮できなかった。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "緊張[きんちょう]していて、実力[じつりょく]を発揮[はっき]できなかった。", "sentence_source": "generated"}, {"text": "新人の彼は、初めての試合で本当の強さを発揮した。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "新人[しんじん]の彼[かれ]は、初[はじ]めての試合[しあい]で本当[ほんとう]の強[つよ]さを発揮[はっき]した。", "sentence_source": "generated"}, {"text": "リーダーとしての力を発揮する機会が来た。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "リーダーとしての力[ちから]を発揮[はっき]する機会[きかい]が来[き]た。", "sentence_source": "generated"}, {"text": "彼は大きな舞台でも、自分らしさを発揮した。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "彼[かれ]は大[おお]きな舞台[ぶたい]でも、自分[じぶん]らしさを発揮[はっき]した。", "sentence_source": "generated"}, {"text": "力を発揮したいなら、まず体調を整えなさい。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "力[ちから]を発揮[はっき]したいなら、まず体調[たいちょう]を整[ととの]えなさい。", "sentence_source": "generated"}, {"text": "部員全員が、持てる力を発揮して戦った。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "部員[ぶいん]全員[ぜんいん]が、持[も]てる力[ちから]を発揮[はっき]して戦[たたか]った。", "sentence_source": "generated"}, {"text": "絵の才能を発揮する場所が見つかって、彼は嬉しそうだ。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "絵[え]の才能[さいのう]を発揮[はっき]する場所[ばしょ]が見[み]つかって、彼[かれ]は嬉[うれ]しそうだ。", "sentence_source": "generated"}, {"text": "練習ではうまくできても、試合で発揮できなければ意味がない。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "練習[れんしゅう]ではうまくできても、試合[しあい]で発揮[はっき]できなければ意味[いみ]がない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発揮", "label": "語幹"}, {"form": "発揮する", "label": "辞書形"}, {"form": "発揮します", "label": "丁寧形"}, {"form": "発揮した", "label": "過去形"}, {"form": "発揮して", "label": "て形"}, {"form": "発揮できる", "label": "可能形"}], "register": "標準", "sense_fingerprint": "自分の力や才能を人前ではっきり見せる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215eb90-f0e8-463e-beea-b84a82a01593') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37366, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発揮", "is_correct": true, "explanation": "「力を発揮するために」と、〈力を見せる〉の意味で自然につながる。"}, {"text": "反省", "is_correct": false, "explanation": "「力を反省する」は成り立たず、空欄に入らない。"}, {"text": "遠慮", "is_correct": false, "explanation": "「力を遠慮する」は成り立たず、文の意味が通らない。"}, {"text": "勝利", "is_correct": false, "explanation": "「力を勝利する」は成り立たず、文が不自然になる。"}], "explanations": {"発揮": "「力を発揮するために」と、〈力を見せる〉の意味で自然につながる。", "反省": "「力を反省する」は成り立たず、空欄に入らない。", "遠慮": "「力を遠慮する」は成り立たず、文の意味が通らない。", "勝利": "「力を勝利する」は成り立たず、文が不自然になる。"}, "sentence_index": 0, "correct_answer": "発揮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "研究所は、この冬に新しい機械を発揮した。", "explanation": "ここは〈発明する〉の意味。発揮は力や才能を見せる意味で、機械を作る文では使わない。"}, {"text": "研究者は、新しい実験の結果を発揮した。", "explanation": "ここは〈発表する〉の意味。発揮は力や才能を見せる意味で、結果を公開する文では使わない。"}, {"text": "天文台の観測チームが、夜空に新しい星を発揮した。", "explanation": "ここは〈発見する〉の意味。発揮は力や才能を見せる意味で、星を見つける文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37366, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発揮", "is_correct": true, "explanation": "「力を発揮したいなら」と、〈力を見せる〉の意味で自然につながる。"}, {"text": "謝罪", "is_correct": false, "explanation": "「力を謝罪したい」は成り立たず、文の意味が通らない。"}, {"text": "翻訳", "is_correct": false, "explanation": "「力を翻訳したい」は成り立たず、空欄に入らない。"}, {"text": "解雇", "is_correct": false, "explanation": "「力を解雇したい」は成り立たず、文が不自然になる。"}], "explanations": {"発揮": "「力を発揮したいなら」と、〈力を見せる〉の意味で自然につながる。", "謝罪": "「力を謝罪したい」は成り立たず、文の意味が通らない。", "翻訳": "「力を翻訳したい」は成り立たず、空欄に入らない。", "解雇": "「力を解雇したい」は成り立たず、文が不自然になる。"}, "sentence_index": 6, "correct_answer": "発揮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その会社は去年、新しいゲームを発揮した。", "explanation": "ここは〈発売する〉の意味。発揮は力や才能を見せる意味で、商品を売り出す文では使わない。"}, {"text": "考古学者のチームが、古代の遺跡を発揮した。", "explanation": "ここは〈発掘する〉の意味。発揮は力や才能を見せる意味で、遺跡を掘り出す文では使わない。"}, {"text": "町は、大きな公園を発揮した。", "explanation": "ここは〈建設する〉の意味。発揮は力や才能を見せる意味で、公園を造る文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
