INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37367, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "持っている能力や特性を、実際の行動や結果に表すこと。", "primary_collocate": null, "pronunciation": "はっき", "ipa": "hakki", "syllable_count": 3, "sentences": [{"text": "この薬は飲むとすぐに効果を発揮する。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "この薬[くすり]は飲[の]むとすぐに効果[こうか]を発揮[はっき]する。", "sentence_source": "generated"}, {"text": "新しいエンジンは、坂道で本当の性能を発揮する。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "新[あたら]しいエンジンは、坂道[さかみち]で本当[ほんとう]の性能[せいのう]を発揮[はっき]する。", "sentence_source": "generated"}, {"text": "雨の日にこそ、この靴は特別な機能を発揮する。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]にこそ、この靴[くつ]は特別[とくべつ]な機能[きのう]を発揮[はっき]する。", "sentence_source": "generated"}, {"text": "チームワークを発揮した結果、難しい仕事が早く終わった。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "チームワークを発揮[はっき]した結果[けっか]、難[むずか]しい仕事[しごと]が早[はや]く終[お]わった。", "sentence_source": "generated"}, {"text": "彼の粘り強さは、交渉の場で大きな威力を発揮した。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "彼[かれ]の粘[ねば]り強[づよ]さは、交渉[こうしょう]の場[ば]で大[おお]きな威力[いりょく]を発揮[はっき]した。", "sentence_source": "generated"}, {"text": "このクリームは、乾燥した季節に高い保湿力を発揮する。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "このクリームは、乾燥[かんそう]した季節[きせつ]に高[たか]い保湿力[ほしつりょく]を発揮[はっき]する。", "sentence_source": "generated"}, {"text": "彼は責任感の強さを発揮して、最後まで仕事をやりとげた。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "彼[かれ]は責任感[せきにんかん]の強[つよ]さを発揮[はっき]して、最後[さいご]まで仕事[しごと]をやりとげた。", "sentence_source": "generated"}, {"text": "この道具は、使い方を知ると、驚くほどの便利さを発揮する。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "この道具[どうぐ]は、使[つか]い方[かた]を知[し]ると、驚[おどろ]くほどの便利[べんり]さを発揮[はっき]する。", "sentence_source": "generated"}, {"text": "犬の鼻のよさは、災害の現場で力を発揮している。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "犬[いぬ]の鼻[はな]のよさは、災害[さいがい]の現場[げんば]で力[ちから]を発揮[はっき]している。", "sentence_source": "generated"}, {"text": "専門家の技術が発揮され、古い建物がきれいに直った。", "target_word": "発揮", "complexity_tier": "T3", "furigana": "専門家[せんもんか]の技術[ぎじゅつ]が発揮[はっき]され、古[ふる]い建物[たてもの]がきれいに直[なお]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発揮", "label": "語幹"}, {"form": "発揮する", "label": "辞書形"}, {"form": "発揮した", "label": "過去形"}, {"form": "発揮して", "label": "て形"}, {"form": "発揮している", "label": "進行形"}, {"form": "発揮される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "人や物の能力・特性が実際の働きや結果として現れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: やりとげ (Zipf 1.99)']::text[], '4215eb90-f0e8-463e-beea-b84a82a01593') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37367, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発揮", "is_correct": true, "explanation": "「効果を発揮する」と、薬の働きが現れる意味で自然につながる。"}, {"text": "反省", "is_correct": false, "explanation": "「効果を反省する」は成り立たず、空欄に入らない。"}, {"text": "辞退", "is_correct": false, "explanation": "「効果を辞退する」は成り立たず、文が不自然になる。"}, {"text": "禁止", "is_correct": false, "explanation": "「効果を禁止する」は成り立たず、文の意味が通らない。"}], "explanations": {"発揮": "「効果を発揮する」と、薬の働きが現れる意味で自然につながる。", "反省": "「効果を反省する」は成り立たず、空欄に入らない。", "辞退": "「効果を辞退する」は成り立たず、文が不自然になる。", "禁止": "「効果を禁止する」は成り立たず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "発揮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察は新しい証拠を発揮して、犯人の名前を明らかにした。", "explanation": "ここは〈示す〉の意味。発揮は働きや特性が現れる意味で、証拠を提示する文では使わない。"}, {"text": "役所は、新しい住民票を発揮した。", "explanation": "ここは〈発行する〉の意味。発揮は働きや特性が現れる意味で、書類を出す文では使わない。"}, {"text": "私は夏休みの計画表を発揮した。", "explanation": "ここは〈作成する〉の意味。発揮は働きや特性が現れる意味で、計画表を作る文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37367, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発揮", "is_correct": true, "explanation": "「責任感の強さを発揮して」と、性質が現れる意味で自然につながる。"}, {"text": "謝罪", "is_correct": false, "explanation": "「責任感の強さを謝罪して」は成り立たず、文の意味が通らない。"}, {"text": "翻訳", "is_correct": false, "explanation": "「責任感の強さを翻訳して」は成り立たず、空欄に入らない。"}, {"text": "解雇", "is_correct": false, "explanation": "「責任感の強さを解雇して」は成り立たず、文が不自然になる。"}], "explanations": {"発揮": "「責任感の強さを発揮して」と、性質が現れる意味で自然につながる。", "謝罪": "「責任感の強さを謝罪して」は成り立たず、文の意味が通らない。", "翻訳": "「責任感の強さを翻訳して」は成り立たず、空欄に入らない。", "解雇": "「責任感の強さを解雇して」は成り立たず、文が不自然になる。"}, "sentence_index": 6, "correct_answer": "発揮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大工さんは、ばらばらの部品を発揮した。", "explanation": "ここは〈組み立てる〉の意味。発揮は働きや特性が現れる意味で、部品を組み立てる文では使わない。"}, {"text": "職人は、壊れた古い時計を発揮した。", "explanation": "ここは〈修理する〉の意味。発揮は働きや特性が現れる意味で、時計を直す文では使わない。"}, {"text": "工場は毎日、新しい部品を発揮している。", "explanation": "ここは〈製造する〉の意味。発揮は働きや特性が現れる意味で、部品を作る文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37367, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この錠剤は飲むとすぐに効果に発揮する。", "corrected_sentence": "この錠剤は飲むとすぐに効果を発揮する。", "error_description": "「発揮する」は「を」で目的語を示す。「効果に」は誤りで、正しくは「効果を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37367, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その会社員は責任感の強さを発揮たので、最後まで仕事を任された。", "corrected_sentence": "その会社員は責任感の強さを発揮したので、最後まで仕事を任された。", "error_description": "「発揮する」の過去形は「発揮した」。「発揮た」は「し」が抜けた誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37368, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「声を」の「を」。掛け合う動作の対象（声）を示す格助詞で、この文に正しく入る。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「声の掛け合った」では文が続かず、対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「声へ掛け合った」は不自然で、対象を示す用法に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」。「声から掛け合った」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「声を」の「を」。掛け合う動作の対象（声）を示す格助詞で、この文に正しく入る。", "の": "連体修飾の「の」。「声の掛け合った」では文が続かず、対象を示せない。", "へ": "方向を示す「へ」。「声へ掛け合った」は不自然で、対象を示す用法に合わない。", "から": "起点を示す「から」。「声から掛け合った」は意味が通らない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37368, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「声を」の「を」。掛け合う動作の対象（声）を示す格助詞で、この文に正しく入る。"}, {"text": "に", "is_correct": false, "explanation": "「声に掛け合って」は対象の示し方として不自然で、動作の対象を示す用法に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「声と掛け合って」は対象の示し方として不自然で、この文の構造に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「声より掛け合って」は比較の意味になり、動作の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「声を」の「を」。掛け合う動作の対象（声）を示す格助詞で、この文に正しく入る。", "に": "「声に掛け合って」は対象の示し方として不自然で、動作の対象を示す用法に合わない。", "と": "「声と掛け合って」は対象の示し方として不自然で、この文の構造に合わない。", "より": "比較の「より」。「声より掛け合って」は比較の意味になり、動作の対象を示せない。"}, "error_tags": {"に": "方向・対象", "と": "相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37368, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二人がおたがいに声を出し合うことです。", "primary_collocate": null, "pronunciation": "かけあう", "ipa": "kakeaɯ", "syllable_count": 4, "sentences": [{"text": "二人は大きな声を掛け合って、重い机を運んだ。", "target_word": "掛け合って", "complexity_tier": "T3", "furigana": "二人[ふたり]は大[おお]きな声[こえ]を掛[か]け合[あ]って、重[おも]い机[つくえ]を運[はこ]んだ。", "sentence_source": "generated"}, {"text": "山の上と下で、友だちと声を掛け合った。", "target_word": "掛け合った", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]と下[した]で、友[とも]だちと声[こえ]を掛[か]け合[あ]った。", "sentence_source": "generated"}, {"text": "祭りでは、二組が「よいしょ」と掛け合う。", "target_word": "掛け合う", "complexity_tier": "T3", "furigana": "祭[まつ]りでは、二組[ふたくみ]が「よいしょ」と掛[か]け合[あ]う。", "sentence_source": "generated"}, {"text": "兄と弟は、走りながら「がんばれ」と掛け合っていた。", "target_word": "掛け合って", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]は、走[はし]りながら「がんばれ」と掛[か]け合[あ]っていた。", "sentence_source": "generated"}, {"text": "霧が深くても、声を掛け合えば、はぐれない。", "target_word": "掛け合えば", "complexity_tier": "T3", "furigana": "霧[きり]が深[ふか]くても、声[こえ]を掛[か]け合[あ]えば、はぐれない。", "sentence_source": "generated"}, {"text": "太鼓の前で、二人は互いに声を掛け合って気合いを入れた。", "target_word": "掛け合って", "complexity_tier": "T3", "furigana": "太鼓[たいこ]の前[まえ]で、二人[ふたり]は互[たが]いに声[こえ]を掛[か]け合[あ]って気合[きあ]いを入[い]れた。", "sentence_source": "generated"}, {"text": "先生と生徒が元気に声を掛け合って、教室は明るくなった。", "target_word": "掛け合って", "complexity_tier": "T3", "furigana": "先生[せんせい]と生徒[せいと]が元気[げんき]に声[こえ]を掛[か]け合[あ]って、教室[きょうしつ]は明[あか]るくなった。", "sentence_source": "generated"}, {"text": "暗い道では、お互いに声を掛け合って歩いた。", "target_word": "掛け合って", "complexity_tier": "T3", "furigana": "暗[くら]い道[みち]では、お互[たが]いに声[こえ]を掛[か]け合[あ]って歩[ある]いた。", "sentence_source": "generated"}, {"text": "漫才の二人が、テンポよく言葉を掛け合っている。", "target_word": "掛け合って", "complexity_tier": "T3", "furigana": "漫才[まんざい]の二人[ふたり]が、テンポよく言葉[ことば]を掛[か]け合[あ]っている。", "sentence_source": "generated"}, {"text": "船の上で、漁師たちは「せーの」と掛け合って網を引いた。", "target_word": "掛け合って", "complexity_tier": "T3", "furigana": "船[ふね]の上[うえ]で、漁師[りょうし]たちは「せーの」と掛[か]け合[あ]って網[あみ]を引[ひ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "掛け合う", "label": "辞書形"}, {"form": "掛け合います", "label": "丁寧形"}, {"form": "掛け合った", "label": "過去形"}, {"form": "掛け合って", "label": "て形"}, {"form": "掛け合わない", "label": "否定形"}, {"form": "掛け合えば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "二人（以上）が合図や調子を合わせて声を出し合う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215eb90-f0e8-463e-beea-b84a82a01593') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37368, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掛け合って", "is_correct": true, "explanation": "「掛け合う」は互いに声を出し合うこと。二人で大きな声を掛け合い、重い机を運ぶ文脈に合う。"}, {"text": "数えて", "is_correct": false, "explanation": "「数える」は数を数える意味。大きな声を数えるという内容は文意に合わない。"}, {"text": "測って", "is_correct": false, "explanation": "「測る」は長さや重さを量る意味。声を測るとは言えず、文が成り立たない。"}, {"text": "煮て", "is_correct": false, "explanation": "「煮る」は食材を加熱して調理する意味。声には使えず、文脈にも合わない。"}], "explanations": {"掛け合って": "「掛け合う」は互いに声を出し合うこと。二人で大きな声を掛け合い、重い机を運ぶ文脈に合う。", "数えて": "「数える」は数を数える意味。大きな声を数えるという内容は文意に合わない。", "測って": "「測る」は長さや重さを量る意味。声を測るとは言えず、文が成り立たない。", "煮て": "「煮る」は食材を加熱して調理する意味。声には使えず、文脈にも合わない。"}, "sentence_index": 0, "correct_answer": "掛け合って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新任の先生は、遅刻した生徒を廊下で大声で掛け合った。", "explanation": "〈叱る〉と取り違えた用法。〈掛け合う〉は互いに声を出し合うことなので、先生から生徒への一方的な叱責には使えない。"}, {"text": "帰り道、先生は一人の生徒にそっと掛け合った。", "explanation": "〈声をかける〉と取り違えた用法。〈掛け合う〉は互いに声を出し合うことなので、先生から生徒への一方的な声かけには使えない。"}, {"text": "市長は駅前で市民に避難を掛け合った。", "explanation": "〈呼びかける〉と取り違えた用法。〈呼びかける〉は一方が訴えることだが、〈掛け合う〉は互いに出し合うことなので、市長から市民への一方的な訴えには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37368, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掛け合って", "is_correct": true, "explanation": "「掛け合う」は互いに声を掛け合うこと。先生と生徒が声を掛け合い、教室が明るくなる文脈に合う。"}, {"text": "担いで", "is_correct": false, "explanation": "「担ぐ」は肩などに載せて運ぶ意味。声を担ぐとは言えず、文が成り立たない。"}, {"text": "結んで", "is_correct": false, "explanation": "「結ぶ」は紐などをつなぐ意味。声には使えず、文脈にも合わない。"}, {"text": "削って", "is_correct": false, "explanation": "「削る」は表面を薄く取り除く意味。声を削るという表現は成り立たない。"}], "explanations": {"掛け合って": "「掛け合う」は互いに声を掛け合うこと。先生と生徒が声を掛け合い、教室が明るくなる文脈に合う。", "担いで": "「担ぐ」は肩などに載せて運ぶ意味。声を担ぐとは言えず、文が成り立たない。", "結んで": "「結ぶ」は紐などをつなぐ意味。声には使えず、文脈にも合わない。", "削って": "「削る」は表面を薄く取り除く意味。声を削るという表現は成り立たない。"}, "sentence_index": 6, "correct_answer": "掛け合って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ゴールが決まると、彼は大声で掛け合った。", "explanation": "〈叫ぶ〉と取り違えた用法。〈叫ぶ〉は一人でもできるが、〈掛け合う〉は二人以上が互いに声を出し合うことなので、一人の「彼」には合わない。"}, {"text": "彼女は小声で独り言を掛け合った。", "explanation": "〈つぶやく〉と取り違えた用法。〈つぶやく〉は一人の独り言だが、〈掛け合う〉は互いに声を出し合うことなので、独り言には使わない。"}, {"text": "母は弟に、道路で走らないよう掛け合った。", "explanation": "〈言い聞かせる〉と取り違えた用法。〈掛け合う〉は互いに声を出し合う意味で、母から弟への一方的な言い聞かせには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37368, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三人は互いに声に掛け合って、荷物を運んだ。", "corrected_sentence": "三人は互いに声を掛け合って、荷物を運んだ。", "error_description": "「声を掛け合う」の対象は「を」で示す。「声に掛け合う」は不自然なので、助詞「に」を「を」に直す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "掛け合った", "is_correct": true, "explanation": "過去形で、山の上と下で友だちと声を掛け合った過去の出来事を述べている。"}, {"text": "掛け合って", "is_correct": false, "explanation": "て形は後ろに続く文が必要で、この文は「掛け合って。」で終わるため成り立たない。"}, {"text": "掛け合いながら", "is_correct": false, "explanation": "「ながら」は同時の動作を表し、後ろに続く動作が必要なので文末では成り立たない。"}, {"text": "掛け合えば", "is_correct": false, "explanation": "仮定形は後ろに条件の続きが必要だが、この文は途中で終わるので合わない。"}], "correct_form": "掛け合った", "base_form": "掛け合う", "form_label": "過去形", "sentence_index": 1, "explanations": {"掛け合った": "過去形で、山の上と下で友だちと声を掛け合った過去の出来事を述べている。", "掛け合って": "て形は後ろに続く文が必要で、この文は「掛け合って。」で終わるため成り立たない。", "掛け合いながら": "「ながら」は同時の動作を表し、後ろに続く動作が必要なので文末では成り立たない。", "掛け合えば": "仮定形は後ろに条件の続きが必要だが、この文は途中で終わるので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37368, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祭りの夜、若者たちは笑いながら声を掛け合いた。", "corrected_sentence": "祭りの夜、若者たちは笑いながら声を掛け合った。", "error_description": "「掛け合う」の過去形は「掛け合った」。「掛け合いた」は存在しない活用形で、語尾の変化を誤っている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "掛け合って", "is_correct": true, "explanation": "て形で、「声を掛け合いながら歩いた」と同時の動作を表す。"}, {"text": "掛け合います", "is_correct": false, "explanation": "丁寧形は文末に使う形で、「歩いた」と続けられず文が成り立たない。"}, {"text": "掛け合っている", "is_correct": false, "explanation": "進行形は「掛け合っている歩いた」とは続かず、文が成り立たない。"}, {"text": "掛け合えない", "is_correct": false, "explanation": "可能形の否定で、「掛け合えない歩いた」と続かず、文の流れに合わない。"}], "correct_form": "掛け合って", "base_form": "掛け合う", "form_label": "て形", "sentence_index": 7, "explanations": {"掛け合って": "て形で、「声を掛け合いながら歩いた」と同時の動作を表す。", "掛け合います": "丁寧形は文末に使う形で、「歩いた」と続けられず文が成り立たない。", "掛け合っている": "進行形は「掛け合っている歩いた」とは続かず、文が成り立たない。", "掛け合えない": "可能形の否定で、「掛け合えない歩いた」と続かず、文の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37369, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「言葉を」の「を」。掛け合う動作の対象（言葉）を示す格助詞で、この文に正しく入る。"}, {"text": "に", "is_correct": false, "explanation": "「言葉に掛け合っていた」は対象の示し方として不自然で、この文の動作に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「言葉と掛け合っていた」は相手を示す用法としても不自然で、この文の構造に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「言葉より掛け合っていた」は比較の意味になり、動作の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「言葉を」の「を」。掛け合う動作の対象（言葉）を示す格助詞で、この文に正しく入る。", "に": "「言葉に掛け合っていた」は対象の示し方として不自然で、この文の動作に合わない。", "と": "「言葉と掛け合っていた」は相手を示す用法としても不自然で、この文の構造に合わない。", "より": "比較の「より」。「言葉より掛け合っていた」は比較の意味になり、動作の対象を示せない。"}, "error_tags": {"に": "方向・対象", "と": "相手", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37369, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「声を」の「を」。掛け合う動作の対象（声）を示す格助詞で、この文に正しく入る。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「声の掛け合う街」では文の構造が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「声へ掛け合う」は不自然で、対象を示す用法に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す「から」。「声から掛け合う街」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「声を」の「を」。掛け合う動作の対象（声）を示す格助詞で、この文に正しく入る。", "の": "連体修飾の「の」。「声の掛け合う街」では文の構造が成り立たない。", "へ": "方向を示す「へ」。「声へ掛け合う」は不自然で、対象を示す用法に合わない。", "から": "起点を示す「から」。「声から掛け合う街」は意味が通らない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37369, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "互いに声をかけたり、話しかけたりすること。", "primary_collocate": null, "pronunciation": "かけあう", "ipa": "kakeaɯ", "syllable_count": 4, "sentences": [{"text": "朝、近所の人たちが「おはよう」と掛け合っている。", "target_word": "掛け合って", "complexity_tier": "T3", "furigana": "朝[あさ]、近所[きんじょ]の人[ひと]たちが「おはよう」と掛[か]け合[あ]っている。", "sentence_source": "generated"}, {"text": "試合中、選手たちは励ましの言葉を掛け合っていた。", "target_word": "掛け合って", "complexity_tier": "T3", "furigana": "試合中[しあいちゅう]、選手[せんしゅ]たちは励[はげ]ましの言葉[ことば]を掛[か]け合[あ]っていた。", "sentence_source": "generated"}, {"text": "親子が笑顔で声を掛け合うと、家の中が明るくなる。", "target_word": "掛け合う", "complexity_tier": "T3", "furigana": "親子[おやこ]が笑顔[えがお]で声[こえ]を掛[か]け合[あ]うと、家[いえ]の中[なか]が明[あか]るくなる。", "sentence_source": "generated"}, {"text": "同じ部屋で働く仲間は、よく声を掛け合って仕事を進める。", "target_word": "掛け合って", "complexity_tier": "T3", "furigana": "同[おな]じ部屋[へや]で働[はたら]く仲間[なかま]は、よく声[こえ]を掛[か]け合[あ]って仕事[しごと]を進[すす]める。", "sentence_source": "generated"}, {"text": "災害のとき、住民が声を掛け合って助け合った。", "target_word": "掛け合って", "complexity_tier": "T3", "furigana": "災害[さいがい]のとき、住民[じゅうみん]が声[こえ]を掛[か]け合[あ]って助[たす]け合[あ]った。", "sentence_source": "generated"}, {"text": "登山道では、すれ違う人と声を掛け合う習慣がある。", "target_word": "掛け合う", "complexity_tier": "T3", "furigana": "登山道[とざんどう]では、すれ違[ちが]う人[ひと]と声[こえ]を掛[か]け合[あ]う習慣[しゅうかん]がある。", "sentence_source": "generated"}, {"text": "新入生どうしが声を掛け合ったおかげで、すぐに友だちになれた。", "target_word": "掛け合った", "complexity_tier": "T3", "furigana": "新入生[しんにゅうせい]どうしが声[こえ]を掛[か]け合[あ]ったおかげで、すぐに友[とも]だちになれた。", "sentence_source": "generated"}, {"text": "近所で声を掛け合う街は、防犯にも強い。", "target_word": "掛け合う", "complexity_tier": "T3", "furigana": "近所[きんじょ]で声[こえ]を掛[か]け合[あ]う街[まち]は、防犯[ぼうはん]にも強[つよ]い。", "sentence_source": "generated"}, {"text": "家族が毎晩「お疲れさま」と掛け合うのが、我が家の決まりだ。", "target_word": "掛け合う", "complexity_tier": "T3", "furigana": "家族[かぞく]が毎晩[まいばん]「お疲[つか]れさま」と掛[か]け合[あ]うのが、我[わ]が家[や]の決[き]まりだ。", "sentence_source": "generated"}, {"text": "店員さんとお客さんが気軽に声を掛け合う店は、居心地がいい。", "target_word": "掛け合う", "complexity_tier": "T3", "furigana": "店員[てんいん]さんとお客[きゃく]さんが気軽[きがる]に声[こえ]を掛[か]け合[あ]う店[みせ]は、居心地[いごこち]がいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "掛け合う", "label": "辞書形"}, {"form": "掛け合います", "label": "丁寧形"}, {"form": "掛け合った", "label": "過去形"}, {"form": "掛け合って", "label": "て形"}, {"form": "掛け合わない", "label": "否定形"}, {"form": "掛け合っている", "label": "進行形"}], "register": "標準", "sense_fingerprint": "人どうしが挨拶や励ましの声を互いにかけ合う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215eb90-f0e8-463e-beea-b84a82a01593') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37369, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掛け合って", "is_correct": true, "explanation": "「掛け合う」は互いに声をかけ合うこと。近所の人たちが「おはよう」と声をかけ合う文脈に合う。"}, {"text": "磨いて", "is_correct": false, "explanation": "「磨く」は物をみがく意味。「おはよう」と磨くとは言えず、文が成り立たない。"}, {"text": "焼いて", "is_correct": false, "explanation": "「焼く」は火で加熱する意味。挨拶の言葉とは結びつかず、文脈に合わない。"}, {"text": "計って", "is_correct": false, "explanation": "「計る」は量や時間を測る意味。挨拶の場面では使えず、文が成り立たない。"}], "explanations": {"掛け合って": "「掛け合う」は互いに声をかけ合うこと。近所の人たちが「おはよう」と声をかけ合う文脈に合う。", "磨いて": "「磨く」は物をみがく意味。「おはよう」と磨くとは言えず、文が成り立たない。", "焼いて": "「焼く」は火で加熱する意味。挨拶の言葉とは結びつかず、文脈に合わない。", "計って": "「計る」は量や時間を測る意味。挨拶の場面では使えず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "掛け合って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "課長は、部下の失敗を大きな声で掛け合った。", "explanation": "〈叱る〉と取り違えた用法。〈掛け合う〉は互いに声を出し合うことなので、課長から部下への一方的な叱責には使えない。"}, {"text": "先生は出席番号順に生徒の名前を掛け合った。", "explanation": "〈呼ぶ〉と取り違えた用法。〈掛け合う〉は互いに声をかけ合うことなので、先生が一方的に名前を呼ぶ場面には合わない。"}, {"text": "彼女はノートを隣の席の友だちに掛け合った。", "explanation": "〈渡す〉と取り違えた用法。〈掛け合う〉は声を互いにかけ合うことで、ノートなど物を渡す動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37369, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掛け合った", "is_correct": true, "explanation": "過去形で、声を掛け合ったおかげで友だちになれたという前の出来事を述べている。"}, {"text": "担いだ", "is_correct": false, "explanation": "「担ぐ」は肩に載せて運ぶ意味。声には使えず、文が成り立たない。"}, {"text": "結んだ", "is_correct": false, "explanation": "「結ぶ」は紐などをつなぐ意味。声には使えず、文脈にも合わない。"}, {"text": "削った", "is_correct": false, "explanation": "「削る」は表面を薄く取り除く意味。声を削るという表現は成り立たない。"}], "explanations": {"掛け合った": "過去形で、声を掛け合ったおかげで友だちになれたという前の出来事を述べている。", "担いだ": "「担ぐ」は肩に載せて運ぶ意味。声には使えず、文が成り立たない。", "結んだ": "「結ぶ」は紐などをつなぐ意味。声には使えず、文脈にも合わない。", "削った": "「削る」は表面を薄く取り除く意味。声を削るという表現は成り立たない。"}, "sentence_index": 6, "correct_answer": "掛け合った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合が終わると、彼女は観客席に向かって一人で掛け合った。", "explanation": "〈叫ぶ〉と取り違えた用法。〈掛け合う〉は互いに声を出し合うことなので、一人で観客席に向かって叫ぶ動作には合わない。"}, {"text": "父は息子に、ひとりで遠くへ行かないよう掛け合った。", "explanation": "〈言い聞かせる〉と取り違えた用法。〈掛け合う〉は互いに声を出し合う意味で、父から息子への一方的な言い聞かせには合わない。"}, {"text": "審判は笛で掛け合った。", "explanation": "〈合図する〉と取り違えた用法。〈掛け合う〉は声を互いに出し合うことで、笛による一方的な合図には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37369, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "休み時間、クラスの友だちが笑顔で声に掛け合っている。", "corrected_sentence": "休み時間、クラスの友だちが笑顔で声を掛け合っている。", "error_description": "「声を掛け合う」の「を」を「に」にしている。「声に掛け合う」は不自然で、対象を示す「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "掛け合って", "is_correct": true, "explanation": "て形で「掛け合っていた」の形になり、「言葉を掛け合っていた」と進行の動作を表す。"}, {"text": "掛け合う", "is_correct": false, "explanation": "辞書形では「ていた」と続けられず、「掛け合う」だけでは過去の進行を表せない。"}, {"text": "掛け合った", "is_correct": false, "explanation": "過去形に「ていた」は続かず、「掛け合ったていた」となって文が成り立たない。"}, {"text": "掛け合います", "is_correct": false, "explanation": "丁寧形は文中の「ていた」と続けられず、普通体の文と合わない。"}], "correct_form": "掛け合って", "base_form": "掛け合う", "form_label": "て形", "sentence_index": 1, "explanations": {"掛け合って": "て形で「掛け合っていた」の形になり、「言葉を掛け合っていた」と進行の動作を表す。", "掛け合う": "辞書形では「ていた」と続けられず、「掛け合う」だけでは過去の進行を表せない。", "掛け合った": "過去形に「ていた」は続かず、「掛け合ったていた」となって文が成り立たない。", "掛け合います": "丁寧形は文中の「ていた」と続けられず、普通体の文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37369, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "授業の前、生徒たちは互いに声を掛け合ていた。", "corrected_sentence": "授業の前、生徒たちは互いに声を掛け合っていた。", "error_description": "「掛け合っていた」の促音「っ」が抜けている。「掛け合ていた」は誤った形で、正しくは「掛け合っていた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "掛け合う", "is_correct": true, "explanation": "辞書形で、後ろの「街は」を修飾する名詞修飾節として文が成り立つ。"}, {"text": "掛け合います", "is_correct": false, "explanation": "丁寧形は名詞を修飾できず、「掛け合います街は」とは続かない。"}, {"text": "掛け合えば", "is_correct": false, "explanation": "仮定形は条件の続きが必要で、名詞を修飾できないので「街は」につながらない。"}, {"text": "掛け合って", "is_correct": false, "explanation": "て形は後続の文へつなぐ形で、「街は」を直接修飾できず、文が成り立たない。"}], "correct_form": "掛け合う", "base_form": "掛け合う", "form_label": "辞書形", "sentence_index": 7, "explanations": {"掛け合う": "辞書形で、後ろの「街は」を修飾する名詞修飾節として文が成り立つ。", "掛け合います": "丁寧形は名詞を修飾できず、「掛け合います街は」とは続かない。", "掛け合えば": "仮定形は条件の続きが必要で、名詞を修飾できないので「街は」につながらない。", "掛け合って": "て形は後続の文へつなぐ形で、「街は」を直接修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
