INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37373, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を始めたり、変化させたりする原因や機会。", "primary_collocate": null, "pronunciation": "きっかけ", "ipa": "kikkake", "syllable_count": 4, "sentences": [{"text": "この事故が切っ掛けとなって、法律が変わった。", "target_word": "切っ掛け", "complexity_tier": "T4", "furigana": "この事故[じこ]が切[き]っ掛[か]けとなって、法律[ほうりつ]が変[か]わった。", "sentence_source": "generated"}, {"text": "引っ越しを切っ掛けに、生活のリズムを見直した。", "target_word": "切っ掛け", "complexity_tier": "T4", "furigana": "引[ひ]っ越[こ]しを切[き]っ掛[か]けに、生活[せいかつ]のリズムを見直[みなお]した。", "sentence_source": "generated"}, {"text": "ささいな言い争いが切っ掛けで、二人は別れた。", "target_word": "切っ掛け", "complexity_tier": "T4", "furigana": "ささいな言[い]い争[あらそ]いが切[き]っ掛[か]けで、二人[ふたり]は別[わか]れた。", "sentence_source": "generated"}, {"text": "病気になったことを切っ掛けに、食生活を変えた。", "target_word": "切っ掛け", "complexity_tier": "T3", "furigana": "病気[びょうき]になったことを切[き]っ掛[か]けに、食生活[しょくせいかつ]を変[か]えた。", "sentence_source": "generated"}, {"text": "転職する切っ掛けをずっと探している。", "target_word": "切っ掛け", "complexity_tier": "T3", "furigana": "転職[てんしょく]する切[き]っ掛[か]けをずっと探[さが]している。", "sentence_source": "generated"}, {"text": "あの発表が切っ掛けで、会社の方針が変わった。", "target_word": "切っ掛け", "complexity_tier": "T3", "furigana": "あの発表[はっぴょう]が切[き]っ掛[か]けで、会社[かいしゃ]の方針[ほうしん]が変[か]わった。", "sentence_source": "generated"}, {"text": "地震を切っ掛けに、防災への関心が高まった。", "target_word": "切っ掛け", "complexity_tier": "T4", "furigana": "地震[じしん]を切[き]っ掛[か]けに、防災[ぼうさい]への関心[かんしん]が高[たか]まった。", "sentence_source": "generated"}, {"text": "変わる切っ掛けを作るのは、いつも小さな決心だ。", "target_word": "切っ掛け", "complexity_tier": "T4", "furigana": "変[か]わる切[き]っ掛[か]けを作[つく]るのは、いつも小[ちい]さな決心[けっしん]だ。", "sentence_source": "generated"}, {"text": "祖母の手紙が切っ掛けとなり、家族の関係が良くなった。", "target_word": "切っ掛け", "complexity_tier": "T4", "furigana": "祖母[そぼ]の手紙[てがみ]が切[き]っ掛[か]けとなり、家族[かぞく]の関係[かんけい]が良[よ]くなった。", "sentence_source": "generated"}, {"text": "この旅行を切っ掛けに、考え方が大きく変わった。", "target_word": "切っ掛け", "complexity_tier": "T3", "furigana": "この旅行[りょこう]を切[き]っ掛[か]けに、考[かんが]え方[かた]が大[おお]きく変[か]わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "切っ掛け", "label": "dictionary"}, {"form": "切っ掛けを", "label": "object"}, {"form": "切っ掛けに", "label": "ni-marked"}, {"form": "切っ掛けで", "label": "de-marked"}], "register": "neutral", "sense_fingerprint": "物事を変えるきっかけとなる原因・機会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7bfaf5f-7601-4049-bf95-765962747195') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37373, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切っ掛け", "is_correct": true, "explanation": "事故が変化の原因になったという意味で、文の内容に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「事故が天気となって」は意味が通らないので、この文には合わない。"}, {"text": "財布", "is_correct": false, "explanation": "「事故が財布となって」は意味が通らないので、この文には合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「事故が鉛筆となって」は意味が通らないので、この文には合わない。"}], "explanations": {"切っ掛け": "事故が変化の原因になったという意味で、文の内容に合う。", "天気": "「事故が天気となって」は意味が通らないので、この文には合わない。", "財布": "「事故が財布となって」は意味が通らないので、この文には合わない。", "鉛筆": "「事故が鉛筆となって」は意味が通らないので、この文には合わない。"}, "sentence_index": 0, "correct_answer": "切っ掛け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病気の切っ掛けを、医者に治してもらった。", "explanation": "切っ掛けは治療の対象ではないので、この文は意味が通らない。"}, {"text": "病気になった切っ掛けを、箱に入れて保管した。", "explanation": "切っ掛けは箱に入れて保管する物ではないので、この文は意味が通らない。"}, {"text": "病気の切っ掛けは、病院の受付で予約した。", "explanation": "切っ掛けは予約して取っておけるものではないので、この文は意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37373, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切っ掛け", "is_correct": true, "explanation": "地震が防災への関心を高めた原因になったという意味で、文の内容に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「地震を冷蔵庫に」は意味が通らないので、この文には合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "「地震を座布団に」は意味が通らないので、この文には合わない。"}, {"text": "黒板", "is_correct": false, "explanation": "「地震を黒板に」は意味が通らないので、この文には合わない。"}], "explanations": {"切っ掛け": "地震が防災への関心を高めた原因になったという意味で、文の内容に合う。", "冷蔵庫": "「地震を冷蔵庫に」は意味が通らないので、この文には合わない。", "座布団": "「地震を座布団に」は意味が通らないので、この文には合わない。", "黒板": "「地震を黒板に」は意味が通らないので、この文には合わない。"}, "sentence_index": 6, "correct_answer": "切っ掛け"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この旅行の切っ掛けを、ホテルに届けた。", "explanation": "切っ掛けは運んで渡せる品物ではないので、この文には合わない。"}, {"text": "この旅行の切っ掛けを、空港で売った。", "explanation": "切っ掛けは売り物ではないので、この文には合わない。"}, {"text": "この旅行の切っ掛けを、三日間ずっと読んだ。", "explanation": "切っ掛けは文章や資料ではないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37373, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が降ったことを切っ掛けを、ボランティアを始めた。", "corrected_sentence": "雨が降ったことを切っ掛けに、ボランティアを始めた。", "error_description": "「切っ掛けに」と原因を示すには「に」が必要で、「を」では目的語になってしまう。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37373, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "転職を切っ掛けと、資格の勉強を始めた。", "corrected_sentence": "転職を切っ掛けに、資格の勉強を始めた。", "error_description": "「切っ掛けに」と原因を示すには「に」が必要で、「と」では文が続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37374, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ゴールが はっきりしている」の主語を示す「が」。「はっきりしている」の主語として自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語に使うので、状態を表す「はっきりしている」には続かない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すので、「ゴールに はっきりしている」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、状態を述べる文の「ゴールで はっきりしている」は不自然。"}], "correct_answer": "が", "explanations": {"が": "「ゴールが はっきりしている」の主語を示す「が」。「はっきりしている」の主語として自然に続く。", "を": "「を」は他動詞の目的語に使うので、状態を表す「はっきりしている」には続かない。", "に": "「に」は場所や相手を示すので、「ゴールに はっきりしている」は成り立たない。", "で": "「で」は手段や場所を示すので、状態を述べる文の「ゴールで はっきりしている」は不自然。"}, "error_tags": {"を": "object", "に": "location_or_target", "で": "means_or_place"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37374, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「今年のゴールは、〜ことです」の主題を示す「は」。文全体の話題を示すのに自然に続く。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「ゴールへ、〜ことです」は主題を立てる文にならず、「〜ことです」と結べない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や理由を示すので、「ゴールから、〜ことです」は主題を述べる形として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる基準を示すので、「ゴールより、〜ことです」は比較の相手がなく不自然。"}], "correct_answer": "は", "explanations": {"は": "「今年のゴールは、〜ことです」の主題を示す「は」。文全体の話題を示すのに自然に続く。", "へ": "「へ」は方向を示すので、「ゴールへ、〜ことです」は主題を立てる文にならず、「〜ことです」と結べない。", "から": "「から」は起点や理由を示すので、「ゴールから、〜ことです」は主題を述べる形として成り立たない。", "より": "「より」は比べる基準を示すので、「ゴールより、〜ことです」は比較の相手がなく不自然。"}, "error_tags": {"へ": "方向", "から": "起点・理由", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37374, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目指す場所や目標にたどり着くことです。", "primary_collocate": null, "pronunciation": "ごーる", "ipa": "ɡoːɾɯ", "syllable_count": 3, "sentences": [{"text": "私の人生のゴールは、小さな本屋を開くことです。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "私[わたし]の人生[じんせい]のゴールは、小[ちい]さな本屋[ほんや]を開[ひら]くことです。", "sentence_source": "generated"}, {"text": "ゴールがはっきりしているので、毎日の勉強に迷いません。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "ゴールがはっきりしているので、毎日[まいにち]の勉強[べんきょう]に迷[まよ]いません。", "sentence_source": "generated"}, {"text": "山の頂上をゴールにして、みんなで歩きはじめました。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "山[やま]の頂上[ちょうじょう]をゴールにして、みんなで歩[ある]きはじめました。", "sentence_source": "generated"}, {"text": "長い話し合いの末に、ようやく合意というゴールに着きました。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "長[なが]い話[はな]し合[あ]いの末[すえ]に、ようやく合意[ごうい]というゴールに着[つ]きました。", "sentence_source": "generated"}, {"text": "ゴールが遠いときは、小さな段階に分けて進みます。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "ゴールが遠[とお]いときは、小[ちい]さな段階[だんかい]に分[わ]けて進[すす]みます。", "sentence_source": "generated"}, {"text": "私たちは同じゴールを目指して、毎週会議を開いています。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "私[わたし]たちは同[おな]じゴールを目指[めざ]して、毎週[まいしゅう]会議[かいぎ]を開[ひら]いています。", "sentence_source": "generated"}, {"text": "ゴールを決めずに歩くと、どこへ着くのか分かりません。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "ゴールを決[き]めずに歩[ある]くと、どこへ着[つ]くのか分[わ]かりません。", "sentence_source": "generated"}, {"text": "今年のゴールは、日本語で手紙が書けるようになることです。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "今年[ことし]のゴールは、日本語[にほんご]で手紙[てがみ]が書[か]けるようになることです。", "sentence_source": "generated"}, {"text": "ゴールにたどり着くまでには、何度も失敗しました。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "ゴールにたどり着[つ]くまでには、何度[なんど]も失敗[しっぱい]しました。", "sentence_source": "generated"}, {"text": "旅のゴールは、海のそばの小さな町でした。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "旅[たび]のゴールは、海[うみ]のそばの小[ちい]さな町[まち]でした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ゴール", "label": "基本形"}, {"form": "ゴールする", "label": "サ変動詞形"}], "register": "丁寧", "sense_fingerprint": "目指す目標・到達点(人生や計画などの最終的な目的)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1bc596f-8b8d-4af6-bf10-97dcd2d33ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37374, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ゴール", "is_correct": true, "explanation": "「人生のゴール」は目指す到達点を表し、「小さな本屋を開くこと」という目標と合う。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気の状態を表す語で、人生の目標という文脈には入らない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさを表す語なので、「人生の〜は」の空所には意味が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は身体の重さを表す語で、人生の目標としては成り立たない。"}], "explanations": {"ゴール": "「人生のゴール」は目指す到達点を表し、「小さな本屋を開くこと」という目標と合う。", "湿度": "湿度は空気の状態を表す語で、人生の目標という文脈には入らない。", "音量": "音量は音の大きさを表す語なので、「人生の〜は」の空所には意味が通らない。", "体重": "体重は身体の重さを表す語で、人生の目標としては成り立たない。"}, "sentence_index": 0, "correct_answer": "ゴール"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女はゴールが豊富で、歴史の質問に何でも答えられます。", "explanation": "ここは〈知識〉の意味。ゴールは目指す到達点を表し、知っている情報の量を指さないので、「豊富」とは合わない。"}, {"text": "新しい計画のゴールで、みんなが一斉に動きだしました。", "explanation": "ここは〈スタート〉の意味。ゴールは最後にたどり着く先なので、動きだす場面には合わない。"}, {"text": "店のゴールは北側にあります。", "explanation": "ここは〈入口〉の意味。ゴールは最後に着く先を指すので、出入りする場所の位置としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37374, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ゴール", "is_correct": true, "explanation": "「ゴールを決めずに歩く」は目指す到達点を決めずに歩くという意味で、目標を表す「ゴール」が入る。"}, {"text": "体温", "is_correct": false, "explanation": "体温は測るものであって決める対象ではないので、「体温を決めずに歩く」は意味をなさない。"}, {"text": "騒音", "is_correct": false, "explanation": "騒音は決めるものではないので、「騒音を決めずに歩く」は成り立たない。"}, {"text": "電池", "is_correct": false, "explanation": "電池は決めて歩く対象にならないので、「電池を決めずに歩く」は意味が通らない。"}], "explanations": {"ゴール": "「ゴールを決めずに歩く」は目指す到達点を決めずに歩くという意味で、目標を表す「ゴール」が入る。", "体温": "体温は測るものであって決める対象ではないので、「体温を決めずに歩く」は意味をなさない。", "騒音": "騒音は決めるものではないので、「騒音を決めずに歩く」は成り立たない。", "電池": "電池は決めて歩く対象にならないので、「電池を決めずに歩く」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "ゴール"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この計画のゴールは、先月の出発でした。", "explanation": "ここは〈起点〉の意味。ゴールは未来に到達する先なので、先月の出発をゴールとするのは矛盾する。"}, {"text": "毎朝のゴールは、七時からです。", "explanation": "ここは〈予定〉の意味。ゴールは到達する地点や目標を指すので、始まる時刻の予定としては合わない。"}, {"text": "雨がゴールで、友達と話すようになりました。", "explanation": "ここは〈きっかけ〉の意味。ゴールは目指す到達点で、物事の原因や始まりは表さないので、この文脈では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37374, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私の夢のゴールを、旅に出ることです。", "corrected_sentence": "私の夢のゴールは、旅に出ることです。", "error_description": "主題を示す「は」が正しい。「を」にすると「ゴールを〜ことです」となり、文の形が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37374, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ゴールが決めてから、次の計画を立てます。", "corrected_sentence": "ゴールを決めてから、次の計画を立てます。", "error_description": "「決める」の対象を示す「を」が正しい。「が」にすると「ゴールが決める」となり、主語と動詞の関係が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37375, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「マラソンのゴールでは」の「で」は場所を示し、「では」として主題を導く。"}, {"text": "を", "is_correct": false, "explanation": "「ゴールを、家族が待っていました」は目的語の形になり、場所の説明として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「ゴールがは」と助詞が重なり、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示すので、待っている場所を表す文には合わない。"}], "correct_answer": "で", "explanations": {"で": "「マラソンのゴールでは」の「で」は場所を示し、「では」として主題を導く。", "を": "「ゴールを、家族が待っていました」は目的語の形になり、場所の説明として成り立たない。", "が": "「ゴールがは」と助詞が重なり、文として成り立たない。", "へ": "「へ」は移動の方向を示すので、待っている場所を表す文には合わない。"}, "error_tags": {"を": "object", "が": "subject", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37375, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「先に〜ゴールに着いた」の「に」は到着する地点を示す。「着く」と結びつく。"}, {"text": "を", "is_correct": false, "explanation": "「ゴールを着いた」は「着く」の目的語として成り立たず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「ゴールで着いた」は到着地点を示せず、移動の結果を表せない。"}, {"text": "が", "is_correct": false, "explanation": "「ゴールが着いた」は主語と述語が成立せず、到着の地点を表せない。"}], "correct_answer": "に", "explanations": {"に": "「先に〜ゴールに着いた」の「に」は到着する地点を示す。「着く」と結びつく。", "を": "「ゴールを着いた」は「着く」の目的語として成り立たず、不自然。", "で": "「ゴールで着いた」は到着地点を示せず、移動の結果を表せない。", "が": "「ゴールが着いた」は主語と述語が成立せず、到着の地点を表せない。"}, "error_tags": {"を": "object", "で": "means_or_place", "が": "subject"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37375, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "競技やゲームなどで、目的とする地点や状態に到達すること。また、その目的そのもの。", "primary_collocate": null, "pronunciation": "ごーる", "ipa": "ɡoːɾɯ", "syllable_count": 3, "sentences": [{"text": "試合の終わりに、選手がゴールを決めました。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "試合[しあい]の終[お]わりに、選手[せんしゅ]がゴールを決[き]めました。", "sentence_source": "generated"}, {"text": "マラソンのゴールでは、家族が待っていました。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "マラソンのゴールでは、家族[かぞく]が待[ま]っていました。", "sentence_source": "generated"}, {"text": "ボールはゴールの左に外れました。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "ボールはゴールの左[ひだり]に外[はず]れました。", "sentence_source": "generated"}, {"text": "ゴールの前で、最後の力をふりしぼって走りました。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "ゴールの前[まえ]で、最後[さいご]の力[ちから]をふりしぼって走[はし]りました。", "sentence_source": "generated"}, {"text": "キーパーが手をのばして、ゴールを守りました。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "キーパーが手[て]をのばして、ゴールを守[まも]りました。", "sentence_source": "generated"}, {"text": "雨の中でも、全員がゴールまで走りぬきました。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "雨[あめ]の中[なか]でも、全員[ぜんいん]がゴールまで走[はし]りぬきました。", "sentence_source": "generated"}, {"text": "最後の一分で、同点のゴールが生まれました。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "最後[さいご]の一分[いっぷん]で、同点[どうてん]のゴールが生[う]まれました。", "sentence_source": "generated"}, {"text": "すごろくでは、先にゴールに着いた人が勝ちです。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "すごろくでは、先[さき]にゴールに着[つ]いた人[ひと]が勝[か]ちです。", "sentence_source": "generated"}, {"text": "ゴールの前に長い坂があって、走るのが苦しかったです。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "ゴールの前[まえ]に長[なが]い坂[さか]があって、走[はし]るのが苦[くる]しかったです。", "sentence_source": "generated"}, {"text": "弟はゴールの隅をねらって、強くボールをけりました。", "target_word": "ゴール", "complexity_tier": "T3", "furigana": "弟[おとうと]はゴールの隅[すみ]をねらって、強[つよ]くボールをけりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ゴール", "label": "基本形"}, {"form": "ゴールする", "label": "サ変動詞形"}], "register": "丁寧", "sense_fingerprint": "競技・ゲームの決勝地点、またはサッカーなどで得点が入る枠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: ふりしぼっ (Zipf 1.46)']::text[], 'f1bc596f-8b8d-4af6-bf10-97dcd2d33ae6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37375, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ゴール", "is_correct": true, "explanation": "「試合の終わりに、選手がゴールを決めた」の空所には、サッカーなどの得点の場所・得点を表す「ゴール」が入る。"}, {"text": "天気", "is_correct": false, "explanation": "天気は「決める」対象にならず、試合の場面にも合わない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさを表す語で、「ゴールを決める」のような場面には入らない。"}, {"text": "気温", "is_correct": false, "explanation": "気温は空気の温度を表す語で、「試合の終わりに〜を決めた」の空所には意味が通らない。"}], "explanations": {"ゴール": "「試合の終わりに、選手がゴールを決めた」の空所には、サッカーなどの得点の場所・得点を表す「ゴール」が入る。", "天気": "天気は「決める」対象にならず、試合の場面にも合わない。", "音量": "音量は音の大きさを表す語で、「ゴールを決める」のような場面には入らない。", "気温": "気温は空気の温度を表す語で、「試合の終わりに〜を決めた」の空所には意味が通らない。"}, "sentence_index": 0, "correct_answer": "ゴール"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "レースのゴールで、選手たちが一斉に走りだしました。", "explanation": "ここは〈スタート〉の意味。ゴールは走り終える地点なので、走りだす場面には合わない。"}, {"text": "試合のゴールは、午後三時の休憩でした。", "explanation": "ここは〈休憩時間〉の意味。ゴールは試合で目指す地点や得点を指すので、休憩の時刻を表す言葉としては使えない。"}, {"text": "ゴールがホイッスルを鳴らしました。", "explanation": "ここは〈審判〉の意味。ゴールは場所や得点を表すので、笛を吹く人にはなれない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37375, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ゴール", "is_correct": true, "explanation": "「同点のゴールが生まれました」の空所には、得点としてのゴールが入る。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気の状態を表す語で、得点が生まれるという文脈には入らない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさを表す語で、「同点の〜が生まれた」には意味が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は身体の重さを表す語で、試合の得点を述べる文には合わない。"}], "explanations": {"ゴール": "「同点のゴールが生まれました」の空所には、得点としてのゴールが入る。", "湿度": "湿度は空気の状態を表す語で、得点が生まれるという文脈には入らない。", "音量": "音量は音の大きさを表す語で、「同点の〜が生まれた」には意味が通らない。", "体重": "体重は身体の重さを表す語で、試合の得点を述べる文には合わない。"}, "sentence_index": 6, "correct_answer": "ゴール"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "強いゴールがポストに当たりました。", "explanation": "ここは〈シュート（蹴ること）〉の意味。ゴールは得点そのものなので、ポストに当たる蹴ったボールとしては使えない。"}, {"text": "ゴールが手をのばして、ボールを止めました。", "explanation": "ここは〈キーパー（人）〉の意味。ゴールは場所や得点を指すので、手を伸ばして止める主体にはなれない。"}, {"text": "ゴールで相手を抜きました。", "explanation": "ここは〈ドリブル〉の意味。ゴールは地点や得点で、相手を抜く動きは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37375, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゴールを向かって、ボールをけりました。", "corrected_sentence": "ゴールに向かって、ボールをけりました。", "error_description": "方向を示す「に向かって」が正しい。「を」を使うと「ゴールを向かう」となり、移動の方向を表せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37375, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "自分のゴールに守りきりました。", "corrected_sentence": "自分のゴールを守りきりました。", "error_description": "「守る」の対象は「を」で示す。「に」にすると「ゴールに守る」となり、対象を正しく表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f31763d-e769-4808-b25d-dcfdc95c7d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37376, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「二倍になる」の主語になるので「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「なる」は目的語を取らないので「を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表し、「二倍になる」の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう先を表すので、「二倍になる」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「二倍になる」の主語になるので「が」が入る。", "を": "「なる」は目的語を取らないので「を」は合わない。", "と": "「と」は相手や並列を表し、「二倍になる」の主語にはならない。", "へ": "「へ」は向かう先を表すので、「二倍になる」の主語にはならない。"}, "error_tags": {"を": "目的語", "と": "相手・並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37376, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「使えば」の目的語になるので「を」が入る。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、使う対象にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を表し、ここでは合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ助詞で、動詞の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「使えば」の目的語になるので「を」が入る。", "から": "「から」は起点を表すので、使う対象にはならない。", "より": "「より」は比較の基準を表し、ここでは合わない。", "の": "「の」は名詞どうしをつなぐ助詞で、動詞の目的語にはならない。"}, "error_tags": {"から": "起点", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37376, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "買い物や利用に応じてもらえ、ためられる特典の点。", "primary_collocate": null, "pronunciation": "ぽいんと", "ipa": "poiɴto", "syllable_count": 4, "sentences": [{"text": "買い物をすると、ポイントがたまる。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "買[か]い物[もの]をすると、ポイントがたまる。", "sentence_source": "generated"}, {"text": "今月はポイントが二倍になるので、ここで買うことにした。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "今月[こんげつ]はポイントが二倍[にばい]になるので、ここで買[か]うことにした。", "sentence_source": "generated"}, {"text": "アンケートに答えると、ポイントがもらえる。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "アンケートに答[こた]えると、ポイントがもらえる。", "sentence_source": "generated"}, {"text": "ためたポイントで、無料のコーヒーを一杯飲んだ。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "ためたポイントで、無料[むりょう]のコーヒーを一杯[いっぱい]飲[の]んだ。", "sentence_source": "generated"}, {"text": "このアプリは歩くだけでポイントがつくから、毎日使っている。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "このアプリは歩[ある]くだけでポイントがつくから、毎日[まいにち]使[つか]っている。", "sentence_source": "generated"}, {"text": "ポイントの期限が切れる前に、全部使ってしまいたい。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "ポイントの期限[きげん]が切[き]れる前[まえ]に、全部[ぜんぶ]使[つか]ってしまいたい。", "sentence_source": "generated"}, {"text": "友達を紹介したら、ポイントをもらった。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "友達[ともだち]を紹介[しょうかい]したら、ポイントをもらった。", "sentence_source": "generated"}, {"text": "ポイントを使えば、電車代が安くなる。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "ポイントを使[つか]えば、電車代[でんしゃだい]が安[やす]くなる。", "sentence_source": "generated"}, {"text": "毎日ログインすると、少しずつポイントがふえる。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "毎日[まいにち]ログインすると、少[すこ]しずつポイントがふえる。", "sentence_source": "generated"}, {"text": "先月は忙しくて、ポイントをあまりためられなかった。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "先月[せんげつ]は忙[いそが]しくて、ポイントをあまりためられなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポイント", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "買い物や利用でもらえてためられる特典の点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0625842b-0888-44c2-8a00-218ebf20c50e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37376, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポイント", "is_correct": true, "explanation": "買い物で貯まる特典の点を指すので、「たまる」と自然につながる。"}, {"text": "メニュー", "is_correct": false, "explanation": "料理の一覧のことで、買い物をしても「たまる」ものではない。"}, {"text": "パスワード", "is_correct": false, "explanation": "ログインに使う暗証番号のことで、「たまる」ものではない。"}, {"text": "カレンダー", "is_correct": false, "explanation": "日付を並べた表のことで、買い物によって「たまる」ものではない。"}], "explanations": {"ポイント": "買い物で貯まる特典の点を指すので、「たまる」と自然につながる。", "メニュー": "料理の一覧のことで、買い物をしても「たまる」ものではない。", "パスワード": "ログインに使う暗証番号のことで、「たまる」ものではない。", "カレンダー": "日付を並べた表のことで、買い物によって「たまる」ものではない。"}, "sentence_index": 0, "correct_answer": "ポイント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雪でポイントが凍り、電車が遅れた。", "explanation": "ここは〈線路の転轍器〉の意味。買い物で貯まる特典の点とは別の意味なので、この文では合わない。"}, {"text": "会議で、話のポイントを三つにまとめた。", "explanation": "ここは〈要点〉の意味。特典としての点とは別の語義なので、この文では使えない。"}, {"text": "タイトルの文字を、十ポイントに大きくした。", "explanation": "ここは〈活字の大きさ〉の意味。特典としての点とは別の語義なので、この文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37376, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポイント", "is_correct": true, "explanation": "紹介のお礼としてもらえる点を指すので、「もらった」と合う。"}, {"text": "ルール", "is_correct": false, "explanation": "決まりごとのことで、紹介してもらうものではない。"}, {"text": "リズム", "is_correct": false, "explanation": "拍子や調子のことで、もらうものではない。"}, {"text": "時差", "is_correct": false, "explanation": "地域の時刻のずれのことで、もらうものではない。"}], "explanations": {"ポイント": "紹介のお礼としてもらえる点を指すので、「もらった」と合う。", "ルール": "決まりごとのことで、紹介してもらうものではない。", "リズム": "拍子や調子のことで、もらうものではない。", "時差": "地域の時刻のずれのことで、もらうものではない。"}, "sentence_index": 6, "correct_answer": "ポイント"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "説明のポイントを押さえて、話した。", "explanation": "ここは〈要点〉の意味。特典としての点とは別の語義なので、この文では合わない。"}, {"text": "コンサートのポイントを予約した。", "explanation": "ここは〈チケット〉の意味。ポイントは予約する券ではなく、利用で貯まる点数なので合わない。"}, {"text": "台紙のポイントを、きれいにはがした。", "explanation": "ここは〈シール〉の意味。ポイントは台紙からはがすものではないので、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37376, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "アプリを使うと、ポイントをたまる。", "corrected_sentence": "アプリを使うと、ポイントがたまる。", "error_description": "「たまる」は自動詞なので、ポイントには「が」を付ける。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37376, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しいカードを作ったら、私がポイントがもらった。", "corrected_sentence": "新しいカードを作ったら、私がポイントをもらった。", "error_description": "「もらう」の目的語には「を」を使うので、「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
