INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37377, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ゲームや競技で、得点や点数を意味する言葉。目標を達成したり、相手より多く集めたりするための数値。", "primary_collocate": null, "pronunciation": "ぽいんと", "ipa": "poiɴto", "syllable_count": 4, "sentences": [{"text": "前半が終わって、私たちのチームは五ポイント負けている。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "前半[ぜんはん]が終[お]わって、私[わたし]たちのチームは五[ご]ポイント負[ま]けている。", "sentence_source": "generated"}, {"text": "最後にシュートを決めて、一気に十ポイントを取った。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "最後[さいご]にシュートを決[き]めて、一気[いっき]に十[じゅう]ポイントを取[と]った。", "sentence_source": "generated"}, {"text": "相手より多くポイントを集めたチームが勝つ。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "相手[あいて]より多[おお]くポイントを集[あつ]めたチームが勝[か]つ。", "sentence_source": "generated"}, {"text": "このゲームは、敵をたおすとポイントが入る。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "このゲームは、敵[てき]をたおすとポイントが入[はい]る。", "sentence_source": "generated"}, {"text": "試合の終わりに、ポイントの多い方が勝った。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "試合[しあい]の終[お]わりに、ポイント[ぽいんと]の多[おお]い方[ほう]が勝[か]った。", "sentence_source": "generated"}, {"text": "一位との差は、たった二ポイントだ。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "一位[いちい]との差[さ]は、たった二[に]ポイントだ。", "sentence_source": "generated"}, {"text": "ミスをしたので、相手にポイントを取られてしまった。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "ミスをしたので、相手[あいて]にポイントを取[と]られてしまった。", "sentence_source": "generated"}, {"text": "彼女は最初のゲームで、いきなり八ポイントも稼いだ。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は最初[さいしょ]のゲームで、いきなり八[はち]ポイントも稼[かせ]いだ。", "sentence_source": "generated"}, {"text": "二人のポイントが同じなので、延長戦をすることになった。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "二人[ふたり]のポイントが同[おな]じなので、延長戦[えんちょうせん]をすることになった。", "sentence_source": "generated"}, {"text": "逆転するには、あと三ポイント必要だ。", "target_word": "ポイント", "complexity_tier": "T3", "furigana": "逆転[ぎゃくてん]するには、あと三[さん]ポイント必要[ひつよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ポイント", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "試合やゲームで取る得点の数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: contains vocabulary far above tier T1: たおす (Zipf 2.21)']::text[], '0625842b-0888-44c2-8a00-218ebf20c50e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37377, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ポイント", "is_correct": true, "explanation": "試合での点差を表す単位で、「五」の後に来て「負けている」と合う。"}, {"text": "ヘルメット", "is_correct": false, "explanation": "競技で頭を守る防具のことで、点差の単位ではない。"}, {"text": "キャプテン", "is_correct": false, "explanation": "チームの主将のことで、点差を表さない。"}, {"text": "ユニフォーム", "is_correct": false, "explanation": "試合で着る服のことで、点差の単位ではない。"}], "explanations": {"ポイント": "試合での点差を表す単位で、「五」の後に来て「負けている」と合う。", "ヘルメット": "競技で頭を守る防具のことで、点差の単位ではない。", "キャプテン": "チームの主将のことで、点差を表さない。", "ユニフォーム": "試合で着る服のことで、点差の単位ではない。"}, "sentence_index": 0, "correct_answer": "ポイント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "見出しの文字を、十ポイントの大きさにした。", "explanation": "ここは〈活字の大きさ〉の意味。試合で取る得点とは別の語義なので、この文では使えない。"}, {"text": "雨で線路のポイントが動かなくなった。", "explanation": "ここは〈線路の転轍器〉の意味。得点を表す語義とは違うので、この文では合わない。"}, {"text": "授業の最後に、大事なポイントを三つ黒板に書いた。", "explanation": "ここは〈要点〉の意味。得点を表す語義とは違うので、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37377, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ポイント", "is_correct": true, "explanation": "相手に得点を取られた、という意味で「取られてしまった」と合う。"}, {"text": "審判", "is_correct": false, "explanation": "試合を裁く人のことで、取られるものではない。"}, {"text": "応援", "is_correct": false, "explanation": "声援のことで、取られるものではない。"}, {"text": "試験", "is_correct": false, "explanation": "テストのことで、試合中に取られるものではない。"}], "explanations": {"ポイント": "相手に得点を取られた、という意味で「取られてしまった」と合う。", "審判": "試合を裁く人のことで、取られるものではない。", "応援": "声援のことで、取られるものではない。", "試験": "テストのことで、試合中に取られるものではない。"}, "sentence_index": 6, "correct_answer": "ポイント"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪で線路のポイントが凍り、電車が遅れた。", "explanation": "ここは〈線路の転轍器〉の意味。得点を表す語義とは違うので、この文では合わない。"}, {"text": "会議で、説明のポイントを三つにまとめた。", "explanation": "ここは〈要点〉の意味。得点を表す語義とは違うので、この文では合わない。"}, {"text": "本文の文字を、九ポイントの大きさにした。", "explanation": "ここは〈活字の大きさ〉の意味。得点を表す語義とは違うので、この文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37377, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最後のシュートで、チームは十ポイントを負けた。", "corrected_sentence": "最後のシュートで、チームは十ポイント負けた。", "error_description": "「負ける」は勝負の結果を表し、ポイントを目的語に取らない。「を」を外して「十ポイント負けた」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37377, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同点になるには、あと一ポイントを必要だ。", "corrected_sentence": "同点になるには、あと一ポイントが必要だ。", "error_description": "「必要だ」は「〜が必要だ」の形で使うので、ポイントには「が」を付ける。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2919c7e-5af5-42bd-b1a1-9ca7649fb20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37378, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「競う」の対象を示す「を」で、「かを競って」の形になる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は帰着点や相手の位置を表すので、競う対象には使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、競う対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すため、競う対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「競う」の対象を示す「を」で、「かを競って」の形になる。", "に": "「に」は帰着点や相手の位置を表すので、競う対象には使えない。", "へ": "「へ」は方向を表すため、競う対象を示せない。", "から": "「から」は起点を表すため、競う対象を示せない。"}, "error_tags": {"に": "相手・帰着点", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37378, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「競う」の対象を示す「を」で、「大きさを競う」の形になる。"}, {"text": "と", "is_correct": false, "explanation": "「〜と競う」は相手を示すが、ここは「大きさ」を競うので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すが、「〜より競う」とは言わないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では競う対象を示せず、「大きさの競う祭り」は不自然になる。"}], "correct_answer": "を", "explanations": {"を": "「競う」の対象を示す「を」で、「大きさを競う」の形になる。", "と": "「〜と競う」は相手を示すが、ここは「大きさ」を競うので合わない。", "より": "「より」は比較を表すが、「〜より競う」とは言わないので合わない。", "の": "連体の「の」では競う対象を示せず、「大きさの競う祭り」は不自然になる。"}, "error_tags": {"と": "相手", "より": "比較", "の": "所属・連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37378, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "おなじことをして、だれがいいかをくらべる。", "primary_collocate": null, "pronunciation": "きそう", "ipa": "kisoː", "syllable_count": 3, "sentences": [{"text": "兄と私は、どちらが速く走れるか競った。", "target_word": "競った", "complexity_tier": "T3", "furigana": "兄(あに)と私(わたし)は、どちらが速(はや)く走(はし)れるか競(きそ)った。", "sentence_source": "generated"}, {"text": "子どもたちは、だれが高く跳べるかを競って遊んでいる。", "target_word": "競って", "complexity_tier": "T3", "furigana": "子(こ)どもたちは、だれが高(たか)く跳(と)べるかを競(きそ)って遊(あそ)んでいる。", "sentence_source": "generated"}, {"text": "料理の上手さを競う大会が、町で開かれた。", "target_word": "競う", "complexity_tier": "T3", "furigana": "料理(りょうり)の上手(じょうず)さを競(きそ)う大会(たいかい)が、町(まち)で開(ひら)かれた。", "sentence_source": "generated"}, {"text": "友だちと漢字のテストの点数を競っている。", "target_word": "競って", "complexity_tier": "T3", "furigana": "友(とも)だちと漢字(かんじ)のテストの点数(てんすう)を競(きそ)っている。", "sentence_source": "generated"}, {"text": "二人は同じ絵を描いて、どちらが上手か競った。", "target_word": "競った", "complexity_tier": "T3", "furigana": "二人(ふたり)は同(おな)じ絵(え)を描(か)いて、どちらが上手(じょうず)か競(きそ)った。", "sentence_source": "generated"}, {"text": "学校のクラスどうしで、縄跳びの回数を競う。", "target_word": "競う", "complexity_tier": "T3", "furigana": "学校(がっこう)のクラスどうしで、縄跳(なわと)びの回数(かいすう)を競(きそ)う。", "sentence_source": "generated"}, {"text": "昨日、弟とだれが多く食べられるか競った。", "target_word": "競った", "complexity_tier": "T3", "furigana": "昨日(きのう)、弟(おとうと)とだれが多(おお)く食(た)べられるか競(きそ)った。", "sentence_source": "generated"}, {"text": "村の人たちは、野菜の大きさを競う祭りを毎年している。", "target_word": "競う", "complexity_tier": "T3", "furigana": "村(むら)の人(ひと)たちは、野菜(やさい)の大(おお)きさを競(きそ)う祭(まつ)りを毎年(まいとし)している。", "sentence_source": "generated"}, {"text": "私たちは、だれが先に本を読み終えるか競ってみた。", "target_word": "競って", "complexity_tier": "T3", "furigana": "私(わたし)たちは、だれが先(さき)に本(ほん)を読(よ)み終(お)えるか競(きそ)ってみた。", "sentence_source": "generated"}, {"text": "子どものころ、姉と泳ぐ速さを競ったことがある。", "target_word": "競った", "complexity_tier": "T3", "furigana": "子(こ)どものころ、姉(あね)と泳(およ)ぐ速(はや)さを競(きそ)ったことがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "競う", "label": "辞書形"}, {"form": "競った", "label": "過去形"}, {"form": "競って", "label": "て形"}, {"form": "競わない", "label": "否定形"}, {"form": "競えば", "label": "仮定形"}, {"form": "競おう", "label": "意向形"}, {"form": "競える", "label": "可能形"}, {"form": "競われる", "label": "受身形"}], "register": "標準", "sense_fingerprint": "同じことを複数の人がして、だれが上手か・速いかを比べる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215eb90-f0e8-463e-beea-b84a82a01593') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37378, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "競った", "is_correct": true, "explanation": "過去形の「競った」は「どちらが速く走れるか競った」と文を言い切れ、文脈とも合う。"}, {"text": "競って", "is_correct": false, "explanation": "て形は文を言い切れないため、「〜か競って。」では文が終わらない。"}, {"text": "競え", "is_correct": false, "explanation": "命令形は「競え」と指示する形で、事実を述べる文には合わない。"}, {"text": "競わせ", "is_correct": false, "explanation": "使役の語幹は文を言い切れず、「競わせた」にすると「相手に競わせた」という別の意味になる。"}], "explanations": {"競った": "過去形の「競った」は「どちらが速く走れるか競った」と文を言い切れ、文脈とも合う。", "競って": "て形は文を言い切れないため、「〜か競って。」では文が終わらない。", "競え": "命令形は「競え」と指示する形で、事実を述べる文には合わない。", "競わせ": "使役の語幹は文を言い切れず、「競わせた」にすると「相手に競わせた」という別の意味になる。"}, "sentence_index": 0, "correct_answer": "競った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町の人々は力を合わせ、洪水の被害を競った。", "explanation": "ここは〈防ぐ〉の意味。競うは人と優劣を争う語なので、災害を食い止める意味では使えない。"}, {"text": "両家は土地の境界を競って、何年も言い争いが続いている。", "explanation": "ここは〈争う〉の意味。競うは実力や成績で優劣を比べることで、土地の権利をめぐるもめごとには使わない。"}, {"text": "隣の国との国境の町を、軍隊が三年間にわたって競った。", "explanation": "ここは〈戦う〉の意味。競うは公平に比べて勝ち負けを決める語で、武力の衝突には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37378, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "競った", "is_correct": true, "explanation": "過去形の「競った」で「昨日」の出来事として文を言い切れ、文脈に合う。"}, {"text": "競おう", "is_correct": false, "explanation": "意向形は「競おう」と誘う形で、「昨日」の事実を述べる文には合わない。"}, {"text": "競わ", "is_correct": false, "explanation": "未然形の語幹は文を言い切れず、「競わ。」では文が終わらない。"}, {"text": "競われ", "is_correct": false, "explanation": "受身の連用形は文を言い切れず、「競われ。」では文が成り立たない。"}], "explanations": {"競った": "過去形の「競った」で「昨日」の出来事として文を言い切れ、文脈に合う。", "競おう": "意向形は「競おう」と誘う形で、「昨日」の事実を述べる文には合わない。", "競わ": "未然形の語幹は文を言い切れず、「競わ。」では文が終わらない。", "競われ": "受身の連用形は文を言い切れず、「競われ。」では文が成り立たない。"}, "sentence_index": 6, "correct_answer": "競った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子犬が猫を競って、庭を走り回った。", "explanation": "ここは〈追いかける〉の意味。競うは互いに同じことをして優劣を比べる語で、相手を追う意味にはならない。"}, {"text": "友だちと将来の夢を、夜遅くまで競った。", "explanation": "ここは〈話し合う〉の意味。競うは勝ち負けを争う語で、考えを出し合う話し合いには使わない。"}, {"text": "妹が落とした鍵を、みんなで競った。", "explanation": "ここは〈見つける〉の意味。競うは優劣を争う語で、物を見つける意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37378, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹と、どちらが先に宿題を終えるかに競った。", "corrected_sentence": "妹と、どちらが先に宿題を終えるかを競った。", "error_description": "誤りは助詞の「に」。「競う」は「〜を競う」と目的語を取るので「を」が正しい。「かに」では競う対象が示せず不自然になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "競って", "is_correct": true, "explanation": "「遊んでいる」へ続く中止形（て形）で、「競ってから遊ぶ」という続き方になる。"}, {"text": "競った", "is_correct": false, "explanation": "過去形だと「競った」で文が完了し、「遊んでいる」と続かない。"}, {"text": "競わない", "is_correct": false, "explanation": "否定形だと「競わない」になり、「競って遊ぶ」という肯定の意味にならない。"}, {"text": "競え", "is_correct": false, "explanation": "命令形「競え」は「遊んでいる」へ続かず、文として成り立たない。"}], "correct_form": "競って", "base_form": "競う", "form_label": "て形", "sentence_index": 1, "explanations": {"競って": "「遊んでいる」へ続く中止形（て形）で、「競ってから遊ぶ」という続き方になる。", "競った": "過去形だと「競った」で文が完了し、「遊んでいる」と続かない。", "競わない": "否定形だと「競わない」になり、「競って遊ぶ」という肯定の意味にならない。", "競え": "命令形「競え」は「遊んでいる」へ続かず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37378, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人は昨日、どちらが速く走れるかを競って。", "corrected_sentence": "二人は昨日、どちらが速く走れるかを競った。", "error_description": "誤りは「競って」で文を終えている点。て形は文を言い切れないので、過去の言い切りの「競った」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "競う", "is_correct": true, "explanation": "辞書形で、後ろの「祭り」を修飾している。「競う祭り」は勝負を競い合う祭りという意味になる。"}, {"text": "競おう", "is_correct": false, "explanation": "意向形は「〜しよう」と誘う形で、名詞を修飾できない。"}, {"text": "競って", "is_correct": false, "explanation": "て形は名詞を修飾できず、「大きさを競って祭り」は成り立たない。"}, {"text": "競われる", "is_correct": false, "explanation": "受身形だと「競われる祭り」となり、祭りのほうが競われるという意味になる。"}], "correct_form": "競う", "base_form": "競う", "form_label": "辞書形", "sentence_index": 7, "explanations": {"競う": "辞書形で、後ろの「祭り」を修飾している。「競う祭り」は勝負を競い合う祭りという意味になる。", "競おう": "意向形は「〜しよう」と誘う形で、名詞を修飾できない。", "競って": "て形は名詞を修飾できず、「大きさを競って祭り」は成り立たない。", "競われる": "受身形だと「競われる祭り」となり、祭りのほうが競われるという意味になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37379, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「世界一の座を競う」の「を」で、競う対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は帰着点を表すので、競う対象には使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すため、競う対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「〜と競う」は相手を示すので、「座と競う」は不自然になる。"}], "correct_answer": "を", "explanations": {"を": "「世界一の座を競う」の「を」で、競う対象を示す。", "に": "「に」は帰着点を表すので、競う対象には使えない。", "へ": "「へ」は方向を表すため、競う対象を示せない。", "と": "「〜と競う」は相手を示すので、「座と競う」は不自然になる。"}, "error_tags": {"に": "相手・帰着点", "へ": "方向", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37379, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「一議席を競った」の「を」で、競う対象を示す。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すため、競う対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すが、「一議席より競った」とは言わないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では競う対象を示せず、「一議席の競った」は不自然になる。"}], "correct_answer": "を", "explanations": {"を": "「一議席を競った」の「を」で、競う対象を示す。", "から": "「から」は起点を表すため、競う対象を示せない。", "より": "「より」は比較を表すが、「一議席より競った」とは言わないので合わない。", "の": "連体の「の」では競う対象を示せず、「一議席の競った」は不自然になる。"}, "error_tags": {"から": "起点", "より": "比較", "の": "所属・連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37379, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "勝ち負けや、どちらが上かを決めるために、相手と力を比べ合う。", "primary_collocate": null, "pronunciation": "きそう", "ipa": "kisoː", "syllable_count": 3, "sentences": [{"text": "二つの強いチームが、優勝をかけて競った。", "target_word": "競った", "complexity_tier": "T3", "furigana": "二(ふた)つの強(つよ)いチームが、優勝(ゆうしょう)をかけて競(きそ)った。", "sentence_source": "generated"}, {"text": "選手たちは世界一の座を競って、毎日きびしい練習をしている。", "target_word": "競って", "complexity_tier": "T3", "furigana": "選手(せんしゅ)たちは世界一(せかいいち)の座(ざ)を競(きそ)って、毎日(まいにち)きびしい練習(れんしゅう)をしている。", "sentence_source": "generated"}, {"text": "決勝では二人の力が同じくらいで、最後まで競う試合になった。", "target_word": "競う", "complexity_tier": "T3", "furigana": "決勝(けっしょう)では二人(ふたり)の力(ちから)が同(おな)じくらいで、最後(さいご)まで競(きそ)う試合(しあい)になった。", "sentence_source": "generated"}, {"text": "新しい店が増えて、各社が品質を競う時代になった。", "target_word": "競う", "complexity_tier": "T3", "furigana": "新(あたら)しい店(みせ)が増(ふ)えて、各社(かくしゃ)が品質(ひんしつ)を競(きそ)う時代(じだい)になった。", "sentence_source": "generated"}, {"text": "彼とは入社した時から、仕事の成績を競ってきた。", "target_word": "競って", "complexity_tier": "T3", "furigana": "彼(かれ)とは入社(にゅうしゃ)した時(とき)から、仕事(しごと)の成績(せいせき)を競(きそ)ってきた。", "sentence_source": "generated"}, {"text": "強いライバルがいるから、練習でも本気で競える。", "target_word": "競える", "complexity_tier": "T3", "furigana": "強(つよ)いライバルがいるから、練習(れんしゅう)でも本気(ほんき)で競(きそ)える。", "sentence_source": "generated"}, {"text": "四年に一度、各国の代表が金メダルを競う。", "target_word": "競う", "complexity_tier": "T3", "furigana": "四年(よねん)に一度(いちど)、各国(かっこく)の代表(だいひょう)が金(きん)メダルを競(きそ)う。", "sentence_source": "generated"}, {"text": "二人の候補者が、最後の一議席を競った。", "target_word": "競った", "complexity_tier": "T3", "furigana": "二人(ふたり)の候補者(こうほしゃ)が、最後(さいご)の一議席(いちぎせき)を競(きそ)った。", "sentence_source": "generated"}, {"text": "スポーツは、勝つために相手と力を競うものだ。", "target_word": "競う", "complexity_tier": "T3", "furigana": "スポーツは、勝(か)つために相手(あいて)と力(ちから)を競(きそ)うものだ。", "sentence_source": "generated"}, {"text": "二人は実力が近く、いつも上位を競っている。", "target_word": "競って", "complexity_tier": "T3", "furigana": "二人(ふたり)は実力(じつりょく)が近(ちか)く、いつも上位(じょうい)を競(きそ)っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "競う", "label": "辞書形"}, {"form": "競った", "label": "過去形"}, {"form": "競って", "label": "て形"}, {"form": "競わない", "label": "否定形"}, {"form": "競えば", "label": "仮定形"}, {"form": "競おう", "label": "意向形"}, {"form": "競える", "label": "可能形"}, {"form": "競われる", "label": "受身形"}], "register": "標準", "sense_fingerprint": "勝敗や順位を決めるために、ライバルと実力でぶつかり合う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215eb90-f0e8-463e-beea-b84a82a01593') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37379, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "競った", "is_correct": true, "explanation": "過去形の「競った」は「優勝をかけて」と文を言い切れ、文脈に合う。"}, {"text": "競わ", "is_correct": false, "explanation": "未然形の語幹は文を言い切れず、「競わ。」では文が成り立たない。"}, {"text": "競え", "is_correct": false, "explanation": "命令形は指示の形で、事実を述べる文には合わない。"}, {"text": "競わせ", "is_correct": false, "explanation": "使役の語幹は文を言い切れず、「競わせた」にすると別の意味になる。"}], "explanations": {"競った": "過去形の「競った」は「優勝をかけて」と文を言い切れ、文脈に合う。", "競わ": "未然形の語幹は文を言い切れず、「競わ。」では文が成り立たない。", "競え": "命令形は指示の形で、事実を述べる文には合わない。", "競わせ": "使役の語幹は文を言い切れず、「競わせた」にすると別の意味になる。"}, "sentence_index": 0, "correct_answer": "競った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一人で昔の写真に目を通し、髪の長さを競った。", "explanation": "ここは〈確認する〉の意味。競うは相手と力を比べ合う語なので、一人で中身を確かめる意味では使えない。"}, {"text": "二人は電車で、お年寄りに席を競って渡した。", "explanation": "ここは〈譲る〉の意味。競うは勝ち負けを争う語なので、相手に物を与える意味では使えない。"}, {"text": "大雨で増えた川の水を、町の人々は力を合わせて競った。", "explanation": "ここは〈せき止める〉の意味。競うは相手と勝敗を比べる語で、協力して水を止める意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37379, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "競う", "is_correct": true, "explanation": "辞書形で「四年に一度」の習慣的な出来事を言い切れ、文脈に合う。"}, {"text": "競おう", "is_correct": false, "explanation": "意向形は「〜しよう」と誘う形で、事実を述べる文には合わない。"}, {"text": "競われ", "is_correct": false, "explanation": "受身の連用形は文を言い切れず、「金メダルを競われ。」では文が成り立たない。"}, {"text": "競って", "is_correct": false, "explanation": "て形は文を言い切れず、「金メダルを競って。」では文が終わらない。"}], "explanations": {"競う": "辞書形で「四年に一度」の習慣的な出来事を言い切れ、文脈に合う。", "競おう": "意向形は「〜しよう」と誘う形で、事実を述べる文には合わない。", "競われ": "受身の連用形は文を言い切れず、「金メダルを競われ。」では文が成り立たない。", "競って": "て形は文を言い切れず、「金メダルを競って。」では文が終わらない。"}, "sentence_index": 6, "correct_answer": "競う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警官が犯人を競って、路地を走った。", "explanation": "ここは〈追いかける〉の意味。競うは互いに同じことをして優劣を比べる語で、相手を追う意味にはならない。"}, {"text": "家族と旅行の計画を、夜遅くまで競った。", "explanation": "ここは〈話し合う〉の意味。競うは勝ち負けを争う語で、計画を出し合う話し合いには使わない。"}, {"text": "なくしたかばんを、みんなで競った。", "explanation": "ここは〈探す〉の意味。競うは優劣を争う語で、物を探す意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37379, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三人は、最後の一席に競った。", "corrected_sentence": "三人は、最後の一席を競った。", "error_description": "誤りは助詞の「に」。「競う」は「〜を競う」と目的語を取るので「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "競って", "is_correct": true, "explanation": "「毎日きびしい練習をしている」へ続く中止形（て形）で、文の流れに合う。"}, {"text": "競った", "is_correct": false, "explanation": "過去形だと「競った」で文が完了し、「練習をしている」と続かない。"}, {"text": "競わない", "is_correct": false, "explanation": "否定形だと「世界一の座を競わない」となり、競う行為を否定する意味になる。"}, {"text": "競え", "is_correct": false, "explanation": "命令形「競え」は「練習をしている」へ続かず、文として成り立たない。"}], "correct_form": "競って", "base_form": "競う", "form_label": "て形", "sentence_index": 1, "explanations": {"競って": "「毎日きびしい練習をしている」へ続く中止形（て形）で、文の流れに合う。", "競った": "過去形だと「競った」で文が完了し、「練習をしている」と続かない。", "競わない": "否定形だと「世界一の座を競わない」となり、競う行為を否定する意味になる。", "競え": "命令形「競え」は「練習をしている」へ続かず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37379, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人は昨日、どちらが先にゴールするかを競って。", "corrected_sentence": "二人は昨日、どちらが先にゴールするかを競った。", "error_description": "誤りは「競って」で文を終えている点。て形は文を言い切れないので、過去の言い切りの「競った」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "競った", "is_correct": true, "explanation": "過去形で「最後の一議席を競った」と出来事を言い切れ、文脈に合う。"}, {"text": "競おう", "is_correct": false, "explanation": "意向形は「〜しよう」と誘う形で、過去の出来事を述べる文には合わない。"}, {"text": "競って", "is_correct": false, "explanation": "て形は文を言い切れず、「最後の一議席を競って。」では文が成り立たない。"}, {"text": "競われる", "is_correct": false, "explanation": "受身形だと「議席が競われた」となり、候補者が競ったという主語の関係が崩れる。"}], "correct_form": "競った", "base_form": "競う", "form_label": "過去形", "sentence_index": 7, "explanations": {"競った": "過去形で「最後の一議席を競った」と出来事を言い切れ、文脈に合う。", "競おう": "意向形は「〜しよう」と誘う形で、過去の出来事を述べる文には合わない。", "競って": "て形は文を言い切れず、「最後の一議席を競って。」では文が成り立たない。", "競われる": "受身形だと「議席が競われた」となり、候補者が競ったという主語の関係が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37380, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「品質が向上した」の「が」で、向上する主語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は帰着点や相手を表すため、「品質に向上した」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、向上の主語は示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すため、「品質より向上した」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「品質が向上した」の「が」で、向上する主語を示す。", "に": "「に」は帰着点や相手を表すため、「品質に向上した」は成り立たない。", "へ": "「へ」は方向を表すので、向上の主語は示せない。", "より": "「より」は比較を表すため、「品質より向上した」は意味が通らない。"}, "error_tags": {"に": "相手・帰着点", "へ": "方向", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低下", "is_correct": true, "explanation": "「向上」の対義語。良くなる方向と逆に、下がって悪くなることを表す。"}, {"text": "維持", "is_correct": false, "explanation": "「維持」は今の状態を保つ意味で、良くも悪くもならないため対義語ではない。"}, {"text": "安定", "is_correct": false, "explanation": "「安定」は変動がないことを表し、「向上」の反対の方向を示す語ではない。"}, {"text": "継続", "is_correct": false, "explanation": "「継続」は続けることを表し、良い方にも悪い方にも変わらないので対義語ではない。"}], "correct_answer": "低下", "explanations": {"低下": "「向上」の対義語。良くなる方向と逆に、下がって悪くなることを表す。", "維持": "「維持」は今の状態を保つ意味で、良くも悪くもならないため対義語ではない。", "安定": "「安定」は変動がないことを表し、「向上」の反対の方向を示す語ではない。", "継続": "「継続」は続けることを表し、良い方にも悪い方にも変わらないので対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37380, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低下", "is_correct": true, "explanation": "「向上」の対義語。良くなる方向と逆に、下がって悪くなることを表す。"}, {"text": "固定", "is_correct": false, "explanation": "「固定」は変わらないように定めることで、「向上」の反対の方向を表す語ではない。"}, {"text": "静止", "is_correct": false, "explanation": "「静止」は動かないことで、良くなる・悪くなるという変化の対義語ではない。"}, {"text": "休止", "is_correct": false, "explanation": "「休止」は一時的に止めることで、「向上」の反対の方向を表す語ではない。"}], "correct_answer": "低下", "explanations": {"低下": "「向上」の対義語。良くなる方向と逆に、下がって悪くなることを表す。", "固定": "「固定」は変わらないように定めることで、「向上」の反対の方向を表す語ではない。", "静止": "「静止」は動かないことで、良くなる・悪くなるという変化の対義語ではない。", "休止": "「休止」は一時的に止めることで、「向上」の反対の方向を表す語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37380, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものごとが前よりも良くなること。", "primary_collocate": null, "pronunciation": "こうじょう", "ipa": "koːdʑoː", "syllable_count": 4, "sentences": [{"text": "毎日練習したので、泳ぐ力がだんだん向上した。", "target_word": "向上", "complexity_tier": "T3", "furigana": "毎日(まいにち)練習(れんしゅう)したので、泳(およ)ぐ力(ちから)がだんだん向上(こうじょう)した。", "sentence_source": "generated"}, {"text": "新しい機械を入れて、会社の品質が向上した。", "target_word": "向上", "complexity_tier": "T3", "furigana": "新(あたら)しい機械(きかい)を入(い)れて、会社(かいしゃ)の品質(ひんしつ)が向上(こうじょう)した。", "sentence_source": "generated"}, {"text": "学校は生徒の学力の向上を目指している。", "target_word": "向上", "complexity_tier": "T3", "furigana": "学校(がっこう)は生徒(せいと)の学力(がくりょく)の向上(こうじょう)を目指(めざ)している。", "sentence_source": "generated"}, {"text": "給料が上がって、暮らしの向上を感じている。", "target_word": "向上", "complexity_tier": "T3", "furigana": "給料(きゅうりょう)が上(あ)がって、暮(く)らしの向上(こうじょう)を感(かん)じている。", "sentence_source": "generated"}, {"text": "本を読む習慣は、日本語の力の向上に役立つ。", "target_word": "向上", "complexity_tier": "T3", "furigana": "本(ほん)を読(よ)む習慣(しゅうかん)は、日本語(にほんご)の力(ちから)の向上(こうじょう)に役立(やくだ)つ。", "sentence_source": "generated"}, {"text": "運動を続ければ、体力の向上が期待できる。", "target_word": "向上", "complexity_tier": "T3", "furigana": "運動(うんどう)を続(つづ)ければ、体力(たいりょく)の向上(こうじょう)が期待(きたい)できる。", "sentence_source": "generated"}, {"text": "先月より成績が向上して、母がよろこんだ。", "target_word": "向上", "complexity_tier": "T3", "furigana": "先月(せんげつ)より成績(せいせき)が向上(こうじょう)して、母(はは)がよろこんだ。", "sentence_source": "generated"}, {"text": "道路が直されて、町の安全が向上した。", "target_word": "向上", "complexity_tier": "T3", "furigana": "道路(どうろ)が直(なお)されて、町(まち)の安全(あんぜん)が向上(こうじょう)した。", "sentence_source": "generated"}, {"text": "技術の向上には、毎日の小さな練習が大切だ。", "target_word": "向上", "complexity_tier": "T3", "furigana": "技術(ぎじゅつ)の向上(こうじょう)には、毎日(まいにち)の小(ちい)さな練習(れんしゅう)が大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "サービスの向上のため、店員は新しい研修を受けている。", "target_word": "向上", "complexity_tier": "T3", "furigana": "サービスの向上(こうじょう)のため、店員(てんいん)は新(あたら)しい研修(けんしゅう)を受(う)けている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "向上", "label": "辞書形"}, {"form": "向上する", "label": "する動詞の辞書形"}, {"form": "向上した", "label": "過去形"}, {"form": "向上して", "label": "て形"}, {"form": "向上しない", "label": "否定形"}, {"form": "向上させる", "label": "使役形"}], "register": "標準", "sense_fingerprint": "能力・品質・成績などが以前より良い状態に上がること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215eb90-f0e8-463e-beea-b84a82a01593') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37380, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "向上", "is_correct": true, "explanation": "「向上した」で「力がだんだん良くなった」という変化を表し、文脈に合う。"}, {"text": "能力", "is_correct": false, "explanation": "「能力」は「〜した」で変化を表せない名詞なので、「力が能力した」は成り立たない。"}, {"text": "速さ", "is_correct": false, "explanation": "「速さ」は状態を表す名詞で「〜した」と変化を表せず、「力が速さした」は不自然。"}, {"text": "体力", "is_correct": false, "explanation": "「体力」は「〜した」と変化を表せない名詞なので、ここでは使えない。"}], "explanations": {"向上": "「向上した」で「力がだんだん良くなった」という変化を表し、文脈に合う。", "能力": "「能力」は「〜した」で変化を表せない名詞なので、「力が能力した」は成り立たない。", "速さ": "「速さ」は状態を表す名詞で「〜した」と変化を表せず、「力が速さした」は不自然。", "体力": "「体力」は「〜した」と変化を表せない名詞なので、ここでは使えない。"}, "sentence_index": 0, "correct_answer": "向上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "道路の渋滞の向上を目指して、信号を増やした。", "explanation": "ここは〈改善〉の意味。向上は能力や品質が良くなることで、問題を直す意味では使わない。"}, {"text": "物価の向上を心配して、家計を見直した。", "explanation": "ここは〈上昇〉の意味。向上は良くなることを指すので、数値や物価が上がることには使わない。"}, {"text": "人口の向上に合わせて、学校の数を増やした。", "explanation": "ここは〈増加〉の意味。向上は質が良くなることで、人数が増えることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37380, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向上", "is_correct": true, "explanation": "「向上して」で成績が良くなった変化を表し、「母がよろこんだ」と筋が通る。"}, {"text": "学力", "is_correct": false, "explanation": "「学力」は「〜した」で変化を表せない名詞なので、「成績が学力した」は成り立たない。"}, {"text": "腕前", "is_correct": false, "explanation": "「腕前」は「〜した」で変化を表せない名詞なので、ここでは使えない。"}, {"text": "点数", "is_correct": false, "explanation": "「点数」は「〜した」と変化を表せず、「成績が点数した」は不自然。"}], "explanations": {"向上": "「向上して」で成績が良くなった変化を表し、「母がよろこんだ」と筋が通る。", "学力": "「学力」は「〜した」で変化を表せない名詞なので、「成績が学力した」は成り立たない。", "腕前": "「腕前」は「〜した」で変化を表せない名詞なので、ここでは使えない。", "点数": "「点数」は「〜した」と変化を表せず、「成績が点数した」は不自然。"}, "sentence_index": 6, "correct_answer": "向上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "急に寒さが向上して、体調を崩した。", "explanation": "ここは〈増す〉の意味。向上は良くなることを指すので、程度が強まる意味では使えない。"}, {"text": "電気代の向上のため、使わない部屋の照明を消した。", "explanation": "ここは〈節約〉の意味。向上は良くなることを指すので、費用を抑える意味では使わない。"}, {"text": "食料の向上を補うため、農地を増やした。", "explanation": "ここは〈不足を埋める〉の意味。向上は良くなることを指すので、足りない分を埋める意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37380, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい設備を導入して、工場の生産性が向上させた。", "corrected_sentence": "新しい設備を導入して、工場の生産性が向上した。", "error_description": "誤りは「向上させた」。主語が「生産性が」の自動詞の文に、他動詞の「させる」形を使っている。「生産性が向上した」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37380, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい研修で、店員の接客が向上させた。", "corrected_sentence": "新しい研修で、店員の接客が向上した。", "error_description": "誤りは「させた」。「向上させた」は他動詞で「〜を向上させた」と目的語が必要。接客が自ら良くなる場合は自動詞の「向上した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73e22a99-b1b1-4831-95f5-f73810dfd3a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37382, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『意見を聞く』の目的語を示す『を』で、空所に入ると文意が通る。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示すので、『意見が聞きました』では目的語を表せず不自然。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すので、『意見で聞きました』とは言えない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すので、『意見へ聞きました』では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "『意見を聞く』の目的語を示す『を』で、空所に入ると文意が通る。", "が": "『が』は主語を示すので、『意見が聞きました』では目的語を表せず不自然。", "で": "『で』は手段や場所を示すので、『意見で聞きました』とは言えない。", "へ": "『へ』は方向を示すので、『意見へ聞きました』では意味が通らない。"}, "error_tags": {"が": "主語の格", "で": "手段の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37382, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『意見を言う』の目的語を示す『を』で、空所に入ると文意が通る。"}, {"text": "に", "is_correct": false, "explanation": "『に』は相手や方向を示すので、『意見に言うとき』では目的語が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示すので、『意見が言うとき』では『言う』の目的語にならず不自然。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示すので、『意見から言うとき』では文意が通らない。"}], "correct_answer": "を", "explanations": {"を": "『意見を言う』の目的語を示す『を』で、空所に入ると文意が通る。", "に": "『に』は相手や方向を示すので、『意見に言うとき』では目的語が成り立たない。", "が": "『が』は主語を示すので、『意見が言うとき』では『言う』の目的語にならず不自然。", "から": "『から』は起点を示すので、『意見から言うとき』では文意が通らない。"}, "error_tags": {"に": "相手・方向の格", "より": "比較の格", "が": "主語の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37382, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分の考えを言うこと。", "primary_collocate": null, "pronunciation": "いけん", "ipa": "ikeɴ", "syllable_count": 3, "sentences": [{"text": "会議で自分の意見を言うのは、少し緊張します。", "target_word": "意見", "complexity_tier": "T3", "furigana": "会議[かいぎ]で自分[じぶん]の意見[いけん]を言[い]うのは、少[すこ]し緊張[きんちょう]します。", "sentence_source": "generated"}, {"text": "先生は生徒一人ひとりに意見を聞きました。", "target_word": "意見", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]一人[ひとり]ひとりに意見[いけん]を聞[き]きました。", "sentence_source": "generated"}, {"text": "彼は反対の意見をはっきり述べた。", "target_word": "意見", "complexity_tier": "T3", "furigana": "彼[かれ]は反対[はんたい]の意見[いけん]をはっきり述[の]べた。", "sentence_source": "generated"}, {"text": "何か意見がある人は、手を挙げてください。", "target_word": "意見", "complexity_tier": "T3", "furigana": "何[なに]か意見[いけん]がある人[ひと]は、手[て]を挙[あ]げてください。", "sentence_source": "generated"}, {"text": "恥ずかしくて、みんなの前で意見が言えなかった。", "target_word": "意見", "complexity_tier": "T3", "furigana": "恥[は]ずかしくて、みんなの前[まえ]で意見[いけん]が言[い]えなかった。", "sentence_source": "generated"}, {"text": "意見を出し合ったおかげで、いい計画ができた。", "target_word": "意見", "complexity_tier": "T3", "furigana": "意見[いけん]を出[だ]し合[あ]ったおかげで、いい計画[けいかく]ができた。", "sentence_source": "generated"}, {"text": "母にも意見を求めたが、「好きにしなさい」と言われた。", "target_word": "意見", "complexity_tier": "T3", "furigana": "母[はは]にも意見[いけん]を求[もと]めたが、「好[す]きにしなさい」と言[い]われた。", "sentence_source": "generated"}, {"text": "田中さんは意見を言うとき、いつも理由も説明する。", "target_word": "意見", "complexity_tier": "T3", "furigana": "田中[たなか]さんは意見[いけん]を言[い]うとき、いつも理由[りゆう]も説明[せつめい]する。", "sentence_source": "generated"}, {"text": "アンケートに意見を書いて、箱に入れてください。", "target_word": "意見", "complexity_tier": "T3", "furigana": "アンケートに意見[いけん]を書[か]いて、箱[はこ]に入[い]れてください。", "sentence_source": "generated"}, {"text": "新しい店について、お客さんの意見を聞いてみよう。", "target_word": "意見", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]について、お客[きゃく]さんの意見[いけん]を聞[き]いてみよう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "意見", "label": "基本形"}], "register": "中立", "sense_fingerprint": "意見=自分の考えを口に出して言うこと(述べる・聞く・求める)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51f98b6-eb48-454d-9dc5-99a082a5e10b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37382, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意見", "is_correct": true, "explanation": "「自分の考えを言う」の意味に合い、空所に入ると文意が通る。"}, {"text": "機会", "is_correct": false, "explanation": "機会は「チャンス」の意味で、自分の考えを言う対象にはならないので合わない。"}, {"text": "順番", "is_correct": false, "explanation": "順番は並ぶ順序のことで、自分の考えそのものとして言うものではないので合わない。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は時間の一点を指し、自分の考えを言う内容にはならないので合わない。"}], "explanations": {"意見": "「自分の考えを言う」の意味に合い、空所に入ると文意が通る。", "機会": "機会は「チャンス」の意味で、自分の考えを言う対象にはならないので合わない。", "順番": "順番は並ぶ順序のことで、自分の考えそのものとして言うものではないので合わない。", "時刻": "時刻は時間の一点を指し、自分の考えを言う内容にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "意見"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はその意見を誤った。", "explanation": "ここは〈判断〉の意味。判断は誤るものだが、意見を誤るとは言わないので合わない。"}, {"text": "その映画は、観客から高い意見を得た。", "explanation": "ここは〈評価〉の意味。評価は高い・低いで表すが、意見には高低の評価を当てないので合わない。"}, {"text": "この言葉の意見がわからないので、辞書で調べた。", "explanation": "ここは〈意味〉の意味。言葉の意味は辞書で調べるものだが、意見は言葉の中身を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37382, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意見", "is_correct": true, "explanation": "「求める」の目的語として文意が通り、空所に入る唯一の語。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、母に求めるものとしては成り立たないので合わない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時の区分で、求めて得るものではないので合わない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は学ぶ場所で、母に求める対象として文が成り立たないので合わない。"}], "explanations": {"意見": "「求める」の目的語として文意が通り、空所に入る唯一の語。", "天気": "天気は空模様のことで、母に求めるものとしては成り立たないので合わない。", "季節": "季節は時の区分で、求めて得るものではないので合わない。", "教室": "教室は学ぶ場所で、母に求める対象として文が成り立たないので合わない。"}, "sentence_index": 6, "correct_answer": "意見"}, "level_6": {"correct_sentence_index": 4, "wrong_sentences": [{"text": "その説明を聞いて、彼はその意見をすっかり晴らした。", "explanation": "ここは〈疑問〉の意味。疑問は晴らすものだが、意見を晴らすとは言わないので合わない。"}, {"text": "雨の日の運転では、足元の意見を払うことが大切だ。", "explanation": "ここは〈注意〉の意味。注意は払うものだが、意見は払うものではないので合わない。"}, {"text": "指先の意見を研ぎ澄ませている。", "explanation": "ここは〈感覚〉の意味。感覚は研ぎ澄ませるものだが、意見は研ぎ澄ませないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37382, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は生徒全員に意見に求めた。", "corrected_sentence": "先生は生徒全員に意見を求めた。", "error_description": "『求める』は目的語に助詞『を』を取る。『意見に求めた』は誤りで、『意見を求めた』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
