INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37383, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある問題や物事について、人が持っている考えや判断。", "primary_collocate": null, "pronunciation": "いけん", "ipa": "ikeɴ", "syllable_count": 3, "sentences": [{"text": "この問題については、二人の意見が違う。", "target_word": "意見", "complexity_tier": "T3", "furigana": "この問題[もんだい]については、二人[ふたり]の意見[いけん]が違[ちが]う。", "sentence_source": "generated"}, {"text": "私は彼の意見に賛成です。", "target_word": "意見", "complexity_tier": "T3", "furigana": "私[わたし]は彼[かれ]の意見[いけん]に賛成[さんせい]です。", "sentence_source": "generated"}, {"text": "専門家の間でも、意見は一つにまとまらなかった。", "target_word": "意見", "complexity_tier": "T3", "furigana": "専門家[せんもんか]の間[あいだ]でも、意見[いけん]は一[ひと]つにまとまらなかった。", "sentence_source": "generated"}, {"text": "彼女は自分の意見をしっかり持っている。", "target_word": "意見", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は自分[じぶん]の意見[いけん]をしっかり持[も]っている。", "sentence_source": "generated"}, {"text": "その意見には、私は反対だ。", "target_word": "意見", "complexity_tier": "T3", "furigana": "その意見[いけん]には、私[わたし]は反対[はんたい]だ。", "sentence_source": "generated"}, {"text": "医者の意見によると、あと一週間は休んだほうがいい。", "target_word": "意見", "complexity_tier": "T3", "furigana": "医者[いしゃ]の意見[いけん]によると、あと一週間[いっしゅうかん]は休[やす]んだほうがいい。", "sentence_source": "generated"}, {"text": "意見の違いがあっても、友だちでいられる。", "target_word": "意見", "complexity_tier": "T3", "furigana": "意見[いけん]の違[ちが]いがあっても、友[とも]だちでいられる。", "sentence_source": "generated"}, {"text": "多くの人が、同じ意見を持っている。", "target_word": "意見", "complexity_tier": "T3", "furigana": "多[おお]くの人[ひと]が、同[おな]じ意見[いけん]を持[も]っている。", "sentence_source": "generated"}, {"text": "ネットには、いろいろな意見がある。", "target_word": "意見", "complexity_tier": "T3", "furigana": "ネットには、いろいろな意見[いけん]がある。", "sentence_source": "generated"}, {"text": "年を取って、考え方が変わり、意見も変わった。", "target_word": "意見", "complexity_tier": "T3", "furigana": "年[とし]を取[と]って、考[かんが]え方[かた]が変[か]わり、意見[いけん]も変[か]わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "意見", "label": "基本形"}], "register": "中立", "sense_fingerprint": "意見=ある問題について人が持つ考え・判断(賛成・反対・違いの対象)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51f98b6-eb48-454d-9dc5-99a082a5e10b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37383, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "意見", "is_correct": true, "explanation": "「二人の考えが違う」の意味に合い、空所に入ると文意が通る。"}, {"text": "予言", "is_correct": false, "explanation": "予言は将来の出来事を言い当てるもので、二人の食い違いの主題としては合わない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時期のことで、二人の考えの食い違いには当てはまらないので合わない。"}, {"text": "紙幣", "is_correct": false, "explanation": "紙幣はお金のことで、二人の考えの食い違いには当てはまらないので合わない。"}], "explanations": {"意見": "「二人の考えが違う」の意味に合い、空所に入ると文意が通る。", "予言": "予言は将来の出来事を言い当てるもので、二人の食い違いの主題としては合わない。", "季節": "季節は時期のことで、二人の考えの食い違いには当てはまらないので合わない。", "紙幣": "紙幣はお金のことで、二人の考えの食い違いには当てはまらないので合わない。"}, "sentence_index": 0, "correct_answer": "意見"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その作品は、批評家から低い意見を受けた。", "explanation": "ここは〈評価〉の意味。評価は高い・低いで表すが、意見には高低の評価を当てないので合わない。"}, {"text": "今朝の天気の意見が外れて、傘を持たずに出かけてしまった。", "explanation": "ここは〈予想〉の意味。予想は当たったり外れたりするものだが、意見は天気の見通しを表さないので合わない。"}, {"text": "運転中は、前方の意見を払ってほしい。", "explanation": "ここは〈注意〉の意味。注意は払うものだが、意見は払うものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37383, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意見", "is_correct": true, "explanation": "「考えの違い」の意味に合い、空所に入ると文意が通る。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている人の呼吸音で、友だちの違いとしては成り立たないので合わない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上の面で、考えの違いとしては成り立たないので合わない。"}, {"text": "湯気", "is_correct": false, "explanation": "湯気は蒸気のことで、考えの違いとは結びつかないので合わない。"}], "explanations": {"意見": "「考えの違い」の意味に合い、空所に入ると文意が通る。", "寝息": "寝息は眠っている人の呼吸音で、友だちの違いとしては成り立たないので合わない。", "天井": "天井は部屋の上の面で、考えの違いとしては成り立たないので合わない。", "湯気": "湯気は蒸気のことで、考えの違いとは結びつかないので合わない。"}, "sentence_index": 6, "correct_answer": "意見"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その説明で、彼女は長年の意見を晴らした。", "explanation": "ここは〈疑問〉の意味。疑問は晴らすものだが、意見を晴らすとは言わないので合わない。"}, {"text": "話し合いの末、彼は私の意見をきれいに解いてくれた。", "explanation": "ここは〈誤解〉の意味。誤解は解くものだが、意見を解くとは言わないので合わない。"}, {"text": "ピアニストは耳の意見を研ぎ澄ませている。", "explanation": "ここは〈感覚〉の意味。感覚は研ぎ澄ませるものだが、意見は研ぎ澄ませないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37383, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は彼の意見を賛成する。", "corrected_sentence": "私は彼の意見に賛成する。", "error_description": "『賛成する』は助詞『に』を取る。『意見を賛成する』は誤りで、『意見に賛成する』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37383, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は彼女の意見に尊重した。", "corrected_sentence": "彼は彼女の意見を尊重した。", "error_description": "『尊重する』は目的語に助詞『を』を取る。『意見に尊重した』は誤りで、『意見を尊重した』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
