INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37384, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、チャットが「送った」主体になるのは不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「チャットと送った文を」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、「チャットより送った文」は比較として成り立たない。"}, {"text": "で", "is_correct": true, "explanation": "「チャットで送った文を」と手段を示し、自然に続く。"}], "correct_answer": "で", "explanations": {"が": "「が」は主語を示すが、チャットが「送った」主体になるのは不自然。", "と": "「と」は相手や並列を示すが、「チャットと送った文を」は意味が通らない。", "より": "「より」は比較を示すが、「チャットより送った文」は比較として成り立たない。", "で": "「チャットで送った文を」と手段を示し、自然に続く。"}, "error_tags": {"が": "主語", "と": "相手・並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37384, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "チャットは、コンピュータや電話で、文字を打って人と話すことです。", "primary_collocate": null, "pronunciation": "ちゃっと", "ipa": "tɕatːo", "syllable_count": 3, "sentences": [{"text": "夜、友だちとチャットで話した。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "夜[よる]、友[とも]だちとチャットで話[はな]した。", "sentence_source": "generated"}, {"text": "仕事の相談は、会議よりチャットのほうが早い。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "仕事[しごと]の相談[そうだん]は、会議[かいぎ]よりチャットのほうが早[はや]い。", "sentence_source": "generated"}, {"text": "電話が苦手なので、チャットで連絡します。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "電話[でんわ]が苦手[にがて]なので、チャットで連絡[れんらく]します。", "sentence_source": "generated"}, {"text": "チャットでは、顔が見えないので、言葉に気をつける。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "チャットでは、顔[かお]が見[み]えないので、言葉[ことば]に気[き]をつける。", "sentence_source": "generated"}, {"text": "兄は毎晩、外国の友だちとチャットをしている。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "兄[あに]は毎晩[まいばん]、外国[がいこく]の友[とも]だちとチャットをしている。", "sentence_source": "generated"}, {"text": "授業中にチャットが届いて、すぐ返事をした。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "授業中[じゅぎょうちゅう]にチャットが届[とど]いて、すぐ返事[へんじ]をした。", "sentence_source": "generated"}, {"text": "声を出せない場所なので、チャットで話しましょう。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "声[こえ]を出[だ]せない場所[ばしょ]なので、チャットで話[はな]しましょう。", "sentence_source": "generated"}, {"text": "チャットで送った文を、あとから読み返した。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "チャットで送[おく]った文[ぶん]を、あとから読[よ]み返[かえ]した。", "sentence_source": "generated"}, {"text": "画面の右側に、チャットの文字が次々と出てくる。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "画面[がめん]の右側[みぎがわ]に、チャットの文字[もじ]が次々[つぎつぎ]と出[で]てくる。", "sentence_source": "generated"}, {"text": "友だちのチャットはいつも短くて、返事が早い。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "友[とも]だちのチャットはいつも短[みじか]くて、返事[へんじ]が早[はや]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チャット", "label": "基本形"}], "register": "口語", "sense_fingerprint": "機器で文字を打って人と話すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ecbfbe-96fb-4154-838a-29e711cd0c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37384, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "写真", "is_correct": false, "explanation": "画像で話す手段ではないので、「友だちと写真で話した」は成立しない。"}, {"text": "天気", "is_correct": false, "explanation": "話題にはなるが、話す手段ではないので空欄には合わない。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物の名前で話す手段ではないので、空欄には入らない。"}, {"text": "チャット", "is_correct": true, "explanation": "機器で文字を打って話す手段で、「夜、友だちとチャットで話した」と自然に続く。"}], "explanations": {"写真": "画像で話す手段ではないので、「友だちと写真で話した」は成立しない。", "天気": "話題にはなるが、話す手段ではないので空欄には合わない。", "料理": "食べ物の名前で話す手段ではないので、空欄には入らない。", "チャット": "機器で文字を打って話す手段で、「夜、友だちとチャットで話した」と自然に続く。"}, "sentence_index": 0, "correct_answer": "チャット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "チャットは、受話器を耳に当てて話す。", "explanation": "ここは〈通話〉の意味。チャットは文字で話すので、受話器を耳に当てて話す意味とは合わない。"}, {"text": "チャットは、件名を入れて送る。", "explanation": "ここは〈メール〉の意味。件名の欄があるのはメールで、チャットには合わない。"}, {"text": "チャットは、切手をはって出す。", "explanation": "ここは〈手紙〉の意味。郵便で送る手紙の話で、チャットは切手を使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37384, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地図", "is_correct": false, "explanation": "場所を示す道具で話す手段ではないので、「地図で話しましょう」は成立しない。"}, {"text": "靴", "is_correct": false, "explanation": "身につける物で話す手段ではないので、空欄には合わない。"}, {"text": "鍵", "is_correct": false, "explanation": "扉を開ける道具で話す手段ではないので、空欄には入らない。"}, {"text": "チャット", "is_correct": true, "explanation": "文字で話す手段で、「声を出せない場所なので、チャットで話しましょう」と自然に続く。"}], "explanations": {"地図": "場所を示す道具で話す手段ではないので、「地図で話しましょう」は成立しない。", "靴": "身につける物で話す手段ではないので、空欄には合わない。", "鍵": "扉を開ける道具で話す手段ではないので、空欄には入らない。", "チャット": "文字で話す手段で、「声を出せない場所なので、チャットで話しましょう」と自然に続く。"}, "sentence_index": 6, "correct_answer": "チャット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "チャットは、長い文章を公開して読んでもらう。", "explanation": "ここは〈ブログ〉の意味。チャットは短い文字で即時に会話するもので、公開の記事を指すのに合わない。"}, {"text": "チャットは、映像と声で伝える。", "explanation": "ここは〈動画〉の意味。チャットは文字で伝えるので、映像と声で伝える形とは合わない。"}, {"text": "チャットは、決まった時間に番組を流す。", "explanation": "ここは〈ラジオ〉の意味。番組を放送する仕組みを指すので、会話のチャットには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37384, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昼休みに、同僚とチャットを話した。", "corrected_sentence": "昼休みに、同僚とチャットで話した。", "error_description": "「話す」の手段は「で」で示す。「チャットを」は誤りで、「チャットで」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37384, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "深夜に、遠くの友だちからチャットを届いた。", "corrected_sentence": "深夜に、遠くの友だちからチャットが届いた。", "error_description": "「届く」は自動詞で、主語に「が」をとる。「を」は誤りで、「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37385, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37385, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「チャットを、名前を出さない」は文として成立しない。"}, {"text": "は", "is_correct": true, "explanation": "主題を示す「は」で、後ろの「名前を出さないほうがいい」に自然に続く。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「チャットと、名前を出さない」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐが、「チャットの、名前を出さない」は主題として機能しない。"}], "correct_answer": "は", "explanations": {"を": "「を」は目的語を示すが、「チャットを、名前を出さない」は文として成立しない。", "は": "主題を示す「は」で、後ろの「名前を出さないほうがいい」に自然に続く。", "と": "「と」は相手や並列を示すが、「チャットと、名前を出さない」は意味が通らない。", "の": "「の」は名詞をつなぐが、「チャットの、名前を出さない」は主題として機能しない。"}, "error_tags": {"を": "目的語", "と": "相手・並列", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37385, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "チャットとは、インターネットなどを通じて、リアルタイムで文字による会話をすることを指す。", "primary_collocate": null, "pronunciation": "ちゃっと", "ipa": "tɕatːo", "syllable_count": 3, "sentences": [{"text": "インターネットのチャットで、遠くの人と話した。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "インターネットのチャットで、遠[とお]くの人[ひと]と話[はな]した。", "sentence_source": "generated"}, {"text": "ライブ配信を見ながら、みんなでチャットをした。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "ライブ配信[はいしん]を見[み]ながら、みんなでチャットをした。", "sentence_source": "generated"}, {"text": "この会社では、会議の間もチャットで意見を出す。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]では、会議[かいぎ]の間[あいだ]もチャットで意見[いけん]を出[だ]す。", "sentence_source": "generated"}, {"text": "チャットはリアルタイムなので、すぐ返事が来る。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "チャットはリアルタイムなので、すぐ返事[へんじ]が来[く]る。", "sentence_source": "generated"}, {"text": "ゲームの仲間と、チャットで作戦を相談した。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "ゲームの仲間[なかま]と、チャットで作戦[さくせん]を相談[そうだん]した。", "sentence_source": "generated"}, {"text": "先生とのチャットは、午後三時からだ。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "先生[せんせい]とのチャットは、午後[ごご]三時[さんじ]からだ。", "sentence_source": "generated"}, {"text": "チャットの部屋に入ると、もう五人が話していた。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "チャットの部屋[へや]に入[はい]ると、もう五人[ごにん]が話[はな]していた。", "sentence_source": "generated"}, {"text": "知らない人とのチャットは、名前を出さないほうがいい。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "知[し]らない人[ひと]とのチャットは、名前[なまえ]を出[だ]さないほうがいい。", "sentence_source": "generated"}, {"text": "質問があれば、チャットに書いてください。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "質問[しつもん]があれば、チャットに書[か]いてください。", "sentence_source": "generated"}, {"text": "急ぎの用事は、メールでなくチャットで送る。", "target_word": "チャット", "complexity_tier": "T3", "furigana": "急[いそ]ぎの用事[ようじ]は、メールでなくチャットで送[おく]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チャット", "label": "基本形"}], "register": "口語", "sense_fingerprint": "インターネット上でのリアルタイムの文字会話", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ecbfbe-96fb-4154-838a-29e711cd0c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37385, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "野菜", "is_correct": false, "explanation": "食べ物で話す手段ではないので、「インターネットの野菜で話した」は成立しない。"}, {"text": "靴", "is_correct": false, "explanation": "身につける物で話す手段ではないので、空欄には合わない。"}, {"text": "地図", "is_correct": false, "explanation": "場所を示す道具で話す手段ではないので、空欄には入らない。"}, {"text": "チャット", "is_correct": true, "explanation": "インターネット上でリアルタイムに文字で話す手段で、「インターネットのチャットで、遠くの人と話した」と自然に続く。"}], "explanations": {"野菜": "食べ物で話す手段ではないので、「インターネットの野菜で話した」は成立しない。", "靴": "身につける物で話す手段ではないので、空欄には合わない。", "地図": "場所を示す道具で話す手段ではないので、空欄には入らない。", "チャット": "インターネット上でリアルタイムに文字で話す手段で、「インターネットのチャットで、遠くの人と話した」と自然に続く。"}, "sentence_index": 0, "correct_answer": "チャット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "チャットは、受話器を耳に当てて声で会話する。", "explanation": "ここは〈通話〉の意味。チャットは文字による会話なので、声で話すという意味とは合わない。"}, {"text": "チャットは、郵便で届くまで数日かかる。", "explanation": "ここは〈手紙〉の意味。チャットは郵便を使わないので、届くまでの日数を言う文には合わない。"}, {"text": "チャットは、決まった時間に番組を流す。", "explanation": "ここは〈テレビ〉の意味。番組を放送する仕組みを指すので、会話のチャットには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37385, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飛行機", "is_correct": false, "explanation": "乗り物で部屋ではないので、「飛行機の部屋に入ると」は成立しない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで部屋ではないので、空欄には合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "調味料で部屋ではないので、空欄には入らない。"}, {"text": "チャット", "is_correct": true, "explanation": "複数人が文字で話す場所を指し、「チャットの部屋に入ると」と自然に続く。"}], "explanations": {"飛行機": "乗り物で部屋ではないので、「飛行機の部屋に入ると」は成立しない。", "天気": "空模様のことで部屋ではないので、空欄には合わない。", "砂糖": "調味料で部屋ではないので、空欄には入らない。", "チャット": "複数人が文字で話す場所を指し、「チャットの部屋に入ると」と自然に続く。"}, "sentence_index": 6, "correct_answer": "チャット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "チャットは、声をあとから聞き返せる。", "explanation": "ここは〈録音〉の意味。チャットは文字で残るので、声を記録する意味では合わない。"}, {"text": "チャットは、その場の景色を残す。", "explanation": "ここは〈写真〉の意味。チャットは画像ではなく文字の会話を指すので、景色を残す意味には合わない。"}, {"text": "チャットは、食材を冷やして保存する。", "explanation": "ここは〈冷蔵庫〉の意味。食材を冷やして保存する機械は文字で会話する仕組みではないので、チャットとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37385, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ゲームの試合中も、チャットを仲間と話せる。", "corrected_sentence": "ゲームの試合中も、チャットで仲間と話せる。", "error_description": "「話す」の手段は「で」で示す。「チャットを」は誤りで、「チャットで」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37385, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜、チャットをログインしたら、友だちがいた。", "corrected_sentence": "夜、チャットにログインしたら、友だちがいた。", "error_description": "「ログインする」は「に」で行き先を示す。「チャットを」は誤りで、「チャットに」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37386, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『音声を英語に変える』の目的語を示す『を』で、空所に入ると文意が通る。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すので、『音声へ英語に変えられる』では文意が通らない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は所属を示すので、『音声の英語に変えられる』では文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示すので、『音声より英語に変えられる』では文意が通らない。"}], "correct_answer": "を", "explanations": {"を": "『音声を英語に変える』の目的語を示す『を』で、空所に入ると文意が通る。", "へ": "『へ』は方向を示すので、『音声へ英語に変えられる』では文意が通らない。", "の": "『の』は所属を示すので、『音声の英語に変えられる』では文が成り立たない。", "より": "『より』は比較を示すので、『音声より英語に変えられる』では文意が通らない。"}, "error_tags": {"へ": "方向の格", "の": "所属の格", "より": "比較の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
