INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37386, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "耳で聞くことができる、人の声や物の音のこと。", "primary_collocate": null, "pronunciation": "おんせい", "ipa": "oɴseː", "syllable_count": 4, "sentences": [{"text": "古いビデオは、音声が小さくて聞こえにくい。", "target_word": "音声", "complexity_tier": "T3", "furigana": "古[ふる]いビデオは、音声[おんせい]が小[ちい]さくて聞[き]こえにくい。", "sentence_source": "generated"}, {"text": "このテレビは、音声を英語に変えられる。", "target_word": "音声", "complexity_tier": "T3", "furigana": "このテレビは、音声[おんせい]を英語[えいご]に変[か]えられる。", "sentence_source": "generated"}, {"text": "動画の音声が途中で消えてしまった。", "target_word": "音声", "complexity_tier": "T3", "furigana": "動画[どうが]の音声[おんせい]が途中[とちゅう]で消[き]えてしまった。", "sentence_source": "generated"}, {"text": "電話の音声がとぎれて、話が分からなかった。", "target_word": "音声", "complexity_tier": "T3", "furigana": "電話[でんわ]の音声[おんせい]がとぎれて、話[はなし]が分[わ]からなかった。", "sentence_source": "generated"}, {"text": "会議の音声を録音して、あとで聞き直した。", "target_word": "音声", "complexity_tier": "T3", "furigana": "会議[かいぎ]の音声[おんせい]を録音[ろくおん]して、あとで聞[き]き直[なお]した。", "sentence_source": "generated"}, {"text": "映像はきれいだが、音声にノイズが入っている。", "target_word": "音声", "complexity_tier": "T3", "furigana": "映像[えいぞう]はきれいだが、音声[おんせい]にノイズが入[はい]っている。", "sentence_source": "generated"}, {"text": "音声を消して、映画を字幕だけで見た。", "target_word": "音声", "complexity_tier": "T3", "furigana": "音声[おんせい]を消[け]して、映画[えいが]を字幕[じまく]だけで見[み]た。", "sentence_source": "generated"}, {"text": "映像がなくても、音声だけで様子が分かった。", "target_word": "音声", "complexity_tier": "T3", "furigana": "映像[えいぞう]がなくても、音声[おんせい]だけで様子[ようす]が分[わ]かった。", "sentence_source": "generated"}, {"text": "目の不自由な人のために、音声で道を案内する。", "target_word": "音声", "complexity_tier": "T3", "furigana": "目[め]の不自由[ふじゆう]な人[ひと]のために、音声[おんせい]で道[みち]を案内[あんない]する。", "sentence_source": "generated"}, {"text": "駅のホームで、電車の到着を知らせる音声が流れている。", "target_word": "音声", "complexity_tier": "T3", "furigana": "駅[えき]のホームで、電車[でんしゃ]の到着[とうちゃく]を知[し]らせる音声[おんせい]が流[なが]れている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "音声", "label": "基本形"}], "register": "中立", "sense_fingerprint": "音声=映像・通話などに含まれる、耳で聞く声や音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: とぎれ (Zipf 2.0)']::text[], 'f51f98b6-eb48-454d-9dc5-99a082a5e10b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37386, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音声", "is_correct": true, "explanation": "耳で聞こえる音を指し、『小さくて聞こえにくい』の主語として文意が通る。"}, {"text": "字幕", "is_correct": false, "explanation": "字幕は画面に出る文字で、耳で聞こえるものではないので合わない。"}, {"text": "画面", "is_correct": false, "explanation": "画面は見るものなので、『聞こえにくい』の主語にはならないので合わない。"}, {"text": "色", "is_correct": false, "explanation": "色は見た目の性質で、『聞こえにくい』の主語にはならないので合わない。"}], "explanations": {"音声": "耳で聞こえる音を指し、『小さくて聞こえにくい』の主語として文意が通る。", "字幕": "字幕は画面に出る文字で、耳で聞こえるものではないので合わない。", "画面": "画面は見るものなので、『聞こえにくい』の主語にはならないので合わない。", "色": "色は見た目の性質で、『聞こえにくい』の主語にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "音声"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は、音声を描くのが得意だ。", "explanation": "ここは〈絵〉の意味。絵は描くものだが、音声を描くとは言わないので合わない。"}, {"text": "壁に、音声を塗ってきれいにした。", "explanation": "ここは〈色〉の意味。色は塗るものだが、音声は塗れないので合わない。"}, {"text": "スクリーンに、音声を映した。", "explanation": "ここは〈映像〉の意味。映像は映すものだが、音声は映せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37386, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音声", "is_correct": true, "explanation": "『音声を消す』は音を止める意味で、空所に入ると文意が通る。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは物の目方で、消すものではないので合わない。"}, {"text": "大きさ", "is_correct": false, "explanation": "大きさは寸法のことで、消すものではないので合わない。"}, {"text": "形", "is_correct": false, "explanation": "形は外見のことで、消すものではないので合わない。"}], "explanations": {"音声": "『音声を消す』は音を止める意味で、空所に入ると文意が通る。", "重さ": "重さは物の目方で、消すものではないので合わない。", "大きさ": "大きさは寸法のことで、消すものではないので合わない。", "形": "形は外見のことで、消すものではないので合わない。"}, "sentence_index": 6, "correct_answer": "音声"}, "level_6": {"correct_sentence_index": 5, "wrong_sentences": [{"text": "明日は、午後から音声が降るでしょう。", "explanation": "ここは〈雨〉の意味。雨は降るものだが、音声は降らないので合わない。"}, {"text": "台所から、おいしそうな音声が漂ってきた。", "explanation": "ここは〈香り〉の意味。香りは漂うものだが、音声は漂わないので合わない。"}, {"text": "桜の木の下で、音声が舞っている。", "explanation": "ここは〈花〉の意味。花は舞うものだが、音声は舞わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37386, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "テレビの音声を大きくなった。", "corrected_sentence": "テレビの音声を大きくした。", "error_description": "『大きくする』は他動詞で『音声を大きくした』と言う。『大きくなった』は自動詞で、目的語『を』とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
