INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37387, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が話す声や、機械などが出す音のこと。", "primary_collocate": null, "pronunciation": "おんせい", "ipa": "oɴseː", "syllable_count": 4, "sentences": [{"text": "このアプリは、音声で文字を入力できる。", "target_word": "音声", "complexity_tier": "T3", "furigana": "このアプリは、音声[おんせい]で文字[もじ]を入力[にゅうりょく]できる。", "sentence_source": "generated"}, {"text": "機械の音声が「次は東京です」と知らせた。", "target_word": "音声", "complexity_tier": "T3", "furigana": "機械[きかい]の音声[おんせい]が「次[つぎ]は東京[とうきょう]です」と知[し]らせた。", "sentence_source": "generated"}, {"text": "スマホに話しかけると、音声を読み取って答えてくれる。", "target_word": "音声", "complexity_tier": "T3", "furigana": "スマホに話[はな]しかけると、音声[おんせい]を読[よ]み取[と]って答[こた]えてくれる。", "sentence_source": "generated"}, {"text": "イヤホンから流れる音声を聞きながら、美術館を回った。", "target_word": "音声", "complexity_tier": "T3", "furigana": "イヤホンから流[なが]れる音声[おんせい]を聞[き]きながら、美術館[びじゅつかん]を回[まわ]った。", "sentence_source": "generated"}, {"text": "車の案内の音声は、女性の声に変えられる。", "target_word": "音声", "complexity_tier": "T3", "furigana": "車[くるま]の案内[あんない]の音声[おんせい]は、女性[じょせい]の声[こえ]に変[か]えられる。", "sentence_source": "generated"}, {"text": "録音した音声を文字にする仕事をしている。", "target_word": "音声", "complexity_tier": "T3", "furigana": "録音[ろくおん]した音声[おんせい]を文字[もじ]にする仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "通勤の電車の中で、音声でメールの文章を書いた。", "target_word": "音声", "complexity_tier": "T3", "furigana": "通勤[つうきん]の電車[でんしゃ]の中[なか]で、音声[おんせい]でメールの文章[ぶんしょう]を書[か]いた。", "sentence_source": "generated"}, {"text": "この人形は、ボタンを押すと音声が出る。", "target_word": "音声", "complexity_tier": "T3", "furigana": "この人形[にんぎょう]は、ボタンを押[お]すと音声[おんせい]が出[で]る。", "sentence_source": "generated"}, {"text": "病院の受付で、呼び出しの音声が流れた。", "target_word": "音声", "complexity_tier": "T3", "furigana": "病院[びょういん]の受付[うけつけ]で、呼[よ]び出[だ]しの音声[おんせい]が流[なが]れた。", "sentence_source": "generated"}, {"text": "外国語の音声を何度も聞いて、発音を練習する。", "target_word": "音声", "complexity_tier": "T3", "furigana": "外国語[がいこくご]の音声[おんせい]を何度[なんど]も聞[き]いて、発音[はつおん]を練習[れんしゅう]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "音声", "label": "基本形"}], "register": "中立", "sense_fingerprint": "音声=人の話し声や、機械が出す案内・読み上げの声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51f98b6-eb48-454d-9dc5-99a082a5e10b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37387, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音声", "is_correct": true, "explanation": "音声で入力する手段を表し、『音声で文字を入力できる』として文意が通る。"}, {"text": "太陽", "is_correct": false, "explanation": "太陽は天体で、文字を入力する手段にはならないので合わない。"}, {"text": "電池", "is_correct": false, "explanation": "電池は電力源で、文字入力の手段として文が成り立たないので合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は人の齢のことで、入力の手段にはならないので合わない。"}], "explanations": {"音声": "音声で入力する手段を表し、『音声で文字を入力できる』として文意が通る。", "太陽": "太陽は天体で、文字を入力する手段にはならないので合わない。", "電池": "電池は電力源で、文字入力の手段として文が成り立たないので合わない。", "年齢": "年齢は人の齢のことで、入力の手段にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "音声"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "そのパン屋は、朝早く音声をこねている。", "explanation": "ここは〈パン〉の意味。パンはこねるものだが、音声はこねられないので合わない。"}, {"text": "彼は机の上に音声を広げて、道順を確かめた。", "explanation": "ここは〈地図〉の意味。地図は広げるものだが、音声は広げられないので合わない。"}, {"text": "花瓶に、音声を生けた。", "explanation": "ここは〈花〉の意味。花は生けるものだが、音声は生けられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37387, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音声", "is_correct": true, "explanation": "音声で文章を書く手段を表し、『音声でメールの文章を書いた』として文意が通る。"}, {"text": "雨", "is_correct": false, "explanation": "雨は降るもので、メールの文章を書く手段にはならないので合わない。"}, {"text": "色", "is_correct": false, "explanation": "色は見た目のことで、文章を書く手段にはならないので合わない。"}, {"text": "湯気", "is_correct": false, "explanation": "湯気は蒸気のことで、文章を書く手段にはならないので合わない。"}], "explanations": {"音声": "音声で文章を書く手段を表し、『音声でメールの文章を書いた』として文意が通る。", "雨": "雨は降るもので、メールの文章を書く手段にはならないので合わない。", "色": "色は見た目のことで、文章を書く手段にはならないので合わない。", "湯気": "湯気は蒸気のことで、文章を書く手段にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "音声"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は黒板に、大きな音声を描いた。", "explanation": "ここは〈絵〉の意味。絵は描くものだが、音声を描くとは言わないので合わない。"}, {"text": "夕方から、音声が降り始めた。", "explanation": "ここは〈雨〉の意味。雨は降るものだが、音声は降らないので合わない。"}, {"text": "旅行で、きれいな景色の音声を撮った。", "explanation": "ここは〈写真〉の意味。写真は撮るものだが、音声を撮るとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37387, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "機械の音声を流れた。", "corrected_sentence": "機械の音声が流れた。", "error_description": "『流れる』は主語に助詞『が』を取る自動詞。『音声を流れた』は誤りで、『音声が流れた』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37387, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ナビの音声を道順を教えてくれた。", "corrected_sentence": "ナビの音声が道順を教えてくれた。", "error_description": "『教えてくれる』は主語に助詞『が』を取る。『音声を』は誤りで、『音声が』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
