INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37389, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37389, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "複数の人が互いに意見を述べ合い、考えを共有したり、結論を導いたりすること。", "primary_collocate": null, "pronunciation": "はなしあう", "ipa": "hanaɕiaɯ", "syllable_count": 5, "sentences": [{"text": "三時間話し合って、ようやく結論が出た。", "target_word": "話し合って", "complexity_tier": "T3", "furigana": "三時間[さんじかん]話[はな]し合[あ]って、ようやく結論[けつろん]が出[で]た。", "sentence_source": "generated"}, {"text": "委員会では、新しい規則について話し合い、全員で決めた。", "target_word": "話し合い", "complexity_tier": "T3", "furigana": "委員会[いいんかい]では、新[あたら]しい規則[きそく]について話[はな]し合[あ]い、全員[ぜんいん]で決[き]めた。", "sentence_source": "generated"}, {"text": "意見が分かれたときは、よく話し合って答えを探そう。", "target_word": "話し合って", "complexity_tier": "T3", "furigana": "意見[いけん]が分[わ]かれたときは、よく話[はな]し合[あ]って答[こた]えを探[さが]そう。", "sentence_source": "generated"}, {"text": "話し合った結果、旅行は来月に延期することになった。", "target_word": "話し合った", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]った結果[けっか]、旅行[りょこう]は来月[らいげつ]に延期[えんき]することになった。", "sentence_source": "generated"}, {"text": "社員みんなで話し合い、会社の方針をまとめた。", "target_word": "話し合い", "complexity_tier": "T3", "furigana": "社員[しゃいん]みんなで話[はな]し合[あ]い、会社[かいしゃ]の方針[ほうしん]をまとめた。", "sentence_source": "generated"}, {"text": "二つの案を話し合って、一つにまとめた。", "target_word": "話し合って", "complexity_tier": "T3", "furigana": "二[ふた]つの案[あん]を話[はな]し合[あ]って、一[ひと]つにまとめた。", "sentence_source": "generated"}, {"text": "兄弟で話し合うことで、お互いの考えが分かった。", "target_word": "話し合う", "complexity_tier": "T3", "furigana": "兄弟[きょうだい]で話[はな]し合[あ]うことで、お互[たが]いの考[かんが]えが分[わ]かった。", "sentence_source": "generated"}, {"text": "みんなが話し合えば、いい方法が見つかるはずだ。", "target_word": "話し合えば", "complexity_tier": "T3", "furigana": "みんなが話[はな]し合[あ]えば、いい方法[ほうほう]が見[み]つかるはずだ。", "sentence_source": "generated"}, {"text": "住民が話し合い、公園の使い方を決めた。", "target_word": "話し合い", "complexity_tier": "T3", "furigana": "住民[じゅうみん]が話[はな]し合[あ]い、公園[こうえん]の使[つか]い方[かた]を決[き]めた。", "sentence_source": "generated"}, {"text": "明日の会議で、予算をどうするか話し合おう。", "target_word": "話し合おう", "complexity_tier": "T3", "furigana": "明日[あした]の会議[かいぎ]で、予算[よさん]をどうするか話[はな]し合[あ]おう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "話し合う", "label": "終止形"}, {"form": "話し合います", "label": "マス形"}, {"form": "話し合って", "label": "テ形"}, {"form": "話し合った", "label": "タ形"}, {"form": "話し合わない", "label": "ナイ形"}, {"form": "話し合えば", "label": "仮定形"}, {"form": "話し合おう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "話し合う=複数の人が意見を出し合い、結論や方針を決める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51f98b6-eb48-454d-9dc5-99a082a5e10b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37389, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "話し合って", "is_correct": true, "explanation": "テ形。「三時間話し合って、ようやく結論が出た」と前後を続けて文が成立する。"}, {"text": "話し合え", "is_correct": false, "explanation": "命令の形。文脈は事実を述べているので、命令とは合わない。"}, {"text": "話し合おう", "is_correct": false, "explanation": "意志形。「三時間話し合おう」は意味が通らず、結論が出た事実と続かない。"}, {"text": "話し合わせ", "is_correct": false, "explanation": "使役の語幹。「話し合わせ」だけでは文が続かず、文脈に合わない。"}], "explanations": {"話し合って": "テ形。「三時間話し合って、ようやく結論が出た」と前後を続けて文が成立する。", "話し合え": "命令の形。文脈は事実を述べているので、命令とは合わない。", "話し合おう": "意志形。「三時間話し合おう」は意味が通らず、結論が出た事実と続かない。", "話し合わせ": "使役の語幹。「話し合わせ」だけでは文が続かず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "話し合って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は一人で、結論を話し合って決めた。", "explanation": "ここは〈自分ひとりで決める〉の意味。話し合うは複数の人が意見を述べ合う行為なので、一人の決定には合わない。"}, {"text": "この料理は、材料を話し合ってから煮込む。", "explanation": "ここは〈選ぶ・下ごしらえする〉の意味。話し合うの対象は意見や計画で、食材は話し合う対象にならない。"}, {"text": "二人は殴り合いながら、話し合った。", "explanation": "ここは〈殴り合う〉の意味。話し合うは言葉での意見交換なので、暴力を伴う行為とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37389, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "話し合う", "is_correct": true, "explanation": "辞書形。「兄弟で話し合うことで」と「こと」に続けて名詞句になる。"}, {"text": "話し合い", "is_correct": false, "explanation": "連用形。「話し合いことで」とは続かず、名詞句にならない。"}, {"text": "話し合わ", "is_correct": false, "explanation": "未然形の語幹。「話し合わことで」と続かず、文が成立しない。"}, {"text": "話し合おう", "is_correct": false, "explanation": "意志形。「話し合おうことで」は文法的に成立しない。"}], "explanations": {"話し合う": "辞書形。「兄弟で話し合うことで」と「こと」に続けて名詞句になる。", "話し合い": "連用形。「話し合いことで」とは続かず、名詞句にならない。", "話し合わ": "未然形の語幹。「話し合わことで」と続かず、文が成立しない。", "話し合おう": "意志形。「話し合おうことで」は文法的に成立しない。"}, "sentence_index": 6, "correct_answer": "話し合う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は生徒に、宿題の答えを一人で話し合って教えた。", "explanation": "ここは〈ひとりで教える〉の意味。話し合うは複数の人が意見を述べ合う行為なので、一人の伝達とは合わない。"}, {"text": "ペンを話し合って、紙に字を書いた。", "explanation": "ここは〈書く・使う〉の意味。話し合うの対象は意見や計画で、道具のペンは対象にならない。"}, {"text": "彼女は合格通知を、一人で話し合って受け取った。", "explanation": "ここは〈ひとりで受け取る〉の意味。話し合うは複数の人の意見交換なので、一人だけでは成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37389, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週の会議で予算について話し合いた。", "corrected_sentence": "来週の会議で予算について話し合った。", "error_description": "タ形の誤り。正しくは「話し合った」で、「話し合いた」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "話し合い", "is_correct": true, "explanation": "連用形。「話し合い、全員で決めた」と中止の形で後ろに続く。"}, {"text": "話し合う", "is_correct": false, "explanation": "辞書形。「話し合う、全員で決めた」とは続かない。"}, {"text": "話し合おう", "is_correct": false, "explanation": "意志形。「話し合おう、全員で決めた」とは続かず、文として成立しない。"}, {"text": "話し合わない", "is_correct": false, "explanation": "否定形。話し合わなかったという意味になり、文中の内容と合わない。"}], "correct_form": "話し合い", "base_form": "話し合う", "form_label": "連用形（中止）", "sentence_index": 1, "explanations": {"話し合い": "連用形。「話し合い、全員で決めた」と中止の形で後ろに続く。", "話し合う": "辞書形。「話し合う、全員で決めた」とは続かない。", "話し合おう": "意志形。「話し合おう、全員で決めた」とは続かず、文として成立しない。", "話し合わない": "否定形。話し合わなかったという意味になり、文中の内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37389, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉妹で話し合わったことで、お互いの気持ちが分かった。", "corrected_sentence": "姉妹で話し合ったことで、お互いの気持ちが分かった。", "error_description": "タ形の誤り。正しくは「話し合った」で、「話し合わった」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "話し合えば", "is_correct": true, "explanation": "仮定形。「話し合えば、いい方法が見つかる」と条件を表して後ろに続く。"}, {"text": "話し合った", "is_correct": false, "explanation": "過去形。「話し合った、いい方法が見つかるはずだ」とは続かず、条件の意味も出ない。"}, {"text": "話し合え", "is_correct": false, "explanation": "命令形。文の途中に命令は入れられず、「話し合え、いい方法が見つかるはずだ」は成立しない。"}, {"text": "話し合います", "is_correct": false, "explanation": "マス形。丁寧体は文の途中に入れられず、「話し合います、いい方法が…」は文として成立しない。"}], "correct_form": "話し合えば", "base_form": "話し合う", "form_label": "仮定形", "sentence_index": 7, "explanations": {"話し合えば": "仮定形。「話し合えば、いい方法が見つかる」と条件を表して後ろに続く。", "話し合った": "過去形。「話し合った、いい方法が見つかるはずだ」とは続かず、条件の意味も出ない。", "話し合え": "命令形。文の途中に命令は入れられず、「話し合え、いい方法が見つかるはずだ」は成立しない。", "話し合います": "マス形。丁寧体は文の途中に入れられず、「話し合います、いい方法が…」は文として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37390, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "所有を示す「互いの顔」の「の」。文中の「の」に一致する。"}, {"text": "を", "is_correct": false, "explanation": "対象を示す。「互いを顔」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を示す。「互いと顔を見て」は成り立たず、所有の関係も表せない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。「互いで顔」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "所有を示す「互いの顔」の「の」。文中の「の」に一致する。", "を": "対象を示す。「互いを顔」は成り立たない。", "と": "並列・相手を示す。「互いと顔を見て」は成り立たず、所有の関係も表せない。", "で": "手段や場所を示す。「互いで顔」は意味が通らない。"}, "error_tags": {"を": "対象", "で": "手段・場所", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37390, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37390, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ふたりのあいだで、かんけいがあること。", "primary_collocate": null, "pronunciation": "たがい", "ipa": "taɡai", "syllable_count": 3, "sentences": [{"text": "私と姉は、互いの部屋に自由に出入りしている。", "target_word": "互い", "complexity_tier": "T3", "furigana": "私(わたし)と姉(あね)は、互(たが)いの部屋(へや)に自由(じゆう)に出入(でい)りしている。", "sentence_source": "generated"}, {"text": "二人は互いの顔を見て、思わず笑ってしまった。", "target_word": "互い", "complexity_tier": "T3", "furigana": "二人(ふたり)は互(たが)いの顔(かお)を見(み)て、思(おも)わず笑(わら)ってしまった。", "sentence_source": "generated"}, {"text": "兄と弟は互いの気持ちを考えて、ゆっくり話し合った。", "target_word": "互い", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]は互[たが]いの気持[きも]ちを考[かんが]えて、ゆっくり話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "彼とは、お互いの仕事が忙しくて、なかなか会えない。", "target_word": "互い", "complexity_tier": "T3", "furigana": "彼(かれ)とは、お互(たが)いの仕事(しごと)が忙(いそが)しくて、なかなか会(あ)えない。", "sentence_source": "generated"}, {"text": "夫婦は互いを支えながら、小さな店を続けてきた。", "target_word": "互い", "complexity_tier": "T3", "furigana": "夫婦(ふうふ)は互(たが)いを支(ささ)えながら、小(ちい)さな店(みせ)を続(つづ)けてきた。", "sentence_source": "generated"}, {"text": "二人は互いの手をしっかり握って、約束を交わした。", "target_word": "互い", "complexity_tier": "T3", "furigana": "二人(ふたり)は互(たが)いの手(て)をしっかり握(にぎ)って、約束(やくそく)を交(か)わした。", "sentence_source": "generated"}, {"text": "試合の後、二人の選手は互いの健闘をたたえた。", "target_word": "互い", "complexity_tier": "T3", "furigana": "試合(しあい)の後(あと)、二人(ふたり)の選手(せんしゅ)は互(たが)いの健闘(けんとう)をたたえた。", "sentence_source": "generated"}, {"text": "私たちは互いの誕生日にプレゼントを贈ることにしている。", "target_word": "互い", "complexity_tier": "T3", "furigana": "私(わたし)たちは互(たが)いの誕生日(たんじょうび)にプレゼントを贈(おく)ることにしている。", "sentence_source": "generated"}, {"text": "隣の家の人と、互いにあいさつをするようになった。", "target_word": "互い", "complexity_tier": "T3", "furigana": "隣(となり)の家(いえ)の人(ひと)と、互(たが)いにあいさつをするようになった。", "sentence_source": "generated"}, {"text": "けんかをした二人は、互いにあやまって仲直りした。", "target_word": "互い", "complexity_tier": "T3", "furigana": "けんかをした二人(ふたり)は、互(たが)いにあやまって仲直(なかなお)りした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "互い", "label": "基本形"}, {"form": "お互い", "label": "丁寧形"}, {"form": "互いに", "label": "副詞的用法"}], "register": "neutral", "sense_fingerprint": "二人の間で、一方が相手に、相手が一方に向かう関係", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51f98b6-eb48-454d-9dc5-99a082a5e10b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37390, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "互い", "is_correct": true, "explanation": "名詞。「互いの部屋」と所有の関係を示し、文が成立する。"}, {"text": "互いに", "is_correct": false, "explanation": "副詞用法。「互いに部屋」は名詞に直接続かない。"}, {"text": "互いを", "is_correct": false, "explanation": "対格の形。「互いを部屋」は成り立たない。"}, {"text": "互いと", "is_correct": false, "explanation": "並列の形。「互いと部屋」では所有の関係が成立しない。"}], "explanations": {"互い": "名詞。「互いの部屋」と所有の関係を示し、文が成立する。", "互いに": "副詞用法。「互いに部屋」は名詞に直接続かない。", "互いを": "対格の形。「互いを部屋」は成り立たない。", "互いと": "並列の形。「互いと部屋」では所有の関係が成立しない。"}, "sentence_index": 0, "correct_answer": "互い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は一人で、互いの机を片付けた。", "explanation": "ここは〈それぞれ〉の意味。互いは二者の相互の関係を表すので、一人で机を片付ける行為には合わない。"}, {"text": "先生が生徒に、互いに宿題を出した。", "explanation": "ここは〈一方的に〉の意味。互いに（相互に）は双方向の関係を表すので、一方向の指示には合わない。"}, {"text": "私は、互いの夢を一人で叶えた。", "explanation": "ここは〈ひとりで成し遂げる〉の意味。互いは相手との相互の関係を表すので、一人だけで叶える行為とは食い違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37390, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互い", "is_correct": true, "explanation": "名詞。「互いの健闘」と所有の関係を示し、文が成立する。"}, {"text": "互いが", "is_correct": false, "explanation": "主格の形。「互いが健闘」は主語にならず成り立たない。"}, {"text": "互いは", "is_correct": false, "explanation": "主題の形。「互いは健闘」では所有の関係が成立しない。"}, {"text": "互いと", "is_correct": false, "explanation": "並列の形。「互いと健闘」では所有の関係が成立しない。"}], "explanations": {"互い": "名詞。「互いの健闘」と所有の関係を示し、文が成立する。", "互いが": "主格の形。「互いが健闘」は主語にならず成り立たない。", "互いは": "主題の形。「互いは健闘」では所有の関係が成立しない。", "互いと": "並列の形。「互いと健闘」では所有の関係が成立しない。"}, "sentence_index": 6, "correct_answer": "互い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は、互いの足音を数えながら、一人で走った。", "explanation": "ここは〈それぞれ〉の意味。互いは二者の相互の関係を表すので、一人で走る行為とは食い違う。"}, {"text": "私は一人で、互いの窓を開けた。", "explanation": "ここは〈それぞれ〉の意味。互いは二者の関係を表すので、一人で窓を開ける行為には合わない。"}, {"text": "この薬は、互いの病気を治すのに効く。", "explanation": "ここは〈両方〉の意味。病気は相互に働きかける相手にならないので、互いの関係として使うのは不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37390, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二人は互いを健康を気にかけている。", "corrected_sentence": "二人は互いの健康を気にかけている。", "error_description": "助詞の誤り。「互いの健康」の「の」を「を」にしてしまっている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37390, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人は互いが成功を喜び合った。", "corrected_sentence": "二人は互いの成功を喜び合った。", "error_description": "助詞の誤り。「互いの成功」の「の」を「が」にしてしまっている。主語の「が」は「互い」には付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37391, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37391, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "副詞用法の「互いに」。「互いに肩を寄せて」と動作を修飾する。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す。「互いと肩を寄せて」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「互いへ肩を寄せて」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「互いから肩を寄せて」は不自然。"}], "correct_answer": "に", "explanations": {"に": "副詞用法の「互いに」。「互いに肩を寄せて」と動作を修飾する。", "と": "並列や相手を示す。「互いと肩を寄せて」は不自然。", "へ": "方向を示す。「互いへ肩を寄せて」は不自然。", "から": "起点を示す。「互いから肩を寄せて」は不自然。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37391, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の人や物の間で、それぞれが相手に対して何かをする関係にあること。", "primary_collocate": null, "pronunciation": "たがい", "ipa": "taɡai", "syllable_count": 3, "sentences": [{"text": "クラスの生徒たちは、互いに教え合って宿題を終えた。", "target_word": "互い", "complexity_tier": "T3", "furigana": "クラスの生徒(せいと)たちは、互(たが)いに教(おし)え合(あ)って宿題(しゅくだい)を終(お)えた。", "sentence_source": "generated"}, {"text": "山に登る仲間たちは、互いに声をかけて励まし合った。", "target_word": "互い", "complexity_tier": "T3", "furigana": "山(やま)に登(のぼ)る仲間(なかま)たちは、互(たが)いに声(こえ)をかけて励(はげ)まし合(あ)った。", "sentence_source": "generated"}, {"text": "近くの三つの町は互いに協力して、祭りを開いている。", "target_word": "互い", "complexity_tier": "T3", "furigana": "近(ちか)くの三(みっ)つの町(まち)は互(たが)いに協力(きょうりょく)して、祭(まつ)りを開(ひら)いている。", "sentence_source": "generated"}, {"text": "磁石の同じ極どうしは、互いに反発し合う。", "target_word": "互い", "complexity_tier": "T3", "furigana": "磁石(じしゃく)の同(おな)じ極(きょく)どうしは、互(たが)いに反発(はんぱつ)し合(あ)う。", "sentence_source": "generated"}, {"text": "引っ越してきた住民は、お互いに顔を知らないままだった。", "target_word": "互い", "complexity_tier": "T3", "furigana": "引(ひ)っ越(こ)してきた住民(じゅうみん)は、お互(たが)いに顔(かお)を知(し)らないままだった。", "sentence_source": "generated"}, {"text": "チームの全員が互いの役割を理解して動いている。", "target_word": "互い", "complexity_tier": "T3", "furigana": "チームの全員(ぜんいん)が互(たが)いの役割(やくわり)を理解(りかい)して動(うご)いている。", "sentence_source": "generated"}, {"text": "森の動物たちは互いに支え合って生きている。", "target_word": "互い", "complexity_tier": "T3", "furigana": "森(もり)の動物(どうぶつ)たちは互(たが)いに支(ささ)え合(あ)って生(い)きている。", "sentence_source": "generated"}, {"text": "観客は互いに肩を寄せて、花火を見上げた。", "target_word": "互い", "complexity_tier": "T3", "furigana": "観客(かんきゃく)は互(たが)いに肩(かた)を寄(よ)せて、花火(はなび)を見上(みあ)げた。", "sentence_source": "generated"}, {"text": "家族みんなで互いの意見を聞いてから、旅行先を決めた。", "target_word": "互い", "complexity_tier": "T3", "furigana": "家族(かぞく)みんなで互(たが)いの意見(いけん)を聞(き)いてから、旅行先(りょこうさき)を決(き)めた。", "sentence_source": "generated"}, {"text": "隣り合う歯車は、互いにかみ合って回っている。", "target_word": "互い", "complexity_tier": "T3", "furigana": "隣(とな)り合(あ)う歯車(はぐるま)は、互(たが)いにかみ合(あ)って回(まわ)っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "互い", "label": "基本形"}, {"form": "お互い", "label": "丁寧形"}, {"form": "互いに", "label": "副詞的用法"}], "register": "neutral", "sense_fingerprint": "三者以上の人や物が、それぞれ他に対して働きかけ合う関係", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51f98b6-eb48-454d-9dc5-99a082a5e10b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37391, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "互い", "is_correct": true, "explanation": "名詞。「互いに教え合う」の副詞用法で、後ろに「に」が続く形として成立する。"}, {"text": "互いの", "is_correct": false, "explanation": "所有の形。「互いの教え合って」は文が成立しない。"}, {"text": "互いを", "is_correct": false, "explanation": "対格。「互いを教え合って」は文として不自然。"}, {"text": "互いで", "is_correct": false, "explanation": "手段を示す形。「互いで教え合って」は意味が通らず、文として成立しない。"}], "explanations": {"互い": "名詞。「互いに教え合う」の副詞用法で、後ろに「に」が続く形として成立する。", "互いの": "所有の形。「互いの教え合って」は文が成立しない。", "互いを": "対格。「互いを教え合って」は文として不自然。", "互いで": "手段を示す形。「互いで教え合って」は意味が通らず、文として成立しない。"}, "sentence_index": 0, "correct_answer": "互い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一人の選手が、互いに得点した。", "explanation": "ここは〈単独で得る〉の意味。互いは複数の相手どうしの関係を表すので、一人の選手の得点には合わない。"}, {"text": "先生が生徒に、互いに宿題を出した。", "explanation": "ここは〈一方的に〉の意味。互いに（相互に）は双方向の関係を表すので、一方向の指示には合わない。"}, {"text": "店員は、互いにお客の注文を一人で受けた。", "explanation": "ここは〈ひとりで受ける〉の意味。互いは複数の相手どうしの相互の行為を表すので、一人の店員の受付には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37391, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互い", "is_correct": true, "explanation": "名詞。「互いに支え合う」の副詞用法で、後ろに「に」が続く形として成立する。"}, {"text": "互いへ", "is_correct": false, "explanation": "方向を示す形。「互いへ支え合う」は不自然。"}, {"text": "互いで", "is_correct": false, "explanation": "手段を示す形。「互いで支え合う」は文が成立しない。"}, {"text": "互いから", "is_correct": false, "explanation": "起点を示す形。「互いから支え合う」は文意が通らない。"}], "explanations": {"互い": "名詞。「互いに支え合う」の副詞用法で、後ろに「に」が続く形として成立する。", "互いへ": "方向を示す形。「互いへ支え合う」は不自然。", "互いで": "手段を示す形。「互いで支え合う」は文が成立しない。", "互いから": "起点を示す形。「互いから支え合う」は文意が通らない。"}, "sentence_index": 6, "correct_answer": "互い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一つの歯車だけが互いにかみ合った。", "explanation": "ここは〈単独で〉の意味。互いは二つ以上の相手どうしの関係を表すので、一つだけでは成り立たない。"}, {"text": "その犬は、互いの主人に毎朝吠えた。", "explanation": "ここは〈一方向に〉の意味。犬が主人に吠えるのは一方向の行為で、相互の関係を表す互いとは食い違う。"}, {"text": "兄は弟に、互いのおもちゃを一人で壊した。", "explanation": "ここは〈単独で〉の意味。互いのおもちゃを一人で壊すのは相互の行為にならず、互いの用法と食い違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37391, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三人の友だちは互いで励まし合った。", "corrected_sentence": "三人の友だちは互いに励まし合った。", "error_description": "助詞の誤り。「互いに」の「に」を「で」にしてしまっている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37391, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三人の兄は互いで助け合って暮らしている。", "corrected_sentence": "三人の兄は互いに助け合って暮らしている。", "error_description": "助詞の誤り。副詞「互いに」の「に」を「で」にしている。「互いで」は手段の意味になり、相互に助け合う関係を表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37392, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「大切にしたい」の対象を示す目的語の「を」。友情が大切にされるものなので正しい。"}, {"text": "に", "is_correct": false, "explanation": "「友情に大切にする」は対象の示し方として不自然で、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「友情で大切にする」は手段の意味になり、大切にする対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「友情と大切にする」は相手や共同を表すが、大切にする対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「大切にしたい」の対象を示す目的語の「を」。友情が大切にされるものなので正しい。", "に": "「友情に大切にする」は対象の示し方として不自然で、文が成り立たない。", "で": "「友情で大切にする」は手段の意味になり、大切にする対象を示せない。", "と": "「友情と大切にする」は相手や共同を表すが、大切にする対象を示せない。"}, "error_tags": {"に": "方向・位置", "で": "手段・場所", "と": "相手・共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37392, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "より", "options": [{"text": "より", "is_correct": true, "explanation": "「友情より恋を選ぶ」の比較の「より」。友情と恋を比べ、恋を選んだことを表す。"}, {"text": "に", "is_correct": false, "explanation": "「友情に恋を選ぶ」は対象の示し方として不自然で、比べる意味にならない。"}, {"text": "を", "is_correct": false, "explanation": "「友情を恋を選ぶ」は目的語が二つ重なり、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「友情へ恋を選ぶ」は意味が通らない。"}], "correct_answer": "より", "explanations": {"より": "「友情より恋を選ぶ」の比較の「より」。友情と恋を比べ、恋を選んだことを表す。", "に": "「友情に恋を選ぶ」は対象の示し方として不自然で、比べる意味にならない。", "を": "「友情を恋を選ぶ」は目的語が二つ重なり、文が成り立たない。", "へ": "方向を表すが、「友情へ恋を選ぶ」は意味が通らない。"}, "error_tags": {"に": "方向・相手", "を": "目的語（重複）", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37392, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "友だち同士が仲良くしている気持ちや関係。", "primary_collocate": null, "pronunciation": "ゆうじょう", "ipa": "jɯːdʑoː", "syllable_count": 4, "sentences": [{"text": "二人の間には、子どものころからの友情がある。", "target_word": "友情", "complexity_tier": "T3", "furigana": "二人(ふたり)の間(あいだ)には、子(こ)どものころからの友情(ゆうじょう)がある。", "sentence_source": "generated"}, {"text": "友情を大切にしたいから、うそはつかないことにした。", "target_word": "友情", "complexity_tier": "T3", "furigana": "友情(ゆうじょう)を大切(たいせつ)にしたいから、うそはつかないことにした。", "sentence_source": "generated"}, {"text": "彼女との友情は、大人になっても変わらなかった。", "target_word": "友情", "complexity_tier": "T3", "furigana": "彼女(かのじょ)との友情(ゆうじょう)は、大人(おとな)になっても変(か)わらなかった。", "sentence_source": "generated"}, {"text": "長い旅を通して、私たちの友情は深まった。", "target_word": "友情", "complexity_tier": "T3", "furigana": "長(なが)い旅(たび)を通(とお)して、私(わたし)たちの友情(ゆうじょう)は深(ふか)まった。", "sentence_source": "generated"}, {"text": "友情の証に、おそろいのペンを買った。", "target_word": "友情", "complexity_tier": "T3", "furigana": "友情(ゆうじょう)の証(あかし)に、おそろいのペンを買(か)った。", "sentence_source": "generated"}, {"text": "転校しても、友情は続くと信じている。", "target_word": "友情", "complexity_tier": "T3", "furigana": "転校(てんこう)しても、友情(ゆうじょう)は続(つづ)くと信(しん)じている。", "sentence_source": "generated"}, {"text": "試合に負けた後も、チームの友情は変わらなかった。", "target_word": "友情", "complexity_tier": "T3", "furigana": "試合(しあい)に負(ま)けた後(あと)も、チームの友情(ゆうじょう)は変(か)わらなかった。", "sentence_source": "generated"}, {"text": "彼は友情より恋を選んだので、友だちは怒った。", "target_word": "友情", "complexity_tier": "T3", "furigana": "彼(かれ)は友情(ゆうじょう)より恋(こい)を選(えら)んだので、友(とも)だちは怒(おこ)った。", "sentence_source": "generated"}, {"text": "手紙のやりとりで、遠い国の人と友情が生まれた。", "target_word": "友情", "complexity_tier": "T3", "furigana": "手紙(てがみ)のやりとりで、遠(とお)い国(くに)の人(ひと)と友情(ゆうじょう)が生(う)まれた。", "sentence_source": "generated"}, {"text": "この映画は、少年たちの友情を描いている。", "target_word": "友情", "complexity_tier": "T3", "furigana": "この映画(えいが)は、少年(しょうねん)たちの友情(ゆうじょう)を描(えが)いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "友情", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "友だち同士が仲良くしている気持ちや関係", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51f98b6-eb48-454d-9dc5-99a082a5e10b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37392, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "友情", "is_correct": true, "explanation": "二人の間にある気持ちを表す語で、「子どものころからの友情がある」と自然に続く。"}, {"text": "完成度", "is_correct": false, "explanation": "作品などの出来ばえを表す語で、人間関係について「子どものころからの完成度がある」とは言わない。"}, {"text": "効率", "is_correct": false, "explanation": "仕事や作業の能率を表す語で、人間関係について「子どものころからの効率がある」とは言わない。"}, {"text": "価格", "is_correct": false, "explanation": "商品の値段を表す語で、「子どものころからの価格がある」は人間関係の文として成り立たない。"}], "explanations": {"友情": "二人の間にある気持ちを表す語で、「子どものころからの友情がある」と自然に続く。", "完成度": "作品などの出来ばえを表す語で、人間関係について「子どものころからの完成度がある」とは言わない。", "効率": "仕事や作業の能率を表す語で、人間関係について「子どものころからの効率がある」とは言わない。", "価格": "商品の値段を表す語で、「子どものころからの価格がある」は人間関係の文として成り立たない。"}, "sentence_index": 0, "correct_answer": "友情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は隣の席の子の友情に落ちてしまった。", "explanation": "ここは〈恋〉の意味。「落ちる」は恋に使う言い方で、友情は人が落ちるものではないので合わない。"}, {"text": "この店は新しい友情を売り出した。", "explanation": "ここは〈商品〉の意味。友情は売り出すものではなく、気持ちや関係なので商品としては合わない。"}, {"text": "彼は小学校からの友情だ。今でも毎週会っている。", "explanation": "ここは〈友人〉の意味。友情は気持ちや関係を指し、人そのものは指さないので「友情だ」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37392, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "友情", "is_correct": true, "explanation": "チームの仲間同士の気持ちや関係を表す語で、「チームの友情は変わらなかった」と続く。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたい気持ちを表す語で、チームの関係について「変わらなかった」とは合わない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表す語で、チームの関係について使えない。"}, {"text": "身長", "is_correct": false, "explanation": "背の高さを表す語で、チームの関係について使えない。"}], "explanations": {"友情": "チームの仲間同士の気持ちや関係を表す語で、「チームの友情は変わらなかった」と続く。", "食欲": "食べたい気持ちを表す語で、チームの関係について「変わらなかった」とは合わない。", "体重": "体の重さを表す語で、チームの関係について使えない。", "身長": "背の高さを表す語で、チームの関係について使えない。"}, "sentence_index": 6, "correct_answer": "友情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は学校の図書館に友情を寄付した。", "explanation": "ここは〈寄付〉の意味。寄付は金銭や物を贈る行為で、気持ちである友情は寄付できないので合わない。"}, {"text": "この店は長年の友情を得て、客が絶えない。", "explanation": "ここは〈信頼〉の意味。友情は個人同士の気持ちで、店と客の評判には使わない。"}, {"text": "チームの友情が集まって、大会の準備をした。", "explanation": "ここは〈仲間〉の意味。友情は集まる人々を指さないので、人の集団には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37392, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二人は長年の友情を結ばれている。", "corrected_sentence": "二人は長年の友情で結ばれている。", "error_description": "「結ばれる」は受身で、手段を表す「で」を取る。「友情を結ばれる」は誤りで、正しくは「友情で結ばれる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37392, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "互いの友情を深まるため、毎週会って話している。", "corrected_sentence": "互いの友情を深めるため、毎週会って話している。", "error_description": "「友情を深める」は他動詞で目的語に「を」を取る。「深まる」は自動詞で「友情を」とは続かないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37393, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「友情とは〜だ」の「と」。「〜とは」で友情の定義を示す。"}, {"text": "を", "is_correct": false, "explanation": "「友情をは」は目的格の「を」に「は」が続き不自然で、定義の文にならない。"}, {"text": "が", "is_correct": false, "explanation": "「友情がは」は主格の「が」に「は」が続き、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「友情のは」は所属の「の」に「は」が続き、文が成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「友情とは〜だ」の「と」。「〜とは」で友情の定義を示す。", "を": "「友情をは」は目的格の「を」に「は」が続き不自然で、定義の文にならない。", "が": "「友情がは」は主格の「が」に「は」が続き、文が成り立たない。", "の": "「友情のは」は所属の「の」に「は」が続き、文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37393, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「友情があるから」の主語を示す「が」。存在を表す「〜がある」と合う。"}, {"text": "を", "is_correct": false, "explanation": "「友情を＋ある」は「ある」と合わず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「友情へある」は存在の示し方として不自然。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示すが、「友情とあるから」は存在を表せない。"}], "correct_answer": "が", "explanations": {"が": "「友情があるから」の主語を示す「が」。存在を表す「〜がある」と合う。", "を": "「友情を＋ある」は「ある」と合わず、文が成り立たない。", "へ": "方向を示すが、「友情へある」は存在の示し方として不自然。", "と": "相手や並列を示すが、「友情とあるから」は存在を表せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37393, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お互いを大切に思い合い、助け合う気持ちや関係。", "primary_collocate": null, "pronunciation": "ゆうじょう", "ipa": "jɯːdʑoː", "syllable_count": 4, "sentences": [{"text": "病気の私を助けてくれた友人の友情に、心から感謝している。", "target_word": "友情", "complexity_tier": "T3", "furigana": "病気(びょうき)の私(わたし)を助(たす)けてくれた友人(ゆうじん)の友情(ゆうじょう)に、心(こころ)から感謝(かんしゃ)している。", "sentence_source": "generated"}, {"text": "友情とは、困ったときに助け合うことだと思う。", "target_word": "友情", "complexity_tier": "T3", "furigana": "友情(ゆうじょう)とは、困(こま)ったときに助(たす)け合(あ)うことだと思(おも)う。", "sentence_source": "generated"}, {"text": "厚い友情に支えられて、彼は再び立ち上がった。", "target_word": "友情", "complexity_tier": "T3", "furigana": "厚(あつ)い友情(ゆうじょう)に支(ささ)えられて、彼(かれ)は再(ふたた)び立(た)ち上(あ)がった。", "sentence_source": "generated"}, {"text": "二人の友情は、お互いの失敗を責めないところから生まれた。", "target_word": "友情", "complexity_tier": "T3", "furigana": "二人(ふたり)の友情(ゆうじょう)は、お互(たが)いの失敗(しっぱい)を責(せ)めないところから生(う)まれた。", "sentence_source": "generated"}, {"text": "彼女は友情から、徹夜で私の宿題を手伝ってくれた。", "target_word": "友情", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は友情(ゆうじょう)から、徹夜(てつや)で私(わたし)の宿題(しゅくだい)を手伝(てつだ)ってくれた。", "sentence_source": "generated"}, {"text": "戦争で離れても、二人は友情を忘れなかった。", "target_word": "友情", "complexity_tier": "T3", "furigana": "戦争(せんそう)で離(はな)れても、二人(ふたり)は友情(ゆうじょう)を忘(わす)れなかった。", "sentence_source": "generated"}, {"text": "本当の友情は、相手の成功を一緒に喜べることだ。", "target_word": "友情", "complexity_tier": "T3", "furigana": "本当(ほんとう)の友情(ゆうじょう)は、相手(あいて)の成功(せいこう)を一緒(いっしょ)に喜(よろこ)べることだ。", "sentence_source": "generated"}, {"text": "友情があるから、厳しいことも正直に言える。", "target_word": "友情", "complexity_tier": "T3", "furigana": "友情(ゆうじょう)があるから、厳(きび)しいことも正直(しょうじき)に言(い)える。", "sentence_source": "generated"}, {"text": "彼は友情を裏切らないために、秘密を守り続けた。", "target_word": "友情", "complexity_tier": "T3", "furigana": "彼(かれ)は友情(ゆうじょう)を裏切(うらぎ)らないために、秘密(ひみつ)を守(まも)り続(つづ)けた。", "sentence_source": "generated"}, {"text": "仲間の友情に励まされて、新人は仕事を続けた。", "target_word": "友情", "complexity_tier": "T3", "furigana": "仲間(なかま)の友情(ゆうじょう)に励(はげ)まされて、新人(しんじん)は仕事(しごと)を続(つづ)けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "友情", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "相手を大切に思い、困ったときに助け合う友人同士の絆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51f98b6-eb48-454d-9dc5-99a082a5e10b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37393, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "友情", "is_correct": true, "explanation": "助けてくれた友人との気持ちや関係を表す語で、「友人の友情に感謝している」と続く。"}, {"text": "完成度", "is_correct": false, "explanation": "作品などの出来ばえを表す語で、「友人の完成度に感謝」とは言わない。"}, {"text": "効率", "is_correct": false, "explanation": "作業の能率を表す語で、人への感謝の対象にはならない。"}, {"text": "価格", "is_correct": false, "explanation": "商品の値段を表す語で、人の行為への感謝の対象にはならない。"}], "explanations": {"友情": "助けてくれた友人との気持ちや関係を表す語で、「友人の友情に感謝している」と続く。", "完成度": "作品などの出来ばえを表す語で、「友人の完成度に感謝」とは言わない。", "効率": "作業の能率を表す語で、人への感謝の対象にはならない。", "価格": "商品の値段を表す語で、人の行為への感謝の対象にはならない。"}, "sentence_index": 0, "correct_answer": "友情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府は被災地に友情を送ることを決めた。", "explanation": "ここは〈援助〉の意味。友情は気持ちや関係を指し、物資や資金を送るものではない。"}, {"text": "プロジェクトには多くの企業の友情が必要だ。", "explanation": "ここは〈協力〉の意味。友情は個人同士の気持ちを指し、企業の共同作業には使わない。"}, {"text": "彼は約束した友情を最後まで果たした。", "explanation": "ここは〈義務〉の意味。友情は果たすものではなく、気持ちや関係なので「果たす」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37393, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "友情", "is_correct": true, "explanation": "お互いを大切に思う気持ちを表す語で、「本当の友情は、相手の成功を喜べることだ」と続く。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を表す語で、「本当の体温は〜ことだ」とは言わない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表す語で、この定義の文には合わない。"}, {"text": "身長", "is_correct": false, "explanation": "背の高さを表す語で、この定義の文には合わない。"}], "explanations": {"友情": "お互いを大切に思う気持ちを表す語で、「本当の友情は、相手の成功を喜べることだ」と続く。", "体温": "体の温度を表す語で、「本当の体温は〜ことだ」とは言わない。", "体重": "体の重さを表す語で、この定義の文には合わない。", "身長": "背の高さを表す語で、この定義の文には合わない。"}, "sentence_index": 6, "correct_answer": "友情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は危険な道に友情を払った。", "explanation": "ここは〈注意〉の意味。「払う」は注意や敬意に使う言い方で、友情は払うものではないので合わない。"}, {"text": "二つの会社は来年まで続く友情に署名した。", "explanation": "ここは〈契約〉の意味。署名するのは契約書で、友情は書類ではないので合わない。"}, {"text": "彼は来年までに資格を取るという友情を立てた。", "explanation": "ここは〈目標〉の意味。友情は目指すものではなく、立てる対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37393, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の友情に助けさせて、私は立ち直れた。", "corrected_sentence": "彼女の友情に助けられて、私は立ち直れた。", "error_description": "「友情に助けられる」は受身。「助けさせる」は使役で、友情が人に助けさせる意味になり誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37393, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仲間の友情が、私はいつも支えられている。", "corrected_sentence": "仲間の友情に、私はいつも支えられている。", "error_description": "「友情に支えられる」の「に」は支えの主体を示す。「友情が支えられる」は格助詞の誤りで、不自然な文になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37394, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「繋ぐには」の「に」。「〜するには」の形で、目的や条件を示す。"}, {"text": "を", "is_correct": false, "explanation": "「繋ぐを」は動詞の後に目的語を置けず、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「繋ぐが必要だ」は主語になるが、「には」と続く文型と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「繋ぐへは」は不自然で文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「繋ぐには」の「に」。「〜するには」の形で、目的や条件を示す。", "を": "「繋ぐを」は動詞の後に目的語を置けず、文が成り立たない。", "が": "「繋ぐが必要だ」は主語になるが、「には」と続く文型と合わない。", "へ": "方向を示すが、「繋ぐへは」は不自然で文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37394, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「二つの川を繋ぐ」の「を」。繋ぐ対象の川を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「二つの川へ繋ぐ」は対象の示し方として不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「二つの川から繋ぐ」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「二つの川で繋ぐ」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「二つの川を繋ぐ」の「を」。繋ぐ対象の川を示す。", "へ": "方向を示すが、「二つの川へ繋ぐ」は対象の示し方として不自然。", "から": "起点を示すが、「二つの川から繋ぐ」は意味が通らない。", "で": "手段や場所を示すが、「二つの川で繋ぐ」は不自然。"}, "error_tags": {"へ": "方向", "から": "起点", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37394, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二つのものをいっしょにする。", "primary_collocate": null, "pronunciation": "つなぐ", "ipa": "t͡sɯnaɡɯ", "syllable_count": 3, "sentences": [{"text": "犬を木に繋いで、店の中に入った。", "target_word": "繋い", "complexity_tier": "T3", "furigana": "犬(いぬ)を木(き)に繋(つな)いで、店(みせ)の中(なか)に入(はい)った。", "sentence_source": "generated"}, {"text": "二本のロープを繋ぐには、強い結び方が必要だ。", "target_word": "繋ぐ", "complexity_tier": "T3", "furigana": "二本(にほん)のロープを繋(つな)ぐには、強(つよ)い結(むす)び方(かた)が必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "子どもと手を繋いで、横断歩道をわたった。", "target_word": "繋い", "complexity_tier": "T3", "furigana": "子(こ)どもと手(て)を繋(つな)いで、横断歩道(おうだんほどう)をわたった。", "sentence_source": "generated"}, {"text": "電源コードを繋ぐと、テレビがつくようになった。", "target_word": "繋ぐ", "complexity_tier": "T3", "furigana": "電源(でんげん)コードを繋(つな)ぐと、テレビがつくようになった。", "sentence_source": "generated"}, {"text": "この橋は島と町を繋ぐ、たった一つの道だ。", "target_word": "繋ぐ", "complexity_tier": "T3", "furigana": "この橋(はし)は島(しま)と町(まち)を繋(つな)ぐ、たった一(ひと)つの道(みち)だ。", "sentence_source": "generated"}, {"text": "切れたひもを繋いだが、すぐにまた切れてしまった。", "target_word": "繋い", "complexity_tier": "T3", "furigana": "切(き)れたひもを繋(つな)いだが、すぐにまた切(き)れてしまった。", "sentence_source": "generated"}, {"text": "パソコンをプリンターに繋いで、写真を印刷した。", "target_word": "繋い", "complexity_tier": "T3", "furigana": "パソコンをプリンターに繋(つな)いで、写真(しゃしん)を印刷(いんさつ)した。", "sentence_source": "generated"}, {"text": "二つの川を繋ぐ水路が、昔つくられた。", "target_word": "繋ぐ", "complexity_tier": "T3", "furigana": "二(ふた)つの川(かわ)を繋(つな)ぐ水路(すいろ)が、昔(むかし)つくられた。", "sentence_source": "generated"}, {"text": "駅で電車の車両を繋ぐ作業を見学した。", "target_word": "繋ぐ", "complexity_tier": "T3", "furigana": "駅(えき)で電車(でんしゃ)の車両(しゃりょう)を繋(つな)ぐ作業(さぎょう)を見学(けんがく)した。", "sentence_source": "generated"}, {"text": "船を港の柱に繋いでおかないと、流されてしまう。", "target_word": "繋い", "complexity_tier": "T3", "furigana": "船(ふね)を港(みなと)の柱(はしら)に繋(つな)いでおかないと、流(なが)されてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "繋ぐ", "label": "辞書形"}, {"form": "繋いで", "label": "て形"}, {"form": "繋いだ", "label": "た形"}, {"form": "繋がない", "label": "ない形"}, {"form": "繋ぎます", "label": "ます形"}, {"form": "繋げば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "ひも・線・道などで、二つの物を実際につなげて離れないようにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51f98b6-eb48-454d-9dc5-99a082a5e10b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37394, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繋い", "is_correct": true, "explanation": "「繋いで」の連用形。木に縛る動作を「〜て」で続け、「店の中に入った」と続く。"}, {"text": "繋ぐ", "is_correct": false, "explanation": "辞書形なので「で」に続かず、文の途中に入らない。"}, {"text": "繋ぎます", "is_correct": false, "explanation": "丁寧形なので「で」に続かず、文の途中に入らない。"}, {"text": "繋げば", "is_correct": false, "explanation": "仮定形は「ば」に続くため、「で」の前には入らない。"}], "explanations": {"繋い": "「繋いで」の連用形。木に縛る動作を「〜て」で続け、「店の中に入った」と続く。", "繋ぐ": "辞書形なので「で」に続かず、文の途中に入らない。", "繋ぎます": "丁寧形なので「で」に続かず、文の途中に入らない。", "繋げば": "仮定形は「ば」に続くため、「で」の前には入らない。"}, "sentence_index": 0, "correct_answer": "繋い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人は固く約束を繋いだ。", "explanation": "ここは〈結ぶ〉の意味。約束のような取り決めは「結ぶ」と言い、「繋ぐ」は物や場所をつなげる意味で使うので合わない。"}, {"text": "荷物を駅まで繋いだ。", "explanation": "ここは〈運ぶ〉の意味。繋ぐは離れた物同士を連結する意味で、物を移動させる意味はないので合わない。"}, {"text": "ケーキを六つに繋いだ。", "explanation": "ここは〈分ける〉の意味。繋ぐは離れた物を一つにする意味で、一つのものを分割する意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37394, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繋い", "is_correct": true, "explanation": "「繋いで」の連用形。パソコンとプリンターを繋いだ動作を「〜て」で続けている。"}, {"text": "繋げ", "is_correct": false, "explanation": "「繋げ」は命令形で、「で」に続かず文が成り立たない。"}, {"text": "繋ぎ", "is_correct": false, "explanation": "連用形だが、「ぎで」とは続かず不自然。"}, {"text": "繋がる", "is_correct": false, "explanation": "自動詞で、人が繋ぐ動作を表せず「繋がるで」とは続かない。"}], "explanations": {"繋い": "「繋いで」の連用形。パソコンとプリンターを繋いだ動作を「〜て」で続けている。", "繋げ": "「繋げ」は命令形で、「で」に続かず文が成り立たない。", "繋ぎ": "連用形だが、「ぎで」とは続かず不自然。", "繋がる": "自動詞で、人が繋ぐ動作を表せず「繋がるで」とは続かない。"}, "sentence_index": 6, "correct_answer": "繋い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この本を英語に繋いだ。", "explanation": "ここは〈翻訳〉の意味。繋ぐは物や場所を結びつける意味で、言語を変える意味はないので合わない。"}, {"text": "夕日の景色を繋いだ。", "explanation": "ここは〈眺める〉の意味。繋ぐは結びつける動作で、見て楽しむ意味はないので合わない。"}, {"text": "オーブンでピザを繋いだ。", "explanation": "ここは〈焼く〉の意味。繋ぐは物を結び合わせる意味で、食べ物を加熱する意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37394, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二本のロープを柱に繋がると、船が流されない。", "corrected_sentence": "二本のロープを柱に繋ぐと、船が流されない。", "error_description": "「繋ぐ」は他動詞で「ロープを繋ぐ」と目的語を取る。「繋がる」は自動詞で「を」と続かないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "繋ぐ", "is_correct": true, "explanation": "「繋ぐには」の辞書形。目的を示す「〜するには」の前で基本形を使う。"}, {"text": "繋いで", "is_correct": false, "explanation": "て形で、「には」に続く形ではない。"}, {"text": "繋いだ", "is_correct": false, "explanation": "過去の形で、目的を表す「〜するには」の前には使わない。"}, {"text": "繋がない", "is_correct": false, "explanation": "否定形で、「繋ぐには」の目的の意味とは合わない。"}], "correct_form": "繋ぐ", "base_form": "繋ぐ", "form_label": "辞書形", "sentence_index": 1, "explanations": {"繋ぐ": "「繋ぐには」の辞書形。目的を示す「〜するには」の前で基本形を使う。", "繋いで": "て形で、「には」に続く形ではない。", "繋いだ": "過去の形で、目的を表す「〜するには」の前には使わない。", "繋がない": "否定形で、「繋ぐには」の目的の意味とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37394, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ケーブルが機械に繋いだところ、音が出た。", "corrected_sentence": "ケーブルを機械に繋いだところ、音が出た。", "error_description": "「繋ぐ」の対象は「を」で示す。「が」にすると対象が主語になり、「ケーブルが機械に繋いだ」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "繋ぐ", "is_correct": true, "explanation": "「水路」を修飾する辞書形。二つの川を繋ぐ水路という意味で正しい。"}, {"text": "繋げば", "is_correct": false, "explanation": "仮定形で、名詞「水路」を修飾できない。"}, {"text": "繋ぎます", "is_correct": false, "explanation": "丁寧形で、名詞「水路」を修飾できない。"}, {"text": "繋げ", "is_correct": false, "explanation": "命令形や可能の形で、名詞「水路」を修飾できない。"}], "correct_form": "繋ぐ", "base_form": "繋ぐ", "form_label": "辞書形", "sentence_index": 7, "explanations": {"繋ぐ": "「水路」を修飾する辞書形。二つの川を繋ぐ水路という意味で正しい。", "繋げば": "仮定形で、名詞「水路」を修飾できない。", "繋ぎます": "丁寧形で、名詞「水路」を修飾できない。", "繋げ": "命令形や可能の形で、名詞「水路」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37395, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「両国の代表を繋いで」の目的語の「を」。繋ぐ対象の代表を示す。"}, {"text": "が", "is_correct": false, "explanation": "「代表が繋いで」は代表を主語にしてしまい、文の主語と合わない。"}, {"text": "や", "is_correct": false, "explanation": "「代表や繋いでくれた」は並列の「や」が動詞に続かず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を示すが、「代表の繋いで」は動詞の対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「両国の代表を繋いで」の目的語の「を」。繋ぐ対象の代表を示す。", "が": "「代表が繋いで」は代表を主語にしてしまい、文の主語と合わない。", "や": "「代表や繋いでくれた」は並列の「や」が動詞に続かず、文が成り立たない。", "の": "所属や修飾を示すが、「代表の繋いで」は動詞の対象にならない。"}, "error_tags": {"が": "主語", "や": "並列", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37395, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「町の人々を繋ぐ」の目的語の「を」。繋ぐ対象の人々を示す。"}, {"text": "や", "is_correct": false, "explanation": "「人々や繋ぐ」は並列の「や」が動詞に続かず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「人々から繋ぐ」は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "「人々の繋ぐ」は所属の「の」の後に動詞が続き、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「町の人々を繋ぐ」の目的語の「を」。繋ぐ対象の人々を示す。", "や": "「人々や繋ぐ」は並列の「や」が動詞に続かず、文が成り立たない。", "から": "起点を示すが、「人々から繋ぐ」は意味が通らない。", "の": "「人々の繋ぐ」は所属の「の」の後に動詞が続き、文が成り立たない。"}, "error_tags": {"や": "並列", "から": "起点", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37395, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や物事の間に関係や連絡を作る。", "primary_collocate": null, "pronunciation": "つなぐ", "ipa": "t͡sɯnaɡɯ", "syllable_count": 3, "sentences": [{"text": "彼は二つの会社を繋ぐ役を引き受けた。", "target_word": "繋ぐ", "complexity_tier": "T3", "furigana": "彼(かれ)は二(ふた)つの会社(かいしゃ)を繋(つな)ぐ役(やく)を引(ひ)き受(う)けた。", "sentence_source": "generated"}, {"text": "通訳の人が、両国の代表を繋いでくれた。", "target_word": "繋い", "complexity_tier": "T3", "furigana": "通訳(つうやく)の人(ひと)が、両国(りょうこく)の代表(だいひょう)を繋(つな)いでくれた。", "sentence_source": "generated"}, {"text": "先生が私と留学生を繋いでくれて、友だちになれた。", "target_word": "繋い", "complexity_tier": "T3", "furigana": "先生(せんせい)が私(わたし)と留学生(りゅうがくせい)を繋(つな)いでくれて、友(とも)だちになれた。", "sentence_source": "generated"}, {"text": "電話を担当の人に繋いでもらった。", "target_word": "繋い", "complexity_tier": "T3", "furigana": "電話(でんわ)を担当(たんとう)の人(ひと)に繋(つな)いでもらった。", "sentence_source": "generated"}, {"text": "この活動は、若い人とお年寄りを繋ぐ場になっている。", "target_word": "繋ぐ", "complexity_tier": "T3", "furigana": "この活動(かつどう)は、若(わか)い人(ひと)とお年寄(としよ)りを繋(つな)ぐ場(ば)になっている。", "sentence_source": "generated"}, {"text": "友人が仕事を紹介して、私と社長を繋いでくれた。", "target_word": "繋い", "complexity_tier": "T3", "furigana": "友人(ゆうじん)が仕事(しごと)を紹介(しょうかい)して、私(わたし)と社長(しゃちょう)を繋(つな)いでくれた。", "sentence_source": "generated"}, {"text": "音楽は、言葉の違う人たちの心を繋ぐと思う。", "target_word": "繋ぐ", "complexity_tier": "T3", "furigana": "音楽(おんがく)は、言葉(ことば)の違(ちが)う人(ひと)たちの心(こころ)を繋(つな)ぐと思(おも)う。", "sentence_source": "generated"}, {"text": "彼女は町の人々を繋ぐために、毎月集まりを開いている。", "target_word": "繋ぐ", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は町(まち)の人々(ひとびと)を繋(つな)ぐために、毎月(まいつき)集(あつ)まりを開(ひら)いている。", "sentence_source": "generated"}, {"text": "SNSは遠くの家族と私を繋ぐ大切な手段だ。", "target_word": "繋ぐ", "complexity_tier": "T3", "furigana": "SNSは遠(とお)くの家族(かぞく)と私(わたし)を繋(つな)ぐ大切(たいせつ)な手段(しゅだん)だ。", "sentence_source": "generated"}, {"text": "地元の店と客を繋ぐサイトを、友人が作った。", "target_word": "繋ぐ", "complexity_tier": "T3", "furigana": "地元(じもと)の店(みせ)と客(きゃく)を繋(つな)ぐサイトを、友人(ゆうじん)が作(つく)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "繋ぐ", "label": "辞書形"}, {"form": "繋いで", "label": "て形"}, {"form": "繋いだ", "label": "た形"}, {"form": "繋がない", "label": "ない形"}, {"form": "繋ぎます", "label": "ます形"}, {"form": "繋げば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "仲立ちをして、人と人や物事の間に関係・連絡をつくる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51f98b6-eb48-454d-9dc5-99a082a5e10b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37395, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繋ぐ", "is_correct": true, "explanation": "辞書形で「会社を繋ぐ役」と名詞「役」を修飾する。"}, {"text": "繋がる", "is_correct": false, "explanation": "自動詞で「会社を」と続けられず、役を修飾できない。"}, {"text": "繋げ", "is_correct": false, "explanation": "命令形で、名詞「役」を修飾できない。"}, {"text": "繋ぎます", "is_correct": false, "explanation": "丁寧形で、名詞「役」を修飾できない。"}], "explanations": {"繋ぐ": "辞書形で「会社を繋ぐ役」と名詞「役」を修飾する。", "繋がる": "自動詞で「会社を」と続けられず、役を修飾できない。", "繋げ": "命令形で、名詞「役」を修飾できない。", "繋ぎます": "丁寧形で、名詞「役」を修飾できない。"}, "sentence_index": 0, "correct_answer": "繋ぐ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "犯人を縄で繋いだ。", "explanation": "ここは〈縛る〉の意味。繋ぐは人や物事の間に関係をつくる意味で、人を縄で縛る意味はないので合わない。"}, {"text": "二人のトラブルを繋いだ。", "explanation": "ここは〈解決〉の意味。繋ぐは関係をつくる意味で、問題を終わらせる意味はないので合わない。"}, {"text": "ホースを蛇口に繋いで、庭に水をまいた。", "explanation": "ここは〈接続〉の意味。繋ぐは人や物事の間に関係や連絡をつくる意味で、物を物理的に接続する意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37395, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繋ぐ", "is_correct": true, "explanation": "辞書形で「心を繋ぐ」と続き、「と思う」の前に文を完成させる。"}, {"text": "繋ぎ", "is_correct": false, "explanation": "連用形で、「心を繋ぎと思う」とは続かない。"}, {"text": "繋がれ", "is_correct": false, "explanation": "「繋がれ」は自動詞「繋がる」の命令形で、「と思う」の前に文を完成させられない。"}, {"text": "繋ぐな", "is_correct": false, "explanation": "禁止の形で、「と思う」へは続かない。"}], "explanations": {"繋ぐ": "辞書形で「心を繋ぐ」と続き、「と思う」の前に文を完成させる。", "繋ぎ": "連用形で、「心を繋ぎと思う」とは続かない。", "繋がれ": "「繋がれ」は自動詞「繋がる」の命令形で、「と思う」の前に文を完成させられない。", "繋ぐな": "禁止の形で、「と思う」へは続かない。"}, "sentence_index": 6, "correct_answer": "繋ぐ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボートを桟橋に繋いだ。", "explanation": "ここは〈係留〉の意味。繋ぐは人や物事の間に関係をつくる意味で、船を桟橋に固定する意味ではないので合わない。"}, {"text": "難しい問題を繋いで、答えを出した。", "explanation": "ここは〈解く〉の意味。繋ぐは問題を解く意味はないので合わない。"}, {"text": "注文の品を家まで繋いだ。", "explanation": "ここは〈届ける〉の意味。繋ぐは物を運んで渡す意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37395, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "通訳者は二国の政府を繋ぐて、交渉を進めた。", "corrected_sentence": "通訳者は二国の政府を繋いで、交渉を進めた。", "error_description": "「繋ぐ」は五段活用で、て形は「繋いで」。「繋ぐて」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "繋い", "is_correct": true, "explanation": "「繋いでくれた」の「繋い」で、て形の語幹にあたる。"}, {"text": "繋ぐ", "is_correct": false, "explanation": "辞書形で、「くれた」の前には来ない。"}, {"text": "繋がない", "is_correct": false, "explanation": "否定形で、文の意味（つないでくれた）と合わない。"}, {"text": "繋げば", "is_correct": false, "explanation": "仮定形で、「くれた」と続かない。"}], "correct_form": "繋い", "base_form": "繋ぐ", "form_label": "連用形（て形の語幹）", "sentence_index": 1, "explanations": {"繋い": "「繋いでくれた」の「繋い」で、て形の語幹にあたる。", "繋ぐ": "辞書形で、「くれた」の前には来ない。", "繋がない": "否定形で、文の意味（つないでくれた）と合わない。", "繋げば": "仮定形で、「くれた」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37395, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "共通の友人が、二人の仲を繋がってくれた。", "corrected_sentence": "共通の友人が、二人の仲を繋いでくれた。", "error_description": "「仲を繋ぐ」は他動詞で「を」を取る。「繋がる」は自動詞なので「仲を繋がる」とは言えず、誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "繋ぐ", "is_correct": true, "explanation": "「町の人々を繋ぐために」の辞書形で、目的を示す「ために」の前に来る。"}, {"text": "繋いだ", "is_correct": false, "explanation": "過去の形で、目的を表す「ために」の前には使わない。"}, {"text": "繋ぎます", "is_correct": false, "explanation": "丁寧形で、「ために」と続く形ではない。"}, {"text": "繋げ", "is_correct": false, "explanation": "命令形で、目的を示す「ために」の前には来ない。"}], "correct_form": "繋ぐ", "base_form": "繋ぐ", "form_label": "辞書形", "sentence_index": 7, "explanations": {"繋ぐ": "「町の人々を繋ぐために」の辞書形で、目的を示す「ために」の前に来る。", "繋いだ": "過去の形で、目的を表す「ために」の前には使わない。", "繋ぎます": "丁寧形で、「ために」と続く形ではない。", "繋げ": "命令形で、目的を示す「ために」の前には来ない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07148bd-7c46-4fe6-b8c2-dd4de843023f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37396, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「コミュニティーの（所属する）みんな」の所属を示す「の」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「みんなで」と続けると不自然になる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や方向を示し、掃除をする主体を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、「みんなで掃除する」にはつながらない。"}], "correct_answer": "の", "explanations": {"の": "正解。「コミュニティーの（所属する）みんな」の所属を示す「の」。", "を": "「を」は目的語を示すが、「みんなで」と続けると不自然になる。", "に": "「に」は相手や方向を示し、掃除をする主体を表せない。", "から": "「から」は起点を示し、「みんなで掃除する」にはつながらない。"}, "error_tags": {"を": "目的語", "に": "相手・方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37396, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「入る」の着点を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「入る」は目的語を取らないので、「を」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は行為の場所を示し、「入る」の着点にはならない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「コミュニティーが入った」では主体が合わない。"}], "correct_answer": "に", "explanations": {"に": "正解。「入る」の着点を示す「に」。", "を": "「入る」は目的語を取らないので、「を」は合わない。", "で": "「で」は行為の場所を示し、「入る」の着点にはならない。", "が": "「が」は主語を示すが、「コミュニティーが入った」では主体が合わない。"}, "error_tags": {"を": "目的語", "で": "行為の場", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37396, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が集まって、いっしょに何かをするグループのことです。", "primary_collocate": null, "pronunciation": "こみゅにてぃー", "ipa": "komjɯnitiː", "syllable_count": 4, "sentences": [{"text": "私は、料理が好きな人のコミュニティーに入った。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "私[わたし]は、料理[りょうり]が好[す]きな人[ひと]のコミュニティーに入[はい]った。", "sentence_source": "generated"}, {"text": "週末は、コミュニティーのみんなで公園を掃除する。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]は、コミュニティーのみんなで公園[こうえん]を掃除[そうじ]する。", "sentence_source": "generated"}, {"text": "このコミュニティーでは、毎月集まって映画を見る。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "このコミュニティーでは、毎月[まいつき]集[あつ]まって映画[えいが]を見[み]る。", "sentence_source": "generated"}, {"text": "新しい町で、友だちができるコミュニティーを探した。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "新[あたら]しい町[まち]で、友[とも]だちができるコミュニティーを探[さが]した。", "sentence_source": "generated"}, {"text": "コミュニティーの仲間と、いっしょに旅行に行った。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "コミュニティーの仲間[なかま]と、いっしょに旅行[りょこう]に行[い]った。", "sentence_source": "generated"}, {"text": "本を読む会は、小さなコミュニティーとして始まった。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "本[ほん]を読[よ]む会[かい]は、小[ちい]さなコミュニティーとして始[はじ]まった。", "sentence_source": "generated"}, {"text": "一人でやるより、コミュニティーで習うほうが続く。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "一人[ひとり]でやるより、コミュニティーで習[なら]うほうが続[つづ]く。", "sentence_source": "generated"}, {"text": "コミュニティーに入ったばかりの人に、やり方を教えた。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "コミュニティーに入[はい]ったばかりの人[ひと]に、やり方[かた]を教[おし]えた。", "sentence_source": "generated"}, {"text": "兄は、自転車のコミュニティーで友だちを作った。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "兄[あに]は、自転車[じてんしゃ]のコミュニティーで友[とも]だちを作[つく]った。", "sentence_source": "generated"}, {"text": "人が減って、コミュニティーの活動をやめることになった。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "人[ひと]が減[へ]って、コミュニティーの活動[かつどう]をやめることになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コミュニティー", "label": "基本形"}], "register": "口語", "sense_fingerprint": "いっしょに活動する人の集まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ecbfbe-96fb-4154-838a-29e711cd0c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37396, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コミュニティー", "is_correct": true, "explanation": "正解。「料理が好きな人の〜」に入る、人が集まる団体を指す。"}, {"text": "ボタン", "is_correct": false, "explanation": "服などに付ける部品で、人の集まりには入れない。"}, {"text": "カレンダー", "is_correct": false, "explanation": "日付を示す表で、人が集まって入る対象ではない。"}, {"text": "トマト", "is_correct": false, "explanation": "野菜の名前で、「〜に入った」の形にはならない。"}], "explanations": {"コミュニティー": "正解。「料理が好きな人の〜」に入る、人が集まる団体を指す。", "ボタン": "服などに付ける部品で、人の集まりには入れない。", "カレンダー": "日付を示す表で、人が集まって入る対象ではない。", "トマト": "野菜の名前で、「〜に入った」の形にはならない。"}, "sentence_index": 0, "correct_answer": "コミュニティー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日から熱が出て、コミュニティーをひいた。", "explanation": "〈風邪〉との言い換え。「ひく」は風邪などの病気に使い、人の集まりには使わない。"}, {"text": "この電話はコミュニティーが混んでいて、つながらなかった。", "explanation": "〈ネットワーク〉との言い換え。「混む」のは回線で、人の集まりには使わない。"}, {"text": "毎朝走るのは、私のコミュニティーだ。", "explanation": "〈習慣〉との言い換え。毎朝の行動は習慣であり、人の集まりではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37396, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コミュニティー", "is_correct": true, "explanation": "正解。「〜で習う」の場所になる、人が集まる団体を指す。"}, {"text": "大根", "is_correct": false, "explanation": "野菜で、習う場所にはならない。"}, {"text": "氷", "is_correct": false, "explanation": "固体の水で、習う場所にはならない。"}, {"text": "靴下", "is_correct": false, "explanation": "衣類で、習う場所にはならない。"}], "explanations": {"コミュニティー": "正解。「〜で習う」の場所になる、人が集まる団体を指す。", "大根": "野菜で、習う場所にはならない。", "氷": "固体の水で、習う場所にはならない。", "靴下": "衣類で、習う場所にはならない。"}, "sentence_index": 6, "correct_answer": "コミュニティー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行先で、コミュニティーのシャッターを切った。", "explanation": "〈カメラ〉との言い換え。シャッターを切るのは写真機で、人の集まりには使わない。"}, {"text": "夕食の前に、コミュニティーを洗った。", "explanation": "〈野菜〉との言い換え。洗うのは野菜などの物で、人の集まりは洗えない。"}, {"text": "毎月、コミュニティーを貯めている。", "explanation": "〈お金〉との言い換え。貯めるのはお金で、人の集まりは貯められない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37396, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先週、料理のコミュニティーを参加した友だちと旅行した。", "corrected_sentence": "先週、料理のコミュニティーに参加した友だちと旅行した。", "error_description": "「参加する」は「に」を取るので、「を」は誤り。正しくは「コミュニティーに参加した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37396, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同じ趣味のコミュニティーを入って、絵を習った。", "corrected_sentence": "同じ趣味のコミュニティーに入って、絵を習った。", "error_description": "「入る」は「に」を取る。「を」は誤り。正しくは「コミュニティーに入って」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37397, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「知り合う」の場所を示す「で」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語で、「コミュニティーを知り合った」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示し、コミュニティーが知り合ったことにはならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属を示し、知り合う場所にはならない。"}], "correct_answer": "で", "explanations": {"で": "正解。「知り合う」の場所を示す「で」。", "を": "「を」は目的語で、「コミュニティーを知り合った」は不自然。", "が": "「が」は主語を示し、コミュニティーが知り合ったことにはならない。", "の": "「の」は所属を示し、知り合う場所にはならない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "所属"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37397, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「中心」を修飾する「の」。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動詞の目的語で、名詞どうしを結べない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示し、名詞を修飾できない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、「中心」を修飾しない。"}], "correct_answer": "の", "explanations": {"の": "正解。「中心」を修飾する「の」。", "を": "「を」は動詞の目的語で、名詞どうしを結べない。", "に": "「に」は場所や相手を示し、名詞を修飾できない。", "で": "「で」は手段や場所を示し、「中心」を修飾しない。"}, "error_tags": {"を": "目的語", "に": "場所・相手", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37397, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "共通の関心や目的を持つ人々の集まり。地域やインターネット上で形成される社会的なグループ。", "primary_collocate": null, "pronunciation": "こみゅにてぃー", "ipa": "komjɯnitiː", "syllable_count": 4, "sentences": [{"text": "古い町では、地域のコミュニティーが大切にされている。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "古[ふる]い町[まち]では、地域[ちいき]のコミュニティーが大切[たいせつ]にされている。", "sentence_source": "generated"}, {"text": "ネット上のコミュニティーで、同じ趣味の人と知り合った。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "ネット上[じょう]のコミュニティーで、同[おな]じ趣味[しゅみ]の人[ひと]と知[し]り合[あ]った。", "sentence_source": "generated"}, {"text": "災害のとき、コミュニティーの助け合いが役に立った。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "災害[さいがい]のとき、コミュニティーの助[たす]け合[あ]いが役[やく]に立[た]った。", "sentence_source": "generated"}, {"text": "この町のコミュニティーは、お年寄りも子どもも参加する。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "この町[まち]のコミュニティーは、お年寄[としよ]りも子[こ]どもも参加[さんか]する。", "sentence_source": "generated"}, {"text": "同じ病気を持つ人のコミュニティーに、勇気をもらった。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "同[おな]じ病気[びょうき]を持[も]つ人[ひと]のコミュニティーに、勇気[ゆうき]をもらった。", "sentence_source": "generated"}, {"text": "外国人が多く住む地域に、新しいコミュニティーができた。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]が多[おお]く住[す]む地域[ちいき]に、新[あたら]しいコミュニティーができた。", "sentence_source": "generated"}, {"text": "開発者のコミュニティーは、世界中に広がっている。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "開発者[かいはつしゃ]のコミュニティーは、世界中[せかいじゅう]に広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "学校は、地域のコミュニティーの中心でもある。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "学校[がっこう]は、地域[ちいき]のコミュニティーの中心[ちゅうしん]でもある。", "sentence_source": "generated"}, {"text": "彼は、ゲーム好きのコミュニティーの代表をしている。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "彼[かれ]は、ゲーム好[ず]きのコミュニティーの代表[だいひょう]をしている。", "sentence_source": "generated"}, {"text": "コミュニティーの決まりを守らない人は、書きこみができなくなる。", "target_word": "コミュニティー", "complexity_tier": "T3", "furigana": "コミュニティーの決[き]まりを守[まも]らない人[ひと]は、書[か]きこみができなくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コミュニティー", "label": "基本形"}], "register": "中立", "sense_fingerprint": "地域やネット上にできる社会的な人々の集まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ecbfbe-96fb-4154-838a-29e711cd0c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37397, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コミュニティー", "is_correct": true, "explanation": "正解。地域で形成され、大切にされる社会的な集まりを指す。"}, {"text": "生ごみ", "is_correct": false, "explanation": "捨てられるごみで、大切にされるものではない。"}, {"text": "割り箸", "is_correct": false, "explanation": "使い捨ての道具で、「地域の〜が大切にされる」とはならない。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "個人が使う道具で、地域単位で大切にされる対象ではない。"}], "explanations": {"コミュニティー": "正解。地域で形成され、大切にされる社会的な集まりを指す。", "生ごみ": "捨てられるごみで、大切にされるものではない。", "割り箸": "使い捨ての道具で、「地域の〜が大切にされる」とはならない。", "歯ブラシ": "個人が使う道具で、地域単位で大切にされる対象ではない。"}, "sentence_index": 0, "correct_answer": "コミュニティー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合の後、コミュニティーを蹴って遊んだ。", "explanation": "〈ボール〉との言い換え。蹴るのはボールなどの物で、人の集まりは蹴れない。"}, {"text": "この町の電線は、コミュニティーが途切れやすい。", "explanation": "〈ネットワーク〉との言い換え。途切れるのは回線で、人の集まりには使わない。"}, {"text": "古くなったので、コミュニティーを買い替えた。", "explanation": "〈車〉との言い換え。買い替えるのは車などの物で、人の集まりは買い替えられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37397, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コミュニティー", "is_correct": true, "explanation": "正解。共通の関心で集まり、世界中に広がる人の集まりを指す。"}, {"text": "天井", "is_correct": false, "explanation": "建物の一部で、世界中に広がるものではない。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "個人の道具で、広がる対象ではない。"}, {"text": "靴下", "is_correct": false, "explanation": "衣類で、広がる対象ではない。"}], "explanations": {"コミュニティー": "正解。共通の関心で集まり、世界中に広がる人の集まりを指す。", "天井": "建物の一部で、世界中に広がるものではない。", "歯ブラシ": "個人の道具で、広がる対象ではない。", "靴下": "衣類で、広がる対象ではない。"}, "sentence_index": 6, "correct_answer": "コミュニティー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "決まりを守らない人は、コミュニティーを払うことになる。", "explanation": "〈罰金〉との言い換え。払うのはお金で、人の集まりは払えない。"}, {"text": "明日は、コミュニティーになる。", "explanation": "〈天気〉との言い換え。「晴れになる」など天候の言葉で、人の集まりには使わない。"}, {"text": "友だちにコミュニティーを送った。", "explanation": "〈手紙〉との言い換え。送るのは郵便物で、人の集まりは送れない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37397, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町のコミュニティーに夏祭りを開いた。", "corrected_sentence": "町のコミュニティーで夏祭りを開いた。", "error_description": "行事を開く場所は「で」。「に」は誤り。正しくは「コミュニティーで夏祭りを開いた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37397, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "開発者のコミュニティーを参加して、新しいツールを試した。", "corrected_sentence": "開発者のコミュニティーに参加して、新しいツールを試した。", "error_description": "「参加する」は「に」を取る。「を」は誤り。正しくは「コミュニティーに参加して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a66f60a0-1a96-4cdb-bd82-a112ae13ca22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
