INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37398, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "遊ぶことや楽しむこと。", "primary_collocate": null, "pronunciation": "ごらく", "ipa": "ɡoɾaku", "syllable_count": 3, "sentences": [{"text": "仕事ばかりで、娯楽の時間がまったくない。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "仕事(しごと)ばかりで、娯楽(ごらく)の時間(じかん)がまったくない。", "sentence_source": "generated"}, {"text": "祖父の唯一の娯楽は、庭で花を育てることだ。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "祖父(そふ)の唯一(ゆいいつ)の娯楽(ごらく)は、庭(にわ)で花(はな)を育(そだ)てることだ。", "sentence_source": "generated"}, {"text": "昔の村には娯楽が少なく、祭りが一番の楽しみだった。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "昔(むかし)の村(むら)には娯楽(ごらく)が少(すく)なく、祭(まつ)りが一番(いちばん)の楽(たの)しみだった。", "sentence_source": "generated"}, {"text": "娯楽のために本を読むのと、勉強のために読むのとは違う。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "娯楽(ごらく)のために本(ほん)を読(よ)むのと、勉強(べんきょう)のために読(よ)むのとは違(ちが)う。", "sentence_source": "generated"}, {"text": "彼は娯楽にお金を使いすぎて、貯金ができない。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "彼(かれ)は娯楽(ごらく)にお金(かね)を使(つか)いすぎて、貯金(ちょきん)ができない。", "sentence_source": "generated"}, {"text": "休日は、娯楽に時間を使うより、家で静かに休みたい。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "休日(きゅうじつ)は、娯楽(ごらく)に時間(じかん)を使(つか)うより、家(いえ)で静(しず)かに休(やす)みたい。", "sentence_source": "generated"}, {"text": "雨の日でも、トランプなら家の中で娯楽になる。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "雨(あめ)の日(ひ)でも、トランプなら家(いえ)の中(なか)で娯楽(ごらく)になる。", "sentence_source": "generated"}, {"text": "昔は、テレビがない家では家族で話すことが娯楽だった。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "昔(むかし)は、テレビがない家(いえ)では家族(かぞく)で話(はな)すことが娯楽(ごらく)だった。", "sentence_source": "generated"}, {"text": "子どもには、勉強だけでなく娯楽も必要だと思う。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "子(こ)どもには、勉強(べんきょう)だけでなく娯楽(ごらく)も必要(ひつよう)だと思(おも)う。", "sentence_source": "generated"}, {"text": "山奥の小屋では、夜に皆で遊ぶことだけが娯楽だった。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "山奥(やまおく)の小屋(こや)では、夜(よる)に皆(みな)で遊(あそ)ぶことだけが娯楽(ごらく)だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "娯楽", "label": "基本形"}, {"form": "娯楽の", "label": "連体形（の）"}, {"form": "娯楽に", "label": "に格"}], "register": "標準", "sense_fingerprint": "遊びや楽しみそのもの。個人が楽しむ行為や気晴らし。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddfe4a92-bcbf-4b7c-b2a1-9385eb43d549') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37398, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "娯楽", "is_correct": true, "explanation": "正解。「娯楽の時間」は、遊びや楽しみに使える時間を指し、空欄に入る。"}, {"text": "名誉", "is_correct": false, "explanation": "名誉は世間からの評価を表す語で、「名誉の時間」とは言わないので空欄に合わない。"}, {"text": "寛容", "is_correct": false, "explanation": "寛容は人を受け入れる心の広さを指し、時間を修飾できないので空欄に合わない。"}, {"text": "規律", "is_correct": false, "explanation": "規律は守るべき決まりを指し、「規律の時間」は不自然で文に合わない。"}], "explanations": {"娯楽": "正解。「娯楽の時間」は、遊びや楽しみに使える時間を指し、空欄に入る。", "名誉": "名誉は世間からの評価を表す語で、「名誉の時間」とは言わないので空欄に合わない。", "寛容": "寛容は人を受け入れる心の広さを指し、時間を修飾できないので空欄に合わない。", "規律": "規律は守るべき決まりを指し、「規律の時間」は不自然で文に合わない。"}, "sentence_index": 0, "correct_answer": "娯楽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅先の散歩で、久しぶりに娯楽を感じた。", "explanation": "ここは〈楽しさ〉の意味。楽しさは感じるものだが、娯楽は楽しませる活動や催しを指すので、感じる対象としては合わない。"}, {"text": "疲れた日は、娯楽を取って早めに寝た。", "explanation": "ここは〈休息〉の意味。体を休めることは休息で、娯楽は楽しむ活動なので、休む行為の代わりにはならない。"}, {"text": "休日は、娯楽を家で静かに過ごした。", "explanation": "ここは〈余暇〉の意味。余暇は自由に使える時間を指し、過ごすのは時間であって、娯楽を過ごすとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37398, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "娯楽", "is_correct": true, "explanation": "正解。「家の中で娯楽になる」は、遊びや楽しみとして役立つという意味で文に合う。"}, {"text": "慈悲", "is_correct": false, "explanation": "慈悲は情けや憐れみを表し、「家の中で慈悲になる」とは言えないので空欄に合わない。"}, {"text": "格式", "is_correct": false, "explanation": "格式は家柄や決まりの重みを指し、「家の中で格式になる」は不自然で合わない。"}, {"text": "献身", "is_correct": false, "explanation": "献身は人のために尽くすことで、家の中の遊びを表す文の空欄には入らない。"}], "explanations": {"娯楽": "正解。「家の中で娯楽になる」は、遊びや楽しみとして役立つという意味で文に合う。", "慈悲": "慈悲は情けや憐れみを表し、「家の中で慈悲になる」とは言えないので空欄に合わない。", "格式": "格式は家柄や決まりの重みを指し、「家の中で格式になる」は不自然で合わない。", "献身": "献身は人のために尽くすことで、家の中の遊びを表す文の空欄には入らない。"}, "sentence_index": 6, "correct_answer": "娯楽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は、服の娯楽がとてもいい。", "explanation": "ここは〈趣味（好み）〉の意味。服の好みの良し悪しを言うのは趣味で、娯楽は楽しむ活動を指すので合わない。"}, {"text": "職人は長年、木を削る娯楽を磨いてきた。", "explanation": "ここは〈技術〉の意味。磨くのは腕前や技術で、娯楽は磨いて上達するものではないので合わない。"}, {"text": "来週の旅行を、娯楽に待っている。", "explanation": "ここは〈楽しみ〉の意味。「楽しみに待つ」という言い方で、娯楽を使うと待つ気持ちを表せず不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37398, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "休日は、家族と娯楽が楽しむことが多い。", "corrected_sentence": "休日は、家族と娯楽を楽しむことが多い。", "error_description": "「楽しむ」の目的語は「を」で示す。「が」にすると娯楽が楽しむ主体になり、文が誤る。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37398, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町では、若者が娯楽が求めて集まる。", "corrected_sentence": "この町では、若者が娯楽を求めて集まる。", "error_description": "「求める」は目的語に「を」を取る。「が」にすると娯楽が主語になり、「求める」と合わなくなる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37399, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「娯楽にかける」は、お金を費やす先を「に」で示す形で、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「娯楽をかける」は費やす先を示せず、「かける」の意味に合わないので、この文には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「娯楽でかける」は費やす意味にならず、文に合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「娯楽がかける」は人の出費という文脈に合わず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "正解。「娯楽にかける」は、お金を費やす先を「に」で示す形で、文に合う。", "を": "「娯楽をかける」は費やす先を示せず、「かける」の意味に合わないので、この文には合わない。", "で": "「で」は手段や場所を示すが、「娯楽でかける」は費やす意味にならず、文に合わない。", "が": "「が」は主語を示すが、「娯楽がかける」は人の出費という文脈に合わず、文が成り立たない。"}, "error_tags": {"を": "対象の格", "で": "手段の格", "が": "主語の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37399, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37399, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人々が楽しみや気晴らしのためにする活動や、そのための物事。", "primary_collocate": null, "pronunciation": "ごらく", "ipa": "ɡoɾaku", "syllable_count": 3, "sentences": [{"text": "この町には、映画館やゲームセンターなど、娯楽が多い。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "この町(まち)には、映画館(えいがかん)やゲームセンターなど、娯楽(ごらく)が多(おお)い。", "sentence_source": "generated"}, {"text": "娯楽にかける人々の出費は、不景気でも大きく減らなかった。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "娯楽(ごらく)にかける人々(ひとびと)の出費(しゅっぴ)は、不景気(ふけいき)でも大(おお)きく減(へ)らなかった。", "sentence_source": "generated"}, {"text": "昔の人にとって、芝居は最も人気のある娯楽だった。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "昔(むかし)の人(ひと)にとって、芝居(しばい)は最(もっと)も人気(にんき)のある娯楽(ごらく)だった。", "sentence_source": "generated"}, {"text": "長い船旅の間、乗客は船内の娯楽で退屈をしのいだ。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "長(なが)い船旅(ふなたび)の間(あいだ)、乗客(じょうきゃく)は船内(せんない)の娯楽(ごらく)で退屈(たいくつ)をしのいだ。", "sentence_source": "generated"}, {"text": "スマートフォンの普及で、娯楽の種類が大きく変わった。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "スマートフォンの普及(ふきゅう)で、娯楽(ごらく)の種類(しゅるい)が大(おお)きく変(か)わった。", "sentence_source": "generated"}, {"text": "テレビは娯楽ばかりで、ニュースを見る人が減っている。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "テレビは娯楽(ごらく)ばかりで、ニュースを見(み)る人(ひと)が減(へ)っている。", "sentence_source": "generated"}, {"text": "このホテルには、プールやカラオケなど娯楽が充実している。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "このホテルには、プールやカラオケなど娯楽(ごらく)が充実(じゅうじつ)している。", "sentence_source": "generated"}, {"text": "江戸時代の庶民は、寄席や相撲を娯楽にしていた。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "江戸時代(えどじだい)の庶民(しょみん)は、寄席(よせ)や相撲(すもう)を娯楽(ごらく)にしていた。", "sentence_source": "generated"}, {"text": "この雑誌は娯楽として、仕事の合間に気軽に読める。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "この雑誌(ざっし)は娯楽(ごらく)として、仕事(しごと)の合間(あいま)に気軽(きがる)に読(よ)める。", "sentence_source": "generated"}, {"text": "小さな島では、娯楽といえば釣りくらいしかない。", "target_word": "娯楽", "complexity_tier": "T3", "furigana": "小(ちい)さな島(しま)では、娯楽(ごらく)といえば釣(つ)りくらいしかない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "娯楽", "label": "基本形"}, {"form": "娯楽の", "label": "連体形（の）"}, {"form": "娯楽に", "label": "に格"}], "register": "標準", "sense_fingerprint": "映画・芝居・ゲームなど、人々の楽しみのための活動や催し・施設の総称。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddfe4a92-bcbf-4b7c-b2a1-9385eb43d549') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37399, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "娯楽", "is_correct": true, "explanation": "正解。「娯楽が多い」は、楽しみのための活動や施設が多いという意味で文に合う。"}, {"text": "礼儀", "is_correct": false, "explanation": "礼儀は作法や態度を指し、「礼儀が多い」とは言えないので空欄に合わない。"}, {"text": "義理", "is_correct": false, "explanation": "義理は人との情にからむ義務を指し、町の施設を説明する文では不自然で合わない。"}, {"text": "忍耐", "is_correct": false, "explanation": "忍耐は我慢する力を指し、町にある施設について「忍耐が多い」とは言えない。"}], "explanations": {"娯楽": "正解。「娯楽が多い」は、楽しみのための活動や施設が多いという意味で文に合う。", "礼儀": "礼儀は作法や態度を指し、「礼儀が多い」とは言えないので空欄に合わない。", "義理": "義理は人との情にからむ義務を指し、町の施設を説明する文では不自然で合わない。", "忍耐": "忍耐は我慢する力を指し、町にある施設について「忍耐が多い」とは言えない。"}, "sentence_index": 0, "correct_answer": "娯楽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "合格の知らせを聞いて、家族は大きな娯楽を感じた。", "explanation": "ここは〈喜び〉の意味。大きな喜びを感じるのは喜びで、娯楽は楽しませる活動や催しを指すので、感じる気持ちの代わりにはならない。"}, {"text": "舞台の演技に、深い娯楽を覚えた。", "explanation": "ここは〈感動〉の意味。感動は心を強く動かされる気持ちで、娯楽は覚える対象ではないので合わない。"}, {"text": "そば職人は長年、そば打ちの娯楽を磨いてきた。", "explanation": "ここは〈技術〉の意味。磨くのは腕前や技術で、娯楽は磨いて上達するものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37399, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "娯楽", "is_correct": true, "explanation": "正解。「娯楽が充実している」は、楽しみのための施設や催しが十分にあることを表す。"}, {"text": "信念", "is_correct": false, "explanation": "信念は固く信じる考えを指し、施設の充実を表す文の空欄には入らない。"}, {"text": "誠実", "is_correct": false, "explanation": "誠実は真心をもって接する態度を指し、「誠実が充実している」とは言えない。"}, {"text": "慈悲", "is_correct": false, "explanation": "慈悲は憐れみや情けを指し、施設やサービスの充実を表す文には合わない。"}], "explanations": {"娯楽": "正解。「娯楽が充実している」は、楽しみのための施設や催しが十分にあることを表す。", "信念": "信念は固く信じる考えを指し、施設の充実を表す文の空欄には入らない。", "誠実": "誠実は真心をもって接する態度を指し、「誠実が充実している」とは言えない。", "慈悲": "慈悲は憐れみや情けを指し、施設やサービスの充実を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "娯楽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は器の娯楽がいい。", "explanation": "ここは〈趣味（好み）〉の意味。器の好みの良し悪しを言うのは趣味で、娯楽は楽しむ活動を指すので合わない。"}, {"text": "休日は、疲れを癒すためにホテルで娯楽を取った。", "explanation": "ここは〈休養〉の意味。体や心を休ませるのは休養で、娯楽は楽しむ活動なので、休む行為の代わりにはならない。"}, {"text": "友人の励ましで、娯楽が湧いてきた。", "explanation": "ここは〈元気〉の意味。湧いてくるのは元気や気力で、娯楽は活動や催しを指すので、わいてくる気力の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37399, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は、友人と娯楽を出かけることが多い。", "corrected_sentence": "週末は、友人と娯楽に出かけることが多い。", "error_description": "「出かける」は行き先や目的を「に」で示す。「を」は目的語用の助詞なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37399, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若い人は、遠くの町まで娯楽に探しに行く。", "corrected_sentence": "若い人は、遠くの町まで娯楽を探しに行く。", "error_description": "「探す」は目的語に「を」を取る。「に」にすると娯楽が探す先になり、文の意味が誤る。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37400, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「示す」は他動詞で、示される対象の「境界」に「を」が付く。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表す助詞で、「示す」の目的語には使わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す助詞で、「境界から示す石」は意味も形も通らず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表す助詞で、ここでは「示す」の対象を導かない。"}], "correct_answer": "を", "explanations": {"を": "「示す」は他動詞で、示される対象の「境界」に「を」が付く。", "に": "位置や相手を表す助詞で、「示す」の目的語には使わない。", "から": "起点を表す助詞で、「境界から示す石」は意味も形も通らず、文が成り立たない。", "と": "共同や引用を表す助詞で、ここでは「示す」の対象を導かない。"}, "error_tags": {"に": "位置・相手", "から": "起点", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37400, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「着く」は到着先を「に」で表し、「町の境界に」が到着先になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す助詞で、到着先を示す位置には入らない。"}, {"text": "を", "is_correct": false, "explanation": "通過する経路や対象を表す助詞で、「着く」の到着先には使わない。"}, {"text": "で", "is_correct": false, "explanation": "場所での行為を表す助詞で、到着の着点を示す文には合わない。"}], "correct_answer": "に", "explanations": {"に": "「着く」は到着先を「に」で表し、「町の境界に」が到着先になる。", "が": "主語を表す助詞で、到着先を示す位置には入らない。", "を": "通過する経路や対象を表す助詞で、「着く」の到着先には使わない。", "で": "場所での行為を表す助詞で、到着の着点を示す文には合わない。"}, "error_tags": {"が": "主語", "を": "経路・対象", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37400, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "国や場所の間の区切り。", "primary_collocate": null, "pronunciation": "きょうかい", "ipa": "kʲoːkai", "syllable_count": 4, "sentences": [{"text": "この川が二つの町の境界になっている。", "target_word": "境界", "complexity_tier": "T3", "furigana": "この川[かわ]が二[ふた]つの町[まち]の境界[きょうかい]になっている。", "sentence_source": "generated"}, {"text": "山の上に、国の境界を示す石がある。", "target_word": "境界", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]に、国[くに]の境界[きょうかい]を示[しめ]す石[いし]がある。", "sentence_source": "generated"}, {"text": "私たちは電車で県の境界をこえた。", "target_word": "境界", "complexity_tier": "T3", "furigana": "私[わたし]たちは電車[でんしゃ]で県[けん]の境界[きょうかい]をこえた。", "sentence_source": "generated"}, {"text": "庭の木が、となりの家との境界に立っている。", "target_word": "境界", "complexity_tier": "T3", "furigana": "庭[にわ]の木[き]が、となりの家[いえ]との境界[きょうかい]に立[た]っている。", "sentence_source": "generated"}, {"text": "二つの国の境界には、高いフェンスがある。", "target_word": "境界", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]の境界[きょうかい]には、高[たか]いフェンスがある。", "sentence_source": "generated"}, {"text": "地図の赤い線は、市の境界を表している。", "target_word": "境界", "complexity_tier": "T3", "furigana": "地図[ちず]の赤[あか]い線[せん]は、市[し]の境界[きょうかい]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "霧が出て、国の境界がよく見えなかった。", "target_word": "境界", "complexity_tier": "T3", "furigana": "霧[きり]が出[で]て、国[くに]の境界[きょうかい]がよく見[み]えなかった。", "sentence_source": "generated"}, {"text": "この道をまっすぐ行くと、町の境界に着く。", "target_word": "境界", "complexity_tier": "T3", "furigana": "この道[みち]をまっすぐ行[い]くと、町[まち]の境界[きょうかい]に着[つ]く。", "sentence_source": "generated"}, {"text": "池の真ん中が、二つの公園の境界だ。", "target_word": "境界", "complexity_tier": "T3", "furigana": "池[いけ]の真[ま]ん中[なか]が、二[ふた]つの公園[こうえん]の境界[きょうかい]だ。", "sentence_source": "generated"}, {"text": "旅行者は、境界の検問所でパスポートを見せた。", "target_word": "境界", "complexity_tier": "T3", "furigana": "旅行者[りょこうしゃ]は、境界[きょうかい]の検問所[けんもんじょ]でパスポートを見[み]せた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "境界", "label": "基本形"}, {"form": "境界の", "label": "連体形（の）"}, {"form": "境界が", "label": "主格（が）"}, {"form": "境界を", "label": "目的格（を）"}], "register": "neutral", "sense_fingerprint": "国・町・土地など二つの場所を分けている区切りの場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8da5f40a-19ae-49fd-abf3-80abdb2562f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37400, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "境界", "is_correct": true, "explanation": "二つの町の間を分ける区切りを表し、川がその区切りになっているという文に合う。"}, {"text": "距離", "is_correct": false, "explanation": "二つの場所の隔たりの長さを表す語で、川が二つの町の区切りになるという意味には合わない。"}, {"text": "料金", "is_correct": false, "explanation": "支払う金額を表す語で、川の位置や区切りを表す文には入らない。"}, {"text": "季節", "is_correct": false, "explanation": "一年の時期を表す語で、町と町を分ける区切りの意味には合わない。"}], "explanations": {"境界": "二つの町の間を分ける区切りを表し、川がその区切りになっているという文に合う。", "距離": "二つの場所の隔たりの長さを表す語で、川が二つの町の区切りになるという意味には合わない。", "料金": "支払う金額を表す語で、川の位置や区切りを表す文には入らない。", "季節": "一年の時期を表す語で、町と町を分ける区切りの意味には合わない。"}, "sentence_index": 0, "correct_answer": "境界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この煮物は、塩の境界がちょうどいい。", "explanation": "ここは〈加減〉の意味。境界は場所の区切りで、味の程よさは表さないので合わない。"}, {"text": "この部屋は、ひとりで静かに過ごせる広い境界だ。", "explanation": "ここは〈空間〉の意味。境界は区切りの線や境目で、広がりのある場所は指さないので合わない。"}, {"text": "彼は立派な境界で、会場でひときわ目立っていた。", "explanation": "ここは〈風采〉の意味。境界は場所の区切りで、人の外見や身なりは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37400, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "境界", "is_correct": true, "explanation": "霧で見えにくくなっていた、国と国の区切りを指す。"}, {"text": "人口", "is_correct": false, "explanation": "人の数を表す語で、目で見えなかったという文の対象にはならない。"}, {"text": "運賃", "is_correct": false, "explanation": "乗り物の料金を表す語で、霧の中で見えなかったものとしては合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "人の年数を表す語で、国の見えにくさを述べる文には入らない。"}], "explanations": {"境界": "霧で見えにくくなっていた、国と国の区切りを指す。", "人口": "人の数を表す語で、目で見えなかったという文の対象にはならない。", "運賃": "乗り物の料金を表す語で、霧の中で見えなかったものとしては合わない。", "年齢": "人の年数を表す語で、国の見えにくさを述べる文には入らない。"}, "sentence_index": 6, "correct_answer": "境界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "受付で境界をもらった。", "explanation": "ここは〈名札〉の意味。境界は場所の区切りで、受け取る物ではないので合わない。"}, {"text": "体力の境界を超えて走った。", "explanation": "ここは〈限界〉の意味。境界は区切りの線や区域で、体力の上限は指さないので合わない。"}, {"text": "部屋の境界を開けて風を入れた。", "explanation": "ここは〈窓〉の意味。境界は場所の区切りで、開け閉めする物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37400, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山の上から、川と森の境界に見下ろした。", "corrected_sentence": "山の上から、川と森の境界を見下ろした。", "error_description": "「見下ろす」は他動詞で目的語に「を」を取る。「境界に」の「に」は誤りで、「境界を」の「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37400, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の中、バスは町の境界が越えた。", "corrected_sentence": "雨の中、バスは町の境界を越えた。", "error_description": "「越える」は他動詞で目的語に「を」を取る。「境界が」の「が」は誤りで、「境界を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37401, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「引き直された」の主語を表し、境界が引き直された対象になる。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を表す助詞で、受身の主語にはならないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表す助詞で、ここでは主語の役割を担えないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を表す助詞で、受身の主語の位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "「引き直された」の主語を表し、境界が引き直された対象になる。", "に": "位置や相手を表す助詞で、受身の主語にはならないので合わない。", "と": "共同や引用を表す助詞で、ここでは主語の役割を担えないので合わない。", "の": "連体修飾を表す助詞で、受身の主語の位置には入らない。"}, "error_tags": {"に": "位置・相手", "と": "共同・引用", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37401, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「描かれている」の主語を表し、境界がくわしく描かれた対象になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す助詞だが、受身の文の主語にはならないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を表す助詞で、受身の主語の位置には入らない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を表す助詞で、ここでは主語の役割を担えないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「描かれている」の主語を表し、境界がくわしく描かれた対象になる。", "を": "目的語を表す助詞だが、受身の文の主語にはならないので合わない。", "の": "連体修飾を表す助詞で、受身の主語の位置には入らない。", "と": "共同や引用を表す助詞で、ここでは主語の役割を担えないので合わない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "と": "共同・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37401, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "国家や地域などの間に引かれた、区分けのための線や境目。", "primary_collocate": null, "pronunciation": "きょうかい", "ipa": "kʲoːkai", "syllable_count": 4, "sentences": [{"text": "地図の上で、二つの国の境界は一本の線で引かれている。", "target_word": "境界", "complexity_tier": "T3", "furigana": "地図[ちず]の上[うえ]で、二[ふた]つの国[くに]の境界[きょうかい]は一本[いっぽん]の線[せん]で引[ひ]かれている。", "sentence_source": "generated"}, {"text": "戦争のあと、国の境界が引き直された。", "target_word": "境界", "complexity_tier": "T3", "furigana": "戦争[せんそう]のあと、国[くに]の境界[きょうかい]が引[ひ]き直[なお]された。", "sentence_source": "generated"}, {"text": "境界を決めるために、二つの村の代表者が話し合った。", "target_word": "境界", "complexity_tier": "T3", "furigana": "境界[きょうかい]を決[き]めるために、二[ふた]つの村[むら]の代表者[だいひょうしゃ]が話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "県と県の境界は、地図ではうすい線で示される。", "target_word": "境界", "complexity_tier": "T3", "furigana": "県[けん]と県[けん]の境界[きょうかい]は、地図[ちず]ではうすい線[せん]で示[しめ]される。", "sentence_source": "generated"}, {"text": "昔の境界の線が、今も道の形に残っている。", "target_word": "境界", "complexity_tier": "T3", "furigana": "昔[むかし]の境界[きょうかい]の線[せん]が、今[いま]も道[みち]の形[かたち]に残[のこ]っている。", "sentence_source": "generated"}, {"text": "土地の境界がはっきりしないので、役所で調べてもらった。", "target_word": "境界", "complexity_tier": "T3", "furigana": "土地[とち]の境界[きょうかい]がはっきりしないので、役所[やくしょ]で調[しら]べてもらった。", "sentence_source": "generated"}, {"text": "国の境界は、川や山にそって決められることが多い。", "target_word": "境界", "complexity_tier": "T3", "furigana": "国[くに]の境界[きょうかい]は、川[かわ]や山[やま]にそって決[き]められることが多[おお]い。", "sentence_source": "generated"}, {"text": "新しい地図には、市の境界がくわしく描かれている。", "target_word": "境界", "complexity_tier": "T3", "furigana": "新[あたら]しい地図[ちず]には、市[し]の境界[きょうかい]がくわしく描[えが]かれている。", "sentence_source": "generated"}, {"text": "森の中の境界には、古い石の杭が打ってある。", "target_word": "境界", "complexity_tier": "T3", "furigana": "森[もり]の中[なか]の境界[きょうかい]には、古[ふる]い石[いし]の杭[くい]が打[う]ってある。", "sentence_source": "generated"}, {"text": "境界の線をまたいで立つと、二つの地域に同時にいる気分になる。", "target_word": "境界", "complexity_tier": "T3", "furigana": "境界[きょうかい]の線[せん]をまたいで立[た]つと、二[ふた]つの地域[ちいき]に同時[どうじ]にいる気分[きぶん]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "境界", "label": "基本形"}, {"form": "境界の", "label": "連体形（の）"}, {"form": "境界は", "label": "主題（は）"}, {"form": "境界を", "label": "目的格（を）"}], "register": "written", "sense_fingerprint": "国家や地域などを区分けするために引かれた線や境目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8da5f40a-19ae-49fd-abf3-80abdb2562f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37401, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "境界", "is_correct": true, "explanation": "国と国を区分ける線を表し、地図上で線が引かれるという文に合う。"}, {"text": "人口", "is_correct": false, "explanation": "人の数を表す語で、線で引かれるものではないので合わない。"}, {"text": "運賃", "is_correct": false, "explanation": "乗り物の料金を表す語で、地図に線で引く対象ではないので合わない。"}, {"text": "季節", "is_correct": false, "explanation": "一年の時期を表す語で、地図上に線で引かれるものではないので合わない。"}], "explanations": {"境界": "国と国を区分ける線を表し、地図上で線が引かれるという文に合う。", "人口": "人の数を表す語で、線で引かれるものではないので合わない。", "運賃": "乗り物の料金を表す語で、地図に線で引く対象ではないので合わない。", "季節": "一年の時期を表す語で、地図上に線で引かれるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "境界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壁の境界が、今は三時を指している。", "explanation": "ここは〈時計〉の意味。境界は場所の区切りで、時刻を指すことはないので合わない。"}, {"text": "体力の境界を感じて、休むことにした。", "explanation": "ここは〈限界〉の意味。境界は区切りの線や区域で、体力の上限は言わないので合わない。"}, {"text": "明日の境界は晴れるらしい。", "explanation": "ここは〈天気〉の意味。境界は区切りの線で、空模様は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37401, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "境界", "is_correct": true, "explanation": "国と国を区分ける区切りを表し、川や山にそって決められるという文に合う。"}, {"text": "年齢", "is_correct": false, "explanation": "人の年数を表す語で、区切りを決めるという文の対象にはならない。"}, {"text": "人気", "is_correct": false, "explanation": "好かれる度合いを表す語で、川や山にそって決められる対象ではない。"}, {"text": "天気", "is_correct": false, "explanation": "その日の気象を表す語で、川や山にそって決める対象ではないので合わない。"}], "explanations": {"境界": "国と国を区分ける区切りを表し、川や山にそって決められるという文に合う。", "年齢": "人の年数を表す語で、区切りを決めるという文の対象にはならない。", "人気": "好かれる度合いを表す語で、川や山にそって決められる対象ではない。", "天気": "その日の気象を表す語で、川や山にそって決める対象ではないので合わない。"}, "sentence_index": 6, "correct_answer": "境界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店では、りんごの境界が百円だ。", "explanation": "ここは〈値段〉の意味。境界は区切りの線で、代金は表さないので合わない。"}, {"text": "部屋の境界を開けて風を入れた。", "explanation": "ここは〈窓〉の意味。境界は場所の区切りで、開け閉めする物ではないので合わない。"}, {"text": "この部屋は、ひとりで静かに過ごせる広い境界だ。", "explanation": "ここは〈空間〉の意味。境界は区切りの線や境目で、広がりのある場所は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37401, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの村は、境界を決まることにした。", "corrected_sentence": "二つの村は、境界を決めることにした。", "error_description": "「決める」は他動詞で目的語「境界を」と組む。「決まる」は自動詞なので目的語を取れず、誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37401, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い地図には、町の境界をくわしく描かれていた。", "corrected_sentence": "古い地図には、町の境界がくわしく描かれていた。", "error_description": "「描かれる」は受身で、主語に「が」を取る。「境界を」の「を」は誤りで、「境界が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c88d12a-58e2-4006-9490-e137dfe02a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37402, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "正解。集結（人が一か所に集まる）の対義語で、人がばらばらに散ることを表す。"}, {"text": "増加", "is_correct": false, "explanation": "増加は数や量が増えることで、集まりの対義語にはならないので合わない。"}, {"text": "完成", "is_correct": false, "explanation": "完成は物事が仕上がることで、人の集まりの対義語には当たらない。"}, {"text": "誕生", "is_correct": false, "explanation": "誕生は新しく生まれることで、集まりとは対義関係にならない。"}], "correct_answer": "分散", "explanations": {"分散": "正解。集結（人が一か所に集まる）の対義語で、人がばらばらに散ることを表す。", "増加": "増加は数や量が増えることで、集まりの対義語にはならないので合わない。", "完成": "完成は物事が仕上がることで、人の集まりの対義語には当たらない。", "誕生": "誕生は新しく生まれることで、集まりとは対義関係にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37402, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "正解。集結（人が一か所に集まる）の対義語で、人がばらばらに散ることを表す。"}, {"text": "上昇", "is_correct": false, "explanation": "上昇は数値や位置が高くなることで、集まりの対義語にはならないので合わない。"}, {"text": "発明", "is_correct": false, "explanation": "発明は新しいものを生み出すことで、集まりとは対義関係にない。"}, {"text": "報告", "is_correct": false, "explanation": "報告は情報を伝えることで、集まりの対義語には当たらない。"}], "correct_answer": "分散", "explanations": {"分散": "正解。集結（人が一か所に集まる）の対義語で、人がばらばらに散ることを表す。", "上昇": "上昇は数値や位置が高くなることで、集まりの対義語にはならないので合わない。", "発明": "発明は新しいものを生み出すことで、集まりとは対義関係にない。", "報告": "報告は情報を伝えることで、集まりの対義語には当たらない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37402, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "たくさんの人が一つの場所に集まること。", "primary_collocate": null, "pronunciation": "しゅうけつ", "ipa": "ɕɯːketsɯ", "syllable_count": 4, "sentences": [{"text": "広場には、朝から多くの市民が集結した。", "target_word": "集結", "complexity_tier": "T3", "furigana": "広場(ひろば)には、朝(あさ)から多(おお)くの市民(しみん)が集結(しゅうけつ)した。", "sentence_source": "generated"}, {"text": "試合の前に、選手たちがグラウンドに集結した。", "target_word": "集結", "complexity_tier": "T3", "furigana": "試合(しあい)の前(まえ)に、選手(せんしゅ)たちがグラウンドに集結(しゅうけつ)した。", "sentence_source": "generated"}, {"text": "抗議のため、数千人がデモの場所に集結している。", "target_word": "集結", "complexity_tier": "T3", "furigana": "抗議(こうぎ)のため、数千人(すうせんにん)がデモの場所(ばしょ)に集結(しゅうけつ)している。", "sentence_source": "generated"}, {"text": "全国から集まったファンが、会場前に集結した。", "target_word": "集結", "complexity_tier": "T3", "furigana": "全国(ぜんこく)から集(あつ)まったファンが、会場前(かいじょうまえ)に集結(しゅうけつ)した。", "sentence_source": "generated"}, {"text": "災害の知らせを聞いて、村の人々が学校に集結した。", "target_word": "集結", "complexity_tier": "T3", "furigana": "災害(さいがい)の知(し)らせを聞(き)いて、村(むら)の人々(ひとびと)が学校(がっこう)に集結(しゅうけつ)した。", "sentence_source": "generated"}, {"text": "開会式の時間までに、全員が体育館へ集結してください。", "target_word": "集結", "complexity_tier": "T3", "furigana": "開会式(かいかいしき)の時間(じかん)までに、全員(ぜんいん)が体育館(たいいくかん)へ集結(しゅうけつ)してください。", "sentence_source": "generated"}, {"text": "各地の代表が東京に集結し、大会が始まった。", "target_word": "集結", "complexity_tier": "T3", "furigana": "各地(かくち)の代表(だいひょう)が東京(とうきょう)に集結(しゅうけつ)し、大会(たいかい)が始(はじ)まった。", "sentence_source": "generated"}, {"text": "花火を見るために、川沿いに大勢の人が集結した。", "target_word": "集結", "complexity_tier": "T3", "furigana": "花火(はなび)を見(み)るために、川沿(かわぞ)いに大勢(おおぜい)の人(ひと)が集結(しゅうけつ)した。", "sentence_source": "generated"}, {"text": "演奏会の始まりを前に、楽団員がホールへ集結した。", "target_word": "集結", "complexity_tier": "T3", "furigana": "演奏会(えんそうかい)の始(はじ)まりを前(まえ)に、楽団員(がくだんいん)がホールへ集結(しゅうけつ)した。", "sentence_source": "generated"}, {"text": "世界中のダンサーが集結する大会が、来月開かれる。", "target_word": "集結", "complexity_tier": "T3", "furigana": "世界中(せかいじゅう)のダンサーが集結(しゅうけつ)する大会(たいかい)が、来月(らいげつ)開(ひら)かれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集結", "label": "基本形"}, {"form": "集結する", "label": "する動詞の辞書形"}, {"form": "集結した", "label": "た形"}, {"form": "集結している", "label": "ている形"}], "register": "やや硬い", "sense_fingerprint": "大勢の人が目的をもって一つの場所に集まること（人の集合）。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddfe4a92-bcbf-4b7c-b2a1-9385eb43d549') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37402, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集結", "is_correct": true, "explanation": "正解。「市民が集結した」は、多くの人が一か所に集まったことを表し、空欄に入る。"}, {"text": "融解", "is_correct": false, "explanation": "融解は固体が液体になることを指し、人の動きを表す文の空欄には合わない。"}, {"text": "摂取", "is_correct": false, "explanation": "摂取は栄養や物を取り入れることで、「市民が摂取した」では意味が通らない。"}, {"text": "修復", "is_correct": false, "explanation": "修復は壊れたものを直すことで、人が集まる出来事を表す文には合わない。"}], "explanations": {"集結": "正解。「市民が集結した」は、多くの人が一か所に集まったことを表し、空欄に入る。", "融解": "融解は固体が液体になることを指し、人の動きを表す文の空欄には合わない。", "摂取": "摂取は栄養や物を取り入れることで、「市民が摂取した」では意味が通らない。", "修復": "修復は壊れたものを直すことで、人が集まる出来事を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "集結"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "卒業式のあと、全員で集結写真を撮った。", "explanation": "ここは〈集合〉の意味。「集合写真」という決まった語で、集結では写真の名称として通らず、不自然。"}, {"text": "彼は勉強に集結して、夜遅くまで机に向かった。", "explanation": "ここは〈集中〉の意味。一つのことに注意を向けるのは集中で、集結は人が一か所に集まることなので、勉強には使えない。"}, {"text": "町内の集結を開いて、住民の意見を聞いた。", "explanation": "ここは〈集会〉の意味。集会は話し合いのために開かれる催しで「開く」対象になるが、集結は集まる出来事そのものなので「開く」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37402, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集結", "is_correct": true, "explanation": "正解。「代表が東京に集結し」は、各地から人が東京に集まったことを表す。"}, {"text": "腐敗", "is_correct": false, "explanation": "腐敗は物が傷んで悪くなることで、人が移動する文の空欄には合わない。"}, {"text": "沈殿", "is_correct": false, "explanation": "沈殿は液体中の物質が底に沈むことで、人の移動を表す文には合わない。"}, {"text": "焼失", "is_correct": false, "explanation": "焼失は火事で燃えて失われることで、代表が集まる文には合わない。"}], "explanations": {"集結": "正解。「代表が東京に集結し」は、各地から人が東京に集まったことを表す。", "腐敗": "腐敗は物が傷んで悪くなることで、人が移動する文の空欄には合わない。", "沈殿": "沈殿は液体中の物質が底に沈むことで、人の移動を表す文には合わない。", "焼失": "焼失は火事で燃えて失われることで、代表が集まる文には合わない。"}, "sentence_index": 6, "correct_answer": "集結"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この選挙は、今夜で集結した。", "explanation": "ここは〈終結〉の意味。終わることは終結で、集結は人や物が一か所に集まることなので、選挙が終わる意味では使えない。"}, {"text": "チームは、勝つために集結を固めた。", "explanation": "ここは〈結束〉の意味。固めるのは心のまとまりで、集結は場所に集まることなので、心理的な団結の代わりにはならない。"}, {"text": "この戦争の集結は、まだ先のことだ。", "explanation": "ここは〈終結〉の意味。戦いが終わることは終結で、集結は人や物が一か所に集まることなので、戦争の終わりには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37402, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祭りの前日、町の人々が神社を集結した。", "corrected_sentence": "祭りの前日、町の人々が神社に集結した。", "error_description": "「集結」は場所を「に」で示す自動詞。「を」は目的語用の助詞なので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37402, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "選手たちは、朝早く集結なかった。", "corrected_sentence": "選手たちは、朝早く集結しなかった。", "error_description": "「集結」は「する」を付けて動詞として活用させる。否定は「しなかった」となるので、「し」が抜けて誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37403, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「部隊を集結している」は、部隊を一か所に集める意味で、目的語を示す「を」が入る。"}, {"text": "の", "is_correct": false, "explanation": "「部隊の集結している」は、の が名詞を修飾する形で、文の動詞とつながらず、ここでは合わない。"}, {"text": "に", "is_correct": false, "explanation": "「部隊に集結している」は、集まる先を表す形として不自然で、部隊を集める意味にならない。"}, {"text": "で", "is_correct": false, "explanation": "「部隊で集結している」は手段を示すが、部隊を集める文として意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "正解。「部隊を集結している」は、部隊を一か所に集める意味で、目的語を示す「を」が入る。", "の": "「部隊の集結している」は、の が名詞を修飾する形で、文の動詞とつながらず、ここでは合わない。", "に": "「部隊に集結している」は、集まる先を表す形として不自然で、部隊を集める意味にならない。", "で": "「部隊で集結している」は手段を示すが、部隊を集める文として意味が通らない。"}, "error_tags": {"の": "連体修飾の格", "に": "帰着の格", "で": "手段の格"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "正解。集結（人や物が一か所に集まる）の対義語で、ばらばらに散ることを表す。"}, {"text": "沈没", "is_correct": false, "explanation": "沈没は船などが水中に沈むことで、集まりの対義語にはならないので合わない。"}, {"text": "成長", "is_correct": false, "explanation": "成長は大きくなることで、集まりの対義語にはならない。"}, {"text": "誕生", "is_correct": false, "explanation": "誕生は新しく生まれることで、集まりとは対義関係にならない。"}], "correct_answer": "分散", "explanations": {"分散": "正解。集結（人や物が一か所に集まる）の対義語で、ばらばらに散ることを表す。", "沈没": "沈没は船などが水中に沈むことで、集まりの対義語にはならないので合わない。", "成長": "成長は大きくなることで、集まりの対義語にはならない。", "誕生": "誕生は新しく生まれることで、集まりとは対義関係にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37403, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "正解。集結（人や物が一か所に集まる）の対義語で、ばらばらに散ることを表す。"}, {"text": "上昇", "is_correct": false, "explanation": "上昇は数値や位置が高くなることで、集まりの対義語にはならないので合わない。"}, {"text": "発明", "is_correct": false, "explanation": "発明は新しいものを生み出すことで、集まりとは対義関係にない。"}, {"text": "報告", "is_correct": false, "explanation": "報告は情報を伝えることで、集まりの対義語には当たらない。"}], "correct_answer": "分散", "explanations": {"分散": "正解。集結（人や物が一か所に集まる）の対義語で、ばらばらに散ることを表す。", "上昇": "上昇は数値や位置が高くなることで、集まりの対義語にはならないので合わない。", "発明": "発明は新しいものを生み出すことで、集まりとは対義関係にない。", "報告": "報告は情報を伝えることで、集まりの対義語には当たらない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37403, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人や物が一か所に集まること。また、集めること。", "primary_collocate": null, "pronunciation": "しゅうけつ", "ipa": "ɕɯːketsɯ", "syllable_count": 4, "sentences": [{"text": "消防隊は、現場に消防車を集結させた。", "target_word": "集結", "complexity_tier": "T3", "furigana": "消防隊(しょうぼうたい)は、現場(げんば)に消防車(しょうぼうしゃ)を集結(しゅうけつ)させた。", "sentence_source": "generated"}, {"text": "軍は国境近くに部隊を集結している。", "target_word": "集結", "complexity_tier": "T3", "furigana": "軍(ぐん)は国境近(こっきょうちか)くに部隊(ぶたい)を集結(しゅうけつ)している。", "sentence_source": "generated"}, {"text": "監督は、優秀な選手を一つのチームに集結させた。", "target_word": "集結", "complexity_tier": "T3", "furigana": "監督(かんとく)は、優秀(ゆうしゅう)な選手(せんしゅ)を一(ひと)つのチームに集結(しゅうけつ)させた。", "sentence_source": "generated"}, {"text": "山のふもとに救助隊の車両が集結した。", "target_word": "集結", "complexity_tier": "T3", "furigana": "山(やま)のふもとに救助隊(きゅうじょたい)の車両(しゃりょう)が集結(しゅうけつ)した。", "sentence_source": "generated"}, {"text": "港に漁船が集結し、出発の時を待っていた。", "target_word": "集結", "complexity_tier": "T3", "furigana": "港(みなと)に漁船(ぎょせん)が集結(しゅうけつ)し、出発(しゅっぱつ)の時(とき)を待(ま)っていた。", "sentence_source": "generated"}, {"text": "社長は全国の営業担当者を本社に集結させた。", "target_word": "集結", "complexity_tier": "T3", "furigana": "社長(しゃちょう)は全国(ぜんこく)の営業担当者(えいぎょうたんとうしゃ)を本社(ほんしゃ)に集結(しゅうけつ)させた。", "sentence_source": "generated"}, {"text": "工事のために、大型の機械が現場へ集結した。", "target_word": "集結", "complexity_tier": "T3", "furigana": "工事(こうじ)のために、大型(おおがた)の機械(きかい)が現場(げんば)へ集結(しゅうけつ)した。", "sentence_source": "generated"}, {"text": "各地の技術者が集結して、新しい宇宙船が作られた。", "target_word": "集結", "complexity_tier": "T3", "furigana": "各地(かくち)の技術者(ぎじゅつしゃ)が集結(しゅうけつ)して、新(あたら)しい宇宙船(うちゅうせん)が作(つく)られた。", "sentence_source": "generated"}, {"text": "最新の機材を一か所に集結させた、大型の撮影スタジオが完成した。", "target_word": "集結", "complexity_tier": "T3", "furigana": "最新(さいしん)の機材(きざい)を一か所(いっかしょ)に集結(しゅうけつ)させた、大型(おおがた)の撮影(さつえい)スタジオが完成(かんせい)した。", "sentence_source": "generated"}, {"text": "台風に備えて、市内に救助用の資材が集結している。", "target_word": "集結", "complexity_tier": "T3", "furigana": "台風(たいふう)に備(そな)えて、市内(しない)に救助用(きゅうじょよう)の資材(しざい)が集結(しゅうけつ)している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集結", "label": "基本形"}, {"form": "集結する", "label": "する動詞の辞書形"}, {"form": "集結させる", "label": "使役形"}, {"form": "集結した", "label": "た形"}], "register": "やや硬い", "sense_fingerprint": "人だけでなく車両・部隊・力なども一か所に集まる、または集める（他動的にも使う）こと。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddfe4a92-bcbf-4b7c-b2a1-9385eb43d549') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37403, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集結", "is_correct": true, "explanation": "正解。「消防車を集結させた」は、消防車を一か所に集めたことを表し、空欄に入る。"}, {"text": "隆起", "is_correct": false, "explanation": "隆起は土地などが盛り上がることで、車を集める文の空欄には合わない。"}, {"text": "乱用", "is_correct": false, "explanation": "乱用は権利や薬などを無闇に使うことで、消防車を集める文には合わない。"}, {"text": "醸造", "is_correct": false, "explanation": "醸造は酒や味噌を作ることで、消防車を動かす文の空欄には入らない。"}], "explanations": {"集結": "正解。「消防車を集結させた」は、消防車を一か所に集めたことを表し、空欄に入る。", "隆起": "隆起は土地などが盛り上がることで、車を集める文の空欄には合わない。", "乱用": "乱用は権利や薬などを無闇に使うことで、消防車を集める文には合わない。", "醸造": "醸造は酒や味噌を作ることで、消防車を動かす文の空欄には入らない。"}, "sentence_index": 0, "correct_answer": "集結"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "選手たちは、試合の前に集結を固めた。", "explanation": "ここは〈結束〉の意味。固めるのは心のまとまりで、集結は場所に集まることなので、心理的な団結の代わりにはならない。"}, {"text": "作業に集結して、時間を忘れた。", "explanation": "ここは〈集中〉の意味。作業に注意を向ける意味は集中で、集結は物や人が一か所に集まることなので、注意を向ける意味では使えない。"}, {"text": "週末、地域の課題の数を集結して発表した。", "explanation": "ここは〈集計〉の意味。数をまとめて数えるのは集計で、集結は人や物が一か所に集まることなので、数を数える意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37403, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集結", "is_correct": true, "explanation": "正解。「現場へ集結した」は、機械が現場に集まったことを表し、空欄に入る。"}, {"text": "撃退", "is_correct": false, "explanation": "撃退は敵などを退けることで、機械が現場に集まる文の空欄には合わない。"}, {"text": "焼失", "is_correct": false, "explanation": "焼失は火事で燃えて失われることで、機械が現場に集まる文には合わない。"}, {"text": "解禁", "is_correct": false, "explanation": "解禁は禁止を解くことで、機械の移動を表す文の空欄には合わない。"}], "explanations": {"集結": "正解。「現場へ集結した」は、機械が現場に集まったことを表し、空欄に入る。", "撃退": "撃退は敵などを退けることで、機械が現場に集まる文の空欄には合わない。", "焼失": "焼失は火事で燃えて失われることで、機械が現場に集まる文には合わない。", "解禁": "解禁は禁止を解くことで、機械の移動を表す文の空欄には合わない。"}, "sentence_index": 6, "correct_answer": "集結"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在庫の確認は、昨日で集結した。", "explanation": "ここは〈終結〉の意味。終わることは終結で、集結は人や物が一か所に集まることなので、確認が終わる意味では使えない。"}, {"text": "修学旅行の日、クラス全員で集結写真を撮った。", "explanation": "ここは〈集合〉の意味。「集合写真」という決まった語で、集結では写真の名称として通らず、不自然。"}, {"text": "試合の終わりに、両チームの争いが集結した。", "explanation": "ここは〈終結〉の意味。争いが終わることは終結で、集結は人や物が一か所に集まることなので、争いの終わりには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37403, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "救助隊は、被災地に車両が集結させた。", "corrected_sentence": "救助隊は、被災地に車両を集結させた。", "error_description": "「集結させる」は他動詞の使役形で、動かされる物には「を」を用いる。「が」にすると車両が主語になり、誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37403, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は、避難所に物資を集結せた。", "corrected_sentence": "市は、避難所に物資を集結させた。", "error_description": "「集結させる」の使役の活用は「させ」であり、「せ」だけでは活用が崩れて誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37404, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「従来のルール」で、名詞をつなぎます。"}, {"text": "を", "is_correct": false, "explanation": "「従来をルールは」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「従来へルールは」は文として成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「従来にルールは変わりません」は文として成り立ちません。"}], "correct_answer": "の", "explanations": {"の": "「従来のルール」で、名詞をつなぎます。", "を": "「従来をルールは」は文として成り立ちません。", "へ": "「従来へルールは」は文として成り立ちません。", "に": "「従来にルールは変わりません」は文として成り立ちません。"}, "error_tags": {"を": "wrong_case", "へ": "direction", "に": "wrong_case"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "将来", "is_correct": true, "explanation": "これから先のことで、「従来」の反対です。"}, {"text": "以前", "is_correct": false, "explanation": "前のことで、反対ではなく近い意味です。"}, {"text": "元来", "is_correct": false, "explanation": "もともとのことで、反対の関係ではありません。"}, {"text": "本来", "is_correct": false, "explanation": "あるべき姿のことで、反対の関係ではありません。"}], "correct_answer": "将来", "explanations": {"将来": "これから先のことで、「従来」の反対です。", "以前": "前のことで、反対ではなく近い意味です。", "元来": "もともとのことで、反対の関係ではありません。", "本来": "あるべき姿のことで、反対の関係ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37404, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「従来から」で、今までずっとという起点を表します。"}, {"text": "を", "is_correct": false, "explanation": "「従来を使っている」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「従来へ使っている」は文として成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「従来に使っている鍋」は意味が通りません。"}], "correct_answer": "から", "explanations": {"から": "「従来から」で、今までずっとという起点を表します。", "を": "「従来を使っている」は文として成り立ちません。", "へ": "「従来へ使っている」は文として成り立ちません。", "に": "「従来に使っている鍋」は意味が通りません。"}, "error_tags": {"を": "wrong_case", "へ": "direction", "に": "wrong_case"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "今後", "is_correct": true, "explanation": "これからのことで、「従来」の反対です。"}, {"text": "昔", "is_correct": false, "explanation": "過去のことで、反対ではなく近い意味です。"}, {"text": "従前", "is_correct": false, "explanation": "今までのことで、反対ではなく近い意味です。"}, {"text": "在来", "is_correct": false, "explanation": "今まであることで、反対ではなく近い意味です。"}], "correct_answer": "今後", "explanations": {"今後": "これからのことで、「従来」の反対です。", "昔": "過去のことで、反対ではなく近い意味です。", "従前": "今までのことで、反対ではなく近い意味です。", "在来": "今まであることで、反対ではなく近い意味です。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
