INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37405, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "今までずっと続いてきた状態や考え方を指す言葉。", "primary_collocate": null, "pronunciation": "じゅうらい", "ipa": "dʑɯːɾai", "syllable_count": 4, "sentences": [{"text": "従来の肉体労働は減少しますが、機械を操作する専門知識を持つ人材の確保が、新たな課題として浮上しているのです。", "target_word": "従来", "complexity_tier": "T6", "furigana": "従来[じゅうらい]の肉体労働[にくたいろうどう]は減少[げんしょう]しますが、機械[きかい]を操作[そうさ]する専門知識[せんもんちしき]を持[も]つ人材[じんざい]の確保[かくほ]が、新[あら]たな課題[かだい]として浮上[ふじょう]しているのです。", "sentence_source": "mined"}, {"text": "従来のやり方を変えよう。", "target_word": "従来", "complexity_tier": "T3", "furigana": "従来[じゅうらい]のやり方[かた]を変[か]えよう。", "sentence_source": "generated"}, {"text": "従来は手で作っていました。", "target_word": "従来", "complexity_tier": "T2", "furigana": "従来[じゅうらい]は手[て]で作[つく]っていました。", "sentence_source": "generated"}, {"text": "この店は従来から人気がある。", "target_word": "従来", "complexity_tier": "T3", "furigana": "この店[みせ]は従来[じゅうらい]から人気[にんき]がある。", "sentence_source": "generated"}, {"text": "従来の考え方では、問題は解けない。", "target_word": "従来", "complexity_tier": "T3", "furigana": "従来[じゅうらい]の考[かんが]え方[かた]では、問題[もんだい]は解[と]けない。", "sentence_source": "generated"}, {"text": "新しい機械は従来より速く動く。", "target_word": "従来", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]は従来[じゅうらい]より速[はや]く動[うご]く。", "sentence_source": "generated"}, {"text": "従来の方法に比べて、安くできる。", "target_word": "従来", "complexity_tier": "T3", "furigana": "従来[じゅうらい]の方法[ほうほう]に比[くら]べて、安[やす]くできる。", "sentence_source": "generated"}, {"text": "従来、この仕事は男性が多かった。", "target_word": "従来", "complexity_tier": "T3", "furigana": "従来[じゅうらい]、この仕事[しごと]は男性[だんせい]が多[おお]かった。", "sentence_source": "generated"}, {"text": "従来の計画を見直す必要がある。", "target_word": "従来", "complexity_tier": "T3", "furigana": "従来[じゅうらい]の計画[けいかく]を見直[みなお]す必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "これは従来の車とはちがう。", "target_word": "従来", "complexity_ti