INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37405, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "従来", "is_correct": true, "explanation": "じゅうらい。正解の語です。"}, {"text": "襲来", "is_correct": false, "explanation": "しゅうらい。「じゅ」が「しゅ」になり、1音だけ違います。"}, {"text": "縦覧", "is_correct": false, "explanation": "じゅうらん。最後の「い」が「ん」になり、1音だけ違います。"}, {"text": "獣害", "is_correct": false, "explanation": "じゅうがい。「ら」が「が」になり、1音だけ違います。"}], "explanations": {"従来": "じゅうらい。正解の語です。", "襲来": "しゅうらい。「じゅ」が「しゅ」になり、1音だけ違います。", "縦覧": "じゅうらん。最後の「い」が「ん」になり、1音だけ違います。", "獣害": "じゅうがい。「ら」が「が」になり、1音だけ違います。"}, "sentence_index": null, "correct_answer": "従来"}, "level_3": {"options": [{"text": "従来", "is_correct": true, "explanation": "今までの方法と比べて安い、と意味が合います。"}, {"text": "偶然", "is_correct": false, "explanation": "形は合うが、「偶然の方法」では意味が合わない。"}, {"text": "景色", "is_correct": false, "explanation": "形は合うが、「景色の方法」では意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、「地震の方法」では意味が合わない。"}], "explanations": {"従来": "今までの方法と比べて安い、と意味が合います。", "偶然": "形は合うが、「偶然の方法」では意味が合わない。", "景色": "形は合うが、「景色の方法」では意味が合わない。", "地震": "形は合うが、「地震の方法」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "従来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "従来の車は、来年はじめて発売される予定だ。", "explanation": "「従来」は今までのことなので、来年はじめて出る車には使えません。"}, {"text": "従来に行く電車は、もうすぐ出る。", "explanation": "「従来」は場所を表す語ではありません。"}, {"text": "今日は従来が痛くて、病院へ行った。", "explanation": "「従来」は体の部分を表す語ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37405, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "従来を方法で作っています。", "corrected_sentence": "従来の方法で作っています。", "error_description": "「従来」は「従来の方法」のように「の」でつなぎます。「を」は誤りです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37405, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい機械は従来と速く動く。", "corrected_sentence": "新しい機械は従来より速く動く。", "error_description": "比べる表現なので「従来より」とします。「と」は誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8a00704-04cf-4dcc-8038-f5b487a1dd7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37406, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「共同で店を始める」の「で」で、手段・様子を表す。"}, {"text": "に", "is_correct": false, "explanation": "「共同に」は形として続かず、「三人は共同に店を始めた」は文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「共同を店」では目的語が二つになり、「始めた」の対象として意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」だが、ここは店を始める手段・様子を示す場面なので合わない。"}], "correct_answer": "で", "explanations": {"で": "「共同で店を始める」の「で」で、手段・様子を表す。", "に": "「共同に」は形として続かず、「三人は共同に店を始めた」は文が成り立たない。", "を": "「共同を店」では目的語が二つになり、「始めた」の対象として意味が通らない。", "へ": "方向の「へ」だが、ここは店を始める手段・様子を示す場面なので合わない。"}, "error_tags": {"に": "相手・帰着", "を": "目的語", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "睡眠", "is_correct": false, "explanation": "眠ること。共同とは対になる語ではない。"}, {"text": "報告", "is_correct": false, "explanation": "相手に知らせる行為を指し、共同とは対になる語ではない。"}, {"text": "単独", "is_correct": true, "explanation": "「共同」の対義語。ひとりで行うこと。"}, {"text": "作業", "is_correct": false, "explanation": "仕事そのものを指す語で、共同の対義語とはいえない。"}], "correct_answer": "単独", "explanations": {"睡眠": "眠ること。共同とは対になる語ではない。", "報告": "相手に知らせる行為を指し、共同とは対になる語ではない。", "単独": "「共同」の対義語。ひとりで行うこと。", "作業": "仕事そのものを指す語で、共同の対義語とはいえない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37406, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「共同でお金を出す」の「で」で、手段・様子を表す。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点の「より」で、「共同よりお金を出して」は意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「共同が」は主語になり、「共同がお金を出す」となって不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手の「と」で、「友だちと共同と」と続くと二重になり文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「共同でお金を出す」の「で」で、手段・様子を表す。", "より": "比較・起点の「より」で、「共同よりお金を出して」は意味が通らない。", "が": "「共同が」は主語になり、「共同がお金を出す」となって不自然。", "と": "並列・相手の「と」で、「友だちと共同と」と続くと二重になり文が成り立たない。"}, "error_tags": {"より": "比較・起点", "が": "主語", "と": "並列・相手"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外出", "is_correct": false, "explanation": "家の外へ出ることを指し、共同の対義語ではない。"}, {"text": "雑談", "is_correct": false, "explanation": "気軽に話すことを指し、共同とは反対の関係ではない。"}, {"text": "単独", "is_correct": true, "explanation": "「共同」の対義語。ひとりで行うこと。"}, {"text": "持参", "is_correct": false, "explanation": "持って行くことを指し、共同の対義語とはいえない。"}], "correct_answer": "単独", "explanations": {"外出": "家の外へ出ることを指し、共同の対義語ではない。", "雑談": "気軽に話すことを指し、共同とは反対の関係ではない。", "単独": "「共同」の対義語。ひとりで行うこと。", "持参": "持って行くことを指し、共同の対義語とはいえない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37406, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "なんにんかで いっしょに する こと。", "primary_collocate": null, "pronunciation": "きょうどう", "ipa": "kʲoːdoː", "syllable_count": 4, "sentences": [{"text": "兄と共同で部屋を使っている。", "target_word": "共同", "complexity_tier": "T3", "furigana": "兄(あに)と共同(きょうどう)で部屋(へや)を使(つか)っている。", "sentence_source": "generated"}, {"text": "三人は共同で店を始めた。", "target_word": "共同", "complexity_tier": "T3", "furigana": "三人(さんにん)は共同(きょうどう)で店(みせ)を始(はじ)めた。", "sentence_source": "generated"}, {"text": "近所の人たちが共同で庭の草むしりをしている。", "target_word": "共同", "complexity_tier": "T3", "furigana": "近所[きんじょ]の人[ひと]たちが共同[きょうどう]で庭[にわ]の草[くさ]むしりをしている。", "sentence_source": "generated"}, {"text": "学生たちは共同で研究をまとめた。", "target_word": "共同", "complexity_tier": "T3", "furigana": "学生(がくせい)たちは共同(きょうどう)で研究(けんきゅう)をまとめた。", "sentence_source": "generated"}, {"text": "隣の家と共同でごみ置き場を掃除している。", "target_word": "共同", "complexity_tier": "T3", "furigana": "隣(となり)の家(いえ)と共同(きょうどう)でごみ置(お)き場(ば)を掃除(そうじ)している。", "sentence_source": "generated"}, {"text": "二つの会社が共同で新しい商品を作った。", "target_word": "共同", "complexity_tier": "T3", "furigana": "二(ふた)つの会社(かいしゃ)が共同(きょうどう)で新(あたら)しい商品(しょうひん)を作(つく)った。", "sentence_source": "generated"}, {"text": "寮の仲間たちは、毎晩の夕食を共同で作っている。", "target_word": "共同", "complexity_tier": "T3", "furigana": "寮[りょう]の仲間[なかま]たちは、毎晩[まいばん]の夕食[ゆうしょく]を共同[きょうどう]で作[つく]っている。", "sentence_source": "generated"}, {"text": "友だちと共同でお金を出して、プレゼントを買った。", "target_word": "共同", "complexity_tier": "T3", "furigana": "友(とも)だちと共同(きょうどう)でお金(かね)を出(だ)して、プレゼントを買(か)った。", "sentence_source": "generated"}, {"text": "村の人々は共同で橋を直した。", "target_word": "共同", "complexity_tier": "T3", "furigana": "村(むら)の人々(ひとびと)は共同(きょうどう)で橋(はし)を直(なお)した。", "sentence_source": "generated"}, {"text": "寮では、トイレやふろを共同で使う。", "target_word": "共同", "complexity_tier": "T3", "furigana": "寮(りょう)では、トイレやふろを共同(きょうどう)で使(つか)う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "共同", "label": "基本形"}, {"form": "共同で", "label": "で格"}, {"form": "共同の", "label": "連体形（の）"}, {"form": "共同する", "label": "する動詞の辞書形"}], "register": "標準", "sense_fingerprint": "数人でいっしょに何かをしたり、同じものを使ったりすること。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddfe4a92-bcbf-4b7c-b2a1-9385eb43d549') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37406, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電話", "is_correct": false, "explanation": "「電話で部屋を使う」は意味が通らず、空欄に入らない。"}, {"text": "共同", "is_correct": true, "explanation": "「兄と共同で部屋を使っている」は、兄とふたりで部屋を共有する意味になり文脈に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩で部屋を使う」は意味が通らず、空欄に入らない。"}, {"text": "食事", "is_correct": false, "explanation": "「食事で部屋を使う」は意味が通らず、空欄に入らない。"}], "explanations": {"電話": "「電話で部屋を使う」は意味が通らず、空欄に入らない。", "共同": "「兄と共同で部屋を使っている」は、兄とふたりで部屋を共有する意味になり文脈に合う。", "散歩": "「散歩で部屋を使う」は意味が通らず、空欄に入らない。", "食事": "「食事で部屋を使う」は意味が通らず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "共同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの川は、この町で共同する。", "explanation": "ここは〈合流〉の意味。「合流する」の「合流」を共同に置き換えると、川などが一つに集まる意味が表せず不自然。"}, {"text": "彼女は困っている仲間への共同を惜しまない人だ。", "explanation": "ここは〈協力〉の意味。「協力を惜しまない」の「協力」を共同に置き換えると、助け合う気持ちを表せない。"}, {"text": "海外の大学との共同を深めている。", "explanation": "ここは〈交流〉の意味。「交流を深める」は行き来して親しくなること。共同は「いっしょに作業する」ことなので、この言い方では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
