INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37407, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二人以上の人が、一緒に同じことをすること。", "primary_collocate": null, "pronunciation": "きょうどう", "ipa": "kʲoːdoː", "syllable_count": 4, "sentences": [{"text": "二人は共同で小説を書き、一冊の本にした。", "target_word": "共同", "complexity_tier": "T3", "furigana": "二人(ふたり)は共同(きょうどう)で小説(しょうせつ)を書(か)き、一冊(いっさつ)の本(ほん)にした。", "sentence_source": "generated"}, {"text": "日本とアメリカの研究者が共同で、新しい薬を開発した。", "target_word": "共同", "complexity_tier": "T3", "furigana": "日本(にほん)とアメリカの研究者(けんきゅうしゃ)が共同(きょうどう)で、新(あたら)しい薬(くすり)を開発(かいはつ)した。", "sentence_source": "generated"}, {"text": "共同の作業では、お互いの考えを聞くことが大切だ。", "target_word": "共同", "complexity_tier": "T3", "furigana": "共同(きょうどう)の作業(さぎょう)では、お互(たが)いの考(かんが)えを聞(き)くことが大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "彼女は友人と共同で、ケーキ屋を経営している。", "target_word": "共同", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は友人(ゆうじん)と共同(きょうどう)で、ケーキ屋(や)を経営(けいえい)している。", "sentence_source": "generated"}, {"text": "この賞は、三人の科学者が共同で受け取った。", "target_word": "共同", "complexity_tier": "T3", "furigana": "この賞(しょう)は、三人(さんにん)の科学者(かがくしゃ)が共同(きょうどう)で受(う)け取(と)った。", "sentence_source": "generated"}, {"text": "三人の学生が共同で論文を仕上げ、学会で発表した。", "target_word": "共同", "complexity_tier": "T3", "furigana": "三人(さんにん)の学生(がくせい)が共同(きょうどう)で論文(ろんぶん)を仕上(しあ)げ、学会(がっかい)で発表(はっぴょう)した。", "sentence_source": "generated"}, {"text": "両国は共同で声明を出した。", "target_word": "共同", "complexity_tier": "T3", "furigana": "両国(りょうこく)は共同(きょうどう)で声明(せいめい)を出(だ)した。", "sentence_source": "generated"}, {"text": "共同の計画なので、勝手に変えないでください。", "target_word": "共同", "complexity_tier": "T3", "furigana": "共同(きょうどう)の計画(けいかく)なので、勝手(かって)に変(か)えないでください。", "sentence_source": "generated"}, {"text": "クラス全員が共同で、文化祭の劇を作り上げた。", "target_word": "共同", "complexity_tier": "T3", "furigana": "クラス全員(ぜんいん)が共同(きょうどう)で、文化祭(ぶんかさい)の劇(げき)を作(つく)り上(あ)げた。", "sentence_source": "generated"}, {"text": "二つの大学は共同で、市民向けの講座を開いている。", "target_word": "共同", "complexity_tier": "T3", "furigana": "二(ふた)つの大学(だいがく)は共同(きょうどう)で、市民向(しみんむ)けの講座(こうざ)を開(ひら)いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "共同", "label": "基本形"}, {"form": "共同で", "label": "で格"}, {"form": "共同の", "label": "連体形（の）"}, {"form": "共同する", "label": "する動詞の辞書形"}], "register": "標準", "sense_fingerprint": "二人以上（または複数の団体）が力を合わせて同じ仕事・研究・計画などを行うこと。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddfe4a92-bcbf-4b7c-b2a1-9385eb43d549') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37407, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散歩", "is_correct": false, "explanation": "「散歩で小説を書く」は意味が通らず、空欄に入らない。"}, {"text": "共同", "is_correct": true, "explanation": "「二人は共同で小説を書き」は、ふたりで力を合わせて書く意味になり文脈に合う。"}, {"text": "食事", "is_correct": false, "explanation": "「食事で小説を書く」は意味が通らず、空欄に入らない。"}, {"text": "買い物", "is_correct": false, "explanation": "「買い物で小説を書く」は意味が通らず、空欄に入らない。"}], "explanations": {"散歩": "「散歩で小説を書く」は意味が通らず、空欄に入らない。", "共同": "「二人は共同で小説を書き」は、ふたりで力を合わせて書く意味になり文脈に合う。", "食事": "「食事で小説を書く」は意味が通らず、空欄に入らない。", "買い物": "「買い物で小説を書く」は意味が通らず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "共同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人は手紙を共同した。", "explanation": "ここは〈交換〉の意味。「手紙を交換する」の「交換」を共同に置き換えると、互いにやり取りする意味が表せず不自然。"}, {"text": "あの店員は、お客さんの頼みに共同を惜しまない。", "explanation": "ここは〈協力〉の意味。「協力を惜しまない」の「協力」を共同にすると、助力する気持ちが伝わらず不自然。"}, {"text": "チームは共同を重んじて練習を続けた。", "explanation": "ここは〈協調〉の意味。「協調を重んじる」の「協調」を共同に置き換えると、互いに合わせる態度の意味にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37407, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掃除", "is_correct": false, "explanation": "「掃除で声明を出す」は意味が通らず、空欄に入らない。"}, {"text": "体操", "is_correct": false, "explanation": "「体操で声明を出す」は意味が通らず、空欄に入らない。"}, {"text": "共同", "is_correct": true, "explanation": "「両国は共同で声明を出した」は、両国が力を合わせて出す意味になり文脈に合う。"}, {"text": "昼寝", "is_correct": false, "explanation": "「昼寝で声明を出す」は意味が通らず、空欄に入らない。"}], "explanations": {"掃除": "「掃除で声明を出す」は意味が通らず、空欄に入らない。", "体操": "「体操で声明を出す」は意味が通らず、空欄に入らない。", "共同": "「両国は共同で声明を出した」は、両国が力を合わせて出す意味になり文脈に合う。", "昼寝": "「昼寝で声明を出す」は意味が通らず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "共同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その団体は被災地を共同している。", "explanation": "ここは〈支援〉の意味。「被災地を支援する」の「支援」を共同に置き換えると、手助けする意味が表せず不自然。"}, {"text": "警察と住民は共同を取って、防犯パトロールを始めた。", "explanation": "ここは〈連携〉の意味。「連携を取る」の「連携」を共同に置き換えると、互いに歩調を合わせる意味が表せず不自然。"}, {"text": "先生の共同を受けて、論文を書き上げた。", "explanation": "ここは〈指導〉の意味。「指導を受ける」の「指導」を共同に置き換えると、教え導いてもらう意味にならず不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
