INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37408, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「デジタルの世界」のように、デジタルが世界を修飾する関係を示す。正解。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示す。「デジタルを世界が好き」では対象の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。ここは所属や範囲を示す位置ではないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "時点や相手を示す。「デジタルに世界が好き」では文の関係が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「デジタルの世界」のように、デジタルが世界を修飾する関係を示す。正解。", "を": "動作の対象を示す。「デジタルを世界が好き」では対象の関係が成り立たない。", "へ": "方向を示す。ここは所属や範囲を示す位置ではないので合わない。", "に": "時点や相手を示す。「デジタルに世界が好き」では文の関係が成り立たない。"}, "error_tags": {"を": "対象", "へ": "方向", "に": "時点・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "アナログ", "is_correct": true, "explanation": "機械やネットに頼らない、連続的な方式の世界を指し、デジタルの対義語。正解。"}, {"text": "紙", "is_correct": false, "explanation": "書く材料のこと。デジタルの世界の対義語にはならない。"}, {"text": "石器", "is_correct": false, "explanation": "石で作った道具のこと。デジタルの対義語とは言えない。"}, {"text": "山岳", "is_correct": false, "explanation": "高い山々のこと。デジタルの対義語にはならない。"}], "correct_answer": "アナログ", "explanations": {"アナログ": "機械やネットに頼らない、連続的な方式の世界を指し、デジタルの対義語。正解。", "紙": "書く材料のこと。デジタルの世界の対義語にはならない。", "石器": "石で作った道具のこと。デジタルの対義語とは言えない。", "山岳": "高い山々のこと。デジタルの対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
