INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37408, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "コンピューターやインターネットの世界のことです。ボタンを押すだけで絵や音が動きます。", "primary_collocate": null, "pronunciation": "でじたる", "ipa": "deʑitaɾɯ", "syllable_count": 4, "sentences": [{"text": "デジタルの世界では、ボタンを押すだけで絵が動きます。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "デジタルの世界[せかい]では、ボタンを押[お]すだけで絵[え]が動[うご]きます。", "sentence_source": "generated"}, {"text": "兄はデジタルの世界が好きで、毎日パソコンを使っています。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "兄[あに]はデジタルの世界[せかい]が好[す]きで、毎日[まいにち]パソコンを使[つか]っています。", "sentence_source": "generated"}, {"text": "学校では、デジタルの道具を使って勉強します。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "学校[がっこう]では、デジタルの道具[どうぐ]を使[つか]って勉強[べんきょう]します。", "sentence_source": "generated"}, {"text": "祖母はデジタルが苦手で、スマートフォンをあまり使いません。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "祖母[そぼ]はデジタルが苦手[にがて]で、スマートフォンをあまり使[つか]いません。", "sentence_source": "generated"}, {"text": "デジタルの本なら、たくさんの本を一つの機械に入れられます。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "デジタルの本[ほん]なら、たくさんの本[ほん]を一[ひと]つの機械[きかい]に入[い]れられます。", "sentence_source": "generated"}, {"text": "妹はデジタルで絵をかいて、友だちに見せています。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "妹[いもうと]はデジタルで絵[え]をかいて、友[とも]だちに見[み]せています。", "sentence_source": "generated"}, {"text": "インターネットなどのデジタルの世界には、気をつけることもあります。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "インターネットなどのデジタルの世界[せかい]には、気[き]をつけることもあります。", "sentence_source": "generated"}, {"text": "夏休みに、デジタルの音楽を作る教室に行きました。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、デジタルの音楽[おんがく]を作[つく]る教室[きょうしつ]に行[い]きました。", "sentence_source": "generated"}, {"text": "デジタルの絵は、色を何度でも直せるので便利です。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "デジタルの絵[え]は、色[いろ]を何度[なんど]でも直[なお]せるので便利[べんり]です。", "sentence_source": "generated"}, {"text": "父は紙の地図ではなく、デジタルの地図を見て道を探します。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "父[ちち]は紙[かみ]の地図[ちず]ではなく、デジタルの地図[ちず]を見[み]て道[みち]を探[さが]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "デジタル", "label": "基本形"}], "register": "丁寧（です・ます体）", "sense_fingerprint": "コンピューターやインターネットなど、機械の中で絵や音が動く世界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95d3b987-f670-4e84-a902-8e7233637a42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37408, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "デジタル", "is_correct": true, "explanation": "コンピューターやインターネットの世界を指す。「デジタルの世界」の形で文に合う。正解。"}, {"text": "手紙", "is_correct": false, "explanation": "人に用件を書いて送るもの。「手紙の世界では、ボタンを押すだけで絵が動く」は成り立たない。"}, {"text": "石器", "is_correct": false, "explanation": "石で作った道具のこと。ボタンで絵が動く世界の説明にはならない。"}, {"text": "山岳", "is_correct": false, "explanation": "高い山々のこと。絵が動く世界を表す語としては合わない。"}], "explanations": {"デジタル": "コンピューターやインターネットの世界を指す。「デジタルの世界」の形で文に合う。正解。", "手紙": "人に用件を書いて送るもの。「手紙の世界では、ボタンを押すだけで絵が動く」は成り立たない。", "石器": "石で作った道具のこと。ボタンで絵が動く世界の説明にはならない。", "山岳": "高い山々のこと。絵が動く世界を表す語としては合わない。"}, "sentence_index": 0, "correct_answer": "デジタル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母はデジタルの糸を紡いで、セーターを編んだ。", "explanation": "ここは〈毛糸〉の意味。デジタルは機械やネットの世界を指すので、紡いで編む材料にはならない。"}, {"text": "庭のデジタルが咲きそろいました。", "explanation": "ここは〈花〉の意味。デジタルは機器やネットの世界を指し、庭の植物は表さないので合わない。"}, {"text": "川でデジタルを釣りました。", "explanation": "ここは〈魚〉の意味。デジタルは機械やネットの世界を指すので、釣りの対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37408, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "デジタル", "is_correct": true, "explanation": "インターネットなどの機械の世界を指す。「デジタルの世界には」の形で文に合う。正解。"}, {"text": "郷土", "is_correct": false, "explanation": "生まれ育った土地のこと。ネットの世界の注意点を述べる文には合わない。"}, {"text": "田園", "is_correct": false, "explanation": "田畑や田舎の景色のこと。インターネットの話とは合わない。"}, {"text": "海底", "is_correct": false, "explanation": "海の底のこと。インターネットの世界を表す語としては合わない。"}], "explanations": {"デジタル": "インターネットなどの機械の世界を指す。「デジタルの世界には」の形で文に合う。正解。", "郷土": "生まれ育った土地のこと。ネットの世界の注意点を述べる文には合わない。", "田園": "田畑や田舎の景色のこと。インターネットの話とは合わない。", "海底": "海の底のこと。インターネットの世界を表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "デジタル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕方になると、デジタルがやみました。", "explanation": "ここは〈雨〉の意味。デジタルは機械やネットの世界を指し、天気の変化には使わないので合わない。"}, {"text": "海でデジタルを拾いました。", "explanation": "ここは〈貝〉の意味。デジタルは機械やネットの世界を指すので、海で拾うものにはならない。"}, {"text": "山小屋でデジタルを燃やしました。", "explanation": "ここは〈薪〉の意味。デジタルは機械やネットの世界を指すので、燃やす対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37408, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟はデジタルに絵をかいて、友だちに見せています。", "corrected_sentence": "弟はデジタルで絵をかいて、友だちに見せています。", "error_description": "デジタルの機器を使って絵をかくと言うときは「で」を使う。「に」では手段の説明にならないので、「で」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37408, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みに、デジタルを音楽を作る講座に行きました。", "corrected_sentence": "夏休みに、デジタルの音楽を作る講座に行きました。", "error_description": "「デジタルの音楽」のように、デジタルが音楽を修飾する形で使う。「を」を付けると形が合わないので、「の」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37409, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "アナログ", "is_correct": true, "explanation": "情報を連続的な量で表す方式を指し、デジタルの対義語。正解。"}, {"text": "紙", "is_correct": false, "explanation": "書く材料のこと。デジタルの対義語にはならない。"}, {"text": "手紙", "is_correct": false, "explanation": "文章を送る手段の一つ。方式を表す語ではないので対義語にならない。"}, {"text": "印刷", "is_correct": false, "explanation": "紙に文字や絵を写すこと。デジタルの対義語とは言えない。"}], "correct_answer": "アナログ", "explanations": {"アナログ": "情報を連続的な量で表す方式を指し、デジタルの対義語。正解。", "紙": "書く材料のこと。デジタルの対義語にはならない。", "手紙": "文章を送る手段の一つ。方式を表す語ではないので対義語にならない。", "印刷": "紙に文字や絵を写すこと。デジタルの対義語とは言えない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
