INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37409, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「デジタル」は、情報を0と1の組み合わせで表し、コンピューターで扱う方式のことです。アナログと対比される概念で、正確に複製や保存ができる特徴があります。", "primary_collocate": null, "pronunciation": "でじたる", "ipa": "deʑitaɾɯ", "syllable_count": 4, "sentences": [{"text": "しかし現代ファッションの文脈では、この伝統的な職人技はデジタルデザインという新たなパラダイムと衝突し、あるいは融合しつつある。", "target_word": "デジタル", "complexity_tier": "T5", "furigana": "しかし現代[げんだい]ファッションの文脈[ぶんみゃく]では、この伝統的[でんとうてき]な職人技[しょくにんわざ]はデジタルデザインという新[あら]たなパラダイムと衝突[しょうとつ]し、あるいは融合[ゆうごう]しつつある。", "sentence_source": "mined"}, {"text": "仮想空間上で構築される3Dモデリングやアルゴリズムによる生成物は、かつての「仕立て屋」の矜持をどう書き換えているのか。そこには、アナログな温もりとデジタルな正確さの間の絶え間ない緊張関係が見て取れ、それは創造性の本質を問うている。", "target_word": "デジタル", "complexity_tier": "T5", "furigana": "仮想[かそう]空間[くうかん]上[じょう]で構築[こうちく]される3Dモデリングやアルゴリズムによる生成物[せいせいぶつ]は、かつての「仕立[した]て屋[や]」の矜持[きょうじ]をどう書[か]き換[か]えているのか。そこには、アナログな温[ぬく]もりとデジタルな正確[せいかく]さの間[あいだ]の絶[た]え間[ま]ない緊張[きんちょう]関係[かんけい]が見[み]て取[と]れ、それは創造性[そうぞうせい]の本質[ほんしつ]を問[と]うている。", "sentence_source": "generated"}, {"text": "デジタルのデータは、何度コピーしても品質が落ちない。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "デジタルのデータは、何度[なんど]コピーしても品質[ひんしつ]が落[お]ちない。", "sentence_source": "generated"}, {"text": "このレコードはアナログだが、新しいCDはデジタルで録音されている。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "このレコードはアナログだが、新[あたら]しいCDはデジタルで録音[ろくおん]されている。", "sentence_source": "generated"}, {"text": "デジタルの時計は数字で時刻を示し、アナログの時計は針で示す。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "デジタルの時計[とけい]は数字[すうじ]で時刻[じこく]を示[しめ]し、アナログの時計[とけい]は針[はり]で示[しめ]す。", "sentence_source": "generated"}, {"text": "音をデジタルに変換すると、細かい雑音を取り除きやすくなる。", "target_word": "デジタル", "complexity_tier": "T4", "furigana": "音[おと]をデジタルに変換[へんかん]すると、細[こま]かい雑音[ざつおん]を取[と]り除[のぞ]きやすくなる。", "sentence_source": "generated"}, {"text": "写真をデジタルで保存しておけば、場所を取らずに済む。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "写真[しゃしん]をデジタルで保存[ほぞん]しておけば、場所[ばしょ]を取[と]らずに済[す]む。", "sentence_source": "generated"}, {"text": "アナログの信号は連続的に変化するが、デジタルは0と1の組み合わせで表される。", "target_word": "デジタル", "complexity_tier": "T4", "furigana": "アナログの信号[しんごう]は連続的[れんぞくてき]に変化[へんか]するが、デジタルは0と1の組[く]み合[あ]わせで表[あらわ]される。", "sentence_source": "generated"}, {"text": "古い映画をデジタルで復元する作業には、何年もかかった。", "target_word": "デジタル", "complexity_tier": "T3", "furigana": "古[ふる]い映画[えいが]をデジタルで復元[ふくげん]する作業[さぎょう]には、何年[なんねん]もかかった。", "sentence_source": "generated"}, {"text": "デジタルの情報は、劣化しにくいという利点がある。", "target_word": "デジタル", "complexity_tier": "T4", "furigana": "デジタルの情報[じょうほう]は、劣化[れっか]しにくいという利点[りてん]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "デジタル", "label": "基本形"}], "register": "中立（書き言葉・常体）", "sense_fingerprint": "情報を0と1で表す方式で、アナログと対になる概念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 見て取れ (Zipf 2.23)']::text[], '95d3b987-f670-4e84-a902-8e7233637a42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37409, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "デジタル", "is_correct": true, "explanation": "情報を0と1で表す方式を指す。「デジタルデザイン」の形で文脈に合う。正解。"}, {"text": "天然", "is_correct": false, "explanation": "人の手が加わっていないこと。「天然デザイン」は方式を表す語として合わない。"}, {"text": "中世", "is_correct": false, "explanation": "歴史上の時代を指す。「中世デザイン」では新しい方式の話とつながらない。"}, {"text": "飲料", "is_correct": false, "explanation": "飲み物のこと。デザインの方式を表す語として文脈に合わない。"}], "explanations": {"デジタル": "情報を0と1で表す方式を指す。「デジタルデザイン」の形で文脈に合う。正解。", "天然": "人の手が加わっていないこと。「天然デザイン」は方式を表す語として合わない。", "中世": "歴史上の時代を指す。「中世デザイン」では新しい方式の話とつながらない。", "飲料": "飲み物のこと。デザインの方式を表す語として文脈に合わない。"}, "sentence_index": 0, "correct_answer": "デジタル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その件は、デジタルに傷つきやすい。", "explanation": "ここは〈繊細〉の意味。デジタルは情報の方式を指す語で、傷つきやすさは表さないので合わない。"}, {"text": "この子はデジタルな笑顔で、すぐ心を開いてくれた。", "explanation": "ここは〈温かい〉の意味。デジタルは方式を表す語で、笑顔の雰囲気は表さないので合わない。"}, {"text": "母は朝、デジタルを炊いてご飯を用意した。", "explanation": "ここは〈米〉の意味。デジタルは情報の方式を指す語で、炊く対象にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37409, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "デジタル", "is_correct": true, "explanation": "情報を0と1で表し、正確に保存できる方式を指す。「デジタルで保存」の形で文に合う。正解。"}, {"text": "木製", "is_correct": false, "explanation": "木でできていること。「写真を木製で保存」は方法として成り立たない。"}, {"text": "発光", "is_correct": false, "explanation": "光を放つこと。写真の保存方法の説明としては合わない。"}, {"text": "寒冷", "is_correct": false, "explanation": "気温が低いこと。写真を保存する方法としては文に合わない。"}], "explanations": {"デジタル": "情報を0と1で表し、正確に保存できる方式を指す。「デジタルで保存」の形で文に合う。正解。", "木製": "木でできていること。「写真を木製で保存」は方法として成り立たない。", "発光": "光を放つこと。写真の保存方法の説明としては合わない。", "寒冷": "気温が低いこと。写真を保存する方法としては文に合わない。"}, "sentence_index": 6, "correct_answer": "デジタル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この布団はデジタルで、ふわふわして暖かい。", "explanation": "ここは〈ふかふか〉の意味。デジタルは方式を表す語で、布団の柔らかさは表さないので合わない。"}, {"text": "このケーキはデジタルで、とてもおいしい。", "explanation": "ここは〈美味〉の意味。デジタルは情報の方式を指す語で、味の良さは表さないので合わない。"}, {"text": "この靴はデジタルで、長く履ける。", "explanation": "ここは〈頑丈〉の意味。デジタルは方式を表す語で、靴の丈夫さは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37409, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ファイルをデジタルを保存すれば、場所を取らずに済む。", "corrected_sentence": "ファイルをデジタルで保存すれば、場所を取らずに済む。", "error_description": "「デジタルで保存する」と言うときは「で」を使う。「を」が二つ入り、デジタルが保存の対象になって文が成り立たないので、「で」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37409, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "写真をデジタルへ保存すれば、場所を取らずに済む。", "corrected_sentence": "写真をデジタルで保存すれば、場所を取らずに済む。", "error_description": "デジタルの方式で保存すると言うときは「で」を使う。「へ」は方向を表すので、「で」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d6d98c9-41ee-45f3-a318-58e42f1f84d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
