INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37410, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "その くにで うまれて そだった ひと。", "primary_collocate": null, "pronunciation": "ねーてぃぶ", "ipa": "neːtibu", "syllable_count": 4, "sentences": [{"text": "私はこの国のネーティブで、家族は代々ここに住んでいる。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "私[わたし]はこの国[くに]のネーティブで、家族[かぞく]は代々[だいだい]ここに住[す]んでいる。", "sentence_source": "generated"}, {"text": "彼は東京のネーティブだから、下町の歴史に詳しい。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "彼[かれ]は東京[とうきょう]のネーティブだから、下町[したまち]の歴史[れきし]に詳[くわ]しい。", "sentence_source": "generated"}, {"text": "その島のネーティブは、毎年夏に古い祭りを開く。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "その島[しま]のネーティブは、毎年[まいとし]夏[なつ]に古[ふる]い祭[まつ]りを開[ひら]く。", "sentence_source": "generated"}, {"text": "ネーティブの友達に、地元のおいしい店を教えてもらった。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "ネーティブの友達[ともだち]に、地元[じもと]のおいしい店[みせ]を教[おし]えてもらった。", "sentence_source": "generated"}, {"text": "外国から来た人より、ネーティブのほうがこの町の天気に慣れている。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "外国[がいこく]から来[き]た人[ひと]より、ネーティブのほうがこの町[まち]の天気[てんき]に慣[な]れている。", "sentence_source": "generated"}, {"text": "彼女は三代続くこの村のネーティブだ。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は三代[さんだい]続[つづ]くこの村[むら]のネーティブだ。", "sentence_source": "generated"}, {"text": "ネーティブでなくても、長く住めばこの土地が好きになる。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "ネーティブでなくても、長[なが]く住[す]めばこの土地[とち]が好[す]きになる。", "sentence_source": "generated"}, {"text": "この国のネーティブとして、私は祖父の話を子どもに伝えたい。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "この国[くに]のネーティブとして、私[わたし]は祖父[そふ]の話[はなし]を子[こ]どもに伝[つた]えたい。", "sentence_source": "generated"}, {"text": "観光客ではなく、ネーティブに道を聞いたほうが早い。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]ではなく、ネーティブに道[みち]を聞[き]いたほうが早[はや]い。", "sentence_source": "generated"}, {"text": "ネーティブの案内で、山の中の小さな神社まで歩いた。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "ネーティブの案内[あんない]で、山[やま]の中[なか]の小[ちい]さな神社[じんじゃ]まで歩[ある]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ネーティブ", "label": "基本形"}, {"form": "ネーティブの", "label": "連体形"}], "register": "標準", "sense_fingerprint": "その国や土地で生まれ育った人（地元生まれの人）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddfe4a92-bcbf-4b7c-b2a1-9385eb43d549') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37410, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電車", "is_correct": false, "explanation": "「この国の電車で、家族は代々ここに住んでいる」は意味が通らず、空欄に入らない。"}, {"text": "ネーティブ", "is_correct": true, "explanation": "「この国のネーティブで、家族は代々ここに住んでいる」は、その土地で生まれ育った意味になり文脈に合う。"}, {"text": "留学生", "is_correct": false, "explanation": "「この国の留学生で、家族は代々ここに住んでいる」は、一時的な滞在と代々の居住が矛盾する。"}, {"text": "旅行者", "is_correct": false, "explanation": "「この国の旅行者で、家族は代々ここに住んでいる」は、旅行者と代々の居住が矛盾する。"}], "explanations": {"電車": "「この国の電車で、家族は代々ここに住んでいる」は意味が通らず、空欄に入らない。", "ネーティブ": "「この国のネーティブで、家族は代々ここに住んでいる」は、その土地で生まれ育った意味になり文脈に合う。", "留学生": "「この国の留学生で、家族は代々ここに住んでいる」は、一時的な滞在と代々の居住が矛盾する。", "旅行者": "「この国の旅行者で、家族は代々ここに住んでいる」は、旅行者と代々の居住が矛盾する。"}, "sentence_index": 0, "correct_answer": "ネーティブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ネーティブとして、去年この町に引っ越してきた。", "explanation": "ここは〈移住者〉の意味。後から町に来た人は生まれ育った人ではないので、「ネーティブとして」と矛盾する。"}, {"text": "ネーティブとして、帰化の申請書を出した。", "explanation": "ここは〈帰化〉の意味。帰化は外国籍の人が日本国籍を得る手続きなので、生まれ育った人には合わない。"}, {"text": "彼はネーティブとして、この国で新しい生活を始めた。", "explanation": "ここは〈移民〉の意味。後から国に来た人の立場を表す「移民として」を、生まれ育った人を指す語に置き換えると矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37410, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨", "is_correct": false, "explanation": "「雨でなくても、長く住めば」は意味が通らず、空欄に入らない。"}, {"text": "教科書", "is_correct": false, "explanation": "「教科書でなくても、長く住めば」は意味が通らず、空欄に入らない。"}, {"text": "ネーティブ", "is_correct": true, "explanation": "「ネーティブでなくても、長く住めばこの土地が好きになる」は、生まれ育った人でなくても、という意味になり文脈に合う。"}, {"text": "週末", "is_correct": false, "explanation": "「週末でなくても、長く住めば」は意味が通らず、空欄に入らない。"}], "explanations": {"雨": "「雨でなくても、長く住めば」は意味が通らず、空欄に入らない。", "教科書": "「教科書でなくても、長く住めば」は意味が通らず、空欄に入らない。", "ネーティブ": "「ネーティブでなくても、長く住めばこの土地が好きになる」は、生まれ育った人でなくても、という意味になり文脈に合う。", "週末": "「週末でなくても、長く住めば」は意味が通らず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "ネーティブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ネーティブとして初めてこの町を訪れた。", "explanation": "ここは〈観光客〉の意味。「観光客として訪れた」の「観光客」を生まれ育った人を指す語に置き換えると、訪問者の立場と矛盾する。"}, {"text": "ネーティブとして、この島へ初めての旅行をした。", "explanation": "ここは〈旅行者〉の意味。旅行者は別の土地から来る人なので、生まれ育った人を指す「ネーティブ」とは合わない。"}, {"text": "おばあちゃんは昔ながらのネーティブを話す。", "explanation": "ここは〈方言〉の意味。「方言を話す」の「方言」を置き換えると、地域の言葉を指せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37410, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女はこの村のネーティブに、祖父母の代から暮らしている。", "corrected_sentence": "彼女はこの村のネーティブで、祖父母の代から暮らしている。", "error_description": "「ネーティブで」は身分・資格を示す「で」が正しい。「ネーティブに」では文が続かず誤りになる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37410, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "東京のネーティブを、下町の歴史に詳しい。", "corrected_sentence": "東京のネーティブは、下町の歴史に詳しい。", "error_description": "「東京のネーティブは」の「は」が正しい。「を」では「詳しい」の主語にならず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37411, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ネーティブの先生」の「の」で、ネーティブを先生の修飾に結びつける。"}, {"text": "に", "is_correct": false, "explanation": "「ネーティブに先生と会話の練習をしている」は、相手を示す形として文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「ネーティブを先生と」では目的語が不自然で、「練習をしている」と続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」だが、「ネーティブへ先生と」では文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「ネーティブの先生」の「の」で、ネーティブを先生の修飾に結びつける。", "に": "「ネーティブに先生と会話の練習をしている」は、相手を示す形として文が成り立たない。", "を": "「ネーティブを先生と」では目的語が不自然で、「練習をしている」と続かない。", "へ": "方向の「へ」だが、「ネーティブへ先生と」では文が成り立たない。"}, "error_tags": {"に": "相手", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37411, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37411, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "その言語を母語として話す人。", "primary_collocate": null, "pronunciation": "ねーてぃぶ", "ipa": "neːtibu", "syllable_count": 4, "sentences": [{"text": "彼女は英語のネーティブなので、発音がとてもきれいだ。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は英語[えいご]のネーティブなので、発音[はつおん]がとてもきれいだ。", "sentence_source": "generated"}, {"text": "ネーティブの先生と毎週会話の練習をしている。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "ネーティブの先生[せんせい]と毎週[まいしゅう]会話[かいわ]の練習[れんしゅう]をしている。", "sentence_source": "generated"}, {"text": "日本語のネーティブでも、敬語を間違えることがある。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "日本語[にほんご]のネーティブでも、敬語[けいご]を間違[まちが]えることがある。", "sentence_source": "generated"}, {"text": "ネーティブのように話すのは、とてもむずかしい。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "ネーティブのように話[はな]すのは、とてもむずかしい。", "sentence_source": "generated"}, {"text": "この店の店員はスペイン語のネーティブだから、注文も安心だ。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "この店[みせ]の店員[てんいん]はスペイン語[ご]のネーティブだから、注文[ちゅうもん]も安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "私はネーティブではないが、五年間日本語を勉強している。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "私[わたし]はネーティブではないが、五年間[ごねんかん]日本語[にほんご]を勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "ネーティブに文章を直してもらって、レポートがよくなった。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "ネーティブに文章[ぶんしょう]を直[なお]してもらって、レポートがよくなった。", "sentence_source": "generated"}, {"text": "彼はフランス語のネーティブで、通訳の仕事をしている。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "彼[かれ]はフランス語[ご]のネーティブで、通訳[つうやく]の仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "ネーティブが使う自然な言い方を、ドラマで覚えた。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "ネーティブが使[つか]う自然[しぜん]な言[い]い方[かた]を、ドラマで覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "子どものころ英語圏で育ったので、英語のネーティブ並みに話せる。", "target_word": "ネーティブ", "complexity_tier": "T3", "furigana": "子[こ]どものころ英語圏[えいごけん]で育[そだ]ったので、英語[えいご]のネーティブ並[な]みに話[はな]せる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ネーティブ", "label": "基本形"}, {"form": "ネーティブの", "label": "連体形"}], "register": "標準", "sense_fingerprint": "ある言語を母語として話す人（母語話者）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddfe4a92-bcbf-4b7c-b2a1-9385eb43d549') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37411, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨", "is_correct": false, "explanation": "「英語の雨なので、発音がとてもきれいだ」は意味が通らず、空欄に入らない。"}, {"text": "電車", "is_correct": false, "explanation": "「英語の電車なので、発音がとてもきれいだ」は意味が通らず、空欄に入らない。"}, {"text": "ネーティブ", "is_correct": true, "explanation": "「英語のネーティブなので、発音がとてもきれいだ」は、英語を母語とする人という意味になり文脈に合う。"}, {"text": "台風", "is_correct": false, "explanation": "「英語の台風なので、発音がとてもきれいだ」は意味が通らず、空欄に入らない。"}], "explanations": {"雨": "「英語の雨なので、発音がとてもきれいだ」は意味が通らず、空欄に入らない。", "電車": "「英語の電車なので、発音がとてもきれいだ」は意味が通らず、空欄に入らない。", "ネーティブ": "「英語のネーティブなので、発音がとてもきれいだ」は、英語を母語とする人という意味になり文脈に合う。", "台風": "「英語の台風なので、発音がとてもきれいだ」は意味が通らず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "ネーティブ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ネーティブとして、三年間この国の大学に留学した。", "explanation": "ここは〈留学生〉の意味。留学は外国で学ぶことなので、この国で生まれ育った人には合わない。"}, {"text": "私のネーティブは中国語だが、日本語もよく話せる。", "explanation": "ここは〈母語〉の意味。「母語は中国語」の「母語」を置き換えると、言語を表す語ではなくなり意味が通らない。"}, {"text": "彼はネーティブを務めて、会議の内容を正確に伝えた。", "explanation": "ここは〈通訳〉の意味。「通訳を務める」の「通訳」をネーティブに置き換えると、役割を表せず不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37411, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗濯機", "is_correct": false, "explanation": "「洗濯機に文章を直してもらって」は意味が通らず、空欄に入らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "「冷蔵庫に文章を直してもらって」は意味が通らず、空欄に入らない。"}, {"text": "ネーティブ", "is_correct": true, "explanation": "「ネーティブに文章を直してもらって、レポートがよくなった」は、その言語の話し手に直してもらう意味になり文脈に合う。"}, {"text": "信号", "is_correct": false, "explanation": "「信号に文章を直してもらって」は意味が通らず、空欄に入らない。"}], "explanations": {"洗濯機": "「洗濯機に文章を直してもらって」は意味が通らず、空欄に入らない。", "冷蔵庫": "「冷蔵庫に文章を直してもらって」は意味が通らず、空欄に入らない。", "ネーティブ": "「ネーティブに文章を直してもらって、レポートがよくなった」は、その言語の話し手に直してもらう意味になり文脈に合う。", "信号": "「信号に文章を直してもらって」は意味が通らず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "ネーティブ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その地方のネーティブを話せる人は少ない。", "explanation": "ここは〈方言〉の意味。「方言を話せる」の「方言」を置き換えると、地域の言葉を指す意味にならない。"}, {"text": "ネーティブを学ぶことで視野が広がる。", "explanation": "ここは〈外国語〉の意味。「外国語を学ぶ」の「外国語」を置き換えると、人を学ぶことになり不自然。"}, {"text": "ネーティブで書かれた本を読む。", "explanation": "ここは〈母国語〉の意味。「母国語で書かれた本」の「母国語」を置き換えると、言語を表す語ではなくなる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37411, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は英語のネーティブに、発音がとてもきれいだ。", "corrected_sentence": "彼女は英語のネーティブで、発音がとてもきれいだ。", "error_description": "「英語のネーティブで」は身分・資格を示す「で」が正しい。「ネーティブに」では文が続かず誤りになる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37411, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女はドイツ語のネーティブを、通訳の仕事をしている。", "corrected_sentence": "彼女はドイツ語のネーティブで、通訳の仕事をしている。", "error_description": "「ドイツ語のネーティブで」は身分・資格を示す「で」が正しい。「を」では「通訳の仕事をしている」と続かず誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37412, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の『の』。『世代』と『友達』をつなぎ、『同じ世代の友達』という名詞句をつくる。"}, {"text": "より", "is_correct": false, "explanation": "比較の『より』には比べる対象が必要で、『同じ世代より友達と話すと』では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』は動作の向かう先を表すが、ここには『世代へ』を向かう先とする動詞がない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』では『世代を友達と』と続いても『話す』の相手が示せず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の『の』。『世代』と『友達』をつなぎ、『同じ世代の友達』という名詞句をつくる。", "より": "比較の『より』には比べる対象が必要で、『同じ世代より友達と話すと』では意味が通らない。", "へ": "方向の『へ』は動作の向かう先を表すが、ここには『世代へ』を向かう先とする動詞がない。", "を": "目的語の『を』では『世代を友達と』と続いても『話す』の相手が示せず、文が成り立たない。"}, "error_tags": {"より": "比較", "へ": "方向", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37412, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語の『を』。『世代を問わず』で『世代に関係なく』という意味になる。"}, {"text": "が", "is_correct": false, "explanation": "主格の『が』だと『世代が問わず』となり、『問わず』と結びつかない。"}, {"text": "の", "is_correct": false, "explanation": "連体の『の』では『世代の問わず』となり、『問わず』の対象を取れず文が壊れる。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の『で』では『世代で問わず』となり、『問う』の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "目的語の『を』。『世代を問わず』で『世代に関係なく』という意味になる。", "が": "主格の『が』だと『世代が問わず』となり、『問わず』と結びつかない。", "の": "連体の『の』では『世代の問わず』となり、『問わず』の対象を取れず文が壊れる。", "で": "手段・場所の『で』では『世代で問わず』となり、『問う』の目的語にならない。"}, "error_tags": {"が": "主格", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37412, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "同じくらいの年の人たちのグループのこと。", "primary_collocate": null, "pronunciation": "せだい", "ipa": "sedai", "syllable_count": 3, "sentences": [{"text": "私たちの世代は、子どものころ携帯電話がなかった。", "target_word": "世代", "complexity_tier": "T3", "furigana": "私[わたし]たちの世代[せだい]は、子[こ]どものころ携帯電話[けいたいでんわ]がなかった。", "sentence_source": "generated"}, {"text": "同じ世代の友達と話すと、昔の流行で盛り上がる。", "target_word": "世代", "complexity_tier": "T3", "furigana": "同[おな]じ世代[せだい]の友達[ともだち]と話[はな]すと、昔[むかし]の流行[りゅうこう]で盛[も]り上[あ]がる。", "sentence_source": "generated"}, {"text": "若い世代は、新聞よりスマートフォンでニュースを読む。", "target_word": "世代", "complexity_tier": "T3", "furigana": "若[わか]い世代[せだい]は、新聞[しんぶん]よりスマートフォンでニュースを読[よ]む。", "sentence_source": "generated"}, {"text": "世代がちがうと、好きな音楽もずいぶん変わる。", "target_word": "世代", "complexity_tier": "T3", "furigana": "世代[せだい]がちがうと、好[す]きな音楽[おんがく]もずいぶん変[か]わる。", "sentence_source": "generated"}, {"text": "この映画は、父の世代にとても人気があった。", "target_word": "世代", "complexity_tier": "T3", "furigana": "この映画[えいが]は、父[ちち]の世代[せだい]にとても人気[にんき]があった。", "sentence_source": "generated"}, {"text": "この雑誌は、同じ世代の読者が多い。", "target_word": "世代", "complexity_tier": "T3", "furigana": "この雑誌[ざっし]は、同[おな]じ世代[せだい]の読者[どくしゃ]が多[おお]い。", "sentence_source": "generated"}, {"text": "祖父の世代は、戦争の話をあまりしたがらない。", "target_word": "世代", "complexity_tier": "T3", "furigana": "祖父[そふ]の世代[せだい]は、戦争[せんそう]の話[はなし]をあまりしたがらない。", "sentence_source": "generated"}, {"text": "世代を問わず、このゲームは多くの人に人気がある。", "target_word": "世代", "complexity_tier": "T3", "furigana": "世代[せだい]を問わず、このゲームは多くの人に人気がある。", "sentence_source": "generated"}, {"text": "同じ世代の選手が、次々に大会で活躍している。", "target_word": "世代", "complexity_tier": "T3", "furigana": "同[おな]じ世代[せだい]の選手[せんしゅ]が、次々[つぎつぎ]に大会[たいかい]で活躍[かつやく]している。", "sentence_source": "generated"}, {"text": "会社では、世代の近い人のほうが話しやすい。", "target_word": "世代", "complexity_tier": "T3", "furigana": "会社[かいしゃ]では、世代[せだい]の近[ちか]い人[ひと]のほうが話[はな]しやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "世代", "label": "基本形"}, {"form": "世代の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "同じくらいの年齢の人たちの集まり（年代層）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddfe4a92-bcbf-4b7c-b2a1-9385eb43d549') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37412, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世代", "is_correct": true, "explanation": "『同じくらいの年の人たちの集まり』を表す『世代』が入り、『私たちの世代』と自然につながる。"}, {"text": "電波", "is_correct": false, "explanation": "『私たちの電波は、子どものころ携帯電話がなかった』は主語として成り立たず、意味も通らない。"}, {"text": "技術", "is_correct": false, "explanation": "『私たちの技術は、子どものころ携帯電話がなかった』は意味が通らず、空欄に入らない。"}, {"text": "基地局", "is_correct": false, "explanation": "『私たちの基地局は』では主語にならず、携帯電話がなかった理由とも結びつかない。"}], "explanations": {"世代": "『同じくらいの年の人たちの集まり』を表す『世代』が入り、『私たちの世代』と自然につながる。", "電波": "『私たちの電波は、子どものころ携帯電話がなかった』は主語として成り立たず、意味も通らない。", "技術": "『私たちの技術は、子どものころ携帯電話がなかった』は意味が通らず、空欄に入らない。", "基地局": "『私たちの基地局は』では主語にならず、携帯電話がなかった理由とも結びつかない。"}, "sentence_index": 0, "correct_answer": "世代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病院で世代を聞かれ、三十歳だと答えた。", "explanation": "ここは〈年齢〉の意味。世代は同年代の人の集まりを指すので、本人が自分の年数を答える場面では合わない。"}, {"text": "江戸世代に建てられた寺が、今も多く残っている。", "explanation": "ここは〈時代〉の意味。世代は同じ年頃の人々を指すので、江戸のような時期の名前には使えない。"}, {"text": "本を出版の世代順に並べた。", "explanation": "ここは〈年代〉の意味（年代順＝時期の順）。世代は人の集まりなので、本の出版時期を並べる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37412, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世代", "is_correct": true, "explanation": "『祖父の世代』は同じ時代に生まれた人々の集まりを指し、文脈に合う。"}, {"text": "戦場", "is_correct": false, "explanation": "『祖父の戦場は』では主語にならず、『話をしたがらない』とも意味がつながらない。"}, {"text": "兵器", "is_correct": false, "explanation": "『祖父の兵器は』は人の話題を表せず、文の主語として成り立たない。"}, {"text": "食糧", "is_correct": false, "explanation": "『祖父の食糧は、戦争の話をしたがらない』は意味が通らず、空欄に入らない。"}], "explanations": {"世代": "『祖父の世代』は同じ時代に生まれた人々の集まりを指し、文脈に合う。", "戦場": "『祖父の戦場は』では主語にならず、『話をしたがらない』とも意味がつながらない。", "兵器": "『祖父の兵器は』は人の話題を表せず、文の主語として成り立たない。", "食糧": "『祖父の食糧は、戦争の話をしたがらない』は意味が通らず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "世代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花火を見るのに、よい世代は夏だ。", "explanation": "ここは〈時期〉の意味。世代は同年代の人々を指すので、花火を見るのに適した季節の話には合わない。"}, {"text": "ペンギンは世代で暮らす。", "explanation": "ここは〈集団〉の意味。世代は年齢の近い人々の集まりなので、動物の群れを指す場面では使わない。"}, {"text": "この町の世代は五万人だ。", "explanation": "ここは〈人口〉の意味。世代は人数を数える単位ではないので、町の総人数を表す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37412, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "若い世代を、古い映画をよく見る。", "corrected_sentence": "若い世代は、古い映画をよく見る。", "error_description": "『世代』は話題の主語になるので『は』を付ける。『を』は目的語を示すため、後ろの『映画を』と重なって文が壊れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37412, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "世代を問うず、このアプリは子どもから大人まで使える。", "corrected_sentence": "世代を問わず、このアプリは子どもから大人まで使える。", "error_description": "『問う』の打ち消しの形は『問わず』。『問うず』は活用の誤りで、『世代を問わず』（〜に関係なく）という定型が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37413, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "起点の『から』。『世代から世代へ』で、代から代へ受け継がれる流れを示す。"}, {"text": "の", "is_correct": false, "explanation": "連体の『の』では『世代の世代へ』となり、『伝わる』の起点を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の『で』では『世代で世代へ』となり、受け継ぎの起点にならない。"}, {"text": "に", "is_correct": false, "explanation": "位置・相手の『に』では『世代に世代へ』となり、起点の意味が成り立たない。"}], "correct_answer": "から", "explanations": {"から": "起点の『から』。『世代から世代へ』で、代から代へ受け継がれる流れを示す。", "の": "連体の『の』では『世代の世代へ』となり、『伝わる』の起点を示せない。", "で": "手段・場所の『で』では『世代で世代へ』となり、受け継ぎの起点にならない。", "に": "位置・相手の『に』では『世代に世代へ』となり、起点の意味が成り立たない。"}, "error_tags": {"の": "連体修飾", "で": "手段・場所", "に": "位置・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37413, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『世代に』は存在の対象を示し、『世代には共通の思い出がある』と続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語の『を』では『世代を共通の思い出がある』となり、存在の文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の『へ』では『世代へ思い出がある』となり、存在する対象として不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の『より』には比べる相手が必要で、『世代より思い出がある』は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "『世代に』は存在の対象を示し、『世代には共通の思い出がある』と続く。", "を": "目的語の『を』では『世代を共通の思い出がある』となり、存在の文として成り立たない。", "へ": "方向の『へ』では『世代へ思い出がある』となり、存在する対象として不自然。", "より": "比較の『より』には比べる相手が必要で、『世代より思い出がある』は意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37413, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "同じ時代に生まれ、同じような社会環境で育った人々の集まり。また、親から子へと続く血筋のつながり。", "primary_collocate": null, "pronunciation": "せだい", "ipa": "sedai", "syllable_count": 3, "sentences": [{"text": "戦後に生まれた世代は、豊かな社会で育った人が多い。", "target_word": "世代", "complexity_tier": "T3", "furigana": "戦後[せんご]に生[う]まれた世代[せだい]は、豊[ゆた]かな社会[しゃかい]で育[そだ]った人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "この家では、世代から世代へ伝わる味噌の作り方がある。", "target_word": "世代", "complexity_tier": "T3", "furigana": "この家[いえ]では、世代[せだい]から世代[せだい]へ伝[つた]わる味噌[みそ]の作[つく]り方[かた]がある。", "sentence_source": "generated"}, {"text": "家族の写真には、三つの世代がそろって写っている。", "target_word": "世代", "complexity_tier": "T3", "furigana": "家族[かぞく]の写真[しゃしん]には、三[みっ]つの世代[せだい]がそろって写[うつ]っている。", "sentence_source": "generated"}, {"text": "バブル時代に育った世代は、お金の使い方が派手だと言われる。", "target_word": "世代", "complexity_tier": "T3", "furigana": "バブル時代[じだい]に育[そだ]った世代[せだい]は、お金[かね]の使[つか]い方[かた]が派手[はで]だと言[い]われる。", "sentence_source": "generated"}, {"text": "世代を重ねるうちに、村の言葉も少しずつ変わっていった。", "target_word": "世代", "complexity_tier": "T3", "furigana": "世代[せだい]を重[かさ]ねるうちに、村[むら]の言葉[ことば]も少[すこ]しずつ変[か]わっていった。", "sentence_source": "generated"}, {"text": "インターネットが当たり前の環境で育った世代が、社会に出はじめた。", "target_word": "世代", "complexity_tier": "T3", "furigana": "インターネットが当[あ]たり前[まえ]の環境[かんきょう]で育[そだ]った世代[せだい]が、社会[しゃかい]に出[で]はじめた。", "sentence_source": "generated"}, {"text": "この木は、いくつもの世代の人々に守られてきた。", "target_word": "世代", "complexity_tier": "T3", "furigana": "この木[き]は、いくつもの世代[せだい]の人々[ひとびと]に守[まも]られてきた。", "sentence_source": "generated"}, {"text": "同じ時代を生きた世代には、共通の思い出がある。", "target_word": "世代", "complexity_tier": "T3", "furigana": "同[おな]じ時代[じだい]を生[い]きた世代[せだい]には、共通[きょうつう]の思[おも]い出[で]がある。", "sentence_source": "generated"}, {"text": "親の世代が築いた店を、子の世代が引きついだ。", "target_word": "世代", "complexity_tier": "T3", "furigana": "親[おや]の世代[せだい]が築[きず]いた店[みせ]を、子[こ]の世代[せだい]が引[ひ]きついだ。", "sentence_source": "generated"}, {"text": "次の世代のために、豊かな自然を残したい。", "target_word": "世代", "complexity_tier": "T3", "furigana": "次[つぎ]の世代[せだい]のために、豊[ゆた]かな自然[しぜん]を残[のこ]したい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "世代", "label": "基本形"}, {"form": "世代の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "同じ時代と環境で育った人々の層、または親から子へ続く代の区切り", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddfe4a92-bcbf-4b7c-b2a1-9385eb43d549') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37413, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世代", "is_correct": true, "explanation": "『戦後に生まれた世代』は同じ時代に生まれた人々の集まりを指し、文に合う。"}, {"text": "国境", "is_correct": false, "explanation": "『戦後に生まれた国境は』では主語として成り立たず、人の話にならない。"}, {"text": "憲法", "is_correct": false, "explanation": "『戦後に生まれた憲法は、豊かな社会で育った人が多い』は意味が通らない。"}, {"text": "税金", "is_correct": false, "explanation": "『戦後に生まれた税金は』では人が育つという文脈に合わない。"}], "explanations": {"世代": "『戦後に生まれた世代』は同じ時代に生まれた人々の集まりを指し、文に合う。", "国境": "『戦後に生まれた国境は』では主語として成り立たず、人の話にならない。", "憲法": "『戦後に生まれた憲法は、豊かな社会で育った人が多い』は意味が通らない。", "税金": "『戦後に生まれた税金は』では人が育つという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "世代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が多い世代は、洗濯物が乾きにくい。", "explanation": "ここは〈時期〉の意味。世代は人の集まりなので、雨の多い季節や時期を表す場面には合わない。"}, {"text": "この壺は、江戸の世代に作られたものだ。", "explanation": "ここは〈時代〉の意味。世代は同じ時代に生きた人々を指すので、物が作られた時期を表す場面には合わない。"}, {"text": "お店で世代を聞かれたので、二十歳だと答えた。", "explanation": "ここは〈年齢〉の意味。世代は同じ時代に生まれた人の集まりで、個人が答える年齢の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37413, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世代", "is_correct": true, "explanation": "『いくつもの世代の人々に守られてきた』は、代々の人々の集まりを指し、文に合う。"}, {"text": "苗木", "is_correct": false, "explanation": "『いくつもの苗木の人々』は意味が通らず、守られる主体として成り立たない。"}, {"text": "根", "is_correct": false, "explanation": "『いくつもの根の人々』では人を表せず、文の意味が壊れる。"}, {"text": "枝", "is_correct": false, "explanation": "『いくつもの枝の人々』は文脈に合わず、守られる対象の説明にならない。"}], "explanations": {"世代": "『いくつもの世代の人々に守られてきた』は、代々の人々の集まりを指し、文に合う。", "苗木": "『いくつもの苗木の人々』は意味が通らず、守られる主体として成り立たない。", "根": "『いくつもの根の人々』では人を表せず、文の意味が壊れる。", "枝": "『いくつもの枝の人々』は文脈に合わず、守られる対象の説明にならない。"}, "sentence_index": 6, "correct_answer": "世代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "アリは世代で巣を作る。", "explanation": "ここは〈集団〉の意味。世代は年齢や時代の近い人々の集まりなので、昆虫の群れが巣を作る場面では使わない。"}, {"text": "この国の世代は一億人を超える。", "explanation": "ここは〈人口〉の意味。世代は人数を数える単位ではないので、国の総人口を表す場面には合わない。"}, {"text": "この地層は、世代が一万年前にさかのぼる。", "explanation": "ここは〈年代〉の意味。世代は人の集まりや血筋を指すので、地層の古さを表す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37413, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母の世代を、この村を守ってきた。", "corrected_sentence": "祖母の世代が、この村を守ってきた。", "error_description": "主語の『世代』には『が』を付ける。『を』は目的語を示すため、『村を』と二つ並ぶと文が壊れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37413, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "世代を減らすうちに、村の祭りも形を変えてきた。", "corrected_sentence": "世代を重ねるうちに、村の祭りも形を変えてきた。", "error_description": "『世代を減らす』は不自然な組み合わせ。代が続いていく意味では『世代を重ねる』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
