INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37414, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "同じくらいの程度や価値があること。", "primary_collocate": null, "pronunciation": "どうとう", "ipa": "doːtoː", "syllable_count": 4, "sentences": [{"text": "この二つの資格は、同等の価値があると認められている。", "target_word": "同等", "complexity_tier": "T3", "furigana": "この二[ふた]つの資格[しかく]は、同等[どうとう]の価値[かち]があると認[みと]められている。", "sentence_source": "generated"}, {"text": "彼の実力は、プロの選手と同等だ。", "target_word": "同等", "complexity_tier": "T3", "furigana": "彼[かれ]の実力[じつりょく]は、プロの選手[せんしゅ]と同等[どうとう]だ。", "sentence_source": "generated"}, {"text": "大学卒業と同等の学力があれば、試験を受けられる。", "target_word": "同等", "complexity_tier": "T3", "furigana": "大学[だいがく]卒業[そつぎょう]と同等[どうとう]の学力[がくりょく]があれば、試験[しけん]を受[う]けられる。", "sentence_source": "generated"}, {"text": "新しい機械は、古いものと同等の性能で、値段は半分だ。", "target_word": "同等", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]は、古[ふる]いものと同等[どうとう]の性能[せいのう]で、値段[ねだん]は半分[はんぶん]だ。", "sentence_source": "generated"}, {"text": "社員もアルバイトも、同等に意見を言える会議にしたい。", "target_word": "同等", "complexity_tier": "T3", "furigana": "社員[しゃいん]もアルバイトも、同等[どうとう]に意見[いけん]を言[い]える会議[かいぎ]にしたい。", "sentence_source": "generated"}, {"text": "同等の条件なら、経験のある人を採用する。", "target_word": "同等", "complexity_tier": "T3", "furigana": "同等[どうとう]の条件[じょうけん]なら、経験[けいけん]のある人[ひと]を採用[さいよう]する。", "sentence_source": "generated"}, {"text": "兄と弟の成績は同等で、どちらも上位に入っている。", "target_word": "同等", "complexity_tier": "T3", "furigana": "兄[あに]と弟[おとうと]の成績[せいせき]は同等[どうとう]で、どちらも上位[じょうい]に入[はい]っている。", "sentence_source": "generated"}, {"text": "正社員と同等の待遇を、パートの人にも求めている。", "target_word": "同等", "complexity_tier": "T3", "furigana": "正社員[せいしゃいん]と同等[どうとう]の待遇[たいぐう]を、パートの人[ひと]にも求[もと]めている。", "sentence_source": "generated"}, {"text": "この国では、男女が同等に教育を受ける権利がある。", "target_word": "同等", "complexity_tier": "T3", "furigana": "この国[くに]では、男女[だんじょ]が同等[どうとう]に教育[きょういく]を受[う]ける権利[けんり]がある。", "sentence_source": "generated"}, {"text": "値段が同等なら、味のよいほうを選びたい。", "target_word": "同等", "complexity_tier": "T3", "furigana": "値段[ねだん]が同等[どうとう]なら、味[あじ]のよいほうを選[えら]びたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "同等だ", "label": "終止形"}, {"form": "同等の", "label": "連体形"}, {"form": "同等に", "label": "連用形"}, {"form": "同等で", "label": "連用形（で）"}], "register": "標準", "sense_fingerprint": "程度や価値が同じくらいであること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddfe4a92-bcbf-4b7c-b2a1-9385eb43d549') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37414, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同等", "is_correct": true, "explanation": "『同等の価値』は『同じくらいの価値』の意味になり、認められている内容に合う。"}, {"text": "必要", "is_correct": false, "explanation": "『必要の価値』は成り立たず、認められている内容とも合わない。"}, {"text": "無効", "is_correct": false, "explanation": "『無効の価値』は矛盾していて、資格が認められるという文脈に合わない。"}, {"text": "不要", "is_correct": false, "explanation": "『不要の価値』では資格が認められるという意味が成り立たない。"}], "explanations": {"同等": "『同等の価値』は『同じくらいの価値』の意味になり、認められている内容に合う。", "必要": "『必要の価値』は成り立たず、認められている内容とも合わない。", "無効": "『無効の価値』は矛盾していて、資格が認められるという文脈に合わない。", "不要": "『不要の価値』では資格が認められるという意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "同等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼も同等に、約束の時間に遅れて来た。", "explanation": "ここは〈同様〉（〜と同じように）の意味。同等は程度や価値が同じことを表すので、行動の『〜もまた』には合わない。"}, {"text": "彼と母親は同等の顔つきだ。", "explanation": "ここは〈似る〉の意味。同等は程度や価値を比べる語で、顔立ちの相似を表す場面には使わない。"}, {"text": "二人は同等の方向を向いて歩いた。", "explanation": "ここは〈同じ〉（向きが同じ）の意味。同等は程度や価値の比較なので、向きが一致する場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37414, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同等", "is_correct": true, "explanation": "『成績は同等で』は二人の成績が同じくらいであることを示し、文に合う。"}, {"text": "静か", "is_correct": false, "explanation": "『兄と弟の成績は静かで』は意味が通らず、成績の話にならない。"}, {"text": "寒冷", "is_correct": false, "explanation": "『兄と弟の成績は寒冷で』は成績の様子を表せず、文として成り立たない。"}, {"text": "無口", "is_correct": false, "explanation": "『兄と弟の成績は無口で』は成績の様子を表せず、文として成り立たない。"}], "explanations": {"同等": "『成績は同等で』は二人の成績が同じくらいであることを示し、文に合う。", "静か": "『兄と弟の成績は静かで』は意味が通らず、成績の話にならない。", "寒冷": "『兄と弟の成績は寒冷で』は成績の様子を表せず、文として成り立たない。", "無口": "『兄と弟の成績は無口で』は成績の様子を表せず、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "同等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この二軒の店は同等の名前を持っている。", "explanation": "ここは〈同名〉（同じ名前）の意味。同等は程度や価値の比較なので、名前が一致する場面には使わない。"}, {"text": "二人は同等の日に生まれた。", "explanation": "ここは〈同日〉の意味。同等は程度や価値の比較なので、生まれた日が同じことは表せない。"}, {"text": "二つの時計が同等の時刻を指している。", "explanation": "ここは〈同時刻〉（時刻がぴったり合う）の意味。同等は程度や価値の比較なので、時刻が一致する場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37414, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店の商品は、新品と同等する品質だ。", "corrected_sentence": "この店の商品は、新品と同等の品質だ。", "error_description": "『同等』は形状詞なので、『する』をつけて動詞にはできない。『新品と同等の品質』が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "同等だ", "is_correct": true, "explanation": "終止形。文末の『同等だ』に当たる形で、『プロの選手と同等だ』と言い切る。"}, {"text": "同等の", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、文末の述語には使えない。"}, {"text": "同等に", "is_correct": false, "explanation": "連用形。動詞を修飾する形で、ここでは述語にならない。"}, {"text": "同等で", "is_correct": false, "explanation": "連用形（で）。後ろに語が続く形で、ここでは文を終えられない。"}], "correct_form": "同等だ", "base_form": "同等", "form_label": "終止形", "sentence_index": 1, "explanations": {"同等だ": "終止形。文末の『同等だ』に当たる形で、『プロの選手と同等だ』と言い切る。", "同等の": "連体形。名詞を修飾する形で、文末の述語には使えない。", "同等に": "連用形。動詞を修飾する形で、ここでは述語にならない。", "同等で": "連用形（で）。後ろに語が続く形で、ここでは文を終えられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37414, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい店員は、ベテランと同等だ仕事を任される。", "corrected_sentence": "新しい店員は、ベテランと同等の仕事を任される。", "error_description": "『同等だ』は文末の形で、名詞『仕事』を直接修飾できない。『同等の仕事』が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "同等の", "is_correct": true, "explanation": "連体形。名詞『待遇』を修飾する形で、文中の『同等の』に当たる。"}, {"text": "同等だ", "is_correct": false, "explanation": "終止形。文末の述語には使えるが、名詞『待遇』を修飾できない。"}, {"text": "同等では", "is_correct": false, "explanation": "『では』が続き、名詞『待遇』を修飾できない。"}, {"text": "同等だと", "is_correct": false, "explanation": "条件の『と』が続き、名詞『待遇』にはつながらない。"}], "correct_form": "同等の", "base_form": "同等", "form_label": "連体形", "sentence_index": 7, "explanations": {"同等の": "連体形。名詞『待遇』を修飾する形で、文中の『同等の』に当たる。", "同等だ": "終止形。文末の述語には使えるが、名詞『待遇』を修飾できない。", "同等では": "『では』が続き、名詞『待遇』を修飾できない。", "同等だと": "条件の『と』が続き、名詞『待遇』にはつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
