INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37415, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "あるものと別のものが、程度や価値において同じであること。", "primary_collocate": null, "pronunciation": "どうとう", "ipa": "doːtoː", "syllable_count": 4, "sentences": [{"text": "この資格は、国家試験と同等のレベルだとされている。", "target_word": "同等", "complexity_tier": "T3", "furigana": "この資格[しかく]は、国家[こっか]試験[しけん]と同等[どうとう]のレベルだとされている。", "sentence_source": "generated"}, {"text": "彼女の英語力は、留学した人と同等だと言われる。", "target_word": "同等", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の英語力[えいごりょく]は、留学[りゅうがく]した人[ひと]と同等[どうとう]だと言[い]われる。", "sentence_source": "generated"}, {"text": "手作りでも、店の商品と同等の品質に仕上がった。", "target_word": "同等", "complexity_tier": "T3", "furigana": "手作[てづく]りでも、店[みせ]の商品[しょうひん]と同等[どうとう]の品質[ひんしつ]に仕上[しあ]がった。", "sentence_source": "generated"}, {"text": "二つのチームの力は同等で、試合は延長戦になった。", "target_word": "同等", "complexity_tier": "T3", "furigana": "二[ふた]つのチームの力[ちから]は同等[どうとう]で、試合[しあい]は延長戦[えんちょうせん]になった。", "sentence_source": "generated"}, {"text": "古い家だが、新築と同等の安全性がある。", "target_word": "同等", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]だが、新築[しんちく]と同等[どうとう]の安全性[あんぜんせい]がある。", "sentence_source": "generated"}, {"text": "経験が同等の人が二人いて、採用に迷っている。", "target_word": "同等", "complexity_tier": "T3", "furigana": "経験[けいけん]が同等[どうとう]の人[ひと]が二人[ふたり]いて、採用[さいよう]に迷[まよ]っている。", "sentence_source": "generated"}, {"text": "友達として、私たちは同等の立場で話し合う。", "target_word": "同等", "complexity_tier": "T3", "furigana": "友達[ともだち]として、私[わたし]たちは同等[どうとう]の立場[たちば]で話[はな]し合[あ]う。", "sentence_source": "generated"}, {"text": "費用が同等でも、こちらのほうが使いやすい。", "target_word": "同等", "complexity_tier": "T3", "furigana": "費用[ひよう]が同等[どうとう]でも、こちらのほうが使[つか]いやすい。", "sentence_source": "generated"}, {"text": "犬も家族の一員として、人間と同等に大切にされている。", "target_word": "同等", "complexity_tier": "T3", "furigana": "犬[いぬ]も家族[かぞく]の一員[いちいん]として、人間[にんげん]と同等[どうとう]に大切[たいせつ]にされている。", "sentence_source": "generated"}, {"text": "彼の作品は、有名な画家のものと同等に評価された。", "target_word": "同等", "complexity_tier": "T3", "furigana": "彼[かれ]の作品[さくひん]は、有名[ゆうめい]な画家[がか]のものと同等[どうとう]に評価[ひょうか]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "同等だ", "label": "終止形"}, {"form": "同等の", "label": "連体形"}, {"form": "同等に", "label": "連用形"}, {"form": "同等で", "label": "連用形（で）"}], "register": "標準", "sense_fingerprint": "二つのものを比べて、程度や価値が同じであること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddfe4a92-bcbf-4b7c-b2a1-9385eb43d549') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37415, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同等", "is_correct": true, "explanation": "『国家試験と同等のレベル』は国家試験と同じくらいの水準を表し、文に合う。"}, {"text": "静か", "is_correct": false, "explanation": "『国家試験と静かのレベル』は意味が通らず、水準の比較にならない。"}, {"text": "元気", "is_correct": false, "explanation": "『国家試験と元気のレベル』は成り立たず、資格の水準を表せない。"}, {"text": "大切", "is_correct": false, "explanation": "『国家試験と大切のレベル』は水準の比較として文が成り立たない。"}], "explanations": {"同等": "『国家試験と同等のレベル』は国家試験と同じくらいの水準を表し、文に合う。", "静か": "『国家試験と静かのレベル』は意味が通らず、水準の比較にならない。", "元気": "『国家試験と元気のレベル』は成り立たず、資格の水準を表せない。", "大切": "『国家試験と大切のレベル』は水準の比較として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "同等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人は同等に、チームを去った。", "explanation": "ここは〈同様〉（〜と同じように）の意味。同等は程度や価値が同じことで、行動の同時性は表せない。"}, {"text": "二本の傘は同等の色をしている。", "explanation": "ここは〈同色〉（色が同じ）の意味。同等は程度や価値の比較なので、色が一致する場面には使わない。"}, {"text": "彼は昨日、同等の夢を見た。", "explanation": "ここは〈同一〉（まったく同じ）の意味（同じ夢）。同等は程度や価値の比較なので、夢が一致する場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37415, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同等", "is_correct": true, "explanation": "『同等の立場で話し合う』は対等な立場を表し、文に合う。"}, {"text": "必要", "is_correct": false, "explanation": "『必要の立場で話し合う』は成り立たず、話し合いの立場を表せない。"}, {"text": "無効", "is_correct": false, "explanation": "『無効の立場で話し合う』は矛盾していて、話し合いの文脈に合わない。"}, {"text": "不要", "is_correct": false, "explanation": "『不要の立場で話し合う』は意味が通らず、立場を表す語として成り立たない。"}], "explanations": {"同等": "『同等の立場で話し合う』は対等な立場を表し、文に合う。", "必要": "『必要の立場で話し合う』は成り立たず、話し合いの立場を表せない。", "無効": "『無効の立場で話し合う』は矛盾していて、話し合いの文脈に合わない。", "不要": "『不要の立場で話し合う』は意味が通らず、立場を表す語として成り立たない。"}, "sentence_index": 6, "correct_answer": "同等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの二人は同等の名字を持っている。", "explanation": "ここは〈同名〉（同じ名字）の意味。同等は程度や価値の比較なので、名字が一致する場面には使わない。"}, {"text": "二つの行事は同等の日に行われた。", "explanation": "ここは〈同日〉（同じ日）の意味。同等は程度や価値の比較なので、日付が同じことには使わない。"}, {"text": "二つの花は同等の季節に咲く。", "explanation": "ここは〈同時期〉（同じ季節）の意味。同等は程度や価値の比較なので、時期が同じことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37415, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この資格は、国家試験と同等だ難しさだと言われる。", "corrected_sentence": "この資格は、国家試験と同等の難しさだと言われる。", "error_description": "『同等だ』は文末の形で、名詞『難しさ』を直接修飾できない。『同等の難しさ』が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "同等だ", "is_correct": true, "explanation": "終止形。『同等だと言われる』の『同等だ』に当たる形で、『〜と』の前に続く。"}, {"text": "同等の", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、文末の『言われる』の前には入らない。"}, {"text": "同等に", "is_correct": false, "explanation": "連用形。動詞を修飾する形で、『〜だと』の述語にはならない。"}, {"text": "同等で", "is_correct": false, "explanation": "連用形（で）。後ろに語が続く形で、ここでは『と言われる』に続かない。"}], "correct_form": "同等だ", "base_form": "同等", "form_label": "終止形", "sentence_index": 1, "explanations": {"同等だ": "終止形。『同等だと言われる』の『同等だ』に当たる形で、『〜と』の前に続く。", "同等の": "連体形。名詞を修飾する形で、文末の『言われる』の前には入らない。", "同等に": "連用形。動詞を修飾する形で、『〜だと』の述語にはならない。", "同等で": "連用形（で）。後ろに語が続く形で、ここでは『と言われる』に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37415, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人は同等に立場で話し合う。", "corrected_sentence": "二人は同等の立場で話し合う。", "error_description": "『同等』は名詞を修飾するときは『の』になる。『同等に』は副詞の形なので、後ろの名詞『立場』にはつながらない。『同等の立場で』が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "同等で", "is_correct": true, "explanation": "連用形（で）。『費用が同等でも』の『同等で』に当たる形で、『〜でも』に続く。"}, {"text": "同等だ", "is_correct": false, "explanation": "終止形。文末の述語には使えるが、『費用が〜でも』の形には合わない。"}, {"text": "同等である", "is_correct": false, "explanation": "終止形の丁寧な言い方で、『〜でも』の前には続かない。"}, {"text": "同等だった", "is_correct": false, "explanation": "過去の終止形で、『費用が〜でも』の条件の形にはならない。"}], "correct_form": "同等で", "base_form": "同等", "form_label": "連用形（で）", "sentence_index": 7, "explanations": {"同等で": "連用形（で）。『費用が同等でも』の『同等で』に当たる形で、『〜でも』に続く。", "同等だ": "終止形。文末の述語には使えるが、『費用が〜でも』の形には合わない。", "同等である": "終止形の丁寧な言い方で、『〜でも』の前には続かない。", "同等だった": "過去の終止形で、『費用が〜でも』の条件の形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec82dd97-75f2-4f8e-b0d6-006980aa9b43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37416, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「予想以上に」は、予想を上回る程度を表す副詞的な「に」。正解。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「予想以上が」では文の骨組みが崩れる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」。「予想以上を」では修飾関係が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "引用・並列の「と」。「予想以上と」は文として不自然。"}], "correct_answer": "に", "explanations": {"に": "「予想以上に」は、予想を上回る程度を表す副詞的な「に」。正解。", "が": "主語を示す「が」。「予想以上が」では文の骨組みが崩れる。", "を": "目的語を示す「を」。「予想以上を」では修飾関係が成り立たない。", "と": "引用・並列の「と」。「予想以上と」は文として不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "引用"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以下", "is_correct": true, "explanation": "「以上」の対義語として辞書に載る語。ある数量と同じか、それより少ないことを表す。"}, {"text": "以前", "is_correct": false, "explanation": "時間的に前であることを表す語。数量の上下の対義語ではない。"}, {"text": "以来", "is_correct": false, "explanation": "ある時から今まで続くことを表す語。数量の対義にはならない。"}, {"text": "途中", "is_correct": false, "explanation": "物事の経過の中間を表す語。数量の対義にはならない。"}], "correct_answer": "以下", "explanations": {"以下": "「以上」の対義語として辞書に載る語。ある数量と同じか、それより少ないことを表す。", "以前": "時間的に前であることを表す語。数量の上下の対義語ではない。", "以来": "ある時から今まで続くことを表す語。数量の対義にはならない。", "途中": "物事の経過の中間を表す語。数量の対義にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37416, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「十八歳以上の人」の「の」で、以上が後ろの名詞を修飾する形。正解。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の「で」。「十八歳以上で人は」では名詞の修飾関係が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」。「十八歳以上から人は」では文として不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。比べる相手がないので、この文には合わない。"}], "correct_answer": "の", "explanations": {"の": "「十八歳以上の人」の「の」で、以上が後ろの名詞を修飾する形。正解。", "で": "場所・手段の「で」。「十八歳以上で人は」では名詞の修飾関係が成り立たない。", "から": "起点の「から」。「十八歳以上から人は」では文として不自然。", "より": "比較の「より」。比べる相手がないので、この文には合わない。"}, "error_tags": {"で": "手段", "から": "起点", "より": "比較"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以下", "is_correct": true, "explanation": "「以上」の対義語として辞書に載る語。ある数量と同じか、それより少ないことを表す。"}, {"text": "外側", "is_correct": false, "explanation": "物の外の方を表す語。数量の対義にはならない。"}, {"text": "中心", "is_correct": false, "explanation": "物事の真ん中を表す語。数量の上下の対義語ではない。"}, {"text": "国内", "is_correct": false, "explanation": "国の中を表す語。数量の対義にはならない。"}], "correct_answer": "以下", "explanations": {"以下": "「以上」の対義語として辞書に載る語。ある数量と同じか、それより少ないことを表す。", "外側": "物の外の方を表す語。数量の対義にはならない。", "中心": "物事の真ん中を表す語。数量の上下の対義語ではない。", "国内": "国の中を表す語。数量の対義にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37416, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある数量や程度を基準として、それと同じか、それより多いことを表す語。基準の値も含む。", "primary_collocate": null, "pronunciation": "いじょう", "ipa": "idʑoː", "syllable_count": 3, "sentences": [{"text": "十八歳以上の人は、この映画を見られます。", "target_word": "以上", "complexity_tier": "T3", "furigana": "十八歳[じゅうはっさい]以上[いじょう]の人[ひと]は、この映画[えいが]を見[み]られます。", "sentence_source": "generated"}, {"text": "予想以上に、会場は人でいっぱいだった。", "target_word": "以上", "complexity_tier": "T3", "furigana": "予想[よそう]以上[いじょう]に、会場[かいじょう]は人[ひと]でいっぱいだった。", "sentence_source": "generated"}, {"text": "三千円以上買うと、送料が無料になります。", "target_word": "以上", "complexity_tier": "T3", "furigana": "三千円[さんぜんえん]以上[いじょう]買[か]うと、送料[そうりょう]が無料[むりょう]になります。", "sentence_source": "generated"}, {"text": "彼は思っていた以上に、日本語が上手だ。", "target_word": "以上", "complexity_tier": "T3", "furigana": "彼[かれ]は思[おも]っていた以上[いじょう]に、日本語[にほんご]が上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "百人以上が、駅の前に集まっていた。", "target_word": "以上", "complexity_tier": "T3", "furigana": "百人[ひゃくにん]以上[いじょう]が、駅[えき]の前[まえ]に集[あつ]まっていた。", "sentence_source": "generated"}, {"text": "今日は昨日以上に、気温が高くなるそうです。", "target_word": "以上", "complexity_tier": "T3", "furigana": "今日[きょう]は昨日[きのう]以上[いじょう]に、気温[きおん]が高[たか]くなるそうです。", "sentence_source": "generated"}, {"text": "時給は千円以上の仕事を探しています。", "target_word": "以上", "complexity_tier": "T3", "furigana": "時給[じきゅう]は千円[せんえん]以上[いじょう]の仕事[しごと]を探[さが]しています。", "sentence_source": "generated"}, {"text": "これ以上は待てません。", "target_word": "以上", "complexity_tier": "T3", "furigana": "これ以上[いじょう]は待[ま]てません。", "sentence_source": "generated"}, {"text": "期待以上の結果が出て、チーム全員が喜んだ。", "target_word": "以上", "complexity_tier": "T3", "furigana": "期待[きたい]以上[いじょう]の結果[けっか]が出[で]て、チーム全員[ぜんいん]が喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "二時間以上歩いたので、足が痛い。", "target_word": "以上", "complexity_tier": "T3", "furigana": "二時間[にじかん]以上[いじょう]歩[ある]いたので、足[あし]が痛[いた]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "以上", "label": "基本形"}, {"form": "以上の", "label": "連体形"}, {"form": "以上に", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "ある数量や程度と同じか、それより多い・上であること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3049333-685e-4b1b-9295-162778d51a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37416, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以上", "is_correct": true, "explanation": "「十八歳以上の人」は十八歳を含めてそれより上の人を表し、映画を見られる条件に合う。正解。"}, {"text": "途中", "is_correct": false, "explanation": "物事の途中を表す語。「十八歳途中の人」では年齢の条件にならない。"}, {"text": "年末", "is_correct": false, "explanation": "一年の終わりを表す語。年齢の条件を示す文には入らない。"}, {"text": "最中", "is_correct": false, "explanation": "何かをしている最中を表す語。年齢の条件を表せない。"}], "explanations": {"以上": "「十八歳以上の人」は十八歳を含めてそれより上の人を表し、映画を見られる条件に合う。正解。", "途中": "物事の途中を表す語。「十八歳途中の人」では年齢の条件にならない。", "年末": "一年の終わりを表す語。年齢の条件を示す文には入らない。", "最中": "何かをしている最中を表す語。年齢の条件を表せない。"}, "sentence_index": 0, "correct_answer": "以上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その件以上は、私には関係ないことだ。", "explanation": "ここは〈以外〉（除く）の意味。「以上」は含めて上を表すので、除外の意味には合わない。"}, {"text": "来週以上は、教室を使えません。", "explanation": "ここは〈以後〉（その時点からあと）の意味。「以上」は数量の範囲を表すので時点には使えない。"}, {"text": "会議は来週以上の時点に延期することになった。", "explanation": "ここは〈以後〉（その時点からあと）の意味。「以上」は数量の範囲を表すので、時点の意味で使うと誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37416, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以上", "is_correct": true, "explanation": "「千円以上の仕事」は千円を含めてそれより高い時給の仕事を表す。正解。"}, {"text": "手前", "is_correct": false, "explanation": "ある地点の少し前を表す語。金額の条件を示す文には入らない。"}, {"text": "真ん中", "is_correct": false, "explanation": "中央を表す語。金額の条件としては意味が通らない。"}, {"text": "真夜中", "is_correct": false, "explanation": "夜の深い時間を表す語。時給の条件を示す文に合わない。"}], "explanations": {"以上": "「千円以上の仕事」は千円を含めてそれより高い時給の仕事を表す。正解。", "手前": "ある地点の少し前を表す語。金額の条件を示す文には入らない。", "真ん中": "中央を表す語。金額の条件としては意味が通らない。", "真夜中": "夜の深い時間を表す語。時給の条件を示す文に合わない。"}, "sentence_index": 6, "correct_answer": "以上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その件以上は問題ない。", "explanation": "ここは〈以外〉（除く）の意味。「以上」は含めて上を表すので、除外の意味には合わない。"}, {"text": "提出の締め切りは一週間以上までです。", "explanation": "ここは〈以内〉（上限）の意味。「以上」は下限を表すので、期限の上限としては意味が逆になる。"}, {"text": "来週の会議は、それ以外の日程では開けない。", "explanation": "ここは〈以外〉（ほかは）の意味。「以上」は上を表す語なので、除外の意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
