INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37418, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが持つ大切な意味や価値のこと。", "primary_collocate": null, "pronunciation": "いぎ", "ipa": "iɡi", "syllable_count": 2, "sentences": [{"text": "読書には意義がある。", "target_word": "意義", "complexity_tier": "T2", "furigana": "読書[どくしょ]には意義[いぎ]がある。", "sentence_source": "generated"}, {"text": "意義を考える。", "target_word": "意義", "complexity_tier": "T1", "furigana": "意義[いぎ]を考[かんが]える。", "sentence_source": "generated"}, {"text": "この仕事は意義があります。", "target_word": "意義", "complexity_tier": "T2", "furigana": "この仕事[しごと]は意義[いぎ]があります。", "sentence_source": "generated"}, {"text": "この行事の意義を教えてください。", "target_word": "意義", "complexity_tier": "T2", "furigana": "この行事[ぎょうじ]の意義[いぎ]を教[おし]えてください。", "sentence_source": "generated"}, {"text": "私は、この活動の意義を信じている。", "target_word": "意義", "complexity_tier": "T3", "furigana": "私[わたし]は、この活動[かつどう]の意義[いぎ]を信[しん]じている。", "sentence_source": "generated"}, {"text": "試合に出ることにも意義がある。", "target_word": "意義", "complexity_tier": "T3", "furigana": "試合[しあい]に出[で]ることにも意義[いぎ]がある。", "sentence_source": "generated"}, {"text": "勉強の意義が分かると、楽しくなる。", "target_word": "意義", "complexity_tier": "T3", "furigana": "勉強[べんきょう]の意義[いぎ]が分[わ]かると、楽[たの]しくなる。", "sentence_source": "generated"}, {"text": "祭りの意義を知った子どもたちは、真剣に手伝い始めた。", "target_word": "意義", "complexity_tier": "T4", "furigana": "祭[まつ]りの意義[いぎ]を知[し]った子[こ]どもたちは、真剣[しんけん]に手伝[てつだ]い始[はじ]めた。", "sentence_source": "generated"}, {"text": "意義のない仕事だと思ったら、続けることはできない。", "target_word": "意義", "complexity_tier": "T4", "furigana": "意義[いぎ]のない仕事[しごと]だと思[おも]ったら、続[つづ]けることはできない。", "sentence_source": "generated"}, {"text": "人の役に立つことに、生きる意義を感じている。", "target_word": "意義", "complexity_tier": "T4", "furigana": "人[ひと]の役[やく]に立[た]つことに、生[い]きる意義[いぎ]を感[かん]じている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "意義深い", "label": "派生"}, {"form": "有意義", "label": "派生"}, {"form": "意義ある", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事が持つ大切な意味や価値", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b9edc6-97f7-4887-afa1-fce3d82da614') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
