INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37418, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "意義", "is_correct": true, "explanation": "いぎ。正解の見出し語。"}, {"text": "意地", "is_correct": false, "explanation": "いじ。二拍目だけが違う。"}, {"text": "池", "is_correct": false, "explanation": "いけ。二拍目だけが違う。"}, {"text": "家", "is_correct": false, "explanation": "いえ。二拍目だけが違う。"}, {"text": "意思", "is_correct": false, "explanation": "いし。二拍目だけが違う。"}], "explanations": {"意義": "いぎ。正解の見出し語。", "意地": "いじ。二拍目だけが違う。", "池": "いけ。二拍目だけが違う。", "家": "いえ。二拍目だけが違う。", "意思": "いし。二拍目だけが違う。"}, "sentence_index": null, "correct_answer": "意義"}, "level_3": {"options": [{"text": "意義", "is_correct": true, "explanation": "勉強の大切な価値が分かると楽しくなる、という意味で合う。"}, {"text": "重量", "is_correct": false, "explanation": "形は合うが、勉強の重量では意味が合わない。"}, {"text": "気温", "is_correct": false, "explanation": "形は合うが、勉強の気温では意味が合わない。"}, {"text": "体積", "is_correct": false, "explanation": "形は合うが、勉強の体積では意味が合わない。"}], "explanations": {"意義": "勉強の大切な価値が分かると楽しくなる、という意味で合う。", "重量": "形は合うが、勉強の重量では意味が合わない。", "気温": "形は合うが、勉強の気温では意味が合わない。", "体積": "形は合うが、勉強の体積では意味が合わない。"}, "sentence_index": 6, "correct_answer": "意義"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅の意義は、午後五時に出発する。", "explanation": "意義は乗り物ではなく、「出発する」の主語にならない。"}, {"text": "意義を飲んで、元気になった。", "explanation": "意義は飲み物ではなく抽象的な価値なので、「飲む」とは合わない。"}, {"text": "兄は毎日、意義でサッカーをしている。", "explanation": "意義は場所ではないので、「で」で場所として使うのは誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
