INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37419, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「意義がある」と存在の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「意義をあります」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞で「意義へあります」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「意義とあります」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「意義がある」と存在の主語を示す。", "を": "「意義をあります」は文法的に成り立たない。", "へ": "方向の助詞で「意義へあります」は成り立たない。", "と": "「意義とあります」は意味が通らない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無意味", "is_correct": true, "explanation": "価値や意義がないことで、反対の意味。"}, {"text": "価値", "is_correct": false, "explanation": "意義と近い意味で、反対ではない。"}, {"text": "重要", "is_correct": false, "explanation": "大切さを表し、近い意味。"}, {"text": "目的", "is_correct": false, "explanation": "めざすものであり、反対の関係ではない。"}], "correct_answer": "無意味", "explanations": {"無意味": "価値や意義がないことで、反対の意味。", "価値": "意義と近い意味で、反対ではない。", "重要": "大切さを表し、近い意味。", "目的": "めざすものであり、反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
