INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37419, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事が持つ、重要な価値や重要性。他の物事との関係において、それがどのような役割を果たすかを示す概念。", "primary_collocate": null, "pronunciation": "いぎ", "ipa": "iɡi", "syllable_count": 2, "sentences": [{"text": "その社会的意義は極めて大きい。", "target_word": "意義", "complexity_tier": "T4", "furigana": "その社会的[しゃかいてき]意義[いぎ]は極[きわ]めて大[おお]きい。", "sentence_source": "mined"}, {"text": "この仕事には大きな意義があります。", "target_word": "意義", "complexity_tier": "T2", "furigana": "この仕事[しごと]には大[おお]きな意義[いぎ]があります。", "sentence_source": "generated"}, {"text": "意義のある毎日を送りたい。", "target_word": "意義", "complexity_tier": "T2", "furigana": "意義[いぎ]のある毎日[まいにち]を送[おく]りたい。", "sentence_source": "generated"}, {"text": "この会議の意義がよく分からなかった。", "target_word": "意義", "complexity_tier": "T3", "furigana": "この会議[かいぎ]の意義[いぎ]がよく分[わ]からなかった。", "sentence_source": "generated"}, {"text": "先生は勉強する意義について話した。", "target_word": "意義", "complexity_tier": "T3", "furigana": "先生[せんせい]は勉強[べんきょう]する意義[いぎ]について話[はな]した。", "sentence_source": "generated"}, {"text": "その発見は科学の歴史において大きな意義を持つ。", "target_word": "意義", "complexity_tier": "T4", "furigana": "その発見[はっけん]は科学[かがく]の歴史[れきし]において大[おお]きな意義[いぎ]を持[も]つ。", "sentence_source": "generated"}, {"text": "ボランティア活動の意義を、子どもたちにもわかりやすく伝えたい。", "target_word": "意義", "complexity_tier": "T4", "furigana": "ボランティア活動[かつどう]の意義[いぎ]を、子[こ]どもたちにもわかりやすく伝[つた]えたい。", "sentence_source": "generated"}, {"text": "意義を見いだせないまま続けるのは、つらいことだ。", "target_word": "意義", "complexity_tier": "T4", "furigana": "意義[いぎ]を見[み]いだせないまま続[つづ]けるのは、つらいことだ。", "sentence_source": "generated"}, {"text": "意義が認められて、計画が始まった。", "target_word": "意義", "complexity_tier": "T3", "furigana": "意義[いぎ]が認[みと]められて、計画[けいかく]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "歴史を学ぶ意義とは、過去の失敗を繰り返さないことにあると私は考える。", "target_word": "意義", "complexity_tier": "T5", "furigana": "歴史[れきし]を学[まな]ぶ意義[いぎ]とは、過去[かこ]の失敗[しっぱい]を繰[く]り返[かえ]さないことにあると私[わたし]は考[かんが]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "意義深い", "label": "派生"}, {"form": "有意義", "label": "派生"}, {"form": "意義ある", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事が持つ重要な価値や役割", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b9edc6-97f7-4887-afa1-fce3d82da614') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
