INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37420, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「金属」が「組成する」の目的語になるので、「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "金属が主語になると、金属が自ら組成する意味になり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は組成の対象ではなく相手を示すので、この文脈に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、組成の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「金属」が「組成する」の目的語になるので、「を」が正しい。", "が": "金属が主語になると、金属が自ら組成する意味になり不自然。", "に": "「に」は組成の対象ではなく相手を示すので、この文脈に合わない。", "へ": "「へ」は方向を示すので、組成の目的語にはならない。"}, "error_tags": {"が": "主語", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
