INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37420, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いくつかの成分を合わせて、物質を作ること。", "primary_collocate": null, "pronunciation": "そせい", "ipa": "sosei", "syllable_count": 3, "sentences": [{"text": "三種類の元素を一定の比率で組成すると、新しい化合物ができる。", "target_word": "組成", "complexity_tier": "T3", "furigana": "さんしゅるいのげんそをいっていのひりつでそせいすると、あたらしいかごうぶつができる。", "sentence_source": "generated"}, {"text": "研究チームは、異なる金属を組成して耐熱性の合金を開発した。", "target_word": "組成", "complexity_tier": "T3", "furigana": "けんきゅうチームは、ことなるきんぞくをそせいしてたいねつせいのごうきんをかいはつした。", "sentence_source": "generated"}, {"text": "部品を組成する際には、一つずつ正確な寸法を確かめる必要がある。", "target_word": "組成", "complexity_tier": "T3", "furigana": "ぶひんをそせいするさいには、ひとつずつせいかくなすんぽうをたしかめるひつようがある。", "sentence_source": "generated"}, {"text": "この触媒は、二種類の金属を組成することで反応を速める。", "target_word": "組成", "complexity_tier": "T3", "furigana": "このしょくばいは、にしゅるいのきんぞくをそせいすることではんのうをはやめる。", "sentence_source": "generated"}, {"text": "異なる色の顔料を組成して、独自の色を作り出す。", "target_word": "組成", "complexity_tier": "T3", "furigana": "ことなるいろのがんりょうをそせいして、どくじのいろをつくりだす。", "sentence_source": "generated"}, {"text": "化学者は、炭素と水素を組成して新しい有機化合物を作った。", "target_word": "組成", "complexity_tier": "T3", "furigana": "かがくしゃは、たんそとすいそをそせいして、あたらしいゆうきかごうぶつをつくった。", "sentence_source": "generated"}, {"text": "異なる種類の樹脂を組成し、軽くて丈夫な素材を生み出した。", "target_word": "組成", "complexity_tier": "T3", "furigana": "ことなるしゅるいのじゅしをそせいし、かるくてじょうぶなそざいをうみだした。", "sentence_source": "generated"}, {"text": "三つの要素を組成するには、順番と分量の両方が重要だ。", "target_word": "組成", "complexity_tier": "T3", "furigana": "みっつのようそをそせいするには、じゅんばんとぶんりょうのりょうほうがじゅうようだ。", "sentence_source": "generated"}, {"text": "研究者は、溶液の成分を組成して標準試料を作った。", "target_word": "組成", "complexity_tier": "T3", "furigana": "けんきゅうしゃは、ようえきのせいぶんをそせいしてひょうじゅんしりょうをつくった。", "sentence_source": "generated"}, {"text": "技術者は、二つの回路を組成して、新しい装置を設計した。", "target_word": "組成", "complexity_tier": "T3", "furigana": "ぎじゅつしゃは、ふたつのかいろをそせいして、あたらしいそうちをせっけいした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組成", "label": "dictionary"}, {"form": "組成を", "label": "object"}, {"form": "組成が", "label": "subject"}, {"form": "組成する", "label": "suru-verb"}], "register": "formal", "sense_fingerprint": "いくつかの要素を合わせて物を作ること、またその成り立ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7bfaf5f-7601-4049-bf95-765962747195') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37420, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組成", "is_correct": true, "explanation": "元素を一定の比率で合わせて化合物を作るという文脈に合う。"}, {"text": "分解", "is_correct": false, "explanation": "分解は物質をばらすこと。新しい化合物ができるという結果と逆の動きになる。"}, {"text": "抽出", "is_correct": false, "explanation": "抽出は成分を取り出すこと。元素を合わせて化合物を作る文脈とは合わない。"}, {"text": "測定", "is_correct": false, "explanation": "測定は量をはかること。元素を比率で合わせて化合物を作る文脈に合わない。"}], "explanations": {"組成": "元素を一定の比率で合わせて化合物を作るという文脈に合う。", "分解": "分解は物質をばらすこと。新しい化合物ができるという結果と逆の動きになる。", "抽出": "抽出は成分を取り出すこと。元素を合わせて化合物を作る文脈とは合わない。", "測定": "測定は量をはかること。元素を比率で合わせて化合物を作る文脈に合わない。"}, "sentence_index": 0, "correct_answer": "組成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は新しい曲を組成して、コンサートで披露した。", "explanation": "曲を作るのは〈作曲〉。組成は物質の成分や人の集まりに使うので、曲には使わない。"}, {"text": "この小説は三つの部から組成されている。", "explanation": "小説の構造は〈構成〉が自然。組成は物質の成分などに使い、作品の組み立てには使わない。"}, {"text": "この音楽は三つの楽器の音を組成して作られた。", "explanation": "音を人工的に作り出すのは〈合成〉。組成は物質の成分の意味で、音には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37420, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組成", "is_correct": true, "explanation": "異なる樹脂を合わせて新しい素材を作るという文脈に合う。"}, {"text": "解体", "is_correct": false, "explanation": "解体は組み立てたものをばらすこと。新しい素材を生み出す文脈と逆になる。"}, {"text": "切断", "is_correct": false, "explanation": "切断は物を断ち切ること。樹脂を合わせて素材を作るという意味にならない。"}, {"text": "採掘", "is_correct": false, "explanation": "採掘は地中から資源を掘り出すこと。樹脂を合わせて素材を作る文脈に合わない。"}], "explanations": {"組成": "異なる樹脂を合わせて新しい素材を作るという文脈に合う。", "解体": "解体は組み立てたものをばらすこと。新しい素材を生み出す文脈と逆になる。", "切断": "切断は物を断ち切ること。樹脂を合わせて素材を作るという意味にならない。", "採掘": "採掘は地中から資源を掘り出すこと。樹脂を合わせて素材を作る文脈に合わない。"}, "sentence_index": 6, "correct_answer": "組成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来月の会議に向けて、報告書を組成した。", "explanation": "文書を作るのは〈作成〉。組成は物質の成分や人の集まりに使うので、報告書には合わない。"}, {"text": "届いた机を一時間かけて組成した。", "explanation": "家具を組み立てるのは〈組み立て〉。組成は物質の成分などに使うので、ここでは使えない。"}, {"text": "来季の番組を組成した。", "explanation": "番組の内容を決めて並べるのは〈編成〉。組成は物質や人の集まりに使い、番組には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37420, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二種類の金属に組成すると、新しい合金ができる。", "corrected_sentence": "二種類の金属を組成すると、新しい合金ができる。", "error_description": "誤りは「に」。「組成する」は他動詞なので、対象は「を」で示す。正しくは「金属を組成する」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37420, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三種類の材料を組成れば、新しい素材ができる。", "corrected_sentence": "三種類の材料を組成すれば、新しい素材ができる。", "error_description": "誤りは「組成れば」。「組成する」の仮定形は「組成すれば」なので、「す」が抜けた活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
