INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37421, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人を集めて、組織や集団を作ること。", "primary_collocate": null, "pronunciation": "そせい", "ipa": "sosei", "syllable_count": 3, "sentences": [{"text": "市は新しい委員会を組成することを決めた。", "target_word": "組成する", "complexity_tier": "T4", "furigana": "市[し]は新[あたら]しい委員会[いいんかい]を組成[そせい]することを決[き]めた。", "sentence_source": "generated"}, {"text": "各部署の代表者を集めて、チームを組成した。", "target_word": "組成した", "complexity_tier": "T4", "furigana": "各部署[かくぶしょ]の代表者[だいひょうしゃ]を集[あつ]めて、チームを組成[そせい]した。", "sentence_source": "generated"}, {"text": "プロジェクトのために、専門家による会議体が組成された。", "target_word": "組成され", "complexity_tier": "T4", "furigana": "プロジェクトのために、専門家[せんもんか]による会議体[かいぎたい]が組成[そせい]された。", "sentence_source": "generated"}, {"text": "社長は、急いで調査団を組成するよう指示した。", "target_word": "組成する", "complexity_tier": "T4", "furigana": "社長[しゃちょう]は、急[いそ]いで調査団[ちょうさだん]を組成[そせい]するよう指示[しじ]した。", "sentence_source": "generated"}, {"text": "この楽団は、地元の若者を集めて組成された。", "target_word": "組成され", "complexity_tier": "T4", "furigana": "この楽団[がくだん]は、地元[じもと]の若者[わかもの]を集[あつ]めて組成[そせい]された。", "sentence_source": "generated"}, {"text": "新しい内閣の組成には、時間がかかった。", "target_word": "組成", "complexity_tier": "T4", "furigana": "新[あたら]しい内閣[ないかく]の組成[そせい]には、時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "災害に備えて、地域の救助隊を組成した。", "target_word": "組成した", "complexity_tier": "T4", "furigana": "災害[さいがい]に備[そな]えて、地域[ちいき]の救助隊[きゅうじょたい]を組成[そせい]した。", "sentence_source": "generated"}, {"text": "委員会の組成が終わり、来週から活動が始まる。", "target_word": "組成", "complexity_tier": "T4", "furigana": "委員会[いいんかい]の組成[そせい]が終[お]わり、来週[らいしゅう]から活動[かつどう]が始[はじ]まる。", "sentence_source": "generated"}, {"text": "会社は海外向けの専門チームを組成する予定だ。", "target_word": "組成する", "complexity_tier": "T4", "furigana": "会社[かいしゃ]は海外向[かいがいむ]けの専門[せんもん]チームを組成[そせい]する予定[よてい]だ。", "sentence_source": "generated"}, {"text": "有志が集まって、勉強会が組成された。", "target_word": "組成され", "complexity_tier": "T4", "furigana": "有志[ゆうし]が集[あつ]まって、勉強会[べんきょうかい]が組成[そせい]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組成", "label": "dictionary"}, {"form": "組成する", "label": "suru-verb"}, {"form": "組成した", "label": "past"}, {"form": "組成され", "label": "passive stem"}], "register": "formal", "sense_fingerprint": "人や要素を集めて組織・集団を作ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7bfaf5f-7601-4049-bf95-765962747195') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37421, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組成する", "is_correct": true, "explanation": "新しい委員会を作ることを決めたという文脈に合う。"}, {"text": "分解する", "is_correct": false, "explanation": "分解は物をばらすこと。委員会を新しく作る文脈と逆になる。"}, {"text": "抽出する", "is_correct": false, "explanation": "抽出は一部を取り出すこと。委員会を作る決定の文脈に合わない。"}, {"text": "測定する", "is_correct": false, "explanation": "測定は量をはかること。委員会を作ることを決めた文脈とは合わない。"}], "explanations": {"組成する": "新しい委員会を作ることを決めたという文脈に合う。", "分解する": "分解は物をばらすこと。委員会を新しく作る文脈と逆になる。", "抽出する": "抽出は一部を取り出すこと。委員会を作る決定の文脈に合わない。", "測定する": "測定は量をはかること。委員会を作ることを決めた文脈とは合わない。"}, "sentence_index": 0, "correct_answer": "組成する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場では、毎日部品を千個組成している。", "explanation": "部品を大量に作るのは〈製造〉。組成は人や要素を集めて一つのまとまりを作る意味で、工場の生産には使わない。"}, {"text": "来月の会議のために、報告書を組成した。", "explanation": "文書を作るのは〈作成〉。組成は人の集まりや物質の成分に使うので合わない。"}, {"text": "論文は三つの章で組成されている。", "explanation": "章立ての組み立ては〈構成〉。組成は人の集まりを作る意味で使うので、論文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37421, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組成した", "is_correct": true, "explanation": "災害に備えて救助隊を作ったという文脈に合う。"}, {"text": "切断した", "is_correct": false, "explanation": "切断は断ち切ること。救助隊を作る文脈とは合わない。"}, {"text": "採掘した", "is_correct": false, "explanation": "採掘は地下から資源を掘り出すこと。救助隊を作る文脈に合わない。"}, {"text": "採取した", "is_correct": false, "explanation": "採取は自然のものを取り集めること。人の集まりを作る文脈に合わない。"}], "explanations": {"組成した": "災害に備えて救助隊を作ったという文脈に合う。", "切断した": "切断は断ち切ること。救助隊を作る文脈とは合わない。", "採掘した": "採掘は地下から資源を掘り出すこと。救助隊を作る文脈に合わない。", "採取した": "採取は自然のものを取り集めること。人の集まりを作る文脈に合わない。"}, "sentence_index": 6, "correct_answer": "組成した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は夏に新しいピアノ曲を組成した。", "explanation": "曲を作るのは〈作曲〉。組成は人の集まりや物質の成分に使うので、音楽には使わない。"}, {"text": "来季の放送枠を組成した。", "explanation": "時間枠や番組を割り振るのは〈編成〉。組成は人の集まりや成分の意味に使うので合わない。"}, {"text": "夏休みの作文を組成した。", "explanation": "文章を書くのは〈作文〉や〈執筆〉。組成は人の集まりや物質の成分に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37421, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい委員会で組成することになった。", "corrected_sentence": "新しい委員会を組成することになった。", "error_description": "誤りは「で」。「組成する」の目的語は「を」で示す。「で」は場所や手段を示すので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37421, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子育て中の母親が集まって、読書会が組成れた。", "corrected_sentence": "子育て中の母親が集まって、読書会が組成された。", "error_description": "誤りは「組成れた」。受身の過去形は「組成された」で、「さ」が抜けた活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0936b7eb-8d94-4f28-b548-1ddd7d9fcff4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
