INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37422, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たくさんの人がインターネットで一緒に遊ぶゲーム", "primary_collocate": null, "pronunciation": "えむえむおーあーるぴーじー", "ipa": "emɯemɯoːaːɾɯpiːdʑiː", "syllable_count": 13, "sentences": [{"text": "この MMORPG では、世界中の人と一緒に冒険できます。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "この MMORPG では、世界中[せかいじゅう]の人[ひと]と一緒[いっしょ]に冒険[ぼうけん]できます。", "sentence_source": "generated"}, {"text": "兄は毎晩、友達と MMORPG で遊んでいます。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "兄[あに]は毎晩[まいばん]、友達[ともだち]と MMORPG で遊[あそ]んでいます。", "sentence_source": "generated"}, {"text": "MMORPG は人が多いので、いつも画面がにぎやかです。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "MMORPG は人[ひと]が多[おお]いので、いつも画面[がめん]がにぎやかです。", "sentence_source": "generated"}, {"text": "新しい MMORPG が出たので、さっそく登録しました。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "新[あたら]しい MMORPG が出[で]たので、さっそく登録[とうろく]しました。", "sentence_source": "generated"}, {"text": "私は MMORPG の中で、外国の友達ができました。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "私[わたし]は MMORPG の中[なか]で、外国[がいこく]の友達[ともだち]ができました。", "sentence_source": "generated"}, {"text": "一人で遊ぶゲームより、MMORPG のほうが好きです。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "一人[ひとり]で遊[あそ]ぶゲームより、MMORPG のほうが好[す]きです。", "sentence_source": "generated"}, {"text": "MMORPG を始めてから、夜更かしが増えてしまいました。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "MMORPG を始[はじ]めてから、夜更[よふ]かしが増[ふ]えてしまいました。", "sentence_source": "generated"}, {"text": "この MMORPG は無料なので、だれでも気軽に始められます。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "この MMORPG は無料[むりょう]なので、だれでも気軽[きがる]に始[はじ]められます。", "sentence_source": "generated"}, {"text": "母は MMORPG を知らなくて、ただのゲームだと思っています。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "母[はは]は MMORPG を知[し]らなくて、ただのゲームだと思[おも]っています。", "sentence_source": "generated"}, {"text": "試験の前は、MMORPG にログインしないと決めました。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]は、MMORPG にログインしないと決[き]めました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "MMORPG", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "ネットで大勢が同時に遊ぶオンラインゲームの種類", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe8a64e-398a-44c0-8fce-9cbeb83b8e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37422, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "MMORPG", "is_correct": true, "explanation": "オンラインで大勢と遊ぶゲームの種類を指し、「この〇〇では、世界中の人と一緒に冒険できます」の空欄に入る。"}, {"text": "教科書", "is_correct": false, "explanation": "勉強に使う本で、世界中の人と冒険できる場ではないので合わない。"}, {"text": "郵便局", "is_correct": false, "explanation": "手紙や荷物を扱う施設で、一緒に冒険できる場所ではないので合わない。"}, {"text": "体温計", "is_correct": false, "explanation": "体温を測る道具で、冒険ができる場ではないので合わない。"}], "explanations": {"MMORPG": "オンラインで大勢と遊ぶゲームの種類を指し、「この〇〇では、世界中の人と一緒に冒険できます」の空欄に入る。", "教科書": "勉強に使う本で、世界中の人と冒険できる場ではないので合わない。", "郵便局": "手紙や荷物を扱う施設で、一緒に冒険できる場所ではないので合わない。", "体温計": "体温を測る道具で、冒険ができる場ではないので合わない。"}, "sentence_index": 0, "correct_answer": "MMORPG"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい MMORPG を、ポケットに入れて持ち歩きました。", "explanation": "〈ゲーム機〉の意味。ゲーム機は持ち歩けるが、MMORPG はゲームの種類で機械ではないので合わない。"}, {"text": "新しい MMORPG を、本のように読んで感想を書きました。", "explanation": "〈本〉の意味。本は読むものだが、MMORPG は遊ぶゲームなので〈読む〉とは合わない。"}, {"text": "新しい MMORPG で、味噌汁を温めました。", "explanation": "〈電子レンジ〉の意味。電子レンジは食べ物を温める器具だが、MMORPG はゲームの種類で器具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37422, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "MMORPG", "is_correct": true, "explanation": "始めることができるゲームの種類で、「を始めてから、夜更かしが増えてしまいました」に入る。"}, {"text": "電子レンジ", "is_correct": false, "explanation": "使う家電で、「始める」対象にはならないので合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を保存する家電で、「始める」対象にはならないので合わない。"}, {"text": "天気予報", "is_correct": false, "explanation": "見たり聞いたりする情報で、「始める」対象としては不自然なので合わない。"}], "explanations": {"MMORPG": "始めることができるゲームの種類で、「を始めてから、夜更かしが増えてしまいました」に入る。", "電子レンジ": "使う家電で、「始める」対象にはならないので合わない。", "冷蔵庫": "食品を保存する家電で、「始める」対象にはならないので合わない。", "天気予報": "見たり聞いたりする情報で、「始める」対象としては不自然なので合わない。"}, "sentence_index": 6, "correct_answer": "MMORPG"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験の前は、MMORPG の上映時間を調べました。", "explanation": "〈映画〉の意味。映画は上映時間があるが、MMORPG は遊ぶゲームで上映されないので合わない。"}, {"text": "試験の前は、MMORPG のえさを毎朝あげました。", "explanation": "〈ペット〉の意味。ペットはえさをあげるが、MMORPG はゲームの種類でえさは要らないので合わない。"}, {"text": "試験の前は、MMORPG で毎朝体重を量りました。", "explanation": "〈体重計〉の意味。体重計は体重を量る器具だが、MMORPG は遊びの種類で量る道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37422, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎晩、友達と MMORPG に遊んでいました。", "corrected_sentence": "毎晩、友達と MMORPG で遊んでいました。", "error_description": "誤りは MMORPG の直後の助詞「に」。ゲームで遊ぶ手段・場所は「で」で示すので、「で」が正しい。「に」は方向や相手を表すため、「遊ぶ」と結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37422, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週、友達に誘われて MMORPG を飲みました。", "corrected_sentence": "先週、友達に誘われて MMORPG を始めました。", "error_description": "誤りは動詞「飲みました」。ゲームは「始める」ものなので「始めました」が正しい。「飲む」は飲み物などに使う動詞で、ゲームの語とは結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
