INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37423, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "大規模多人数同時参加型のオンラインロールプレイングゲーム", "primary_collocate": null, "pronunciation": "えむえむおーあーるぴーじー", "ipa": "emɯemɯoːaːɾɯpiːdʑiː", "syllable_count": 13, "sentences": [{"text": "MMORPG は、大規模なオンラインのロールプレイングゲームです。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "MMORPG は、大規模[だいきぼ]なオンラインのロールプレイングゲームです。", "sentence_source": "generated"}, {"text": "多くの MMORPG では、プレイヤーが自分のキャラクターを育てます。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "多[おお]くの MMORPG では、プレイヤーが自分[じぶん]のキャラクターを育[そだ]てます。", "sentence_source": "generated"}, {"text": "昔の MMORPG は、パソコンでしか遊べませんでした。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "昔[むかし]の MMORPG は、パソコンでしか遊[あそ]べませんでした。", "sentence_source": "generated"}, {"text": "この MMORPG には、数万人が同時に参加します。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "この MMORPG には、数万人[すうまんにん]が同時[どうじ]に参加[さんか]します。", "sentence_source": "generated"}, {"text": "MMORPG のサーバーは、人が増えると重くなります。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "MMORPG のサーバーは、人[ひと]が増[ふ]えると重[おも]くなります。", "sentence_source": "generated"}, {"text": "友達に誘われて、人気の MMORPG を始めました。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "友達[ともだち]に誘[さそ]われて、人気[にんき]の MMORPG を始[はじ]めました。", "sentence_source": "generated"}, {"text": "MMORPG では、仲間と協力して強い敵を倒します。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "MMORPG では、仲間[なかま]と協力[きょうりょく]して強[つよ]い敵[てき]を倒[たお]します。", "sentence_source": "generated"}, {"text": "週末に MMORPG の大きなイベントがあります。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]に MMORPG の大[おお]きなイベントがあります。", "sentence_source": "generated"}, {"text": "弟は MMORPG の攻略サイトを毎日読んでいます。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "弟[おとうと]は MMORPG の攻略[こうりゃく]サイトを毎日[まいにち]読[よ]んでいます。", "sentence_source": "generated"}, {"text": "その MMORPG は十年前に始まり、今も続いています。", "target_word": "MMORPG", "complexity_tier": "T3", "furigana": "その MMORPG は十年前[じゅうねんまえ]に始[はじ]まり、今[いま]も続[つづ]いています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "MMORPG", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "大規模な多人数参加型オンラインロールプレイングゲームというジャンル名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe8a64e-398a-44c0-8fce-9cbeb83b8e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37423, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "MMORPG", "is_correct": true, "explanation": "大規模なオンラインのロールプレイングゲームという種類の名前で、定義文の主語に入る。"}, {"text": "鉄道", "is_correct": false, "explanation": "乗り物の一種で、オンラインゲームの定義にはならないので合わない。"}, {"text": "焼き鳥", "is_correct": false, "explanation": "料理の名前で、ゲームの定義にはならないので合わない。"}, {"text": "郵便", "is_correct": false, "explanation": "手紙などを届ける仕組みで、ゲームの定義にはならないので合わない。"}], "explanations": {"MMORPG": "大規模なオンラインのロールプレイングゲームという種類の名前で、定義文の主語に入る。", "鉄道": "乗り物の一種で、オンラインゲームの定義にはならないので合わない。", "焼き鳥": "料理の名前で、ゲームの定義にはならないので合わない。", "郵便": "手紙などを届ける仕組みで、ゲームの定義にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "MMORPG"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この MMORPG の客席には、数万人が座ります。", "explanation": "〈競技場〉の意味。競技場には客席があるが、MMORPG はゲームの種類で客席は持たないので合わない。"}, {"text": "この MMORPG には、わずかな利息がつきます。", "explanation": "〈銀行口座〉の意味。口座には利息がつくが、MMORPG は遊びの種類で利息を生まないので合わない。"}, {"text": "この MMORPG は、朝早くから焼きたてのパンを売ります。", "explanation": "〈パン屋〉の意味。パン屋は商品を売るが、MMORPG は遊びのジャンルなので物を売る主体にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37423, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "MMORPG", "is_correct": true, "explanation": "仲間と協力して敵を倒すゲームの種類で、「では」で場を示す文に入る。"}, {"text": "洗濯機", "is_correct": false, "explanation": "洗濯をする家電で、仲間と敵を倒す場ではないので合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "勉強に使う本で、仲間と敵を倒す場ではないので合わない。"}, {"text": "味噌汁", "is_correct": false, "explanation": "料理の一種で、敵を倒す場ではないので合わない。"}], "explanations": {"MMORPG": "仲間と協力して敵を倒すゲームの種類で、「では」で場を示す文に入る。", "洗濯機": "洗濯をする家電で、仲間と敵を倒す場ではないので合わない。", "教科書": "勉強に使う本で、仲間と敵を倒す場ではないので合わない。", "味噌汁": "料理の一種で、敵を倒す場ではないので合わない。"}, "sentence_index": 6, "correct_answer": "MMORPG"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その MMORPG は十年前に設立され、今も続いています。", "explanation": "〈会社〉の意味。会社は設立されるが、MMORPG はジャンル名なので設立される対象にはならないので合わない。"}, {"text": "その MMORPG は十年前に一冊目が出版され、今も続いています。", "explanation": "〈出版物〉の意味。本や雑誌は出版されるが、MMORPG は遊びの種類で出版物ではないので合わない。"}, {"text": "その MMORPG は十年前に炊かれ、今も温かいです。", "explanation": "〈ご飯〉の意味。ご飯は炊かれるが、MMORPG はゲームの種類で炊く対象ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37423, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟は MMORPG を攻略本を毎日読んでいます。", "corrected_sentence": "弟は MMORPG の攻略本を毎日読んでいます。", "error_description": "誤りは MMORPG に続く助詞「を」。「攻略本」との関係を示すのは「の」で、「を」を重ねると目的語が二つになり不自然。正しくは「MMORPG の攻略本を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37423, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来月、MMORPG を大きな大会が開かれます。", "corrected_sentence": "来月、MMORPG で大きな大会が開かれます。", "error_description": "誤りは MMORPG の直後の助詞「を」。大会が開かれる場は「で」で示すので、「で」が正しい。「開かれます」は受け身で目的語を取らないため、「を」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37424, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「人数が決まったら」の「が」。決まるという動作の主語を示し、ここで正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。「人数へ決まったら」では意味が通らないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞。「人数より決まったら」では比べる文にならないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞。「決まる」は自動詞なので「人数を決まったら」は不自然で合わない。"}], "correct_answer": "が", "explanations": {"が": "「人数が決まったら」の「が」。決まるという動作の主語を示し、ここで正しい。", "へ": "方向を示す助詞。「人数へ決まったら」では意味が通らないので合わない。", "より": "比較の助詞。「人数より決まったら」では比べる文にならないので合わない。", "を": "目的語を示す助詞。「決まる」は自動詞なので「人数を決まったら」は不自然で合わない。"}, "error_tags": {"へ": "方向", "より": "比較", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37424, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「座れる人数が四人まで」の「が」。人数が四人までという主語を示し、ここで正しい。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示す助詞。「人数に四人まで」では意味が通らないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列の助詞。「人数と四人まで」では文が成り立たないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞。「座れる人数の四人まで」では文が成り立たないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「座れる人数が四人まで」の「が」。人数が四人までという主語を示し、ここで正しい。", "に": "場所や相手を示す助詞。「人数に四人まで」では意味が通らないので合わない。", "と": "並列の助詞。「人数と四人まで」では文が成り立たないので合わない。", "の": "連体修飾の助詞。「座れる人数の四人まで」では文が成り立たないので合わない。"}, "error_tags": {"に": "相手", "と": "並列", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37424, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "グループの中の人の数。", "primary_collocate": null, "pronunciation": "にんずう", "ipa": "ɲiɴzɯː", "syllable_count": 4, "sentences": [{"text": "今日の会議は人数が少ないので、小さい部屋で行います。", "target_word": "人数", "complexity_tier": "T3", "furigana": "今日[きょう]の会議[かいぎ]は人数[にんずう]が少[すく]ないので、小[ちい]さい部屋[へや]で行[おこな]います。", "sentence_source": "generated"}, {"text": "旅行に行く人数が決まったら、教えてください。", "target_word": "人数", "complexity_tier": "T3", "furigana": "旅行[りょこう]に行[い]く人数[にんずう]が決[き]まったら、教[おし]えてください。", "sentence_source": "generated"}, {"text": "人数を数えたら、全部で十二人でした。", "target_word": "人数", "complexity_tier": "T3", "furigana": "人数[にんずう]を数[かぞ]えたら、全部[ぜんぶ]で十二人[じゅうににん]でした。", "sentence_source": "generated"}, {"text": "クラスの人数が多すぎて、先生は名前を覚えられません。", "target_word": "人数", "complexity_tier": "T3", "furigana": "クラスの人数[にんずう]が多[おお]すぎて、先生[せんせい]は名前[なまえ]を覚[おぼ]えられません。", "sentence_source": "generated"}, {"text": "予約をするとき、人数を店に伝えました。", "target_word": "人数", "complexity_tier": "T3", "furigana": "予約[よやく]をするとき、人数[にんずう]を店[みせ]に伝[つた]えました。", "sentence_source": "generated"}, {"text": "来客の人数を確認して、お茶を用意してください。", "target_word": "人数", "complexity_tier": "T3", "furigana": "来客[らいきゃく]の人数[にんずう]を確認[かくにん]して、お茶[ちゃ]を用意[ようい]してください。", "sentence_source": "generated"}, {"text": "集まった人数が足りなかったので、試合は中止になりました。", "target_word": "人数", "complexity_tier": "T3", "furigana": "集[あつ]まった人数[にんずう]が足[た]りなかったので、試合[しあい]は中止[ちゅうし]になりました。", "sentence_source": "generated"}, {"text": "このテーブルには、座れる人数が四人までと書いてあります。", "target_word": "人数", "complexity_tier": "T3", "furigana": "このテーブルには、座[すわ]れる人数[にんずう]が四人[よにん]までと書[か]いてあります。", "sentence_source": "generated"}, {"text": "一つのチームの人数は、十一人と決まっています。", "target_word": "人数", "complexity_tier": "T3", "furigana": "一[ひと]つのチームの人数[にんずう]は、十一人[じゅういちにん]と決[き]まっています。", "sentence_source": "generated"}, {"text": "欠席者が出て、グループの人数が減りました。", "target_word": "人数", "complexity_tier": "T3", "furigana": "欠席者[けっせきしゃ]が出[で]て、グループの人数[にんずう]が減[へ]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人数", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "グループやチームなど、まとまりの中にいる人の数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe8a64e-398a-44c0-8fce-9cbeb83b8e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37424, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人数", "is_correct": true, "explanation": "会議に集まる人の数を表し、「少ない」と合うので空欄に入る。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで、「天気が少ない」とは言わず、会議の人数の話にならないので合わない。"}, {"text": "味", "is_correct": false, "explanation": "食べ物の質を表す語で、量の「少ない」とは成り立たないので合わない。"}, {"text": "歌", "is_correct": false, "explanation": "歌を表す語で、会議の規模を決める「少ない」の対象にはならないので合わない。"}], "explanations": {"人数": "会議に集まる人の数を表し、「少ない」と合うので空欄に入る。", "天気": "空模様のことで、「天気が少ない」とは言わず、会議の人数の話にならないので合わない。", "味": "食べ物の質を表す語で、量の「少ない」とは成り立たないので合わない。", "歌": "歌を表す語で、会議の規模を決める「少ない」の対象にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "人数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町の人数は、時速五十キロで走りました。", "explanation": "〈車〉の意味。車は時速で走るが、人数は数を表すので走る主体にはならないので合わない。"}, {"text": "この部屋の人数は、とても広いです。", "explanation": "〈広さ〉の意味。人数は数を表すので、部屋の広さを表す「広い」とは組み合わないので合わない。"}, {"text": "その人数は、五人で活動しています。", "explanation": "〈グループ〉の意味。グループは活動するが、人数は数であり活動する主体ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37424, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人数", "is_correct": true, "explanation": "集まった人の数を表し、「足りなかった」と合うので空欄に入る。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除に使う道具で、「集まった掃除機が足りない」は意味が通らないので合わない。"}, {"text": "照明", "is_correct": false, "explanation": "明かりの器具で、集まるものではなく「足りない」と合わないので合わない。"}, {"text": "虫", "is_correct": false, "explanation": "生き物だが、試合の中止につながる不足の対象にはならないので合わない。"}], "explanations": {"人数": "集まった人の数を表し、「足りなかった」と合うので空欄に入る。", "掃除機": "掃除に使う道具で、「集まった掃除機が足りない」は意味が通らないので合わない。", "照明": "明かりの器具で、集まるものではなく「足りない」と合わないので合わない。", "虫": "生き物だが、試合の中止につながる不足の対象にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "人数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その人数は、とても親切です。", "explanation": "〈メンバー〉の意味。メンバーは人なので親切と言えるが、人数は数を表すので人の性質は表さないので合わない。"}, {"text": "グループの人数を、強火で焼きました。", "explanation": "人数は焼けるものではなく、〈焼く〉と組み合わない。調理の語を数に使うのは誤り。"}, {"text": "欠席者が出て、グループの人数が長くなりました。", "explanation": "人数は数であり、「長くなる」は長さのあるものに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37424, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議の人数を増えました。", "corrected_sentence": "会議の人数が増えました。", "error_description": "誤りは「人数」に続く助詞「を」。増えるのは人数という主語なので「が」が正しい。「を」は他動詞の目的語に使うため、自動詞「増える」とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37424, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当日は人数を多いので、席を増やしました。", "corrected_sentence": "当日は人数が多いので、席を増やしました。", "error_description": "誤りは「人数」に続く助詞「を」。形容詞「多い」の主語は「が」で示すので、「が」が正しい。「を」は動作の目的語に使うため、形容詞とは組み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37425, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「人数は、思ったより多かった」の「は」。人数を話題として示し、ここで正しい。"}, {"text": "に", "is_correct": false, "explanation": "時点や相手を示す助詞。「人数に思ったより多かった」は文が成り立たないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。「人数へ思ったより」は意味が通らないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞。「人数を思ったより多かった」は文が成り立たないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「人数は、思ったより多かった」の「は」。人数を話題として示し、ここで正しい。", "に": "時点や相手を示す助詞。「人数に思ったより多かった」は文が成り立たないので合わない。", "へ": "方向を示す助詞。「人数へ思ったより」は意味が通らないので合わない。", "を": "目的語を示す助詞。「人数を思ったより多かった」は文が成り立たないので合わない。"}, "error_tags": {"に": "相手", "へ": "方向", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37425, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「乗れる人数が決まっています」の「が」。人数が決まるという主語を示し、ここで正しい。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞。「人数より決まっています」は意味が通らないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞。「乗れる人数の決まっています」は文が成り立たないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "確定を示す「と決まっている」の形に合わず、「人数と決まっています」は不自然で合わない。"}], "correct_answer": "が", "explanations": {"が": "「乗れる人数が決まっています」の「が」。人数が決まるという主語を示し、ここで正しい。", "より": "比較の助詞。「人数より決まっています」は意味が通らないので合わない。", "の": "連体修飾の助詞。「乗れる人数の決まっています」は文が成り立たないので合わない。", "と": "確定を示す「と決まっている」の形に合わず、「人数と決まっています」は不自然で合わない。"}, "error_tags": {"より": "比較", "の": "連体修飾", "と": "確定"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37425, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人々の集まりの数を表す言葉。", "primary_collocate": null, "pronunciation": "にんずう", "ipa": "ɲiɴzɯː", "syllable_count": 4, "sentences": [{"text": "会場に入れる人数は、二百人までです。", "target_word": "人数", "complexity_tier": "T3", "furigana": "会場[かいじょう]に入[はい]れる人数[にんずう]は、二百人[にひゃくにん]までです。", "sentence_source": "generated"}, {"text": "昨日のコンサートの人数は、思ったより多かったです。", "target_word": "人数", "complexity_tier": "T3", "furigana": "昨日[きのう]のコンサートの人数[にんずう]は、思[おも]ったより多[おお]かったです。", "sentence_source": "generated"}, {"text": "人数が増えるにつれて、部屋が暑くなりました。", "target_word": "人数", "complexity_tier": "T3", "furigana": "人数[にんずう]が増[ふ]えるにつれて、部屋[へや]が暑[あつ]くなりました。", "sentence_source": "generated"}, {"text": "先生は教室の人数を見て、椅子を足しました。", "target_word": "人数", "complexity_tier": "T3", "furigana": "先生[せんせい]は教室[きょうしつ]の人数[にんずう]を見[み]て、椅子[いす]を足[た]しました。", "sentence_source": "generated"}, {"text": "祭りに来た人数を、係の人が記録しています。", "target_word": "人数", "complexity_tier": "T3", "furigana": "祭[まつ]りに来[き]た人数[にんずう]を、係[かかり]の人[ひと]が記録[きろく]しています。", "sentence_source": "generated"}, {"text": "人数に合わせて、料理の量を決めます。", "target_word": "人数", "complexity_tier": "T3", "furigana": "人数[にんずう]に合[あ]わせて、料理[りょうり]の量[りょう]を決[き]めます。", "sentence_source": "generated"}, {"text": "駅前に集まった人数は、およそ五百人でした。", "target_word": "人数", "complexity_tier": "T3", "furigana": "駅前[えきまえ]に集[あつ]まった人数[にんずう]は、およそ五百人[ごひゃくにん]でした。", "sentence_source": "generated"}, {"text": "エレベーターは、乗れる人数が決まっています。", "target_word": "人数", "complexity_tier": "T3", "furigana": "エレベーターは、乗[の]れる人数[にんずう]が決[き]まっています。", "sentence_source": "generated"}, {"text": "去年と比べて、見学に来る人数が減りました。", "target_word": "人数", "complexity_tier": "T3", "furigana": "去年[きょねん]と比[くら]べて、見学[けんがく]に来[く]る人数[にんずう]が減[へ]りました。", "sentence_source": "generated"}, {"text": "人数が多い日は、受付に長い列ができます。", "target_word": "人数", "complexity_tier": "T3", "furigana": "人数[にんずう]が多[おお]い日[ひ]は、受付[うけつけ]に長[なが]い列[れつ]ができます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人数", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "会場や場所に集まった人々の数を表す言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe8a64e-398a-44c0-8fce-9cbeb83b8e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37425, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人数", "is_correct": true, "explanation": "会場に入る人の数を表し、「二百人まで」と合うので空欄に入る。"}, {"text": "温度", "is_correct": false, "explanation": "温度は入場の上限を決める基準にはならず、「二百人まで」と合わないので合わない。"}, {"text": "車", "is_correct": false, "explanation": "車は台数で数えるもので、人数の上限とは合わないので合わない。"}, {"text": "予算", "is_correct": false, "explanation": "お金の見積もりで、入場できる人数の上限にはならないので合わない。"}], "explanations": {"人数": "会場に入る人の数を表し、「二百人まで」と合うので空欄に入る。", "温度": "温度は入場の上限を決める基準にはならず、「二百人まで」と合わないので合わない。", "車": "車は台数で数えるもので、人数の上限とは合わないので合わない。", "予算": "お金の見積もりで、入場できる人数の上限にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "人数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は教室の人数を、重さで量りました。", "explanation": "〈重さ〉の意味。重さは量るものだが、人数は数えるもので、重さで量る対象ではないので合わない。"}, {"text": "先生は教室の名札を見て、人数の名前を呼びました。", "explanation": "〈名札〉の意味。名札は名前を示すが、人数には個々の名前がなく、呼ぶ対象にはならないので合わない。"}, {"text": "先生は教室の人数を鳴らして、授業を始めました。", "explanation": "〈ベル〉の意味。ベルは鳴らすものだが、人数は鳴らせないので、〈鳴らす〉とは組み合わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37425, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人数", "is_correct": true, "explanation": "駅前に集まった人の数を表し、「およそ五百人」と合うので空欄に入る。"}, {"text": "写真", "is_correct": false, "explanation": "撮った画像で、人の数を表さず「五百人」と合わないので合わない。"}, {"text": "雨", "is_correct": false, "explanation": "天気の一つで、集まるものではないので「集まった雨」は意味が通らないので合わない。"}, {"text": "看板", "is_correct": false, "explanation": "店などに掲げる札で、集まるものではなく「五百人」と数えられないので合わない。"}], "explanations": {"人数": "駅前に集まった人の数を表し、「およそ五百人」と合うので空欄に入る。", "写真": "撮った画像で、人の数を表さず「五百人」と合わないので合わない。", "雨": "天気の一つで、集まるものではないので「集まった雨」は意味が通らないので合わない。", "看板": "店などに掲げる札で、集まるものではなく「五百人」と数えられないので合わない。"}, "sentence_index": 6, "correct_answer": "人数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人数が赤い日は、受付に長い列ができます。", "explanation": "〈色〉の意味。色は赤いと言えるが、人数は数を表すので色を表す「赤い」とは組み合わない。"}, {"text": "その人数は、とても丁寧に話します。", "explanation": "〈話す人〉の意味。話す主体は人なので、人数が話すとは言えないので合わない。"}, {"text": "人数が重くなる日は、受付に長い列ができます。", "explanation": "〈重さ〉の意味。重さは増えて重くなるが、人数は数なので重さとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37425, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "イベントの人数が数えて、席を用意しました。", "corrected_sentence": "イベントの人数を数えて、席を用意しました。", "error_description": "誤りは「人数」に続く助詞「が」。数える対象は「を」で示すので「を」が正しい。「が」では人数が数える主体になり、不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37425, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人数を多い日は、早めに来てください。", "corrected_sentence": "人数が多い日は、早めに来てください。", "error_description": "誤りは「人数」に続く助詞「を」。形容詞「多い」の主語は「が」で示すので、「が」が正しい。「を」は動作の目的語に使うため、形容詞とは組み合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37426, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「ゲームでは」で場所や範囲を示し、「仲間になれる」という文の前提として自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "「ゲームをは」は目的語の格として成り立たず、不自然。"}, {"text": "が", "is_correct": false, "explanation": "「ゲームがは」は主語の格として成り立たず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「ゲームのは」は所属や修飾の格として成り立たず、不自然。"}], "correct_answer": "で", "explanations": {"で": "「ゲームでは」で場所や範囲を示し、「仲間になれる」という文の前提として自然に続く。", "を": "「ゲームをは」は目的語の格として成り立たず、不自然。", "が": "「ゲームがは」は主語の格として成り立たず、不自然。", "の": "「ゲームのは」は所属や修飾の格として成り立たず、不自然。"}, "error_tags": {"で": "場所・範囲", "を": "目的語", "が": "主語", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37426, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ゲームの大会」は所属や修飾を表し、ゲームに関する大会を示す自然な言い方になる。"}, {"text": "を", "is_correct": false, "explanation": "「ゲームを大会が」は目的語の格として成り立たず、不自然。"}, {"text": "が", "is_correct": false, "explanation": "「ゲームが大会が」は主語が二重になり、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「ゲームへ大会が」は方向の格として成り立たず、大会の開催を述べる文に合わない。"}], "correct_answer": "の", "explanations": {"の": "「ゲームの大会」は所属や修飾を表し、ゲームに関する大会を示す自然な言い方になる。", "を": "「ゲームを大会が」は目的語の格として成り立たず、不自然。", "が": "「ゲームが大会が」は主語が二重になり、文として成り立たない。", "へ": "「ゲームへ大会が」は方向の格として成り立たず、大会の開催を述べる文に合わない。"}, "error_tags": {"の": "所属・修飾", "を": "目的語", "が": "主語", "へ": "方向・帰属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37426, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たくさんの人がインターネットで一緒に遊ぶゲームです。", "primary_collocate": null, "pronunciation": "おんらいんろーるぷれいんぐげーむ", "ipa": "oɴɾaiɴɾoːɾɯpɯɾeiŋɡɯɡeːmɯ", "syllable_count": 16, "sentences": [{"text": "弟はオンラインロールプレイングゲームに夢中で、夜も遅くまで遊んでいます。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "弟[おとうと]はオンラインロールプレイングゲームに夢中[むちゅう]で、夜[よる]も遅[おそ]くまで遊[あそ]んでいます。", "sentence_source": "generated"}, {"text": "オンラインロールプレイングゲームでは、世界中の人と仲間になれます。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "オンラインロールプレイングゲームでは、世界中[せかいじゅう]の人[ひと]と仲間[なかま]になれます。", "sentence_source": "generated"}, {"text": "友だちに誘われて、オンラインロールプレイングゲームを始めました。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "友[とも]だちに誘[さそ]われて、オンラインロールプレイングゲームを始[はじ]めました。", "sentence_source": "generated"}, {"text": "オンラインロールプレイングゲームは、時間を忘れてしまうので注意が必要です。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "オンラインロールプレイングゲームは、時間[じかん]を忘[わす]れてしまうので注意[ちゅうい]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "遠くに住む兄と、オンラインロールプレイングゲームで会って話します。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "遠[とお]くに住[す]む兄[あに]と、オンラインロールプレイングゲームで会[あ]って話[はな]します。", "sentence_source": "generated"}, {"text": "このオンラインロールプレイングゲームは、子どもでも遊べます。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "このオンラインロールプレイングゲームは、子[こ]どもでも遊[あそ]べます。", "sentence_source": "generated"}, {"text": "私はオンラインロールプレイングゲームの中で、魔法使いになりました。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "私[わたし]はオンラインロールプレイングゲームの中[なか]で、魔法使[まほうつか]いになりました。", "sentence_source": "generated"}, {"text": "オンラインロールプレイングゲームの大会が、来月開かれます。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "オンラインロールプレイングゲームの大会[たいかい]が、来月[らいげつ]開[ひら]かれます。", "sentence_source": "generated"}, {"text": "宿題が終わってから、オンラインロールプレイングゲームをする約束です。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]が終[お]わってから、オンラインロールプレイングゲームをする約束[やくそく]です。", "sentence_source": "generated"}, {"text": "オンラインロールプレイングゲームで知り合った人と、実際に会いました。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "オンラインロールプレイングゲームで知[し]り合[あ]った人[ひと]と、実際[じっさい]に会[あ]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "オンラインロールプレイングゲーム", "label": "基本形"}], "register": "標準", "sense_fingerprint": "ネットで大勢が一緒に遊ぶ役割演技のゲーム", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b906860-ce3e-49f4-97db-f10691e443cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37426, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "オンラインロールプレイングゲーム", "is_correct": true, "explanation": "「ゲームに夢中」は自然な言い方で、夜遅くまで遊んでいる文脈に合う。"}, {"text": "税金", "is_correct": false, "explanation": "「税金に夢中」は不自然で、弟が遊んでいる話とは関係がない。"}, {"text": "発電機", "is_correct": false, "explanation": "「発電機に夢中」は成り立たず、遊びの話題とつながらない。"}, {"text": "抽選", "is_correct": false, "explanation": "「抽選に夢中」は不自然で、夜遅くまで遊ぶという文脈には入らない。"}], "explanations": {"オンラインロールプレイングゲーム": "「ゲームに夢中」は自然な言い方で、夜遅くまで遊んでいる文脈に合う。", "税金": "「税金に夢中」は不自然で、弟が遊んでいる話とは関係がない。", "発電機": "「発電機に夢中」は成り立たず、遊びの話題とつながらない。", "抽選": "「抽選に夢中」は不自然で、夜遅くまで遊ぶという文脈には入らない。"}, "sentence_index": 0, "correct_answer": "オンラインロールプレイングゲーム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "オンラインロールプレイングゲームは、食べ物をすばやく温めるので便利です。", "explanation": "ここは〈電子レンジ〉の意味。ゲームは食べ物を温める道具ではないので合わない。"}, {"text": "毎朝、オンラインロールプレイングゲームを顔に塗って、肌を整えている。", "explanation": "ここは〈化粧品〉の意味。ゲームは肌に塗る物ではないので、顔に塗る対象にはならない。"}, {"text": "事故に備えて、オンラインロールプレイングゲームに加入した。", "explanation": "ここは〈保険〉の意味。ゲームは補償を受ける契約ではないので、加入する対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37426, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "オンラインロールプレイングゲーム", "is_correct": true, "explanation": "「ゲームの中で」は仮想世界の中を指し、魔法使いになったという内容に合う。"}, {"text": "宿題", "is_correct": false, "explanation": "「宿題の中で」は意味が通らず、魔法使いになる話とは結びつかない。"}, {"text": "停電", "is_correct": false, "explanation": "「停電の中で」は不自然で、魔法使いになるという文脈には入らない。"}, {"text": "地震", "is_correct": false, "explanation": "「地震の中で」は成り立たず、この文の内容とも関係がない。"}], "explanations": {"オンラインロールプレイングゲーム": "「ゲームの中で」は仮想世界の中を指し、魔法使いになったという内容に合う。", "宿題": "「宿題の中で」は意味が通らず、魔法使いになる話とは結びつかない。", "停電": "「停電の中で」は不自然で、魔法使いになるという文脈には入らない。", "地震": "「地震の中で」は成り立たず、この文の内容とも関係がない。"}, "sentence_index": 6, "correct_answer": "オンラインロールプレイングゲーム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "畑では、オンラインロールプレイングゲームを育てている。", "explanation": "ここは〈野菜〉の意味。ゲームは育てる対象ではないので、畑で育てるものには合わない。"}, {"text": "牛乳はオンラインロールプレイングゲームで冷やしてから飲みましょう。", "explanation": "ここは〈冷蔵庫〉の意味。ゲームは物を冷やす道具ではないので合わない。"}, {"text": "床の汚れはオンラインロールプレイングゲームでふく。", "explanation": "ここは〈モップ〉の意味。ゲームは掃除の道具ではないので、床をふく手段にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37426, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹はオンラインロールプレイングゲームを夢中で、毎晩遅くまで遊んでいます。", "corrected_sentence": "妹はオンラインロールプレイングゲームに夢中で、毎晩遅くまで遊んでいます。", "error_description": "「夢中」の前に来る助詞は「に」。「を」は誤りで、「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37426, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉はオンラインロールプレイングゲームを好きで、毎晩遊んでいます。", "corrected_sentence": "姉はオンラインロールプレイングゲームが好きで、毎晩遊んでいます。", "error_description": "「好き」の前に来る助詞は「が」。「を」は誤りで、「が」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
