INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37427, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ゲームの途中」で後ろの名詞を修飾する連体修飾で、正しい。"}, {"text": "と", "is_correct": false, "explanation": "「ゲームと途中で終わって」は並列の形にならず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「ゲームへ途中で終わって」は方向の意味にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「ゲームより途中で終わって」は比較の意味にならず、文として不自然。"}], "correct_answer": "の", "explanations": {"の": "「ゲームの途中」で後ろの名詞を修飾する連体修飾で、正しい。", "と": "「ゲームと途中で終わって」は並列の形にならず、文が成り立たない。", "へ": "「ゲームへ途中で終わって」は方向の意味にならず、文が成り立たない。", "より": "「ゲームより途中で終わって」は比較の意味にならず、文として不自然。"}, "error_tags": {"の": "連体修飾", "と": "並列", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37427, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "インターネットを通じて、多くのプレイヤーが同時に参加し、それぞれの役割を演じながら進めるゲーム。", "primary_collocate": null, "pronunciation": "おんらいんろーるぷれいんぐげーむ", "ipa": "oɴɾaiɴɾoːɾɯpɯɾeiŋɡɯɡeːmɯ", "syllable_count": 16, "sentences": [{"text": "オンラインロールプレイングゲームでは、プレイヤーがそれぞれ戦士や魔法使いの役を演じます。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "オンラインロールプレイングゲームでは、プレイヤーがそれぞれ戦士[せんし]や魔法使[まほうつか]いの役[やく]を演[えん]じます。", "sentence_source": "generated"}, {"text": "数万人が同時に参加するオンラインロールプレイングゲームが増えています。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "数万人[すうまんにん]が同時[どうじ]に参加[さんか]するオンラインロールプレイングゲームが増[ふ]えています。", "sentence_source": "generated"}, {"text": "彼はオンラインロールプレイングゲームで、仲間と協力して強い敵を倒しました。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "彼[かれ]はオンラインロールプレイングゲームで、仲間[なかま]と協力[きょうりょく]して強[つよ]い敵[てき]を倒[たお]しました。", "sentence_source": "generated"}, {"text": "オンラインロールプレイングゲームの世界では、プレイヤー同士が物語を作っていきます。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "オンラインロールプレイングゲームの世界[せかい]では、プレイヤー同士[どうし]が物語[ものがたり]を作[つく]っていきます。", "sentence_source": "generated"}, {"text": "サーバーが混むと、オンラインロールプレイングゲームに入れないことがあります。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "サーバーが混[こ]むと、オンラインロールプレイングゲームに入[はい]れないことがあります。", "sentence_source": "generated"}, {"text": "この会社は、新しいオンラインロールプレイングゲームを来年発売します。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、新[あたら]しいオンラインロールプレイングゲームを来年[らいねん]発売[はつばい]します。", "sentence_source": "generated"}, {"text": "オンラインロールプレイングゲームでは、役割を分けて進めるのが普通です。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "オンラインロールプレイングゲームでは、役割[やくわり]を分[わ]けて進[すす]めるのが普通[ふつう]です。", "sentence_source": "generated"}, {"text": "通信が切れて、オンラインロールプレイングゲームの途中で終わってしまいました。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "通信[つうしん]が切[き]れて、オンラインロールプレイングゲームの途中[とちゅう]で終[お]わってしまいました。", "sentence_source": "generated"}, {"text": "姉はオンラインロールプレイングゲームの中で店を開き、道具を売っています。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "姉[あね]はオンラインロールプレイングゲームの中[なか]で店[みせ]を開[ひら]き、道具[どうぐ]を売[う]っています。", "sentence_source": "generated"}, {"text": "オンラインロールプレイングゲームは、画面の向こうの人と一緒に冒険できるのが魅力です。", "target_word": "オンラインロールプレイングゲーム", "complexity_tier": "T3", "furigana": "オンラインロールプレイングゲームは、画面[がめん]の向[む]こうの人[ひと]と一緒[いっしょ]に冒険[ぼうけん]できるのが魅力[みりょく]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "オンラインロールプレイングゲーム", "label": "基本形"}], "register": "標準", "sense_fingerprint": "多数のプレイヤーが同時参加し役を演じて進めるネットゲーム", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b906860-ce3e-49f4-97db-f10691e443cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37427, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "オンラインロールプレイングゲーム", "is_correct": true, "explanation": "「では」の前に置く主語で、多人数が役を演じて進むネットゲームを指すので文が成り立つ。"}, {"text": "ボランティア活動", "is_correct": false, "explanation": "社会活動を指す語で、プレイヤーが戦士や魔法使いの役を演じる文脈と合わない。"}, {"text": "電子レンジ", "is_correct": false, "explanation": "調理家電の名前で、役を演じる場面の主語にはならない。"}, {"text": "プラモデル", "is_correct": false, "explanation": "組み立てて遊ぶ模型で、プレイヤーが役を演じるという文の主語として成り立たない。"}], "explanations": {"オンラインロールプレイングゲーム": "「では」の前に置く主語で、多人数が役を演じて進むネットゲームを指すので文が成り立つ。", "ボランティア活動": "社会活動を指す語で、プレイヤーが戦士や魔法使いの役を演じる文脈と合わない。", "電子レンジ": "調理家電の名前で、役を演じる場面の主語にはならない。", "プラモデル": "組み立てて遊ぶ模型で、プレイヤーが役を演じるという文の主語として成り立たない。"}, "sentence_index": 0, "correct_answer": "オンラインロールプレイングゲーム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このアプリは、友達と順番にブロックを並べるオンラインロールプレイングゲームです。", "explanation": "〈パズルゲーム〉の意味。ブロックを並べて消す遊びは、役を演じて物語を進めるこの語とは合わない。"}, {"text": "新人研修では、上司役と部下役に分かれてオンラインロールプレイングゲームの練習をします。", "explanation": "〈役割演習〉の意味。研修で役を分けて行う練習は対面の訓練で、インターネットを通じて遊ぶゲームのこの語とは合わない。"}, {"text": "休日、家族が机を囲んで、このオンラインロールプレイングゲームのさいころを振りました。", "explanation": "〈テーブルトークRPG〉の意味。机を囲んでさいころで遊ぶ形式は、インターネットを通じて多くの人が参加するこの語とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37427, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "オンラインロールプレイングゲーム", "is_correct": true, "explanation": "「役割を分けて進める」の主語になり、ゲームの進め方を説明する文に合う。"}, {"text": "ペットボトル", "is_correct": false, "explanation": "容器の名前で、役割を分けて進めるという文の主語にはならない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "家電の名前で、役割を分けて進めるという文と意味が結びつかない。"}, {"text": "体温計", "is_correct": false, "explanation": "測定器の名前で、役割分担の進め方を説明する文の主語として成り立たない。"}], "explanations": {"オンラインロールプレイングゲーム": "「役割を分けて進める」の主語になり、ゲームの進め方を説明する文に合う。", "ペットボトル": "容器の名前で、役割を分けて進めるという文の主語にはならない。", "洗濯機": "家電の名前で、役割を分けて進めるという文と意味が結びつかない。", "体温計": "測定器の名前で、役割分担の進め方を説明する文の主語として成り立たない。"}, "sentence_index": 6, "correct_answer": "オンラインロールプレイングゲーム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このオンラインロールプレイングゲームを読むと、選んだ番号のページに進んで冒険できます。", "explanation": "〈ゲームブック〉の意味。紙の本のページを選んで読み進める形式で、画面で遊ぶこの語とは合わない。"}, {"text": "このオンラインロールプレイングゲームでは、視聴者が好きな番組を選んで見ます。", "explanation": "〈動画配信〉の意味。番組を選んで見るのは配信サービスの話で、プレイヤーが役を演じるこの語とは合わない。"}, {"text": "このオンラインロールプレイングゲームは、二人が画面の前で対戦して勝ち負けを決めます。", "explanation": "〈格闘ゲーム〉の意味。二人が対戦して勝敗を決める遊びは、役を演じて物語を進めるこの語とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37427, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私はオンラインロールプレイングゲームを入って、新しい仲間と出会いました。", "corrected_sentence": "私はオンラインロールプレイングゲームに入って、新しい仲間と出会いました。", "error_description": "助詞の誤り。「入る」は場所や対象を「に」で受けるので、「を」は誤り（正しくは「ゲームに入って」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37427, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週、初めてオンラインロールプレイングゲームを始めます。", "corrected_sentence": "先週、初めてオンラインロールプレイングゲームを始めました。", "error_description": "時制の誤り。「先週」という過去の出来事なので過去形の「始めました」にする。「始めます」は非過去形で不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66bdfcb6-8f73-438a-ada1-5829239b81a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37428, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、戦術が変えるという形になり、文の意味が通らない。"}, {"text": "を", "is_correct": true, "explanation": "「変える」の目的語として戦術を示す。「戦術を変える必要がある」は自然な形。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するため、「戦術の変える必要」は文法的に続かない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示し、「戦術と変える」は「変える」の目的語として成り立たない。"}], "correct_answer": "を", "explanations": {"が": "「が」は主語を示すため、戦術が変えるという形になり、文の意味が通らない。", "を": "「変える」の目的語として戦術を示す。「戦術を変える必要がある」は自然な形。", "の": "「の」は名詞を修飾するため、「戦術の変える必要」は文法的に続かない。", "と": "「と」は並列や引用を示し、「戦術と変える」は「変える」の目的語として成り立たない。"}, "error_tags": {"が": "主格", "の": "連体修飾", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37428, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "に", "is_correct": false, "explanation": "「に」は相手を示す格で、「戦術に選手たちに教える」では「に」が二つ並び文が成り立たない。"}, {"text": "を", "is_correct": true, "explanation": "「教えてくれた」の直接の目的語として戦術を示す。「戦術を選手たちに教える」は自然な形。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、教える内容である戦術を表すことができない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、戦術が選手たちに教えるという意味になり、戦術が人に教えるのは不自然。"}], "correct_answer": "を", "explanations": {"に": "「に」は相手を示す格で、「戦術に選手たちに教える」では「に」が二つ並び文が成り立たない。", "を": "「教えてくれた」の直接の目的語として戦術を示す。「戦術を選手たちに教える」は自然な形。", "へ": "「へ」は方向を示すため、教える内容である戦術を表すことができない。", "が": "「が」は主語を示すため、戦術が選手たちに教えるという意味になり、戦術が人に教えるのは不自然。"}, "error_tags": {"に": "相手・二重格", "へ": "方向", "が": "主格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37428, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目標を達成するための計画や方法を選ぶこと。", "primary_collocate": null, "pronunciation": "せんじゅつ", "ipa": "seɴdʑɯtsɯ", "syllable_count": 4, "sentences": [{"text": "監督は、試合の前に新しい戦術を説明しました。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "監督[かんとく]は、試合[しあい]の前[まえ]に新[あたら]しい戦術[せんじゅつ]を説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "相手が強いので、戦術を変える必要があります。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "相手[あいて]が強[つよ]いので、戦術[せんじゅつ]を変[か]える必要[ひつよう]があります。", "sentence_source": "generated"}, {"text": "この戦術は簡単ですが、よく効きます。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "この戦術[せんじゅつ]は簡単[かんたん]ですが、よく効[き]きます。", "sentence_source": "generated"}, {"text": "彼のチームは、守りを中心にした戦術で勝ちました。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "彼[かれ]のチームは、守[まも]りを中心[ちゅうしん]にした戦術[せんじゅつ]で勝[か]ちました。", "sentence_source": "generated"}, {"text": "ゲームでは、仲間と戦術を話し合うことが大切です。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "ゲームでは、仲間[なかま]と戦術[せんじゅつ]を話[はな]し合[あ]うことが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "戦術がよくなかったので、私たちは負けてしまいました。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "戦術[せんじゅつ]がよくなかったので、私[わたし]たちは負[ま]けてしまいました。", "sentence_source": "generated"}, {"text": "将棋の本を読んで、新しい戦術を覚えました。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "将棋[しょうぎ]の本[ほん]を読[よ]んで、新[あたら]しい戦術[せんじゅつ]を覚[おぼ]えました。", "sentence_source": "generated"}, {"text": "コーチは、後半に逆転するための戦術を選手たちに教えてくれました。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "コーチは、後半[こうはん]に逆転[ぎゃくてん]するための戦術[せんじゅつ]を選手[せんしゅ]たちに教[おし]えてくれました。", "sentence_source": "generated"}, {"text": "戦術を立てる前に、相手の力を調べましょう。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "戦術[せんじゅつ]を立[た]てる前[まえ]に、相手[あいて]の力[ちから]を調[しら]べましょう。", "sentence_source": "generated"}, {"text": "相手の戦術が分かれば、対策もしやすくなります。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "相手[あいて]の戦術[せんじゅつ]が分[わ]かれば、対策[たいさく]もしやすくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戦術", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "勝つためなど目標のために計画や方法を選ぶこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe8a64e-398a-44c0-8fce-9cbeb83b8e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37428, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天気", "is_correct": false, "explanation": "天気は説明する対象として「新しい天気を説明する」とは言わず、文が通らない。"}, {"text": "戦術", "is_correct": true, "explanation": "試合に向けて立てる計画や方法を指し、「新しい戦術を説明する」と自然につながる。"}, {"text": "得点", "is_correct": false, "explanation": "得点は数えるもので、「新しい得点を説明する」は意味が通らない。"}, {"text": "試合", "is_correct": false, "explanation": "「試合の前に新しい試合を説明する」は意味が重なり不自然で、空欄に入らない。"}], "explanations": {"天気": "天気は説明する対象として「新しい天気を説明する」とは言わず、文が通らない。", "戦術": "試合に向けて立てる計画や方法を指し、「新しい戦術を説明する」と自然につながる。", "得点": "得点は数えるもので、「新しい得点を説明する」は意味が通らない。", "試合": "「試合の前に新しい試合を説明する」は意味が重なり不自然で、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "戦術"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はピアノの戦術が高く、コンクールで優勝した。", "explanation": "戦術は目標を達成するための計画や方法を指し、腕前の高さは指さないので合わない。"}, {"text": "新しい選手が加わって、チームの戦術の体重が増えた。", "explanation": "戦術は計画や方法で、重さを量る対象にはならないので、体重のように増えるという言い方には合わない。"}, {"text": "新しい戦術を買って、敵を倒した。", "explanation": "戦術は計画や方法で、店で買って使う物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37428, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防具", "is_correct": false, "explanation": "防具は身を守る道具で、将棋の本を読んで覚えるものとしては文が成り立たない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は覚える対象として不自然で、「新しい手紙を覚えました」は意味が通らない。"}, {"text": "戦術", "is_correct": true, "explanation": "将棋の本で覚えるのは指し方の方法なので、「新しい戦術を覚えました」と自然につながる。"}, {"text": "反射", "is_correct": false, "explanation": "反射は覚えるものではなく、「新しい反射を覚えました」は文として成り立たない。"}], "explanations": {"防具": "防具は身を守る道具で、将棋の本を読んで覚えるものとしては文が成り立たない。", "手紙": "手紙は覚える対象として不自然で、「新しい手紙を覚えました」は意味が通らない。", "戦術": "将棋の本で覚えるのは指し方の方法なので、「新しい戦術を覚えました」と自然につながる。", "反射": "反射は覚えるものではなく、「新しい反射を覚えました」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "戦術"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "うちの会社は十年先まで続く戦術を発表した。", "explanation": "戦術は当面の目標を達成する具体的な方法を指し、十年単位の大きな方針には使わない。"}, {"text": "その戦術は重くて、一人では運べない。", "explanation": "戦術は形のある物ではないので、重さを言ったり運んだりできない。"}, {"text": "マラソンの終盤で戦術がしびれて、歩いてしまった。", "explanation": "しびれるのは足などの体の感覚で、戦術は計画や方法なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37428, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "コーチは試合の前に戦術に説明しました。", "corrected_sentence": "コーチは試合の前に戦術を説明しました。", "error_description": "誤：「戦術に」、正：「戦術を」。「説明する」は他動詞で、説明の対象である戦術を「を」で示す。「に」では成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37428, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "監督は戦術を立てた前に、選手の体調を確認しました。", "corrected_sentence": "監督は戦術を立てる前に、選手の体調を確認しました。", "error_description": "誤：「立てた前に」、正：「立てる前に」。「〜前に」は動詞の辞書形につけるため、過去形の「立てた」は続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
