INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37429, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "を", "is_correct": false, "explanation": "「うまくいく」は自動詞なので、「戦術をうまくいって」と目的語は取れない。"}, {"text": "が", "is_correct": true, "explanation": "「うまくいく」の主語として戦術を示す。「戦術がうまくいって」は自然な形。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するため、「戦術のうまくいって」は文として続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「戦術へうまくいって」は成り立たない。"}], "correct_answer": "が", "explanations": {"を": "「うまくいく」は自動詞なので、「戦術をうまくいって」と目的語は取れない。", "が": "「うまくいく」の主語として戦術を示す。「戦術がうまくいって」は自然な形。", "の": "「の」は名詞を修飾するため、「戦術のうまくいって」は文として続かない。", "へ": "「へ」は方向を示すため、「戦術へうまくいって」は成り立たない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9be07a7a-c1ec-4907-bdec-1939a686e743') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37429, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目標を達成するために、状況に応じて最も効果的な行動や方法を選び、実行すること。", "primary_collocate": null, "pronunciation": "せんじゅつ", "ipa": "seɴdʑɯtsɯ", "syllable_count": 4, "sentences": [{"text": "状況が変わったので、戦術を急いで変えました。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "状況[じょうきょう]が変[か]わったので、戦術[せんじゅつ]を急[いそ]いで変[か]えました。", "sentence_source": "generated"}, {"text": "彼は相手の動きを見て、最も効果的な戦術を選びました。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "彼[かれ]は相手[あいて]の動[うご]きを見[み]て、最[もっと]も効果的[こうかてき]な戦術[せんじゅつ]を選[えら]びました。", "sentence_source": "generated"}, {"text": "雨の日の試合では、戦術を工夫しなければなりません。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]の試合[しあい]では、戦術[せんじゅつ]を工夫[くふう]しなければなりません。", "sentence_source": "generated"}, {"text": "前半に点を取られ、後半は攻める戦術に切り替えました。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "前半[ぜんはん]に点[てん]を取[と]られ、後半[こうはん]は攻[せ]める戦術[せんじゅつ]に切[き]り替[か]えました。", "sentence_source": "generated"}, {"text": "選手たちは、監督の戦術どおりに動きました。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "選手[せんしゅ]たちは、監督[かんとく]の戦術[せんじゅつ]どおりに動[うご]きました。", "sentence_source": "generated"}, {"text": "会社の営業部は、新しい戦術で売り上げを伸ばしました。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の営業部[えいぎょうぶ]は、新[あたら]しい戦術[せんじゅつ]で売[う]り上[あ]げを伸[の]ばしました。", "sentence_source": "generated"}, {"text": "敵が多いときは、逃げるのも一つの戦術です。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "敵[てき]が多[おお]いときは、逃[に]げるのも一[ひと]つの戦術[せんじゅつ]です。", "sentence_source": "generated"}, {"text": "戦術がうまくいって、強い相手に勝てました。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "戦術[せんじゅつ]がうまくいって、強[つよ]い相手[あいて]に勝[か]てました。", "sentence_source": "generated"}, {"text": "状況を見ながら、戦術を柔軟に変えるのが上手な人です。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "状況[じょうきょう]を見[み]ながら、戦術[せんじゅつ]を柔軟[じゅうなん]に変[か]えるのが上手[じょうず]な人[ひと]です。", "sentence_source": "generated"}, {"text": "このゲームでは、場面ごとの戦術が勝敗を決めます。", "target_word": "戦術", "complexity_tier": "T3", "furigana": "このゲームでは、場面[ばめん]ごとの戦術[せんじゅつ]が勝敗[しょうはい]を決[き]めます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "戦術", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "状況に応じて最も効果的な行動や方法を選び実行すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfe8a64e-398a-44c0-8fce-9cbeb83b8e67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
